-- Generated from data/roadmap-tracks.json + data/seed.json by scripts/generate-roadmap-tracks.mjs.
-- Adds each role focus to a 21-phase conversion of the authored ZTE curriculum.
-- Existing owner curriculum tables and user progress are not modified.
begin;
update public.roadmap_versions set is_current=false where roadmap_id='zte-frontend-v1';
update public.roadmap_versions set is_current=false where roadmap_id='zte-backend-java-v1';
update public.roadmap_versions set is_current=false where roadmap_id='zte-fullstack-v1';
delete from public.role_roadmap_assignments where role_id in ('frontend-developer','backend-developer','fullstack-developer','sde-1','devops-engineer','cloud-engineer','mobile-engineer','qa-engineer','bi-data-analyst','operations-analyst');
on conflict (role_id, roadmap_id) do update set priority=excluded.priority;
commit;
