insert into public.roadmaps (id, title, track, description, is_public) values ('zte-frontend-v1', 'ZTE Frontend Engineering', 'frontend', 'A project-centered frontend path covering browser foundations, accessible interfaces, typed application architecture, quality, performance, and career evidence.', true) on conflict (id) do update set title=excluded.title, track=excluded.track, description=excluded.description, is_public=true;
insert into public.roadmap_versions (roadmap_id, version_number, label, is_current) values ('zte-frontend-v1', 2, 'v2.0', true) on conflict (roadmap_id, version_number) do update set label=excluded.label, is_current=true returning id;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-01', 'zte-frontend-v1', id, '01', 'Developer Environment & Foundations', 'Foundation', 'You cannot learn to code without a place to write it, run it, and save it. This stage exists so every topic after it has a working environment underneath it.', 199, 0 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
