insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-01-m03', 'zte-frontend-v1-core-phase-01', 3, 'Adding Types: TypeScript and Data: SQL Fundamentals', 'TypeScript only makes sense once JavaScript is solid — it''s a typed layer on top of JS, not a separate language. Intro concepts come first, then the full Mastery set from Phase 01b, each ordered so foundational type mechanics (generics, narrowing) precede the advanced techniques that combine them (conditional/mapped types, template literals).', 42, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
