insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-01-m04', 'zte-frontend-v1-core-phase-01', 4, 'Collaboration & Code Quality', 'Everything in this final stage assumes you now have real, multi-file projects worth versioning, linting, and formatting properly — HTML/CSS pages, JS/TS scripts, and SQL schemas from Stages 2–6. This is why deeper Git workflows, commit hygiene, and tooling are saved for last rather than front-loaded in Stage 1, where you had nothing substantial to collaborate on yet.', 13, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
