insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-01', 'zte-frontend-v1-core-phase-01', 'Dotfiles Time Capsule', 'Build a personal dotfiles repository that configures your entire terminal + editor environment from scratch on a fresh machine. Includes a bootstrap.sh script that installs nvm, sets Node version, configures VS Code settings.json, keybindings, and a curated extension list via "code --install-extension", and sets up SSH key generation with a checklist prompt. Domain: developer tooling / DevOps. Why it’s real: every professional engineer eventually builds this, and you’ll actually reuse it.', array['Deliver the working outcome described in the Dotfiles Time Capsule brief.', 'Use at least two skills from Your Workspace (before writing a single line of real code) and Structure: HTML and Presentation: CSS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Dotfiles Time Capsule', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Your Workspace (before writing a single line of real code) and Structure: HTML and Presentation: CSS']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-02', 'zte-frontend-v1-core-phase-01', 'New Machine, Ten Minutes', 'Extend the dotfiles project into a single idempotent shell script that provisions a brand-new Ubuntu/macOS machine for full-stack development in under 10 minutes — installs Git, nvm, correct Node LTS, global CLI tools (pnpm, gh CLI), configures a global .gitignore, sets up commit signing with SSH keys, and verifies everything with a self-test script that prints pass/fail per component. Why it’s real: this is what onboarding scripts at real companies look like.', array['Deliver the working outcome described in the New Machine, Ten Minutes brief.', 'Use at least two skills from Your Workspace (before writing a single line of real code) and Structure: HTML and Presentation: CSS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working New Machine, Ten Minutes', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Your Workspace (before writing a single line of real code) and Structure: HTML and Presentation: CSS']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-03', 'zte-frontend-v1-core-phase-01', 'Team Onboarding Kit', 'Package the above into a shareable CLI tool ("npx create-dev-environment") that asks interactive questions (shell preference, editor, GitHub username) and generates a personalized setup repo plus a rendered onboarding README with screenshots. Publish it as an npm package others could install. Why it’s real: this is a genuine open-source-worthy tool — portfolio-impressive because it is meta (a tool that builds tools).', array['Deliver the working outcome described in the Team Onboarding Kit brief.', 'Use at least two skills from Your Workspace (before writing a single line of real code) and Structure: HTML and Presentation: CSS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Team Onboarding Kit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Your Workspace (before writing a single line of real code) and Structure: HTML and Presentation: CSS']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-04', 'zte-frontend-v1-core-phase-01', 'Recipe Card, Zero CSS', 'Build a single recipe page using only semantic HTML5 (article, section, figure, time, details) — no CSS at all. It must still be readable, accessible, and make logical sense structurally. Domain: food/lifestyle.', array['Deliver the working outcome described in the Recipe Card, Zero CSS brief.', 'Use at least two skills from Structure: HTML.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Recipe Card, Zero CSS', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Structure: HTML']::text[], 'beginner', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-05', 'zte-frontend-v1-core-phase-01', 'Accessible Government Notice Board', 'Recreate a public notice/announcements page (like a city council site) with correct heading hierarchy, ARIA landmarks, a data table of meeting minutes using proper caption/th-scope, and a downloadable-document list using semantically correct link text (no "click here"). Must pass a Lighthouse accessibility audit at 100. Domain: civic tech.', array['Deliver the working outcome described in the Accessible Government Notice Board brief.', 'Use at least two skills from Structure: HTML.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Accessible Government Notice Board', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Structure: HTML']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-06', 'zte-frontend-v1-core-phase-01', 'Structured Résumé That’s Also a Sitemap', 'Build a résumé page using HTML microdata / Schema.org (itemscope, itemprop for Person, JobPosting history) so it’s machine-readable by search engines and could populate a rich search result. Validate with Google’s Rich Results Test. Domain: personal branding / SEO engineering.', array['Deliver the working outcome described in the Structured Résumé That’s Also a Sitemap brief.', 'Use at least two skills from Structure: HTML.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Structured Résumé That’s Also a Sitemap', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Structure: HTML']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-07', 'zte-frontend-v1-core-phase-01', 'Print-Perfect Invoice', 'Design an invoice that looks correct both on-screen and when printed (@media print), with page-break control, so a small business could literally print/PDF it for clients. Domain: business/finance tooling.', array['Deliver the working outcome described in the Print-Perfect Invoice brief.', 'Use at least two skills from Presentation: CSS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Print-Perfect Invoice', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Presentation: CSS']::text[], 'beginner', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-08', 'zte-frontend-v1-core-phase-01', 'CSS-Only Data Dashboard Skeleton', 'Build a responsive analytics dashboard layout (sidebar, KPI cards, chart placeholders, table) using CSS Grid + Flexbox combined, fully responsive from 320px to 4K, with no JavaScript — including a CSS-only collapsible sidebar using the checkbox hack or :has(). Domain: SaaS/analytics.', array['Deliver the working outcome described in the CSS-Only Data Dashboard Skeleton brief.', 'Use at least two skills from Presentation: CSS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CSS-Only Data Dashboard Skeleton', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Presentation: CSS']::text[], 'intermediate', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-09', 'zte-frontend-v1-core-phase-01', 'Theatre Seat Map', 'Build a fully CSS-driven interactive seat-selection map (like a cinema/concert booking UI) — hover states, sold/available/selected visual states, using CSS Grid for the seat layout and pure CSS (:checked, sibling selectors) for selection logic, no JS. Domain: ticketing/events. Why it’s real: real booking sites need exactly this pattern; doing it CSS-only proves deep selector mastery.', array['Deliver the working outcome described in the Theatre Seat Map brief.', 'Use at least two skills from Presentation: CSS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Theatre Seat Map', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Presentation: CSS']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-10', 'zte-frontend-v1-core-phase-01', 'Command-Line Expense Tracker', 'A Node.js CLI tool that tracks expenses in a local JSON file, using Maps/Sets for category dedup, robust try/catch with custom Error subclasses, and regex-based input validation. Domain: personal finance. Covers: language core, data structures, error handling, regex. A choose-your-own-adventure engine driven by a JSON story graph, using classes for Room/Player/Item, prototypal inheritance for enemy types, and regex command parsing ("go north", "take sword"). Domain: games/interactive fiction.', array['Deliver the working outcome described in the Command-Line Expense Tracker brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Command-Line Expense Tracker', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'beginner', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-11', 'zte-frontend-v1-core-phase-01', 'Log File Forensics Tool', 'A Node CLI that ingests raw server log files, uses regex to extract structured events, aggregates with Maps, and flags anomalies using custom error classes for malformed lines. Domain: SRE/observability. A mini fluent query builder (db.users.where("age").gt(18).select("name")) using Proxy to intercept property access, Reflect for meta-operations, and generators for lazy result iteration. Domain: backend tooling. Covers: prototypes, classes, iterators/generators, symbols, meta-programming, Proxy, Reflect.', array['Deliver the working outcome described in the Log File Forensics Tool brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Log File Forensics Tool', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'intermediate', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-12', 'zte-frontend-v1-core-phase-01', 'Reactive State Store from Scratch', 'Build a tiny Redux/Zustand-like state management library using Proxy for reactivity, Symbols for private internal keys, and a plugin system using meta-programming. Ship as an npm-installable package with tests. Domain: frontend infrastructure. Why it’s real: this is literally how real state libraries are built internally.', array['Deliver the working outcome described in the Reactive State Store from Scratch brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Reactive State Store from Scratch', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'advanced', 11) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-13', 'zte-frontend-v1-core-phase-01', 'Iterable Deck of Cards / Card Game Engine', 'Model a deck of cards as a custom iterable (Symbol.iterator), build a generator-based shuffle/deal system, and implement Blackjack or War fully in the terminal. Domain: games.', array['Deliver the working outcome described in the Iterable Deck of Cards / Card Game Engine brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Iterable Deck of Cards / Card Game Engine', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'intermediate', 12) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-14', 'zte-frontend-v1-core-phase-01', 'Weather-Aware Commute Planner', 'A Node script that calls a real weather API and a geocoding API concurrently using Promise.all, handles partial failures with Promise.allSettled, retries with exponential backoff, and outputs a commute recommendation. Domain: productivity/logistics. Covers: modules, event loop, async, promises, HTTP/APIs.', array['Deliver the working outcome described in the Weather-Aware Commute Planner brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Weather-Aware Commute Planner', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'intermediate', 13) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-15', 'zte-frontend-v1-core-phase-01', 'Rate-Limited API Aggregator', 'A tool that fetches data from 3+ public APIs while respecting each one’s rate limit using a hand-written async queue/throttler, with correct microtask/macrotask ordering, and caches results. Domain: data engineering.', array['Deliver the working outcome described in the Rate-Limited API Aggregator brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Rate-Limited API Aggregator', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'advanced', 14) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-16', 'zte-frontend-v1-core-phase-01', 'Live Order Status Simulator', 'Simulate an e-commerce order pipeline (payment → packing → shipping → delivered) as async stages with realistic delays, custom event emitters, and retry logic on failure. Domain: e-commerce/logistics. A fully vanilla-JS Trello-style kanban board: native Drag and Drop API, localStorage persistence, keyboard accessibility, IntersectionObserver-based lazy rendering. Domain: productivity tools. Covers: DOM, events, forms, storage, browser APIs, observers, workers, binary data.', array['Deliver the working outcome described in the Live Order Status Simulator brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Live Order Status Simulator', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'intermediate', 15) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-17', 'zte-frontend-v1-core-phase-01', 'Client-Side Image Compressor', 'Users drag in images, compression/resizing happens client-side via Canvas + binary data (ArrayBuffer/Blob), the compression runs in a Web Worker so the UI never freezes, and results are downloadable — zero backend. Domain: media tooling / privacy-first apps. Why it’s real: this is how tools like Squoosh.app actually work.', array['Deliver the working outcome described in the Client-Side Image Compressor brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Client-Side Image Compressor', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'advanced', 16) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
