insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-20', 'zte-frontend-v1-core-phase-01', 'Functional Data Pipeline Library', 'Build your own functional utility library (pipe, compose, curry, memoize, immutable update helpers) from scratch, fully unit-tested, then use it to process a real CSV dataset end-to-end. Domain: data processing / dev tools. A single documented codebase implementing 8 classic design patterns (Observer, Factory, Singleton, Strategy, Decorator, Command, Module, Facade), each solving a real mini-problem, with tests and a written doc explaining when to use each. Domain: software architecture. Why it’s real: genuinely useful as a portfolio artifact demonstrating architectural maturity.', array['Deliver the working outcome described in the Functional Data Pipeline Library brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Functional Data Pipeline Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'advanced', 19) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-21', 'zte-frontend-v1-core-phase-01', 'Type-Safe Config Loader', 'A small library that loads and validates environment-variable-based app config, using discriminated unions for different deploy environments and strict TypeScript to make invalid states unrepresentable. Domain: dev tooling.', array['Deliver the working outcome described in the Type-Safe Config Loader brief.', 'Use at least two skills from Adding Types: TypeScript and Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Type-Safe Config Loader', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Adding Types: TypeScript and Data: SQL Fundamentals']::text[], 'beginner', 20) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-22', 'zte-frontend-v1-core-phase-01', 'Generic Data Table Library', 'Build a fully generic, reusable data-table utility (sort/filter/paginate) typed with generics so it works correctly for any row shape (DataTable<User>, DataTable<Order>) with full autocomplete and compile-time safety on column keys. Domain: frontend infrastructure.', array['Deliver the working outcome described in the Generic Data Table Library brief.', 'Use at least two skills from Adding Types: TypeScript and Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Generic Data Table Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Adding Types: TypeScript and Data: SQL Fundamentals']::text[], 'intermediate', 21) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-23', 'zte-frontend-v1-core-phase-01', 'Typed API Client Generator', 'Given an OpenAPI-like JSON schema, generate fully-typed TypeScript API client functions using mapped types, conditional types, and template literal types (e.g. typed route strings), plus a Zod runtime validator layer so types are enforced at compile time and runtime. Domain: API tooling / codegen. Why it’s real: this is essentially what openapi-typescript and tRPC do internally.', array['Deliver the working outcome described in the Typed API Client Generator brief.', 'Use at least two skills from Adding Types: TypeScript and Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Typed API Client Generator', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Adding Types: TypeScript and Data: SQL Fundamentals']::text[], 'advanced', 22) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
