insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-25', 'zte-frontend-v1-core-phase-01', 'E-commerce Analytics Query Pack', 'Given a realistic multi-table e-commerce schema, write 15 real analytical queries a business would actually ask for: cohort retention, top products by margin, customers at risk of churn via window functions/RFM logic. Domain: e-commerce analytics.', array['Deliver the working outcome described in the E-commerce Analytics Query Pack brief.', 'Use at least two skills from Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working E-commerce Analytics Query Pack', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Data: SQL Fundamentals']::text[], 'intermediate', 24) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
