insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-28', 'zte-frontend-v1-core-phase-01', 'Team Code Quality Gate', 'Configure a shared ESLint + Prettier config as its own publishable npm package (@yourname/eslint-config) that multiple projects could extend, including at least one custom lint rule for a project-specific convention. Domain: engineering tooling.', array['Deliver the working outcome described in the Team Code Quality Gate brief.', 'Use at least two skills from Collaboration & Code Quality.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Team Code Quality Gate', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Collaboration & Code Quality']::text[], 'intermediate', 27) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-29', 'zte-frontend-v1-core-phase-01', 'Git Archaeology Report', 'Pick a real open-source repo, use git log, git blame, and git bisect to trace the history of a specific bug fix or feature through its evolution, and write a technical report, including reconstructing a rebase/merge scenario locally. Domain: software forensics.', array['Deliver the working outcome described in the Git Archaeology Report brief.', 'Use at least two skills from Collaboration & Code Quality.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Git Archaeology Report', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Collaboration & Code Quality']::text[], 'advanced', 28) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-30', 'zte-frontend-v1-core-phase-01', 'A Personal Developer Journal & Snippet Manager', 'Build a complete, deployable application that: is scaffolded with a proper dotfiles-provisioned dev environment (Stage 1); has full semantic, accessible HTML structure (Stage 2); is responsively styled with hand-written CSS Grid/Flexbox, no framework (Stage 3); implements all core logic in strict TypeScript compiled from scratch, covering async data fetching from a raw Node http server, custom iterators for browsing entries, a Proxy-based reactive UI updater, Web Worker-based full-text search indexing, and IndexedDB or a JSON file store for persistence (Stages 4–5); uses a real SQL database (SQLite is fine) with a normalized schema for entries/tags/snippets and at least 3 non-trivial analytical queries (Stage 6); and is version-controlled with clean Conventional Commit history, a CONTRIBUTING.md, linting, and a documented Git workflow (Stage 7). Deliverable: a working local-first journal/snippet app plus a written architecture doc explaining every technical decision. Domain: developer productivity tools. Why it matters: this project alone demonstrates command of the entire JS/TS/SQL/Git foundation without leaning on any framework crutch.', array['Deliver the working outcome described in the A Personal Developer Journal & Snippet Manager brief.', 'Use at least two skills from Developer Environment & Foundations.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Personal Developer Journal & Snippet Manager', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'engineering documentation']::text[], 'advanced', 29) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01-project-31', 'zte-frontend-v1-core-phase-01', 'Accessible responsive documentation site', 'Create a maintainable documentation site for a small open-source tool.', array['Semantic navigation and content structure', 'Responsive layouts', 'Accessible search and feedback form', 'Clear empty and error states']::text[], array['Content model and page map', 'Responsive implementation', 'Keyboard and screen-reader pass', 'Deployment and README']::text[], array['Deployed site', 'Accessibility checklist', 'README with setup and design decisions']::text[], array['HTML', 'CSS', 'accessibility', 'Git', 'frontend', 'engineering delivery']::text[], 'beginner', 30) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
