insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-01b-project-01', 'zte-frontend-v1-core-phase-01b', 'TypeScript Mastery applied challenge', 'Apply the core ideas in TypeScript Mastery to a small, useful engineering outcome.', array['Choose a concrete problem that uses the phase concepts.', 'Deliver a working result and document setup and decisions.']::text[], array['Write the problem and a short plan.', 'Build and review the result.', 'Capture evidence and a retrospective.']::text[], array['Working implementation', 'README with design decisions', 'Evidence and retrospective']::text[], array['TypeScript Mastery', 'engineering documentation']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-02', 'zte-frontend-v1', id, '03', 'React + Next.js Core', 'Foundation', 'Everything else in Phase 02 sits on top of React. Next.js is a framework around React, not a replacement for it — so React must be solid, and deep, first.', 234, 2 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-02-m01', 'zte-frontend-v1-core-phase-02', 1, 'React 18 (Foundation)', 'Everything else in Phase 02 sits on top of React. Next.js is a framework around React, not a replacement for it — so React must be solid, and deep, first.', 37, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
