insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m02-t02', 'zte-frontend-v1-core-phase-03-m02', 'tailwind-merge', array['Explain and apply null in tailwind-merge.', 'Use tailwind-merge to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Why conflicting Tailwind classes need special merging (CSS specificity ties, not overrides) in a small working example.', 'Demonstrate twMerge() resolving conflicting utility classes by keeping the last one in a small working example.', 'Demonstrate Common pattern: combining clsx + tailwind-merge into a cn() helper function in a small working example.']::text[], array['Submit a working tailwind-merge example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-frontend-v1-core-phase-03-m02-t01']::text[], '[]'::jsonb, 60, 'beginner', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m02-t03', 'zte-frontend-v1-core-phase-03-m02', 'CVA (Class Variance Authority)', array['Explain and apply null in CVA (Class Variance Authority).', 'Use CVA (Class Variance Authority) to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Defining a base class set plus variant definitions in a small working example.', 'Demonstrate variants, defaultVariants, compoundVariants configuration in a small working example.', 'Demonstrate Type-safe variant props when combined with TypeScript (VariantProps<>) in a small working example.', 'Demonstrate Why CVA exists — replacing manual conditional class logic for multi-axis variant components in a small working example.']::text[], array['Submit a working CVA (Class Variance Authority) example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-frontend-v1-core-phase-03-m02-t02']::text[], '[]'::jsonb, 240, 'beginner', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-03-m03', 'zte-frontend-v1-core-phase-03', 3, 'Component Libraries', 'Both libraries in this stage assume Tailwind (Stage 2\\) and the class-composition utilities (Stage 3\\) are already understood — shadcn/ui in particular is built directly from both.', 8, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m03-t01', 'zte-frontend-v1-core-phase-03-m03', 'Radix UI', array['Explain and apply null in Radix UI.', 'Use Radix UI to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Unstyled, accessible component primitives — what "headless" UI means in a small working example.', 'Demonstrate Compound component API pattern (ties back to Phase 02, Stage 1, Topic 5 — Component Design Patterns) in a small working example.', 'Demonstrate Built-in accessibility: focus management, keyboard navigation, ARIA attributes handled automatically in a small working example.', 'Demonstrate Common primitives: Dialog, DropdownMenu, Popover, Tooltip, Select, Tabs in a small working example.', 'Demonstrate Controlled vs uncontrolled usage of Radix primitives in a small working example.']::text[], array['Submit a working Radix UI example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array[]::text[], '[]'::jsonb, 480, 'beginner', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m03-t02', 'zte-frontend-v1-core-phase-03-m03', 'shadcn/ui', array['Explain and apply null in shadcn/ui.', 'Use shadcn/ui to complete a practical task in UI System & Styling.']::text[], array['Demonstrate The "copy, don''t install" philosophy — components live in your codebase, fully editable in a small working example.', 'Demonstrate CLI usage — adding components on demand in a small working example.', 'Demonstrate Anatomy of a shadcn component: Radix primitive + CVA variants + Tailwind classes in a small working example.', 'Demonstrate Customizing theme tokens (ties back to Stage 1, Topic 1 — CSS Custom Properties, which shadcn uses for its color system) in a small working example.', 'Demonstrate Composing shadcn components into larger patterns in a small working example.']::text[], array['Submit a working shadcn/ui example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-frontend-v1-core-phase-03-m03-t01']::text[], '[]'::jsonb, 540, 'beginner', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m03-t03', 'zte-frontend-v1-core-phase-03-m03', 'next-themes', array['Explain and apply null in next-themes.', 'Use next-themes to complete a practical task in UI System & Styling.']::text[], array['Demonstrate ThemeProvider setup in a Next.js app in a small working example.', 'Demonstrate System theme detection vs manual toggle in a small working example.', 'Demonstrate Avoiding flash-of-incorrect-theme on page load (script injection strategy) in a small working example.', 'Demonstrate useTheme hook for building a theme toggle UI in a small working example.']::text[], array['Submit a working next-themes example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-frontend-v1-core-phase-03-m03-t02']::text[], '[]'::jsonb, 120, 'beginner', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-03-m04', 'zte-frontend-v1-core-phase-03', 4, 'Forms & Validation', 'Forms are placed after component libraries (Stage 4\\) because real form UIs are typically built from shadcn/Radix inputs, not raw HTML elements — though the underlying form-state logic is library-agnostic.', 7, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m04-t01', 'zte-frontend-v1-core-phase-03-m04', 'react-hook-form', array['Explain and apply Core Concepts in react-hook-form.', 'Explain and apply Validation in react-hook-form.', 'Explain and apply Advanced Patterns in react-hook-form.']::text[], array['Demonstrate Uncontrolled-by-default philosophy (register() vs controlled useState-per-field) in a small working example.', 'Demonstrate useForm hook — register, handleSubmit, formState in a small working example.', 'Demonstrate Why uncontrolled inputs reduce re-renders compared to a useState-per-field approach (ties back to Phase 02''s performance hooks) in a small working example.', 'Demonstrate Built-in HTML validation rules (required, min, max, pattern) via register options in a small working example.', 'Demonstrate Custom validation functions in a small working example.']::text[], array['Submit a working react-hook-form example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array[]::text[], '[]'::jsonb, 840, 'beginner', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m04-t02', 'zte-frontend-v1-core-phase-03-m04', 'Zod (react-hook-form Integration)', array['Explain and apply null in Zod (react-hook-form Integration).', 'Use Zod (react-hook-form Integration) to complete a practical task in UI System & Styling.']::text[], array['Demonstrate @hookform/resolvers/zod — connecting a Zod schema as RHF''s validation source in a small working example.', 'Demonstrate Deriving TypeScript types from a Zod schema for full form type-safety (z.infer, tying back to Phase 01''s type system) in a small working example.', 'Demonstrate Schema reuse between client-side form validation and server-side validation (Server Actions, ties back to Phase 02, Stage 2, Topic 11) in a small working example.']::text[], array['Submit a working Zod (react-hook-form Integration) example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-frontend-v1-core-phase-03-m04-t01']::text[], '[]'::jsonb, 60, 'beginner', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-03-m05', 'zte-frontend-v1-core-phase-03', 5, 'General-Purpose Utilities', 'These three libraries are independent of styling and forms — placed after Stage 5 simply because they''re commonly reached for while building the form/data-display logic that comes right after this phase, not because of any real dependency.', 3.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
