insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m05-t03', 'zte-frontend-v1-core-phase-03-m05', 'nanoid', array['Explain and apply null in nanoid.', 'Use nanoid to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Generating compact, URL-safe unique IDs in a small working example.', 'Demonstrate nanoid vs uuid — size and performance tradeoffs in a small working example.', 'Demonstrate Common use: client-generated temporary IDs before a record is persisted (e.g. optimistic UI list items) in a small working example.']::text[], array['Submit a working nanoid example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-frontend-v1-core-phase-03-m05-t02']::text[], '[]'::jsonb, 60, 'beginner', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-03-m06', 'zte-frontend-v1-core-phase-03', 6, 'Design Tokens & Alternative Styling Systems', 'Placed last deliberately — both topics here are either an extension of concepts already covered (Style Dictionary formalizes what CSS Custom Properties \+ theming already introduced) or a full alternative to the Tailwind approach (vanilla-extract), most meaningful as a comparison once Tailwind is already second nature.', 6, 5) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m06-t01', 'zte-frontend-v1-core-phase-03-m06', 'Style Dictionary', array['Explain and apply null in Style Dictionary.', 'Use Style Dictionary to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Design tokens as a concept — single source of truth for colors, spacing, typography values in a small working example.', 'Demonstrate Token definition format (JSON/YAML) in a small working example.', 'Demonstrate Build transforms — generating CSS custom properties, Tailwind config, or platform-specific outputs (iOS/Android) from one token set in a small working example.', 'Demonstrate Where this fits in a design-system workflow (design tool exports → tokens → code) in a small working example.']::text[], array['Submit a working Style Dictionary example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'beginner', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-m06-t02', 'zte-frontend-v1-core-phase-03-m06', 'vanilla-extract', array['Explain and apply null in vanilla-extract.', 'Use vanilla-extract to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Zero-runtime philosophy — styles compiled to static CSS at build time, not generated at runtime like traditional CSS-in-JS in a small working example.', 'Demonstrate style() function and typed style objects in a small working example.', 'Demonstrate Theming via createTheme() / createThemeContract() — contrasted with Tailwind + CSS Custom Properties theming (Stage 4, Topic 11) in a small working example.', 'Demonstrate Sprinkles (atomic CSS utilities within vanilla-extract) as a Tailwind-like layer in a small working example.', 'Demonstrate When vanilla-extract is preferable to Tailwind: component-scoped complex styles, type-safe design tokens, teams wanting CSS-in-JS ergonomics without runtime cost in a small working example.']::text[], array['Submit a working vanilla-extract example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-frontend-v1-core-phase-03-m06-t01']::text[], '[]'::jsonb, 480, 'beginner', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
