insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-01', 'zte-frontend-v1-core-phase-03', 'Themeable Component Sandbox', 'A small component gallery (buttons, cards, alerts) fully re-themeable at runtime via CSS Custom Properties, with a light/dark and a "high contrast" theme. Domain: design systems.', array['Deliver the working outcome described in the Themeable Component Sandbox brief.', 'Use at least two skills from CSS Foundations (Beyond Phase 01''s CSS3 Basics) and Tailwind CSS (Utility-First Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Themeable Component Sandbox', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'CSS Foundations (Beyond Phase 01''s CSS3 Basics) and Tailwind CSS (Utility-First Foundation)']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-02', 'zte-frontend-v1-core-phase-03', 'Legacy CSS Layering Refactor', 'Take a deliberately messy, specificity-war-ridden stylesheet (provided or self-authored) and refactor it using @layer (reset, base, components, utilities, overrides) so cascade order becomes predictable and documented. Domain: engineering/refactoring. A small component library authored with strict BEM naming and CSS Modules for scoping, published as a usable style guide page (a mini Storybook-style catalog page built by hand) with documented naming conventions. Domain: design systems.', array['Deliver the working outcome described in the Legacy CSS Layering Refactor brief.', 'Use at least two skills from CSS Foundations (Beyond Phase 01''s CSS3 Basics) and Tailwind CSS (Utility-First Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Legacy CSS Layering Refactor', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'CSS Foundations (Beyond Phase 01''s CSS3 Basics) and Tailwind CSS (Utility-First Foundation)']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-03', 'zte-frontend-v1-core-phase-03', 'Pricing Page, Pixel-Faithful', 'Recreate a real SaaS pricing page layout using only Tailwind utilities, responsive at 3 breakpoints. Domain: SaaS marketing.', array['Deliver the working outcome described in the Pricing Page, Pixel-Faithful brief.', 'Use at least two skills from Tailwind CSS (Utility-First Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Pricing Page, Pixel-Faithful', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Tailwind CSS (Utility-First Foundation)']::text[], 'beginner', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-04', 'zte-frontend-v1-core-phase-03', 'Custom Tailwind Design Token Theme', 'Extend Tailwind’s config with a fully custom design token set (brand colors, spacing scale, typography scale) for a fictional client brand, then rebuild 5 components using only the custom tokens (no arbitrary values). Domain: agency/freelance work.', array['Deliver the working outcome described in the Custom Tailwind Design Token Theme brief.', 'Use at least two skills from Tailwind CSS (Utility-First Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Custom Tailwind Design Token Theme', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Tailwind CSS (Utility-First Foundation)']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-05', 'zte-frontend-v1-core-phase-03', 'Dashboard UI Kit, Utility-First', 'A full admin dashboard UI (nav, cards, tables, forms, charts placeholders) built at production polish level using only Tailwind, with a documented approach for avoiding class-name bloat (extracted components, not @apply-everything). Domain: SaaS/enterprise tooling.', array['Deliver the working outcome described in the Dashboard UI Kit, Utility-First brief.', 'Use at least two skills from Tailwind CSS (Utility-First Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Dashboard UI Kit, Utility-First', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Tailwind CSS (Utility-First Foundation)']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-06', 'zte-frontend-v1-core-phase-03', 'Conditional Class Playground', 'A small set of components (badge, alert, button) with multiple visual states driven entirely by clsx-based conditional logic. Domain: design systems.', array['Deliver the working outcome described in the Conditional Class Playground brief.', 'Use at least two skills from Class Composition Utilities.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Conditional Class Playground', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Class Composition Utilities']::text[], 'beginner', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-07', 'zte-frontend-v1-core-phase-03', 'Merge-Safe Themeable Button', 'A Button component that accepts a className override prop and correctly merges/overrides Tailwind classes using tailwind-merge (no visual bugs from conflicting utilities), tested against 10 tricky override cases.', array['Deliver the working outcome described in the Merge-Safe Themeable Button brief.', 'Use at least two skills from Class Composition Utilities.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Merge-Safe Themeable Button', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Class Composition Utilities']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-08', 'zte-frontend-v1-core-phase-03', 'CVA-Powered Component Library Core', 'Build 6 components (Button, Badge, Alert, Input, Card, Tag) using Class Variance Authority for variant/size/state management, with full TypeScript prop inference from the CVA config. Domain: design systems / component libraries.', array['Deliver the working outcome described in the CVA-Powered Component Library Core brief.', 'Use at least two skills from Class Composition Utilities.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CVA-Powered Component Library Core', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Class Composition Utilities']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-09', 'zte-frontend-v1-core-phase-03', 'Accessible Custom Select', 'Build a fully accessible custom dropdown/select using Radix UI primitives (keyboard nav, ARIA, focus trapping handled correctly) styled to match a custom brand, not default Radix look. Domain: accessibility engineering.', array['Deliver the working outcome described in the Accessible Custom Select brief.', 'Use at least two skills from Component Libraries.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Accessible Custom Select', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Component Libraries']::text[], 'intermediate', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-10', 'zte-frontend-v1-core-phase-03', 'shadcn/ui-Based Admin Starter', 'Assemble a small admin panel using shadcn/ui components (customized, not default theme) integrated with next-themes for dark mode, including a documented decision on which components were customized and why. Domain: SaaS/internal tools.', array['Deliver the working outcome described in the shadcn/ui-Based Admin Starter brief.', 'Use at least two skills from Component Libraries.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working shadcn/ui-Based Admin Starter', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Component Libraries']::text[], 'intermediate', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-11', 'zte-frontend-v1-core-phase-03', 'Multi-Brand Theming Demo', 'One codebase that can render 3 completely different visual brands (different logos, colors, radii, fonts) at runtime by swapping a theme provider — combining Radix primitives, next-themes, and CSS variables. Domain: white-label SaaS / multi-tenant products.', array['Deliver the working outcome described in the Multi-Brand Theming Demo brief.', 'Use at least two skills from Component Libraries.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Brand Theming Demo', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Component Libraries']::text[], 'advanced', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-12', 'zte-frontend-v1-core-phase-03', 'Schema-Driven Dynamic Form Builder', 'A form renderer that takes a Zod schema as input and dynamically renders the correct react-hook-form-powered fields (text, number, select, date) with validation derived entirely from the schema — no hardcoded field JSX per form. Domain: internal tooling / low-code platforms.', array['Deliver the working outcome described in the Schema-Driven Dynamic Form Builder brief.', 'Use at least two skills from Forms & Validation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Schema-Driven Dynamic Form Builder', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Forms & Validation']::text[], 'advanced', 11) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-13', 'zte-frontend-v1-core-phase-03', 'Event Countdown & Scheduling Widget', 'A small widget showing "time until" and formatted relative dates using date-fns, correctly handling timezones. Domain: events/scheduling.', array['Deliver the working outcome described in the Event Countdown & Scheduling Widget brief.', 'Use at least two skills from General-Purpose Utilities.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Event Countdown & Scheduling Widget', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'General-Purpose Utilities']::text[], 'beginner', 12) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-14', 'zte-frontend-v1-core-phase-03', 'Deduplicating Data Import Tool', 'A CSV import utility that uses lodash-es for deep merging/grouping/deduplication logic on messy imported records, plus nanoid for generating stable client-side temp IDs before server save. Domain: data tooling/back-office.', array['Deliver the working outcome described in the Deduplicating Data Import Tool brief.', 'Use at least two skills from General-Purpose Utilities.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Deduplicating Data Import Tool', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'General-Purpose Utilities']::text[], 'intermediate', 13) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-15', 'zte-frontend-v1-core-phase-03', 'Zero-Runtime Styled Component Library', 'Rebuild 4 components from Stage 3/4 using vanilla-extract instead of Tailwind/CVA, compare bundle output and runtime cost, and write a comparison report (DX, performance, type safety) between utility-first and zero-runtime CSS-in-TS approaches. Domain: performance engineering / design systems.', array['Deliver the working outcome described in the Zero-Runtime Styled Component Library brief.', 'Use at least two skills from Design Tokens & Alternative Styling Systems.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Zero-Runtime Styled Component Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'Design Tokens & Alternative Styling Systems']::text[], 'advanced', 14) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-16', 'zte-frontend-v1-core-phase-03', 'A Production-Grade, Multi-Brand Design System', 'Build a documented, installable component library (published as a local/private npm package) combining: a token pipeline (Style Dictionary) as the single source of truth, Tailwind and vanilla-extract both wired to consume those tokens, Radix-based accessible primitives styled with CVA, dark mode and multi-brand theming via next-themes/CSS variables, a schema-driven dynamic form system using react-hook-form \+ Zod, and a hand-built documentation/catalog page showing every component in every variant and theme. Domain: design systems / platform engineering. Why it matters: design systems are one of the highest-leverage, most portfolio-impressive artifacts a front-end engineer can build — this project proves you can architect one, not just consume one.', array['Deliver the working outcome described in the A Production-Grade, Multi-Brand Design System brief.', 'Use at least two skills from UI System & Styling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Production-Grade, Multi-Brand Design System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['UI System & Styling', 'engineering documentation']::text[], 'advanced', 15) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-03-project-17', 'zte-frontend-v1-core-phase-03', 'Team issue tracker', 'Help a small team triage work and understand project status.', array['Issue list, detail, filtering, and status transitions', 'Accessible forms and dialogs', 'Loading, empty, and error states', 'Role-appropriate visual hierarchy']::text[], array['Flow and component plan', 'Core issue interactions', 'API integration and resilient states', 'Accessibility and deployment']::text[], array['Deployed product', 'Interaction test suite', 'Design and architecture notes']::text[], array['React', 'state management', 'routing', 'accessibility', 'frontend', 'engineering delivery']::text[], 'intermediate', 16) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-04', 'zte-frontend-v1', id, '05', 'State, Data Fetching & Advanced React', 'Core', 'React Context was introduced generally in Phase 02\. This stage starts from where Context breaks down, then introduces the tool that fixes it.', 167, 4 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-04-m01', 'zte-frontend-v1-core-phase-04', 1, 'Client State: Context''s Limits, Then Zustand', 'React Context was introduced generally in Phase 02\. This stage starts from where Context breaks down, then introduces the tool that fixes it.', 7, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m01-t01', 'zte-frontend-v1-core-phase-04-m01', 'React Context — Revisited: Where It Breaks Down', array['Explain and apply null in React Context — Revisited: Where It Breaks Down.', 'Use React Context — Revisited: Where It Breaks Down to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Recap: Provider/Consumer, useContext in a small working example.', 'Demonstrate The re-render problem: every consumer re-renders on any context value change, even unrelated fields in a small working example.', 'Demonstrate Splitting contexts to limit blast radius — and why this gets unwieldy with many independent pieces of state in a small working example.', 'Demonstrate Context is not a state manager — it''s a dependency-injection mechanism; conflating the two causes the scaling problem in a small working example.', 'Demonstrate When Context alone is still the right tool (rarely-changing values: theme, auth session, locale) in a small working example.']::text[], array['Submit a working React Context — Revisited: Where It Breaks Down example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m01-t02', 'zte-frontend-v1-core-phase-04-m01', 'Zustand', array['Explain and apply Core API in Zustand.', 'Explain and apply Patterns in Zustand.', 'Explain and apply When to Reach for Zustand vs Context vs Server State (Stage 2) in Zustand.']::text[], array['Demonstrate create() — defining a store as a hook in a small working example.', 'Demonstrate Reading state via selectors (subscribing to only the slice you need) in a small working example.', 'Demonstrate Updating state — set() and functional updates in a small working example.', 'Demonstrate Why Zustand doesn''t cause the Context re-render problem: components only re-render when their selected slice changes in a small working example.', 'Demonstrate Store slicing — splitting a large store into composable slices in a small working example.']::text[], array['Submit a working Zustand example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m01-t01']::text[], '[]'::jsonb, 540, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-04-m02', 'zte-frontend-v1-core-phase-04', 2, 'Server State: TanStack Query, Then tRPC', 'Server state (data that lives on a server and is merely cached on the client) is a fundamentally different problem from client state (Stage 1\\) — it needs caching, revalidation, and request deduplication, which is what this stage''s tools provide.', 15, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m02-t01', 'zte-frontend-v1-core-phase-04-m02', 'TanStack Query v5', array['Explain and apply Core Concepts in TanStack Query v5.', 'Explain and apply Mutations in TanStack Query v5.', 'Explain and apply Advanced Patterns in TanStack Query v5.', 'Explain and apply DevTools in TanStack Query v5.']::text[], array['Demonstrate Server state vs client state — why they need different tools in a small working example.', 'Demonstrate Query keys — structuring them for correct caching and invalidation in a small working example.', 'Demonstrate useQuery — status states (pending, error, success), data/error/isLoading in a small working example.', 'Demonstrate staleTime vs gcTime (formerly cacheTime) — the two most misunderstood options in a small working example.', 'Demonstrate useMutation — mutate/mutateAsync, onSuccess/onError/onSettled callbacks in a small working example.']::text[], array['Submit a working TanStack Query v5 example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array[]::text[], '[]'::jsonb, 1380, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m02-t02', 'zte-frontend-v1-core-phase-04-m02', 'tRPC v11', array['Explain and apply Core Concepts in tRPC v11.', 'Explain and apply Client Integration in tRPC v11.', 'Explain and apply Advanced Patterns in tRPC v11.']::text[], array['Demonstrate End-to-end type safety — types flow from server router to client without code generation in a small working example.', 'Demonstrate Defining a router: procedures (query vs mutation), input validation (typically Zod, ties back to Phase 01/03) in a small working example.', 'Demonstrate Context (tRPC''s server-side request context, not to be confused with React Context from Stage 1) — auth, DB client injection in a small working example.', 'Demonstrate @trpc/react-query — tRPC''s hooks are TanStack Query hooks with typed inputs/outputs in a small working example.', 'Demonstrate trpc.useQuery / trpc.useMutation — same mental model as Topic 3, now fully typed in a small working example.']::text[], array['Submit a working tRPC v11 example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m02-t01']::text[], '[]'::jsonb, 1440, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-04-m03', 'zte-frontend-v1-core-phase-04', 3, 'State Machines', 'Conceptually independent of Stages 1–2, but placed after both because state machines are usually reached for once you''ve felt the pain of complex state logic that plain useState/Zustand/useReducer can''t cleanly express — that pain is easier to appreciate with Stage 1–2 experience already in hand.', 8, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m03-t01', 'zte-frontend-v1-core-phase-04-m03', 'XState v5', array['Explain and apply Core Concepts in XState v5.', 'Explain and apply Advanced Machine Features in XState v5.', 'Explain and apply React Integration in XState v5.']::text[], array['Demonstrate Finite state machines — states, events, transitions in a small working example.', 'Demonstrate Why explicit state machines prevent "impossible states" that boolean-flag-based state allows (e.g. isLoading && isError simultaneously) in a small working example.', 'Demonstrate createMachine — defining states and transitions declaratively in a small working example.', 'Demonstrate Actions (side effects on transition), guards (conditional transitions) in a small working example.', 'Demonstrate Context (XState''s own typed extended state, not to be confused with React Context from Stage 1 or tRPC Context from Stage 2) in a small working example.']::text[], array['Submit a working XState v5 example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array[]::text[], '[]'::jsonb, 1200, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m03-t02', 'zte-frontend-v1-core-phase-04-m03', 'Stately Studio', array['Explain and apply null in Stately Studio.', 'Use Stately Studio to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Visualizing machines defined in code in a small working example.', 'Demonstrate Editing machines visually and syncing back to code in a small working example.', 'Demonstrate Using it for design/engineering collaboration on complex flows in a small working example.']::text[], array['Submit a working Stately Studio example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m03-t01']::text[], '[]'::jsonb, 120, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-04-m04', 'zte-frontend-v1-core-phase-04', 4, 'Rendering & Resilience Primitives (Applied Depth)', 'React.lazy, Suspense, and createPortal were already introduced at a conceptual level in Phase 02, Stage 1\. This stage doesn''t re-teach the mechanics — it applies them at real-project depth, now that Stage 2''s data-fetching layer exists to make Suspense-for-data meaningful.', 6.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m04-t01', 'zte-frontend-v1-core-phase-04-m04', 'React.lazy — Applied', array['Explain and apply null in React.lazy — Applied.', 'Use React.lazy — Applied to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Route-level vs component-level code splitting decisions in a small working example.', 'Demonstrate Combining with Suspense fallback UI (Topic 8) for a real loading experience in a small working example.', 'Demonstrate Measuring the actual bundle-size impact of a lazy boundary in a small working example.']::text[], array['Submit a working React.lazy — Applied example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m04-t02', 'zte-frontend-v1-core-phase-04-m04', 'Suspense — For Data', array['Explain and apply null in Suspense — For Data.', 'Use Suspense — For Data to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate useSuspenseQuery — TanStack Query''s Suspense-integrated query hook in a small working example.', 'Demonstrate Suspense boundaries around data-dependent UI instead of manual isLoading checks in a small working example.', 'Demonstrate Waterfalls — why naive nested Suspense boundaries can serialize requests, and how to prevent it (parallel fetching, prefetching) in a small working example.', 'Demonstrate Combining with Error Boundaries (Topic 9) for the full loading/error/success triad in a small working example.']::text[], array['Submit a working Suspense — For Data example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m04-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m04-t03', 'zte-frontend-v1-core-phase-04-m04', 'react-error-boundary', array['Explain and apply null in react-error-boundary.', 'Use react-error-boundary to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate FallbackComponent / fallbackRender props in a small working example.', 'Demonstrate resetErrorBoundary — retry logic without a full page reload in a small working example.', 'Demonstrate Combining with TanStack Query''s error handling (Stage 2) for a full data-fetching error UI in a small working example.', 'Demonstrate Placement strategy: one boundary per independently-failing UI region, not one global boundary in a small working example.']::text[], array['Submit a working react-error-boundary example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m04-t02']::text[], '[]'::jsonb, 120, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m04-t04', 'zte-frontend-v1-core-phase-04-m04', 'ReactDOM.createPortal — Applied', array['Explain and apply null in ReactDOM.createPortal — Applied.', 'Use ReactDOM.createPortal — Applied to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Building a real modal system: portal target, focus trapping, scroll locking in a small working example.', 'Demonstrate Toast/notification system architecture using a Zustand store (Stage 1) to queue and dismiss toasts in a small working example.', 'Demonstrate Accessibility requirements for portal content (focus management, aria-modal, returning focus on close) in a small working example.']::text[], array['Submit a working ReactDOM.createPortal — Applied example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m04-t03']::text[], '[]'::jsonb, 60, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-04-m05', 'zte-frontend-v1-core-phase-04', 5, 'Browser Observation APIs', 'Independent of the state/data/rendering stages above — these are browser-native APIs for observing layout and viewport changes, placed here because their most common React use case (infinite scroll, responsive components) is more meaningful with the data-fetching layer (Stage 2\\) already available.', 4.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m05-t01', 'zte-frontend-v1-core-phase-04-m05', 'Intersection Observer', array['Explain and apply null in Intersection Observer.', 'Use Intersection Observer to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Observing when an element enters/exits the viewport in a small working example.', 'Demonstrate Threshold and rootMargin configuration in a small working example.', 'Demonstrate Common use: infinite scroll — triggering useInfiniteQuery''s fetchNextPage (Stage 2) when a sentinel element becomes visible in a small working example.', 'Demonstrate Common use: lazy-loading images/components on scroll into view in a small working example.', 'Demonstrate Wrapping in a custom hook (useIntersectionObserver) — ties back to Phase 02''s custom hook patterns in a small working example.']::text[], array['Submit a working Intersection Observer example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m05-t02', 'zte-frontend-v1-core-phase-04-m05', 'ResizeObserver', array['Explain and apply null in ResizeObserver.', 'Use ResizeObserver to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Observing element size changes without window resize listeners in a small working example.', 'Demonstrate Common use: responsive components that adapt to container size, not just viewport size (container queries'' JS-based precursor) in a small working example.', 'Demonstrate Performance considerations — avoiding observer callback loops in a small working example.']::text[], array['Submit a working ResizeObserver example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m05-t01']::text[], '[]'::jsonb, 120, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-04-m06', 'zte-frontend-v1-core-phase-04', 6, 'Virtualization & Profiling (Capstone)', 'Both topics require a real, data-populated, multi-feature app to be meaningful — placed last because they''re applied to everything built in Stages 1–5, not new concepts in isolation.', 6, 5) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m06-t01', 'zte-frontend-v1-core-phase-04-m06', 'React DevTools Profiler', array['Explain and apply null in React DevTools Profiler.', 'Use React DevTools Profiler to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Recording a profiling session in a small working example.', 'Demonstrate Flamegraph vs ranked chart views in a small working example.', 'Demonstrate Identifying unnecessary re-renders — tying back to Phase 02''s memoization concepts (React.memo, useMemo, useCallback) in a small working example.', 'Demonstrate Committed vs rendered — understanding what the Profiler actually measures in a small working example.', 'Demonstrate Using profiling data to decide where memoization, Zustand selector-splitting (Stage 1), or virtualization (Topic 13) would actually help, vs premature optimization in a small working example.']::text[], array['Submit a working React DevTools Profiler example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-04-m06-t02', 'zte-frontend-v1-core-phase-04-m06', 'TanStack Virtual', array['Explain and apply null in TanStack Virtual.', 'Use TanStack Virtual to complete a practical task in State, Data Fetching & Advanced React.']::text[], array['Demonstrate Why virtualization exists — rendering only visible rows for large lists instead of the entire dataset in a small working example.', 'Demonstrate useVirtualizer — core API, item size estimation (fixed vs dynamic) in a small working example.', 'Demonstrate Combining with useInfiniteQuery (Stage 2) for infinite-scroll virtualized lists in a small working example.', 'Demonstrate Overscan configuration — rendering a buffer beyond the visible area for smoother scrolling in a small working example.']::text[], array['Submit a working TanStack Virtual example and explain the key decisions.', 'Record a short review showing how the example satisfies the State, Data Fetching & Advanced React learning goal.']::text[], array['zte-frontend-v1-core-phase-04-m06-t01']::text[], '[]'::jsonb, 300, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
