insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-m06-t03', 'zte-frontend-v1-core-phase-05-m06', 'Deployment, monitoring, and incident response', array['Use environment configuration and staged releases', 'Interpret client errors and recover safely']::text[], array['Deploy preview and production release', 'Simulate a failed release and rollback']::text[], array['Runbook, health signals, and verified rollback']::text[], array['zte-frontend-v1-core-phase-05-m06-t02']::text[], '[]'::jsonb, 210, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-01', 'zte-frontend-v1-core-phase-05', 'Raw Node HTTP File Server', 'A file server built with zero frameworks using only the Node.js http module — routing, static file serving, and JSON responses hand-rolled — to understand what Express actually abstracts away. Domain: systems/infra fundamentals.', array['Deliver the working outcome described in the Raw Node HTTP File Server brief.', 'Use at least two skills from Server Runtime & Framework.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Raw Node HTTP File Server', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Server Runtime & Framework']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-02', 'zte-frontend-v1-core-phase-05', 'Bookstore REST API with Express', 'A clean Express-based REST API (CRUD for books, authors, categories) with proper middleware layering, route organization, and centralized error handling. Domain: retail/inventory.', array['Deliver the working outcome described in the Bookstore REST API with Express brief.', 'Use at least two skills from Server Runtime & Framework.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Bookstore REST API with Express', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Server Runtime & Framework']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-03', 'zte-frontend-v1-core-phase-05', 'Pluggable Middleware Pipeline Framework', 'Build a tiny Express-compatible middleware pipeline from scratch (your own mini-framework mimicking app.use()/next()) to fully understand the middleware pattern, then reimplement one real feature (logging) both in your framework and in real Express side-by-side. Domain: framework/systems engineering.', array['Deliver the working outcome described in the Pluggable Middleware Pipeline Framework brief.', 'Use at least two skills from Server Runtime & Framework.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Pluggable Middleware Pipeline Framework', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Server Runtime & Framework']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-04', 'zte-frontend-v1-core-phase-05', 'Public API with Rate Limiting & CORS Policy', 'A small public-facing API (e.g., a quotes/jokes API) with a documented CORS policy, express-rate-limit tuned per endpoint tier (free vs authenticated), and async error handling via express-async-errors so no unhandled rejection crashes the server. Domain: public API products. A comment/review submission API where all HTML input is sanitized server-side with DOMPurify (server-side variant) before storage, with a deliberate XSS payload test suite proving the sanitization actually works. Domain: content platforms / trust & safety.', array['Deliver the working outcome described in the Public API with Rate Limiting & CORS Policy brief.', 'Use at least two skills from API Design & Hardening and Testing the API.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Public API with Rate Limiting & CORS Policy', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'API Design & Hardening and Testing the API']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-05', 'zte-frontend-v1-core-phase-05', 'Hardened Production API Checklist Implementation', 'Take an existing API and harden it end-to-end: Helmet.js security headers, response compression, tuned CORS, rate limiting by IP and by API key, and a written security checklist with before/after header comparison (via curl -I). Domain: security engineering / SRE.', array['Deliver the working outcome described in the Hardened Production API Checklist Implementation brief.', 'Use at least two skills from API Design & Hardening and Testing the API.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Hardened Production API Checklist Implementation', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'API Design & Hardening and Testing the API']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-06', 'zte-frontend-v1-core-phase-05', 'Full Supertest Suite for the Bookstore API', 'A comprehensive Supertest test suite for the Stage 1 Bookstore API covering happy paths, validation failures, auth-protected routes, and edge cases (empty body, malformed JSON, huge payloads). Domain: QA engineering.', array['Deliver the working outcome described in the Full Supertest Suite for the Bookstore API brief.', 'Use at least two skills from Testing the API.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Full Supertest Suite for the Bookstore API', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Testing the API']::text[], 'intermediate', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-07', 'zte-frontend-v1-core-phase-05', 'Normalized Multi-Tenant Schema Design', 'Design and implement (via Prisma migrations) a normalized PostgreSQL schema for a multi-tenant SaaS (organizations, users, projects, roles) with correct foreign keys and cascade rules. Domain: B2B SaaS.', array['Deliver the working outcome described in the Normalized Multi-Tenant Schema Design brief.', 'Use at least two skills from Database Layer.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Normalized Multi-Tenant Schema Design', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Database Layer']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-08', 'zte-frontend-v1-core-phase-05', 'Serverless Postgres Comparison Project', 'Deploy the same schema/API to both Supabase and Neon, documenting connection pooling differences, cold-start behavior, and pricing/scaling tradeoffs from hands-on testing. Domain: infrastructure decision-making.', array['Deliver the working outcome described in the Serverless Postgres Comparison Project brief.', 'Use at least two skills from Database Layer.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Serverless Postgres Comparison Project', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Database Layer']::text[], 'intermediate', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-09', 'zte-frontend-v1-core-phase-05', 'Slow Query Detective Agency', 'Given a seeded database with 1M+ rows and a set of deliberately slow endpoints, use EXPLAIN ANALYZE to diagnose each bottleneck, apply the correct fix (index, query restructure, N+1 fix via Prisma include), and document before/after query plans and timings. Domain: database performance engineering.', array['Deliver the working outcome described in the Slow Query Detective Agency brief.', 'Use at least two skills from Database Layer.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Slow Query Detective Agency', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Database Layer']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-10', 'zte-frontend-v1-core-phase-05', 'From-Scratch Password Auth', 'A signup/login system built without an auth-as-a-service library: bcrypt for hashing, JWT access tokens, httpOnly refresh-token cookies with SameSite=Lax, and a documented token-rotation strategy. Domain: security engineering / any product needing custom auth. A small service that receives webhooks (simulate a payment provider) and verifies HMAC-SHA256 signatures before trusting the payload, including a deliberate test proving a tampered payload is rejected. Domain: payments/fintech infrastructure.', array['Deliver the working outcome described in the From-Scratch Password Auth brief.', 'Use at least two skills from Authentication & Token Security.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working From-Scratch Password Auth', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Authentication & Token Security']::text[], 'intermediate', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-11', 'zte-frontend-v1-core-phase-05', 'jose-Based Multi-Audience Token System', 'A token system using the jose library supporting multiple audiences (web client, mobile client, internal service-to-service) with different expiry/claims per audience, and a key-rotation mechanism (JWKS-style) so old tokens gracefully expire during a key rotation. Domain: platform/identity engineering.', array['Deliver the working outcome described in the jose-Based Multi-Audience Token System brief.', 'Use at least two skills from Authentication & Token Security.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working jose-Based Multi-Audience Token System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'Authentication & Token Security']::text[], 'advanced', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-12', 'zte-frontend-v1-core-phase-05', 'A Secure Multi-Tenant Expense-Approval API', 'A production-grade backend for a B2B expense-approval SaaS: hand-rolled Express architecture with layered middleware, a normalized multi-tenant PostgreSQL schema (via Prisma) supporting organizations/roles/approval chains, hardened with Helmet/CORS/rate-limiting/sanitization, a from-scratch JWT \+ httpOnly refresh-token auth system with rotation, HMAC-signed webhook endpoints for a simulated payment provider, comprehensive Supertest coverage (happy paths, auth failures, tampered webhooks), and a documented EXPLAIN ANALYZE-driven performance pass on the top 3 slowest endpoints under seeded load. Domain: fintech / B2B SaaS. Why it matters: this is a genuinely defensible "I built a secure backend" portfolio piece — covering real auth, real multi-tenancy, real hardening, not a tutorial CRUD app.', array['Deliver the working outcome described in the A Secure Multi-Tenant Expense-Approval API brief.', 'Use at least two skills from Backend + Database + Auth.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Secure Multi-Tenant Expense-Approval API', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Backend + Database + Auth', 'engineering documentation']::text[], 'advanced', 11) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-05-project-13', 'zte-frontend-v1-core-phase-05', 'Production-grade frontend product', 'Deliver a polished product interface for a real workflow with measurable user outcomes.', array['Responsive and accessible critical journeys', 'Typed API boundary and robust error states', 'Automated behavioral tests', 'Performance budget and privacy-aware analytics']::text[], array['User research and interaction model', 'Architecture and implementation', 'Test and accessibility gate', 'Performance review and launch']::text[], array['Live product', 'Test/quality report', 'Performance comparison', 'Incident and rollback notes']::text[], array['frontend architecture', 'testing', 'accessibility', 'performance', 'security', 'frontend', 'engineering delivery']::text[], 'advanced', 12) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-06', 'zte-frontend-v1', id, '07', 'Testing + CI/CD + Deployment', 'Core', 'The foundation of the testing pyramid. Requires a real app with components and logic (Phases 01–05) to have anything meaningful to test.', 155, 6 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-06-m01', 'zte-frontend-v1-core-phase-06', 1, 'Unit & Component Testing and End-to-End Testing and Continuous Integration', 'The foundation of the testing pyramid. Requires a real app with components and logic (Phases 01–05) to have anything meaningful to test.', 15.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t01', 'zte-frontend-v1-core-phase-06-m01', 'Vitest', array['Explain and apply null in Vitest.', 'Use Vitest to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate Test file conventions and running tests (vitest run, watch mode) in a small working example.', 'Demonstrate describe/it/test, expect assertions in a small working example.', 'Demonstrate Setup/teardown: beforeEach, afterEach, beforeAll, afterAll in a small working example.', 'Demonstrate Mocking: vi.fn(), vi.mock(), spying on functions in a small working example.', 'Demonstrate Vitest vs Jest — why Vitest is the modern default for Vite/Next.js projects (native ESM, faster, shared config with Vite) in a small working example.']::text[], array['Submit a working Vitest example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array[]::text[], '[]'::jsonb, 540, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t02', 'zte-frontend-v1-core-phase-06-m01', 'React Testing Library', array['Explain and apply null in React Testing Library.', 'Use React Testing Library to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate render() — mounting a component in a test environment in a small working example.', 'Demonstrate Query methods: getBy, queryBy, findBy, and their variants (ByRole, ByText, ByLabelText) in a small working example.', 'Demonstrate Why RTL queries prioritize accessibility-based queries (ByRole) over implementation details (class names, test IDs) in a small working example.', 'Demonstrate Testing philosophy: "test behavior, not implementation" — what this actually means in practice in a small working example.', 'Demonstrate screen object vs destructured render() queries in a small working example.']::text[], array['Submit a working React Testing Library example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-frontend-v1-core-phase-06-m01-t01']::text[], '[]'::jsonb, 720, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t03', 'zte-frontend-v1-core-phase-06-m01', '@testing-library/user-event', array['Explain and apply null in @testing-library/user-event.', 'Use @testing-library/user-event to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate userEvent.click(), .type(), .selectOptions() and how they differ from fireEvent (simulating real browser event sequences, not just dispatching one event) in a small working example.', 'Demonstrate Async nature of user-event — why interactions must be awaited in a small working example.', 'Demonstrate Testing forms end-to-end within a component test (ties back to Phase 02''s forms, Phase 03''s react-hook-form) in a small working example.']::text[], array['Submit a working @testing-library/user-event example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-frontend-v1-core-phase-06-m01-t02']::text[], '[]'::jsonb, 120, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t04', 'zte-frontend-v1-core-phase-06-m01', 'MSW (Mock Service Worker)', array['Explain and apply null in MSW (Mock Service Worker).', 'Use MSW (Mock Service Worker) to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate Intercepting requests at the network level (service worker in browser, request interception in Node for tests) in a small working example.', 'Demonstrate Defining request handlers — mocking REST and GraphQL responses in a small working example.', 'Demonstrate Why MSW is preferred over mocking fetch/axios directly — tests exercise real request code paths in a small working example.', 'Demonstrate Using MSW in both tests and local development (mocking a backend that isn''t ready yet) in a small working example.']::text[], array['Submit a working MSW (Mock Service Worker) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-frontend-v1-core-phase-06-m01-t03']::text[], '[]'::jsonb, 300, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t05', 'zte-frontend-v1-core-phase-06-m01', 'v8 Coverage', array['Explain and apply null in v8 Coverage.', 'Use v8 Coverage to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate Coverage metrics: statements, branches, functions, lines in a small working example.', 'Demonstrate Configuring Vitest''s built-in v8 coverage provider in a small working example.', 'Demonstrate Reading a coverage report — where gaps actually matter vs where 100% coverage is a vanity metric in a small working example.', 'Demonstrate Coverage thresholds — failing CI if coverage drops below a set percentage (bridges to Stage 3) in a small working example.']::text[], array['Submit a working v8 Coverage example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-frontend-v1-core-phase-06-m01-t04']::text[], '[]'::jsonb, 60, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t06', 'zte-frontend-v1-core-phase-06-m01', 'Codecov', array['Explain and apply null in Codecov.', 'Use Codecov to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate Uploading coverage reports from CI (bridges to Stage 3''s GitHub Actions) in a small working example.', 'Demonstrate Coverage badges (precursor to the CI badge work in Stage 5) in a small working example.', 'Demonstrate Coverage diffs on pull requests — seeing whether a PR increases or decreases coverage in a small working example.']::text[], array['Submit a working Codecov example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-frontend-v1-core-phase-06-m01-t05']::text[], '[]'::jsonb, 60, 'intermediate', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t07', 'zte-frontend-v1-core-phase-06-m01', 'Playwright', array['Explain and apply Core Concepts in Playwright.', 'Explain and apply Writing Real E2E Flows in Playwright.', 'Explain and apply Tooling in Playwright.']::text[], array['Demonstrate Browser automation model — Playwright drives real browsers (Chromium, Firefox, WebKit) in a small working example.', 'Demonstrate page.goto(), locators, and Playwright''s auto-waiting (vs manual waits/sleeps) in a small working example.', 'Demonstrate Assertions with expect() in a Playwright context in a small working example.', 'Demonstrate Testing full user journeys: signup → login → core app action (ties directly to the JWT auth flow from Phase 05) in a small working example.', 'Demonstrate Handling authentication state across tests (storageState, reusing a logged-in session) in a small working example.']::text[], array['Submit a working Playwright example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-frontend-v1-core-phase-06-m01-t06']::text[], '[]'::jsonb, 1080, 'intermediate', 6) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m01-t08', 'zte-frontend-v1-core-phase-06-m01', 'GitHub Actions', array['Explain and apply Workflow Fundamentals in GitHub Actions.', 'Explain and apply Building a Real CI Pipeline in GitHub Actions.', 'Explain and apply Secrets & Environments in GitHub Actions.']::text[], array['Demonstrate Workflow YAML structure — on, jobs, steps in a small working example.', 'Demonstrate Triggers: push, pull_request, schedule, workflow_dispatch in a small working example.', 'Demonstrate Runners — GitHub-hosted vs self-hosted (conceptual) in a small working example.', 'Demonstrate Actions marketplace — using pre-built actions (checkout, setup-node) in a small working example.', 'Demonstrate Running Vitest (Stage 1) and Playwright (Stage 2) in CI in a small working example.']::text[], array['Submit a working GitHub Actions example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-frontend-v1-core-phase-06-m01-t07']::text[], '[]'::jsonb, 960, 'intermediate', 7) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-06-m02', 'zte-frontend-v1-core-phase-06', 2, 'Containerization', 'Independent of testing/CI conceptually, but placed here because Docker images are what CI will build and what deployment (Stage 5\\) will run — this stage sits at the intersection.', 18, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06-m02-t01', 'zte-frontend-v1-core-phase-06-m02', 'Docker', array['Explain and apply Core Concepts in Docker.', 'Explain and apply Building for a Real App in Docker.', 'Explain and apply Running Containers in Docker.']::text[], array['Demonstrate Images vs containers — the class/instance analogy in a small working example.', 'Demonstrate Dockerfile syntax: FROM, WORKDIR, COPY, RUN, CMD/ENTRYPOINT in a small working example.', 'Demonstrate Layers and layer caching — why instruction order in a Dockerfile affects build speed in a small working example.', 'Demonstrate Multi-stage builds — separating build dependencies from the final runtime image in a small working example.', 'Demonstrate Dockerizing a Next.js app — the standalone output mode and its Dockerfile implications in a small working example.']::text[], array['Submit a working Docker example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array[]::text[], '[]'::jsonb, 1500, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
