insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-m04-t01', 'zte-frontend-v1-core-phase-06b-m04', 'FlatList Performance + Virtualization', array['Explain and apply null in FlatList Performance + Virtualization.', 'Use FlatList Performance + Virtualization to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate getItemLayout for fixed-height items — skipping expensive layout measurement in a small working example.', 'Demonstrate keyExtractor and why stable keys matter as much here as in web React (Phase 02) in a small working example.', 'Demonstrate windowSize, initialNumToRender, maxToRenderPerBatch — tuning virtualization aggressiveness in a small working example.', 'Demonstrate When to reach for a dedicated virtualization library vs FlatList''s built-in behavior in a small working example.']::text[], array['Submit a working FlatList Performance + Virtualization example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-m04-t02', 'zte-frontend-v1-core-phase-06b-m04', 'Hermes Engine', array['Explain and apply null in Hermes Engine.', 'Use Hermes Engine to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate What Hermes is — a JS engine built specifically for React Native (vs JavaScriptCore) in a small working example.', 'Demonstrate Bytecode precompilation — why this improves app startup time in a small working example.', 'Demonstrate Enabling/verifying Hermes is active in a project in a small working example.']::text[], array['Submit a working Hermes Engine example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-frontend-v1-core-phase-06b-m04-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-m04-t03', 'zte-frontend-v1-core-phase-06b-m04', 'New Architecture (Fabric + TurboModules)', array['Explain and apply null in New Architecture (Fabric + TurboModules).', 'Use New Architecture (Fabric + TurboModules) to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate The old bridge architecture and its performance limitations (async, serialized JSON messaging) in a small working example.', 'Demonstrate Fabric — the new rendering system, enabling synchronous layout measurement in a small working example.', 'Demonstrate TurboModules — lazy-loaded native modules with direct JS-to-native calls, replacing the bridge in a small working example.', 'Demonstrate Practical implication: most apps don''t need to think about this directly, but library compatibility increasingly assumes it in a small working example.']::text[], array['Submit a working New Architecture (Fabric + TurboModules) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-frontend-v1-core-phase-06b-m04-t02']::text[], '[]'::jsonb, 60, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-06b-m05', 'zte-frontend-v1-core-phase-06b', 5, 'Shipping', 'Deliberately last. Requires a working, tested app (Stages 1–4) and EAS Build (Stage 1, Topic 2\\) as the build pipeline that makes submission possible.', 8, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-m05-t01', 'zte-frontend-v1-core-phase-06b-m05', 'App Store + Play Store Submission', array['Explain and apply Preparing for Submission in App Store + Play Store Submission.', 'Explain and apply Submission Process in App Store + Play Store Submission.']::text[], array['Demonstrate App signing — certificates and provisioning profiles (iOS), keystores (Android) in a small working example.', 'Demonstrate App Store Connect setup, Google Play Console setup in a small working example.', 'Demonstrate Required assets: icons, screenshots, privacy policy, app description in a small working example.', 'Demonstrate Building a production binary with EAS Build (Stage 1, Topic 2) in a small working example.', 'Demonstrate Submitting via EAS Submit or manual upload in a small working example.']::text[], array['Submit a working App Store + Play Store Submission example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-m05-t02', 'zte-frontend-v1-core-phase-06b-m05', 'EAS Update (OTA Updates)', array['Explain and apply null in EAS Update (OTA Updates).', 'Use EAS Update (OTA Updates) to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate What EAS Update enables — pushing JS/asset changes without a full app store review cycle in a small working example.', 'Demonstrate What CANNOT be updated OTA — native code changes still require a full resubmission in a small working example.', 'Demonstrate Update channels — staging vs production update tracks in a small working example.', 'Demonstrate Rollback strategy if a bad update ships in a small working example.']::text[], array['Submit a working EAS Update (OTA Updates) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-frontend-v1-core-phase-06b-m05-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-01', 'zte-frontend-v1-core-phase-06b', 'Cross-Platform Habit Tracker', 'Rebuild Phase 2’s habit tracker as a React Native + Expo app, documenting layout differences (Flexbox defaults differ from web) and navigation using React Navigation (stack + tabs). Domain: personal wellness / mobile.', array['Deliver the working outcome described in the Cross-Platform Habit Tracker brief.', 'Use at least two skills from React Native Foundation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cross-Platform Habit Tracker', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'React Native Foundation']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-02', 'zte-frontend-v1-core-phase-06b', 'Recipe Browser with Deep Linking', 'A recipe browsing app with nested navigation (stack inside tabs), deep linking support (opening a specific recipe from a shared URL), and platform-aware layout adjustments for notches/safe areas. Domain: lifestyle/food.', array['Deliver the working outcome described in the Recipe Browser with Deep Linking brief.', 'Use at least two skills from React Native Foundation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Recipe Browser with Deep Linking', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'React Native Foundation']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-03', 'zte-frontend-v1-core-phase-06b', 'EAS-Built Multi-Environment App', 'An app configured with separate dev/staging/production build profiles via EAS Build, each pointing to a different API environment, with a documented build-and-distribute workflow for internal testers. Domain: mobile release engineering.', array['Deliver the working outcome described in the EAS-Built Multi-Environment App brief.', 'Use at least two skills from React Native Foundation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working EAS-Built Multi-Environment App', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'React Native Foundation']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-04', 'zte-frontend-v1-core-phase-06b', 'Offline-First Grocery List', 'A grocery list app that works fully offline using AsyncStorage, queues changes made offline, and syncs to a backend when connectivity returns, with conflict resolution for simultaneous edits. Domain: productivity / offline-first apps. A mobile login flow storing tokens in expo-secure-store (not AsyncStorage) with biometric-gated access to sensitive actions, and a documented threat-model comparison of AsyncStorage vs. secure-store. Domain: mobile security.', array['Deliver the working outcome described in the Offline-First Grocery List brief.', 'Use at least two skills from Storage & Secure Token Handling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Offline-First Grocery List', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Storage & Secure Token Handling']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-05', 'zte-frontend-v1-core-phase-06b', 'Receipt Scanner Utility', 'An app using the camera API to photograph receipts, request the correct permissions gracefully (with a fallback UI if denied), and save images locally. Domain: personal finance / utility apps. A reminders app sending real push notifications (via Expo push service) with platform-specific permission flows for iOS vs Android documented and handled distinctly. Domain: productivity.', array['Deliver the working outcome described in the Receipt Scanner Utility brief.', 'Use at least two skills from Native Device Capabilities.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Receipt Scanner Utility', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Native Device Capabilities']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-06', 'zte-frontend-v1-core-phase-06b', '10,000-Item Contact List', 'A contacts app rendering a very large list using FlatList performance best practices (getItemLayout, windowing tuning) profiled before/after optimization. Domain: productivity / performance engineering.', array['Deliver the working outcome described in the 10,000-Item Contact List brief.', 'Use at least two skills from Performance & Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working 10,000-Item Contact List', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Performance & Internals']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-07', 'zte-frontend-v1-core-phase-06b', 'Hermes vs JSC Benchmark Report', 'Build a CPU-intensive screen (e.g., client-side image filtering) and benchmark its performance under the Hermes engine vs JSC, documenting startup time and runtime differences with real numbers. Domain: mobile performance engineering.', array['Deliver the working outcome described in the Hermes vs JSC Benchmark Report brief.', 'Use at least two skills from Performance & Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Hermes vs JSC Benchmark Report', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Performance & Internals']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-08', 'zte-frontend-v1-core-phase-06b', 'Zero-Downtime OTA Update Demo', 'Ship a bug fix to a live-installed app using EAS Update (over-the-air) without requiring users to redownload from the store, with a before/after demonstration and a documented rollback plan if the OTA update itself is broken. Domain: mobile release engineering.', array['Deliver the working outcome described in the Zero-Downtime OTA Update Demo brief.', 'Use at least two skills from Shipping.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Zero-Downtime OTA Update Demo', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Shipping']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-06b-project-09', 'zte-frontend-v1-core-phase-06b', 'An Offline-First Field Reporting App', 'A mobile app for field workers (e.g., inspectors, delivery drivers) who often lack connectivity: photo capture with camera permissions handled gracefully, offline-first data entry via AsyncStorage with a sync queue and conflict resolution on reconnect, secure token storage via expo-secure-store, push notifications for assignment updates, a FlatList-based large history view tuned for performance, multi-environment EAS build profiles, and a full store-submission-ready asset package plus at least one OTA update shipped to a test build. Domain: field service / logistics mobile tooling. Why it matters: offline-first, secure, store-ready mobile apps are a distinct and valuable skill set from web development — this proves end-to-end mobile shipping competence.', array['Deliver the working outcome described in the An Offline-First Field Reporting App brief.', 'Use at least two skills from React Native (Mobile).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working An Offline-First Field Reporting App', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'engineering documentation']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-07', 'zte-frontend-v1', id, '09', 'API Documentation & Developer Tooling', 'Core', 'Requires a real API to hit (Phase 05\\) — these tools exist to inspect, test, and debug HTTP requests/responses by hand, before any documentation layer is added on top.', 71, 8 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-07-m01', 'zte-frontend-v1-core-phase-07', 1, 'Manual HTTP Tooling', 'Requires a real API to hit (Phase 05\\) — these tools exist to inspect, test, and debug HTTP requests/responses by hand, before any documentation layer is added on top.', 6, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-m01-t01', 'zte-frontend-v1-core-phase-07-m01', 'Postman', array['Explain and apply null in Postman.', 'Use Postman to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Building and sending requests — the GUI equivalent of curl''s flags in a small working example.', 'Demonstrate Collections — organizing related requests together in a small working example.', 'Demonstrate Environments and variables — swapping base URLs/tokens between dev/staging/prod without editing every request in a small working example.', 'Demonstrate Scripting: pre-request scripts and tests (JavaScript) for automated checks on responses in a small working example.', 'Demonstrate Exporting a Postman collection — this is the literal artifact Exit B''s checklist wants linked in your README in a small working example.']::text[], array['Submit a working Postman example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-m01-t02', 'zte-frontend-v1-core-phase-07-m01', 'Insomnia', array['Explain and apply null in Insomnia.', 'Use Insomnia to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Core workflow parity with Postman — requests, environments, collections (called "workspaces") in a small working example.', 'Demonstrate Where Insomnia differs: simpler interface, native GraphQL support (foreshadows Stage 3) in a small working example.', 'Demonstrate When to reach for Insomnia over Postman — personal/lightweight use vs Postman''s team-collaboration features in a small working example.']::text[], array['Submit a working Insomnia example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-frontend-v1-core-phase-07-m01-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-m01-t03', 'zte-frontend-v1-core-phase-07-m01', 'curl', array['Explain and apply null in curl.', 'Use curl to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Basic syntax — curl <url>, -X for method, -H for headers, -d for body in a small working example.', 'Demonstrate Sending JSON payloads (-H "Content-Type: application/json" -d ''{...}'') in a small working example.', 'Demonstrate Inspecting response headers (-i, -I) and verbose output (-v) for debugging in a small working example.', 'Demonstrate Authentication — sending a Bearer token (ties back to Phase 05''s JWT), Basic auth in a small working example.', 'Demonstrate Saving/loading cookies (-c, -b) — relevant given Phase 05''s httpOnly cookie auth flow in a small working example.']::text[], array['Submit a working curl example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-frontend-v1-core-phase-07-m01-t02']::text[], '[]'::jsonb, 180, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-07-m02', 'zte-frontend-v1-core-phase-07', 2, 'API Documentation and GraphQL (Alternative API Paradigm)', 'Requires a real, stable API (Phase 05\\) and familiarity with inspecting requests/responses (Stage 1\\) — you can''t document an API accurately without having manually explored its behavior first.', 9, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-m02-t01', 'zte-frontend-v1-core-phase-07-m02', 'OpenAPI 3.0', array['Explain and apply Specification Fundamentals in OpenAPI 3.0.', 'Explain and apply Writing a Real Spec in OpenAPI 3.0.']::text[], array['Demonstrate The OpenAPI spec as a language-agnostic contract for describing a REST API in a small working example.', 'Demonstrate Structure: paths, operations, parameters, requestBody, responses in a small working example.', 'Demonstrate Schema objects — describing request/response shapes (conceptually parallel to the Zod schemas from Phases 01/03/05) in a small working example.', 'Demonstrate Reusable components — $ref for shared schemas, parameters, responses in a small working example.', 'Demonstrate Documenting authentication (JWT Bearer scheme, ties to Phase 05) in a small working example.']::text[], array['Submit a working OpenAPI 3.0 example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array[]::text[], '[]'::jsonb, 720, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-m02-t02', 'zte-frontend-v1-core-phase-07-m02', 'Swagger UI', array['Explain and apply null in Swagger UI.', 'Use Swagger UI to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Serving Swagger UI from your API (as a route, e.g. /docs) in a small working example.', 'Demonstrate Interactive "Try it out" — making real requests from the docs page itself in a small working example.', 'Demonstrate Why a live Swagger UI link (not a screenshot) is what Exit B''s checklist specifically wants in your portfolio in a small working example.', 'Demonstrate Customizing Swagger UI branding/appearance (minor, but relevant for portfolio polish) in a small working example.']::text[], array['Submit a working Swagger UI example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-frontend-v1-core-phase-07-m02-t01']::text[], '[]'::jsonb, 240, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-m02-t03', 'zte-frontend-v1-core-phase-07-m02', 'Mermaid', array['Explain and apply null in Mermaid.', 'Use Mermaid to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Mermaid syntax basics — flowcharts, sequence diagrams, ER diagrams in a small working example.', 'Demonstrate Sequence diagrams for documenting an auth flow (login → JWT issuance → protected route, ties to Phase 05) in a small working example.', 'Demonstrate ER diagrams for documenting a database schema (ties to Phase 05''s PostgreSQL/Prisma schema) in a small working example.', 'Demonstrate Rendering Mermaid directly in GitHub READMEs — no external tooling needed in a small working example.']::text[], array['Submit a working Mermaid example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-frontend-v1-core-phase-07-m02-t02']::text[], '[]'::jsonb, 120, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-m02-t04', 'zte-frontend-v1-core-phase-07-m02', 'GraphQL', array['Explain and apply Core Concepts in GraphQL.', 'Explain and apply Building a GraphQL API in GraphQL.', 'Explain and apply Client-Side GraphQL in GraphQL.', 'Explain and apply REST vs GraphQL — The Interview-Ready Comparison in GraphQL.']::text[], array['Demonstrate Single endpoint, client-specified queries — the central contrast with REST''s multiple resource endpoints in a small working example.', 'Demonstrate Schema Definition Language (SDL) — types, queries, mutations, resolvers in a small working example.', 'Demonstrate Over-fetching and under-fetching — the specific REST pain points GraphQL addresses in a small working example.', 'Demonstrate N+1 query problem in GraphQL resolvers (ties back to the same problem flagged for Prisma in Phase 05) and DataLoader as the standard fix in a small working example.', 'Demonstrate Defining a schema — types, Query, Mutation root types in a small working example.']::text[], array['Submit a working GraphQL example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-frontend-v1-core-phase-07-m02-t03']::text[], '[]'::jsonb, 1560, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-01', 'zte-frontend-v1-core-phase-07', 'Zero-GUI API Debugging Toolkit', 'A personal collection of curl scripts (with a Makefile or shell aliases) that fully exercise every endpoint of an earlier project’s API, usable by teammates with no GUI tool installed. Domain: developer tooling.', array['Deliver the working outcome described in the Zero-GUI API Debugging Toolkit brief.', 'Use at least two skills from Manual HTTP Tooling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Zero-GUI API Debugging Toolkit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'Manual HTTP Tooling']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-02', 'zte-frontend-v1-core-phase-07', 'Shared Postman Collection with Environments', 'A Postman collection for a full-stack project with dev/staging/prod environments, pre-request scripts for auth token refresh, and automated test assertions per request, exported and version-controlled alongside the code. Domain: API QA/tooling.', array['Deliver the working outcome described in the Shared Postman Collection with Environments brief.', 'Use at least two skills from Manual HTTP Tooling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Shared Postman Collection with Environments', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'Manual HTTP Tooling']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-03', 'zte-frontend-v1-core-phase-07', 'Auto-Generated OpenAPI Docs Site', 'Write a complete OpenAPI 3.0 spec for an earlier project’s API by hand, render it with Swagger UI, and verify every documented example actually matches real API behavior (no doc drift). Domain: API developer experience.', array['Deliver the working outcome described in the Auto-Generated OpenAPI Docs Site brief.', 'Use at least two skills from API Documentation and GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Auto-Generated OpenAPI Docs Site', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'API Documentation and GraphQL (Alternative API Paradigm)']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-04', 'zte-frontend-v1-core-phase-07', 'Architecture Diagrams as Code', 'Document a full-stack project’s system architecture (request flow, database relationships, deployment topology) entirely using Mermaid diagrams embedded in markdown, version-controlled alongside the code. Domain: technical documentation / architecture.', array['Deliver the working outcome described in the Architecture Diagrams as Code brief.', 'Use at least two skills from API Documentation and GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Architecture Diagrams as Code', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'API Documentation and GraphQL (Alternative API Paradigm)']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-05', 'zte-frontend-v1-core-phase-07', 'Public-Facing Developer Portal', 'A polished, standalone documentation site for a public API combining OpenAPI-generated Swagger UI, hand-written getting-started guides, and Mermaid sequence diagrams showing common integration flows (e.g., OAuth handshake). Domain: developer relations / API products.', array['Deliver the working outcome described in the Public-Facing Developer Portal brief.', 'Use at least two skills from API Documentation and GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Public-Facing Developer Portal', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'API Documentation and GraphQL (Alternative API Paradigm)']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-06', 'zte-frontend-v1-core-phase-07', 'Blog GraphQL API', 'A GraphQL API (posts, authors, comments) with proper resolver structure, demonstrating the N+1 problem occurring naturally, then fixed with DataLoader-style batching. Domain: publishing/content. Implement the identical feature (a nested product/reviews/author data fetch) as both a REST endpoint and a GraphQL query, measuring over-fetching/under-fetching and request-count differences with real network data, and write a decision-framework document for when to choose each. Domain: API architecture.', array['Deliver the working outcome described in the Blog GraphQL API brief.', 'Use at least two skills from GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Blog GraphQL API', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'GraphQL (Alternative API Paradigm)']::text[], 'intermediate', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-07', 'zte-frontend-v1-core-phase-07', 'Federated Multi-Service GraphQL Gateway', 'Split a schema across 2 independent services (e.g., Users service and Orders service) and compose them behind a single gateway, demonstrating schema federation concepts. Domain: microservices/API architecture.', array['Deliver the working outcome described in the Federated Multi-Service GraphQL Gateway brief.', 'Use at least two skills from GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Federated Multi-Service GraphQL Gateway', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'GraphQL (Alternative API Paradigm)']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-07-project-08', 'zte-frontend-v1-core-phase-07', 'A Fully Documented, Dual-Paradigm Public API Product', 'Take an existing backend (Phase 5’s "Ledger" works well) and ship it as a genuine API product: a complete hand-written OpenAPI 3.0 spec rendered via Swagger UI, Mermaid-diagrammed architecture and auth-flow documentation, a parallel GraphQL interface over the same data exposing at least one N+1-fixed resolver, a curated Postman collection with environments and auto-refreshing auth, and a written REST-vs-GraphQL decision document explaining which consumers should use which interface and why. Domain: developer platforms / API products. Why it matters: documenting and exposing an API well is a distinct, high-value skill from building it — this proves you can make your work usable by other engineers, not just functional.', array['Deliver the working outcome described in the A Fully Documented, Dual-Paradigm Public API Product brief.', 'Use at least two skills from API Documentation & Developer Tooling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Fully Documented, Dual-Paradigm Public API Product', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'engineering documentation']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-08', 'zte-frontend-v1', id, '10', 'DSA & Interview Preparation', 'Core', 'The simplest pattern family — each operates directly on arrays/strings using nothing but the loop and indexing fundamentals from Phase 01\. No data structure beyond an array is required.', 331, 9 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-08-m01', 'zte-frontend-v1-core-phase-08', 1, 'Array & String Scanning Techniques and Hashing', 'The simplest pattern family — each operates directly on arrays/strings using nothing but the loop and indexing fundamentals from Phase 01\. No data structure beyond an array is required.', 14, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m01-t01', 'zte-frontend-v1-core-phase-08-m01', 'Two Pointers', array['Explain and apply null in Two Pointers.', 'Use Two Pointers to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate The pattern: two indices moving through a structure, either toward each other or in the same direction in a small working example.', 'Demonstrate Classic problems: pair sum in a sorted array, reversing in place, removing duplicates in place in a small working example.', 'Demonstrate Recognizing when a problem is a two-pointer candidate: sorted or orderable data, looking for pairs/triplets in a small working example.']::text[], array['Submit a working Two Pointers example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 1080, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m01-t02', 'zte-frontend-v1-core-phase-08-m01', 'Sliding Window', array['Explain and apply null in Sliding Window.', 'Use Sliding Window to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Fixed-size window vs variable-size (expand/shrink) window in a small working example.', 'Demonstrate Classic problems: longest substring without repeating characters, maximum sum subarray of size k in a small working example.', 'Demonstrate Recognizing sliding window candidates: contiguous subarray/substring problems with a size or condition constraint in a small working example.']::text[], array['Submit a working Sliding Window example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m01-t01']::text[], '[]'::jsonb, 1080, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m01-t03', 'zte-frontend-v1-core-phase-08-m01', 'Binary Search', array['Explain and apply null in Binary Search.', 'Use Binary Search to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Classic binary search — search space, mid calculation, avoiding overflow/off-by-one errors in a small working example.', 'Demonstrate Binary search on answer — a common advanced pattern where the search space isn''t the array itself but a range of possible answers in a small working example.', 'Demonstrate Recognizing binary search candidates: sorted data, or a monotonic condition that lets you eliminate half the search space in a small working example.']::text[], array['Submit a working Binary Search example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m01-t02']::text[], '[]'::jsonb, 1080, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m01-t04', 'zte-frontend-v1-core-phase-08-m01', 'HashMap / Frequency Count Patterns', array['Explain and apply null in HashMap / Frequency Count Patterns.', 'Use HashMap / Frequency Count Patterns to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Using a hash map to achieve O(n) where a naive approach would be O(n²) — the single most common optimization pattern in interviews in a small working example.', 'Demonstrate Frequency counting — character/element counts for anagram, majority element, and grouping problems in a small working example.', 'Demonstrate Combining hashing with two pointers/sliding window (Stage 1) — e.g. tracking window contents in a hash map while sliding in a small working example.', 'Demonstrate Set vs Map — when you only need existence checks vs when you need counts/associated values in a small working example.']::text[], array['Submit a working HashMap / Frequency Count Patterns example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m01-t03']::text[], '[]'::jsonb, 900, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m01-t05', 'zte-frontend-v1-core-phase-08-m01', 'Kadane''s Algorithm', array['Explain and apply null in Kadane''s Algorithm.', 'Use Kadane''s Algorithm to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Maximum subarray sum — the canonical Kadane''s problem in a small working example.', 'Demonstrate The core insight: at each position, either extend the previous subarray or start fresh in a small working example.', 'Demonstrate Why this is DP in miniature — one state variable, one transition — worth recognizing explicitly before Stage 6 introduces DP formally in a small working example.']::text[], array['Submit a working Kadane''s Algorithm example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m01-t04']::text[], '[]'::jsonb, 300, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-08-m02', 'zte-frontend-v1-core-phase-08', 2, 'Linear Structures: Stack & Queue', 'Both structures are prerequisites for Stage 4''s traversal algorithms — DFS is naturally expressed with a stack (or recursion, which uses the call stack implicitly), BFS requires a queue. This stage must come before Stage 4\.', 9, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m02-t01', 'zte-frontend-v1-core-phase-08-m02', 'Stack Patterns', array['Explain and apply null in Stack Patterns.', 'Use Stack Patterns to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate LIFO mechanics and where a stack beats an array for a given problem in a small working example.', 'Demonstrate Classic problems: valid parentheses matching, evaluating expressions, undo/redo-style problems in a small working example.', 'Demonstrate Using a stack to track "most recent unmatched" state — the general shape of most stack problems in a small working example.']::text[], array['Submit a working Stack Patterns example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 900, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m02-t02', 'zte-frontend-v1-core-phase-08-m02', 'Monotonic Stack', array['Explain and apply null in Monotonic Stack.', 'Use Monotonic Stack to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Maintaining a stack in increasing or decreasing order, popping elements that violate the order in a small working example.', 'Demonstrate Classic problems: next greater element, daily temperatures, largest rectangle in histogram in a small working example.', 'Demonstrate Recognizing monotonic stack candidates: "next greater/smaller element" style problems in a small working example.']::text[], array['Submit a working Monotonic Stack example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m02-t01']::text[], '[]'::jsonb, 900, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m02-t03', 'zte-frontend-v1-core-phase-08-m02', 'Queue / Deque Patterns', array['Explain and apply null in Queue / Deque Patterns.', 'Use Queue / Deque Patterns to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate FIFO mechanics — where a queue is the natural fit (level-by-level processing, foreshadows BFS in Stage 4) in a small working example.', 'Demonstrate Deque (double-ended queue) — sliding window maximum/minimum using a monotonic deque (combines Stage 1''s sliding window with Stage 3''s monotonic stack idea) in a small working example.', 'Demonstrate Circular queue implementation (conceptual) in a small working example.']::text[], array['Submit a working Queue / Deque Patterns example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m02-t02']::text[], '[]'::jsonb, 660, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-08-m03', 'zte-frontend-v1-core-phase-08', 3, 'Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming', 'Directly requires the queue (Stage 3, Topic 8\\) for BFS and the stack/recursion model (Stage 3, Topic 6\\) for DFS — cannot be taught before those exist.', 14, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m03-t01', 'zte-frontend-v1-core-phase-08-m03', 'BFS / DFS', array['Explain and apply Depth-First Search in BFS / DFS.', 'Explain and apply Breadth-First Search in BFS / DFS.', 'Explain and apply Choosing Between Them in BFS / DFS.']::text[], array['Demonstrate Recursive DFS — using the call stack implicitly in a small working example.', 'Demonstrate Iterative DFS — using an explicit stack (direct application of Stage 3, Topic 6) in a small working example.', 'Demonstrate Graph representations: adjacency list vs adjacency matrix in a small working example.', 'Demonstrate Visited-set tracking to avoid infinite loops in cyclic graphs in a small working example.', 'Demonstrate Queue-based level-by-level traversal (direct application of Stage 3, Topic 8) in a small working example.']::text[], array['Submit a working BFS / DFS example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 1800, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m03-t02', 'zte-frontend-v1-core-phase-08-m03', 'Dynamic Programming (Memoization + Tabulation)', array['Explain and apply Core Concepts in Dynamic Programming (Memoization + Tabulation).', 'Explain and apply Common DP Shapes in Dynamic Programming (Memoization + Tabulation).', 'Explain and apply Recognizing DP Candidates in Dynamic Programming (Memoization + Tabulation).']::text[], array['Demonstrate Overlapping subproblems and optimal substructure — the two properties that make a problem DP-solvable in a small working example.', 'Demonstrate Memoization (top-down) — recursion plus a cache in a small working example.', 'Demonstrate Tabulation (bottom-up) — building the solution iteratively from base cases in a small working example.', 'Demonstrate Converting between the two approaches in a small working example.', 'Demonstrate 1D DP — climbing stairs, house robber, fibonacci-style problems in a small working example.']::text[], array['Submit a working Dynamic Programming (Memoization + Tabulation) example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m03-t01']::text[], '[]'::jsonb, 3480, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m03-t03', 'zte-frontend-v1-core-phase-08-m03', 'Tree Traversal', array['Explain and apply null in Tree Traversal.', 'Use Tree Traversal to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate In-order, pre-order, post-order traversal — all DFS variants, differing only in when the node is "visited" relative to its children in a small working example.', 'Demonstrate Level-order traversal — a direct application of BFS (9) in a small working example.', 'Demonstrate Recursive vs iterative implementations of each order in a small working example.', 'Demonstrate Binary Search Tree-specific properties that in-order traversal reveals (sorted output) in a small working example.', 'Demonstrate Common tree problems: validate BST, lowest common ancestor, tree diameter, serialize/deserialize in a small working example.']::text[], array['Submit a working Tree Traversal example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m03-t02']::text[], '[]'::jsonb, 60, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m03-t04', 'zte-frontend-v1-core-phase-08-m03', 'Floyd''s Cycle Detection', array['Explain and apply null in Floyd''s Cycle Detection.', 'Use Floyd''s Cycle Detection to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Fast/slow pointer technique ("tortoise and hare") for detecting a cycle in a linked list in a small working example.', 'Demonstrate Finding the start of a cycle once one is detected in a small working example.', 'Demonstrate Why this is effectively Two Pointers (Stage 1) applied to a linked structure instead of an array in a small working example.']::text[], array['Submit a working Floyd''s Cycle Detection example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m03-t03']::text[], '[]'::jsonb, 300, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m03-t05', 'zte-frontend-v1-core-phase-08-m03', 'Heap / Priority Queue', array['Explain and apply null in Heap / Priority Queue.', 'Use Heap / Priority Queue to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Min-heap vs max-heap — underlying array representation and heapify operations in a small working example.', 'Demonstrate Insert and extract-min/max — O(log n) operations and why they matter for priority-based problems in a small working example.', 'Demonstrate Classic problems: top K frequent elements (combines directly with Stage 2''s frequency counting), merge K sorted lists, median of a data stream in a small working example.', 'Demonstrate When a heap beats sorting the entire dataset — maintaining a running "best K" without re-sorting in a small working example.']::text[], array['Submit a working Heap / Priority Queue example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m03-t04']::text[], '[]'::jsonb, 1320, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-08-m04', 'zte-frontend-v1-core-phase-08', 4, 'Interview Meta-Skills', 'Requires actual DSA competence (Stages 1–6) to be meaningful — a communication framework or system design vocabulary is empty without real problems solved to apply it to.', 12, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m04-t01', 'zte-frontend-v1-core-phase-08-m04', 'Interview Frameworks (STAR, REACTO)', array['Explain and apply null in Interview Frameworks (STAR, REACTO).', 'Use Interview Frameworks (STAR, REACTO) to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate STAR (Situation, Task, Action, Result) — structuring behavioral interview answers in a small working example.', 'Demonstrate REACTO (Requirements, Examples, Approach, Code, Tests, Optimize) — structuring a live coding interview response, applied directly to the patterns from Stages 1–6 in a small working example.', 'Demonstrate Practicing narrating your thought process out loud while solving a problem — the skill interviewers are actually evaluating, distinct from just getting the right answer in a small working example.']::text[], array['Submit a working Interview Frameworks (STAR, REACTO) example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-m04-t02', 'zte-frontend-v1-core-phase-08-m04', 'System Design Interview Basics', array['Explain and apply Core Concepts in System Design Interview Basics.', 'Explain and apply Framing a System Design Answer in System Design Interview Basics.']::text[], array['Demonstrate Scalability basics — vertical vs horizontal scaling in a small working example.', 'Demonstrate Load balancing — concept and common strategies in a small working example.', 'Demonstrate Caching layers — where and why (connects to Redis, introduced in a later phase, but the concept is introduced here) in a small working example.', 'Demonstrate Database scaling — read replicas, sharding (concept, connects to Phase 05''s PostgreSQL depth) in a small working example.', 'Demonstrate Clarifying requirements before designing — functional and non-functional (scale, latency, consistency) in a small working example.']::text[], array['Submit a working System Design Interview Basics example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-frontend-v1-core-phase-08-m04-t01']::text[], '[]'::jsonb, 1140, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-01', 'zte-frontend-v1-core-phase-08', 'Pattern Recognition Drill Set', 'Solve and document 8 problems each for Two Pointers and Sliding Window (16 total) from a mix of easy/medium difficulty, with a personal "pattern recognition cheat sheet" written afterward describing the signal phrases that indicate each pattern.', array['Deliver the working outcome described in the Pattern Recognition Drill Set brief.', 'Use at least two skills from Array & String Scanning Techniques and Hashing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Pattern Recognition Drill Set', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Array & String Scanning Techniques and Hashing']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-02', 'zte-frontend-v1-core-phase-08', 'Binary Search Beyond Sorted Arrays', 'Solve 6 problems that use binary search in non-obvious ways (search on answer space, rotated arrays, first/last occurrence), documenting the invariant maintained in each solution.', array['Deliver the working outcome described in the Binary Search Beyond Sorted Arrays brief.', 'Use at least two skills from Array & String Scanning Techniques and Hashing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Binary Search Beyond Sorted Arrays', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Array & String Scanning Techniques and Hashing']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-03', 'zte-frontend-v1-core-phase-08', 'Stock Trading Simulator via Kadane’s Variants', 'Solve the full family of "best time to buy/sell stock" problems (I through IV) building from basic Kadane’s to the DP-augmented versions with transaction limits, with a written explanation of how each variant extends the last.', array['Deliver the working outcome described in the Stock Trading Simulator via Kadane’s Variants brief.', 'Use at least two skills from Array & String Scanning Techniques and Hashing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Stock Trading Simulator via Kadane’s Variants', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Array & String Scanning Techniques and Hashing']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-04', 'zte-frontend-v1-core-phase-08', 'Expression Evaluator', 'Build a calculator that evaluates infix mathematical expressions with correct operator precedence and parentheses using a stack-based approach (shunting-yard or recursive descent), tested against 20 hand-crafted tricky expressions. Solve 6 monotonic stack problems (next greater element family, daily temperatures, largest rectangle in histogram), with a written template for recognizing when a monotonic stack applies.', array['Deliver the working outcome described in the Expression Evaluator brief.', 'Use at least two skills from Linear Structures: Stack & Queue.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Expression Evaluator', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Linear Structures: Stack & Queue']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-05', 'zte-frontend-v1-core-phase-08', 'Maze & Graph Explorer Toolkit', 'Solve a set of grid-based BFS/DFS problems (number of islands, rotting oranges, word ladder) with a shared, reusable grid-traversal helper function. Implement every classic tree traversal (in/pre/post-order, level-order) both recursively and iteratively, plus tree construction from traversal pairs, serialization/deserialization, and LCA — packaged as a small reusable tree utility module with tests.', array['Deliver the working outcome described in the Maze & Graph Explorer Toolkit brief.', 'Use at least two skills from Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Maze & Graph Explorer Toolkit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-06', 'zte-frontend-v1-core-phase-08', 'Cycle Detection Across Data Structures', 'Implement Floyd’s Cycle Detection (tortoise and hare) applied to 3 different contexts: a linked list, an implicit "functional graph" (array where value = next index), and duplicate-number detection — documenting the shared mathematical insight across all three.', array['Deliver the working outcome described in the Cycle Detection Across Data Structures brief.', 'Use at least two skills from Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cycle Detection Across Data Structures', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-07', 'zte-frontend-v1-core-phase-08', '1D DP Warm-Up Set', 'Solve 6 classic 1D DP problems (climbing stairs, house robber, coin change, longest increasing subsequence) implementing each with both memoization (top-down) and tabulation (bottom-up), comparing code clarity and space usage. Solve 8 2D DP problems (unique paths, edit distance, longest common subsequence, 0/1 knapsack) with a written "DP state design" note for each: what does dp[i][j] represent, and why.', array['Deliver the working outcome described in the 1D DP Warm-Up Set brief.', 'Use at least two skills from Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working 1D DP Warm-Up Set', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Dynamic Programming']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-08', 'zte-frontend-v1-core-phase-08', 'DP Optimization Showcase', 'Take 3 of your 2D DP solutions and optimize their space complexity from O(n²) to O(n) using rolling arrays, documenting the transformation reasoning and benchmarking actual memory usage before/after on large inputs.', array['Deliver the working outcome described in the DP Optimization Showcase brief.', 'Use at least two skills from Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working DP Optimization Showcase', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Dynamic Programming']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-09', 'zte-frontend-v1-core-phase-08', 'System Design Interview Playbook', 'Produce full written system design solutions (with diagrams) for 4 classic prompts (URL shortener, rate limiter, news feed, chat system) following a consistent framework: requirements clarification, capacity estimation, high-level design, deep dive, bottleneck/scaling discussion. Domain: systems design / interview prep.', array['Deliver the working outcome described in the System Design Interview Playbook brief.', 'Use at least two skills from Interview Meta-Skills.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working System Design Interview Playbook', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Interview Meta-Skills']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-08-project-10', 'zte-frontend-v1-core-phase-08', 'A Personal DSA + System Design Reference System', 'Build a personal, structured knowledge base (could be a static site generated from markdown, tying back to Phase 1– 3 skills) cataloging: every pattern from Stages 1–6 with your own annotated solutions and a "recognize this pattern when..." cheat sheet per category, 4 fully written system design case studies with Mermaid architecture diagrams (tying back to Phase 7), and a log of at least 10 timed, REACTO-framework mock interviews with self-critique notes. Domain: career preparation / technical knowledge management. Why it matters: the artifact itself (a searchable, well-organized personal reference) is arguably more valuable long-term than any single solved problem — and building it forces genuine synthesis rather than passive practice.', array['Deliver the working outcome described in the A Personal DSA + System Design Reference System brief.', 'Use at least two skills from DSA & Interview Preparation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Personal DSA + System Design Reference System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'engineering documentation']::text[], 'advanced', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-09', 'zte-frontend-v1', id, '11', 'Caching + Email + Payments', 'Advanced', 'Requires PostgreSQL and a real backend (Phase 05\\) — caching only matters once there''s real query load and connection pressure to relieve.', 98, 10 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-09-m01', 'zte-frontend-v1-core-phase-09', 1, 'Self-Hosted Caching Infrastructure', 'Requires PostgreSQL and a real backend (Phase 05\\) — caching only matters once there''s real query load and connection pressure to relieve.', 11.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m01-t01', 'zte-frontend-v1-core-phase-09-m01', 'Redis', array['Explain and apply Core Data Structures in Redis.', 'Explain and apply Caching Patterns in Redis.', 'Explain and apply Beyond Simple Caching in Redis.']::text[], array['Demonstrate Strings, hashes, lists, sets, sorted sets — Redis''s core data types and when each fits a use case in a small working example.', 'Demonstrate Key expiration (TTL) — the foundation of cache invalidation in a small working example.', 'Demonstrate Redis as a cache vs Redis as a primary data store — the distinction and why it matters in a small working example.', 'Demonstrate Cache-aside (lazy loading) — the most common pattern: check cache, miss, fetch from DB, populate cache in a small working example.', 'Demonstrate Write-through vs write-behind caching in a small working example.']::text[], array['Submit a working Redis example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array[]::text[], '[]'::jsonb, 1140, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m01-t02', 'zte-frontend-v1-core-phase-09-m01', 'ioredis', array['Explain and apply null in ioredis.', 'Use ioredis to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Connecting to a Redis instance from Node/Express (Phase 05) in a small working example.', 'Demonstrate Basic commands via the client API — get/set/expire, hash and list operations in a small working example.', 'Demonstrate Connection resilience — retry strategies, handling connection drops in a small working example.', 'Demonstrate Pipelining and transactions (MULTI/EXEC) for batching commands efficiently in a small working example.']::text[], array['Submit a working ioredis example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-frontend-v1-core-phase-09-m01-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m01-t03', 'zte-frontend-v1-core-phase-09-m01', 'PgBouncer', array['Explain and apply null in PgBouncer.', 'Use PgBouncer to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate The connection limit problem — why PostgreSQL can''t handle unlimited direct connections, especially from serverless/edge functions (Phase 02''s Edge Runtime) in a small working example.', 'Demonstrate Transaction pooling vs session pooling modes in a small working example.', 'Demonstrate Where PgBouncer sits in the request path — app → PgBouncer → PostgreSQL in a small working example.', 'Demonstrate Why this matters more in serverless contexts than traditional long-running servers in a small working example.']::text[], array['Submit a working PgBouncer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-frontend-v1-core-phase-09-m01-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-09-m02', 'zte-frontend-v1-core-phase-09', 2, 'Hosted & Distributed Caching', 'Requires Redis fundamentals (Stage 1\\) — this stage is the caching-layer parallel to Phase 05''s PostgreSQL → Supabase/Neon progression: self-hosted concept first, hosted/managed alternative second.', 3.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m02-t01', 'zte-frontend-v1-core-phase-09-m02', 'Upstash', array['Explain and apply null in Upstash.', 'Use Upstash to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Serverless Redis — HTTP-based access instead of persistent TCP connections, designed for edge/serverless environments in a small working example.', 'Demonstrate Why Upstash fits Next.js Edge Runtime/Middleware (Phase 02) where traditional Redis clients (ioredis) can''t run in a small working example.', 'Demonstrate Pricing model differences — pay-per-request vs traditional Redis''s always-on instance cost in a small working example.', 'Demonstrate When to choose Upstash over self-hosted Redis — mirrors the Supabase/Neon vs raw PostgreSQL decision from Phase 05 in a small working example.']::text[], array['Submit a working Upstash example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m02-t02', 'zte-frontend-v1-core-phase-09-m02', '@upstash/ratelimit', array['Explain and apply null in @upstash/ratelimit.', 'Use @upstash/ratelimit to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Why in-memory rate limiting (Phase 05) breaks across multiple serverless function instances — no shared state in a small working example.', 'Demonstrate Sliding window, fixed window, and token bucket algorithms as implemented by this library in a small working example.', 'Demonstrate Applying rate limits in Next.js Middleware (Phase 02) or Edge Functions using Upstash''s HTTP-based access (4) in a small working example.']::text[], array['Submit a working @upstash/ratelimit example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-frontend-v1-core-phase-09-m02-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-09-m03', 'zte-frontend-v1-core-phase-09', 3, 'Transactional Email and Payments', 'Independent of the caching stages above — a new capability area. Ordered so the delivery mechanism (Resend) is understood before investing in a component-based templating system (React Email) that plugs into it.', 5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m03-t01', 'zte-frontend-v1-core-phase-09-m03', 'Resend', array['Explain and apply null in Resend.', 'Use Resend to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Sending a transactional email via Resend''s API — the simplest possible send call in a small working example.', 'Demonstrate Domain verification and sender reputation basics (SPF, DKIM — conceptual) in a small working example.', 'Demonstrate Common triggers: signup confirmation, password reset, notification emails — tying back to Phase 05''s auth flow in a small working example.', 'Demonstrate Handling send failures and retries in a small working example.']::text[], array['Submit a working Resend example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m03-t02', 'zte-frontend-v1-core-phase-09-m03', 'React Email', array['Explain and apply null in React Email.', 'Use React Email to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Building email templates as React components — familiar syntax from Phase 02, compiled to email-safe HTML in a small working example.', 'Demonstrate Why email HTML/CSS is far more constrained than web CSS (Phase 03) — table-based layouts, inline styles, limited property support in a small working example.', 'Demonstrate Component library (@react-email/components) — pre-built email-safe primitives (Button, Section, Text) in a small working example.', 'Demonstrate Previewing emails locally during development in a small working example.', 'Demonstrate Connecting a React Email template''s output to a Resend send call (6) — completing the pipeline in a small working example.']::text[], array['Submit a working React Email example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-frontend-v1-core-phase-09-m03-t01']::text[], '[]'::jsonb, 480, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-m03-t03', 'zte-frontend-v1-core-phase-09-m03', 'Razorpay', array['Explain and apply Payment Flow Fundamentals in Razorpay.', 'Explain and apply Webhooks in Razorpay.', 'Explain and apply Production Considerations in Razorpay.']::text[], array['Demonstrate Order creation → checkout → payment capture → webhook confirmation — the standard flow in a small working example.', 'Demonstrate Client-side checkout integration (Razorpay''s JS SDK) in a Next.js app (Phase 02) in a small working example.', 'Demonstrate Server-side order creation and signature verification in a small working example.', 'Demonstrate Why payment confirmation must be server-to-server (webhook), not trusted from the client alone in a small working example.', 'Demonstrate Verifying webhook signatures (HMAC-based, ties directly back to Phase 05''s HMAC-SHA256 topic) in a small working example.']::text[], array['Submit a working Razorpay example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-frontend-v1-core-phase-09-m03-t02']::text[], '[]'::jsonb, 1140, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-project-01', 'zte-frontend-v1-core-phase-09', 'Cache-Aside API Layer', 'Add Redis caching (via ioredis) to an earlier project’s read-heavy endpoints using the cache-aside pattern, with a documented cache-hit-rate measurement before/after and a sensible TTL/invalidation strategy per resource type. Domain: performance engineering.', array['Deliver the working outcome described in the Cache-Aside API Layer brief.', 'Use at least two skills from Self-Hosted Caching Infrastructure.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cache-Aside API Layer', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Self-Hosted Caching Infrastructure']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-project-02', 'zte-frontend-v1-core-phase-09', 'Connection Pool Exhaustion Lab', 'Deliberately misconfigure PgBouncer to cause connection pool exhaustion under simulated load, observe and document the failure mode, then correctly configure pooling (transaction vs session mode) and prove the fix under the same load test. Domain: database infrastructure / SRE.', array['Deliver the working outcome described in the Connection Pool Exhaustion Lab brief.', 'Use at least two skills from Self-Hosted Caching Infrastructure.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Connection Pool Exhaustion Lab', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Self-Hosted Caching Infrastructure']::text[], 'advanced', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-project-03', 'zte-frontend-v1-core-phase-09', 'Serverless-Friendly Rate Limiter', 'Implement API rate limiting using Upstash (Redis-over-HTTP, works from serverless/edge functions) with @upstash/ratelimit, comparing sliding-window vs fixed-window algorithms with real traffic simulation. Domain: API infrastructure.', array['Deliver the working outcome described in the Serverless-Friendly Rate Limiter brief.', 'Use at least two skills from Hosted & Distributed Caching.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Serverless-Friendly Rate Limiter', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Hosted & Distributed Caching']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-project-04', 'zte-frontend-v1-core-phase-09', 'Branded Transactional Email System', 'Build a full transactional email flow (welcome, password reset, receipt) using React Email for templates (so emails are built with real component reuse) and Resend for delivery, tested across multiple email clients for rendering consistency. Domain: product/growth engineering.', array['Deliver the working outcome described in the Branded Transactional Email System brief.', 'Use at least two skills from Transactional Email and Payments.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Branded Transactional Email System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Transactional Email and Payments']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-project-05', 'zte-frontend-v1-core-phase-09', 'Subscription Billing System', 'A full subscription billing integration with Razorpay: plan selection, checkout, webhook-based subscription-status sync (active/past-due/cancelled) back into your own database, and a customer-facing billing history page. Domain: fintech / SaaS billing. A one-time purchase flow (e.g., for a digital product) with Razorpay, including a documented refund process both via API and via the dashboard, and idempotent webhook handling so a duplicate webhook delivery never double-credits an order. Domain: e-commerce/fintech.', array['Deliver the working outcome described in the Subscription Billing System brief.', 'Use at least two skills from Payments.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Subscription Billing System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Payments']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-09-project-06', 'zte-frontend-v1-core-phase-09', 'A Caching-Optimized SaaS Billing Backend', 'Extend Phase 5’s "Ledger" (or a similar backend) with: Redis cache-aside caching on the highest-traffic read endpoints with measured hit-rate improvements, PgBouncer correctly configured for connection pooling under load, Upstash-based edge-compatible rate limiting on public endpoints, a full React Email \+ Resend transactional email suite (welcome/receipt/billing-alert), and a complete Razorpay subscription billing integration with idempotent, signature-verified webhook handling syncing subscription state into the database. Domain: SaaS infrastructure / fintech. Why it matters: caching, email, and payments are the unglamorous plumbing every real SaaS product needs — getting them right (idempotency, cache invalidation, webhook security) is what separates hobby projects from production systems.', array['Deliver the working outcome described in the A Caching-Optimized SaaS Billing Backend brief.', 'Use at least two skills from Caching + Email + Payments.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Caching-Optimized SaaS Billing Backend', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'engineering documentation']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-10', 'zte-frontend-v1', id, '12', 'Monitoring & Analytics', 'Advanced', 'Requires a real backend (Phase 05\\) with real request traffic — logging and context tracing only matter once there''s something happening to log.', 103, 11 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-10-m01', 'zte-frontend-v1-core-phase-10', 1, 'Request Context & Structured Logging', 'Requires a real backend (Phase 05\\) with real request traffic — logging and context tracing only matter once there''s something happening to log.', 6.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m01-t01', 'zte-frontend-v1-core-phase-10-m01', 'AsyncLocalStorage', array['Explain and apply null in AsyncLocalStorage.', 'Use AsyncLocalStorage to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate The problem: a single Express request handler (Phase 05) may call through many async functions — how do you tag every log line from that request with the same request ID without passing it as a parameter everywhere? in a small working example.', 'Demonstrate AsyncLocalStorage.run() and .getStore() — the core API in a small working example.', 'Demonstrate Building request-scoped context: request ID, user ID, correlation ID in a small working example.', 'Demonstrate Express middleware pattern for initializing AsyncLocalStorage per request in a small working example.']::text[], array['Submit a working AsyncLocalStorage example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m01-t02', 'zte-frontend-v1-core-phase-10-m01', 'pino', array['Explain and apply null in pino.', 'Use pino to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Why pino is fast — minimal serialization overhead, JSON-first output by design in a small working example.', 'Demonstrate Log levels (trace, debug, info, warn, error, fatal) and when to use each in a small working example.', 'Demonstrate Structured logging — logging objects, not just strings, so logs are queryable later (bridges to Stage 3''s aggregation platforms) in a small working example.', 'Demonstrate Child loggers — attaching AsyncLocalStorage context (1) automatically to every log call within a request in a small working example.']::text[], array['Submit a working pino example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m01-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m01-t03', 'zte-frontend-v1-core-phase-10-m01', 'winston', array['Explain and apply null in winston.', 'Use winston to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Winston''s transport model — logging to multiple destinations simultaneously (console, file, external service) in a small working example.', 'Demonstrate Winston vs pino — performance tradeoffs (winston is more configurable, pino is faster by design) in a small working example.', 'Demonstrate When to choose one over the other for a given project''s needs in a small working example.']::text[], array['Submit a working winston example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m01-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-10-m02', 'zte-frontend-v1-core-phase-10', 2, 'Error Tracking & Uptime', 'Requires structured logging (Stage 1\\) as a complementary but distinct concept — logs answer "what happened," error tracking answers "what went wrong and who does it affect."', 5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m02-t01', 'zte-frontend-v1-core-phase-10-m02', 'Sentry', array['Explain and apply Core Error Tracking in Sentry.', 'Explain and apply Context & Correlation in Sentry.']::text[], array['Demonstrate Automatic error capture — uncaught exceptions and promise rejections (ties back to Phase 01''s Node.js error handling topics) in a small working example.', 'Demonstrate Manual error capture — Sentry.captureException() for handled errors worth tracking anyway in a small working example.', 'Demonstrate Source maps — seeing real file/line info in production errors instead of minified gibberish in a small working example.', 'Demonstrate Error grouping — how Sentry deduplicates the same underlying error across many occurrences in a small working example.', 'Demonstrate Attaching user context to errors — connecting an error to the specific user/request that triggered it, using the same AsyncLocalStorage context (Stage 1, Topic 1) as your logs in a small working example.']::text[], array['Submit a working Sentry example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 420, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m02-t02', 'zte-frontend-v1-core-phase-10-m02', 'UptimeRobot', array['Explain and apply null in UptimeRobot.', 'Use UptimeRobot to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Setting up HTTP(S) monitors against your deployed app (Phase 06) in a small working example.', 'Demonstrate Alert configuration — email/SMS/webhook when a monitor fails in a small working example.', 'Demonstrate Status pages — a public-facing uptime history, useful portfolio polish in a small working example.']::text[], array['Submit a working UptimeRobot example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m02-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-10-m03', 'zte-frontend-v1-core-phase-10', 3, 'Log Aggregation & Observability Platforms', 'Requires structured logs to exist (Stage 1\\) — these platforms exist to collect, search, and visualize exactly that output at scale, which a single server''s local log files can''t do.', 10, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m03-t01', 'zte-frontend-v1-core-phase-10-m03', 'Better Stack (formerly Logtail)', array['Explain and apply null in Better Stack (formerly Logtail).', 'Use Better Stack (formerly Logtail) to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Shipping pino/winston logs (Stage 1) to a hosted log aggregation service in a small working example.', 'Demonstrate Searching and filtering logs across deployments in a small working example.', 'Demonstrate Alerting on log patterns (e.g. error rate spikes) in a small working example.']::text[], array['Submit a working Better Stack (formerly Logtail) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m03-t02', 'zte-frontend-v1-core-phase-10-m03', 'Axiom', array['Explain and apply null in Axiom.', 'Use Axiom to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Axiom''s dataset model for high-volume structured log ingestion in a small working example.', 'Demonstrate Query language for filtering/aggregating logs in a small working example.', 'Demonstrate Where Axiom differs from Better Stack — pricing model, retention, query capabilities in a small working example.']::text[], array['Submit a working Axiom example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m03-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m03-t03', 'zte-frontend-v1-core-phase-10-m03', 'Grafana Cloud', array['Explain and apply null in Grafana Cloud.', 'Use Grafana Cloud to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate The three pillars of observability: metrics, logs, traces — and how Grafana Cloud unifies them in one dashboard in a small working example.', 'Demonstrate Building dashboards from application metrics in a small working example.', 'Demonstrate Connecting Grafana to multiple data sources in a small working example.']::text[], array['Submit a working Grafana Cloud example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m03-t02']::text[], '[]'::jsonb, 300, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m03-t04', 'zte-frontend-v1-core-phase-10-m03', 'Loki', array['Explain and apply null in Loki.', 'Use Loki to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Loki''s log-indexing model — indexing labels, not full log content (a key difference from Elasticsearch-style systems) in a small working example.', 'Demonstrate LogQL — Loki''s query language in a small working example.', 'Demonstrate Why Loki pairs naturally with Grafana (8) rather than standing alone in a small working example.']::text[], array['Submit a working Loki example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m03-t03']::text[], '[]'::jsonb, 180, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m03-t05', 'zte-frontend-v1-core-phase-10-m03', 'Datadog', array['Explain and apply null in Datadog.', 'Use Datadog to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Datadog''s all-in-one model — APM, logs, infrastructure metrics, and RUM (Real User Monitoring) in one product in a small working example.', 'Demonstrate Where Datadog differs from Grafana Cloud — pricing at scale, ease of setup vs configurability in a small working example.', 'Demonstrate When a team would choose Datadog over a Grafana/Loki stack in a small working example.']::text[], array['Submit a working Datadog example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m03-t04']::text[], '[]'::jsonb, 180, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m03-t06', 'zte-frontend-v1-core-phase-10-m03', 'CloudWatch', array['Explain and apply null in CloudWatch.', 'Use CloudWatch to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate CloudWatch Logs, Metrics, and Alarms — AWS-native observability in a small working example.', 'Demonstrate When CloudWatch is the natural default (already deploying on AWS/ECS/Lambda) vs when a dedicated tool (8–10) is worth the extra integration effort in a small working example.']::text[], array['Submit a working CloudWatch example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m03-t05']::text[], '[]'::jsonb, 180, 'advanced', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-10-m04', 'zte-frontend-v1-core-phase-10', 4, 'Product Analytics Foundation', 'A distinct concern from infrastructure monitoring (Stages 1–3) — this is about user behavior, not system health. Independent of everything above, but grouped after it since it''s a separate observability axis, not a prerequisite.', 5.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m04-t01', 'zte-frontend-v1-core-phase-10-m04', 'PostHog', array['Explain and apply null in PostHog.', 'Use PostHog to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Event-based analytics model — tracking user actions as named events with properties in a small working example.', 'Demonstrate Self-hosted vs PostHog Cloud — the platform choice in a small working example.', 'Demonstrate Core concepts: persons, events, properties, cohorts in a small working example.', 'Demonstrate Dashboards and insights built from raw event data in a small working example.']::text[], array['Submit a working PostHog example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 540, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m04-t02', 'zte-frontend-v1-core-phase-10-m04', 'posthog-js', array['Explain and apply null in posthog-js.', 'Use posthog-js to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Initializing PostHog in a Next.js app (Phase 02) in a small working example.', 'Demonstrate Autocapture vs manual event tracking — tradeoffs in a small working example.', 'Demonstrate Identifying users — connecting anonymous pre-signup activity to a known user after login (ties to Phase 05''s auth) in a small working example.']::text[], array['Submit a working posthog-js example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m04-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m04-t03', 'zte-frontend-v1-core-phase-10-m04', 'posthog-node', array['Explain and apply null in posthog-node.', 'Use posthog-node to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Server-side event capture — tracking events that happen outside the browser (webhook-triggered actions, background jobs) in a small working example.', 'Demonstrate Combining client and server events into a single coherent user timeline in a small working example.']::text[], array['Submit a working posthog-node example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m04-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-10-m05', 'zte-frontend-v1-core-phase-10', 5, 'Analytics-Driven Features and Compliance', 'All four topics require the PostHog foundation (Stage 4\\) — none of these features exist without an analytics platform and event pipeline already in place.', 8.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m05-t01', 'zte-frontend-v1-core-phase-10-m05', 'Feature Flags', array['Explain and apply null in Feature Flags.', 'Use Feature Flags to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Defining a feature flag and gating code paths behind it in a small working example.', 'Demonstrate Percentage rollouts — releasing a feature to a subset of users in a small working example.', 'Demonstrate Flag evaluation — client-side vs server-side, and the tradeoffs (ties to posthog-js/posthog-node, Stage 4) in a small working example.']::text[], array['Submit a working Feature Flags example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m05-t02', 'zte-frontend-v1-core-phase-10-m05', 'A/B Testing', array['Explain and apply null in A/B Testing.', 'Use A/B Testing to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Experiment design — control vs variant groups, sample size basics in a small working example.', 'Demonstrate Statistical significance — enough to interpret PostHog''s built-in significance calculations, not full statistical theory in a small working example.', 'Demonstrate Connecting an experiment to a measurable outcome event (ties to Stage 4''s event tracking) in a small working example.']::text[], array['Submit a working A/B Testing example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m05-t01']::text[], '[]'::jsonb, 420, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m05-t03', 'zte-frontend-v1-core-phase-10-m05', 'Funnel Analysis', array['Explain and apply null in Funnel Analysis.', 'Use Funnel Analysis to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Defining a funnel — an ordered sequence of events representing a user journey (e.g. signup → onboarding → first action) in a small working example.', 'Demonstrate Drop-off analysis — identifying where users abandon the journey in a small working example.', 'Demonstrate Connecting funnel insights back to real product decisions in a small working example.']::text[], array['Submit a working Funnel Analysis example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m05-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m05-t04', 'zte-frontend-v1-core-phase-10-m05', 'Session Recording', array['Explain and apply null in Session Recording.', 'Use Session Recording to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate What session recording captures — DOM mutations replayed as a video-like session, not actual video in a small working example.', 'Demonstrate Privacy implications and masking sensitive input fields (direct segue into Stage 6''s GDPR topic) in a small working example.', 'Demonstrate Using recordings alongside funnel drop-off points (17) to see exactly why users abandoned a flow in a small working example.']::text[], array['Submit a working Session Recording example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m05-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-m05-t05', 'zte-frontend-v1-core-phase-10-m05', 'GDPR Consent Mode', array['Explain and apply null in GDPR Consent Mode.', 'Use GDPR Consent Mode to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate What GDPR requires for analytics/tracking consent — opt-in before tracking, not opt-out after in a small working example.', 'Demonstrate Consent banners and their effect on PostHog initialization — delaying or conditionally enabling tracking (Stage 4) based on consent state in a small working example.', 'Demonstrate Handling session recording (18) specifically — masking or disabling entirely without consent in a small working example.', 'Demonstrate Cookie-less/anonymous tracking modes as a partial compliance strategy before consent is granted in a small working example.', 'Demonstrate Documenting what''s collected — the practical deliverable a real compliance review would ask for in a small working example.']::text[], array['Submit a working GDPR Consent Mode example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-frontend-v1-core-phase-10-m05-t04']::text[], '[]'::jsonb, 180, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-project-01', 'zte-frontend-v1-core-phase-10', 'Request-Traceable Logging System', 'Add structured logging (pino) to an earlier API with a request ID propagated via AsyncLocalStorage through every log line of a request’s lifecycle, so any single request’s full log trail can be grepped by ID. Domain: observability / SRE.', array['Deliver the working outcome described in the Request-Traceable Logging System brief.', 'Use at least two skills from Request Context & Structured Logging.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Request-Traceable Logging System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Request Context & Structured Logging']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-project-02', 'zte-frontend-v1-core-phase-10', 'Dual-Transport Logging Setup', 'Configure winston with two transports (console for dev, file/JSON for production) and demonstrate log-level filtering (debug locally, warn+ in production) driven by environment config. Domain: observability.', array['Deliver the working outcome described in the Dual-Transport Logging Setup brief.', 'Use at least two skills from Request Context & Structured Logging.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Dual-Transport Logging Setup', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Request Context & Structured Logging']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-project-03', 'zte-frontend-v1-core-phase-10', 'Production Error Triage Dashboard', 'Integrate Sentry into a full-stack app (both frontend and backend), including source maps for readable stack traces, user context attachment, and custom error grouping/tagging for a specific error-prone feature. Domain: SRE / observability. Set up UptimeRobot monitors for a deployed project’s critical endpoints and build a small public status page that reflects real uptime data. Domain: SRE / product trust.', array['Deliver the working outcome described in the Production Error Triage Dashboard brief.', 'Use at least two skills from Error Tracking & Uptime.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Production Error Triage Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Error Tracking & Uptime']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-project-04', 'zte-frontend-v1-core-phase-10', 'Unified Observability Stack Comparison', 'Ship the same application’s logs to 3 different platforms in parallel (e.g., Better Stack, Axiom, and Grafana Cloud + Loki) and write a hands-on comparison covering query experience, retention/pricing, and alerting capability. Domain: infrastructure decision-making.', array['Deliver the working outcome described in the Unified Observability Stack Comparison brief.', 'Use at least two skills from Log Aggregation & Observability Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Unified Observability Stack Comparison', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Log Aggregation & Observability Platforms']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-project-05', 'zte-frontend-v1-core-phase-10', 'CloudWatch-Based AWS Monitoring Setup', 'For any component deployed with AWS involvement, configure CloudWatch log groups, metric filters, and a basic alarm (e.g., error-rate spike) that would page a real on-call engineer. Domain: AWS/SRE.', array['Deliver the working outcome described in the CloudWatch-Based AWS Monitoring Setup brief.', 'Use at least two skills from Log Aggregation & Observability Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CloudWatch-Based AWS Monitoring Setup', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Log Aggregation & Observability Platforms']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-project-06', 'zte-frontend-v1-core-phase-10', 'Feature-Flagged A/B Pricing Experiment', 'Run a real (or realistic simulated) A/B test on a pricing page using PostHog feature flags to split traffic, tracked through to a conversion event, with statistical significance discussed in a written results report. Domain: growth engineering / experimentation. Use funnel analysis and session recordings to identify the exact step where users abandon an onboarding flow, propose and implement a fix, then re-measure the funnel to validate improvement. Domain: product/UX engineering.', array['Deliver the working outcome described in the Feature-Flagged A/B Pricing Experiment brief.', 'Use at least two skills from Analytics-Driven Features and Compliance.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Feature-Flagged A/B Pricing Experiment', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Analytics-Driven Features and Compliance']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-10-project-07', 'zte-frontend-v1-core-phase-10', 'A Full Observability & Analytics Platform for a Production App', 'Wrap a complete observability and analytics layer around an earlier full-stack project: AsyncLocalStorage-propagated structured logging (pino) shipped to a real aggregation platform (Grafana Cloud \+ Loki), Sentry error tracking with source maps on both frontend and backend, UptimeRobot-backed public status page, full PostHog funnel instrumentation from landing to conversion with an active feature-flagged A/B experiment, session-recording-driven UX fixes with before/after funnel data, and a GDPR-compliant consent system that actually gates tracking. Domain: SRE / product analytics / privacy engineering. Why it matters: shipping a feature is half the job; knowing whether it works, why it breaks, and whether users actually use it is the other half — this project proves that operational maturity.', array['Deliver the working outcome described in the A Full Observability & Analytics Platform for a Production App brief.', 'Use at least two skills from Monitoring & Analytics.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Full Observability & Analytics Platform for a Production App', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-11', 'zte-frontend-v1', id, '13', 'Real-Time + Search + PostgreSQL Internals', 'Advanced', 'Ordered by mechanism complexity — each topic''s limitations motivate the next. Requires a real deployed app (Phase 06\\) and backend (Phase 05\\) to build real-time features on top of.', 164, 12 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-11-m01', 'zte-frontend-v1-core-phase-11', 1, 'Real-Time Communication', 'Ordered by mechanism complexity — each topic''s limitations motivate the next. Requires a real deployed app (Phase 06\\) and backend (Phase 05\\) to build real-time features on top of.', 15, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m01-t01', 'zte-frontend-v1-core-phase-11-m01', 'SSE (EventSource)', array['Explain and apply null in SSE (EventSource).', 'Use SSE (EventSource) to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate The EventSource API — how a client subscribes to a stream of server-sent events in a small working example.', 'Demonstrate Server-side implementation — keeping an HTTP connection open and writing event-formatted chunks in a small working example.', 'Demonstrate Automatic reconnection behavior built into EventSource in a small working example.', 'Demonstrate When SSE is sufficient: notifications, live feeds, progress updates — anything server-to-client only in a small working example.', 'Demonstrate The limitation that motivates WebSockets next: no client-to-server messages over the same connection in a small working example.']::text[], array['Submit a working SSE (EventSource) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m01-t02', 'zte-frontend-v1-core-phase-11-m01', 'WebSockets', array['Explain and apply Protocol Fundamentals in WebSockets.', 'Explain and apply Implementation in WebSockets.', 'Explain and apply Common Use Cases in WebSockets.']::text[], array['Demonstrate The WebSocket handshake — upgrading from HTTP to a persistent WebSocket connection in a small working example.', 'Demonstrate Frames, message types (text/binary), ping/pong keepalive in a small working example.', 'Demonstrate Setting up a WebSocket server (ws library or Socket.IO) alongside Express (Phase 05) in a small working example.', 'Demonstrate Client-side connection management — reconnection strategies, connection state in a small working example.', 'Demonstrate Broadcasting to multiple clients, rooms/channels for scoped broadcasts (Socket.IO-specific) in a small working example.']::text[], array['Submit a working WebSockets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m01-t01']::text[], '[]'::jsonb, 1200, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m01-t03', 'zte-frontend-v1-core-phase-11-m01', 'WebRTC', array['Explain and apply Core Concepts in WebRTC.', 'Explain and apply Data & Media Channels in WebRTC.']::text[], array['Demonstrate Peer-to-peer connections — why WebRTC bypasses the server for the actual media/data stream after setup in a small working example.', 'Demonstrate ICE, STUN, and TURN — how two peers behind NATs actually find and connect to each other in a small working example.', 'Demonstrate Signaling — the offer/answer exchange (SDP) that happens over WebSockets (2) before the peer connection is established in a small working example.', 'Demonstrate RTCDataChannel — peer-to-peer data transfer (not just audio/video) in a small working example.', 'Demonstrate MediaStream API — capturing camera/microphone for video calls in a small working example.']::text[], array['Submit a working WebRTC example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m01-t02']::text[], '[]'::jsonb, 1080, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-11-m02', 'zte-frontend-v1-core-phase-11', 2, 'PostgreSQL Index Depth', 'Requires Phase 05''s PostgreSQL fundamentals — this stage goes deeper into exactly the index/EXPLAIN ANALYZE territory Phase 05 introduced at a basic level.', 9.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m02-t01', 'zte-frontend-v1-core-phase-11-m02', 'B-Tree Indexes', array['Explain and apply null in B-Tree Indexes.', 'Use B-Tree Indexes to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate B-Tree structure — why it''s the default, and what "balanced tree" actually means for lookup performance in a small working example.', 'Demonstrate When a B-Tree index helps: equality and range queries, sorting in a small working example.', 'Demonstrate When a B-Tree index does NOT help — and gets ignored by the planner (ties back to Phase 05''s EXPLAIN ANALYZE) in a small working example.']::text[], array['Submit a working B-Tree Indexes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m02-t02', 'zte-frontend-v1-core-phase-11-m02', 'Composite Indexes', array['Explain and apply null in Composite Indexes.', 'Use Composite Indexes to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Column order matters — why an index on (a, b) doesn''t help a query filtering only on b in a small working example.', 'Demonstrate Covering indexes — when an index alone satisfies a query without touching the table in a small working example.', 'Demonstrate Multi-column index design in practice, for the Prisma schemas built in Phase 05 in a small working example.']::text[], array['Submit a working Composite Indexes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m02-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m02-t03', 'zte-frontend-v1-core-phase-11-m02', 'Partial Indexes', array['Explain and apply null in Partial Indexes.', 'Use Partial Indexes to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate WHERE clause on the index definition itself — indexing only rows matching a condition in a small working example.', 'Demonstrate Use case: indexing only active/non-deleted rows for a soft-delete pattern in a small working example.', 'Demonstrate Smaller index size and faster writes vs a full-table index, at the cost of only helping queries matching that same condition in a small working example.']::text[], array['Submit a working Partial Indexes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m02-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m02-t04', 'zte-frontend-v1-core-phase-11-m02', 'Materialized Views', array['Explain and apply null in Materialized Views.', 'Use Materialized Views to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Regular views vs materialized views — the difference between a saved query and a saved, physically-stored result in a small working example.', 'Demonstrate REFRESH MATERIALIZED VIEW — manual vs scheduled refresh strategies in a small working example.', 'Demonstrate When a materialized view beats indexing alone: expensive aggregations/joins queried repeatedly with acceptable staleness in a small working example.']::text[], array['Submit a working Materialized Views example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m02-t03']::text[], '[]'::jsonb, 240, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-11-m03', 'zte-frontend-v1-core-phase-11', 3, 'Storage & Concurrency Internals', 'The deepest topics in the phase. Ordered so MVCC comes first (it explains what VACUUM cleans up), then WAL (which read replicas directly depend on for replication), then monitoring (most useful once there''s real concurrent/replicated activity to observe).', 13.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m03-t01', 'zte-frontend-v1-core-phase-11-m03', 'VACUUM', array['Explain and apply null in VACUUM.', 'Use VACUUM to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate What VACUUM actually does — reclaiming space from dead tuples, updating statistics for the query planner in a small working example.', 'Demonstrate Autovacuum — PostgreSQL''s automatic background process, and when its defaults need tuning in a small working example.', 'Demonstrate VACUUM FULL — the more aggressive, table-locking variant, and why it''s rarely run casually in a small working example.', 'Demonstrate Table bloat — what happens when VACUUM falls behind on a high-write table in a small working example.']::text[], array['Submit a working VACUUM example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m03-t02', 'zte-frontend-v1-core-phase-11-m03', 'MVCC (Multi-Version Concurrency Control)', array['Explain and apply null in MVCC (Multi-Version Concurrency Control).', 'Use MVCC (Multi-Version Concurrency Control) to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Why PostgreSQL doesn''t use simple read locks — readers never block writers and vice versa in a small working example.', 'Demonstrate Row versioning — an UPDATE creates a new row version rather than overwriting in place; a DELETE marks a row dead rather than removing it immediately in a small working example.', 'Demonstrate Transaction visibility — how PostgreSQL determines which row versions a given transaction can see in a small working example.', 'Demonstrate Dead tuples — the direct consequence of MVCC''s versioning approach, and exactly what VACUUM (9) is for in a small working example.', 'Demonstrate Connecting this back to the isolation levels covered in Phase 05 — MVCC is the mechanism underneath them in a small working example.']::text[], array['Submit a working MVCC (Multi-Version Concurrency Control) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m03-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m03-t03', 'zte-frontend-v1-core-phase-11-m03', 'WAL (Write-Ahead Log)', array['Explain and apply null in WAL (Write-Ahead Log).', 'Use WAL (Write-Ahead Log) to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate The write-ahead logging principle — changes are logged before they''re applied to the actual data files, guaranteeing crash recovery in a small working example.', 'Demonstrate How WAL enables point-in-time recovery in a small working example.', 'Demonstrate WAL as the mechanism underlying replication (11) — replicas are built by streaming and replaying the WAL in a small working example.']::text[], array['Submit a working WAL (Write-Ahead Log) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m03-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m03-t04', 'zte-frontend-v1-core-phase-11-m03', 'Read Replicas', array['Explain and apply null in Read Replicas.', 'Use Read Replicas to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Streaming replication — how a replica stays in sync via WAL (10) in a small working example.', 'Demonstrate Read replicas for scaling read-heavy workloads — directing SELECT queries away from the primary in a small working example.', 'Demonstrate Replication lag — why replicas aren''t perfectly real-time, and the consistency implications in a small working example.', 'Demonstrate Failover concepts — promoting a replica to primary (conceptual) in a small working example.']::text[], array['Submit a working Read Replicas example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m03-t03']::text[], '[]'::jsonb, 240, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m03-t05', 'zte-frontend-v1-core-phase-11-m03', 'pg_stat_activity', array['Explain and apply null in pg_stat_activity.', 'Use pg_stat_activity to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Querying pg_stat_activity to see currently running queries and connections in a small working example.', 'Demonstrate Identifying long-running or blocked queries in real time in a small working example.', 'Demonstrate Connecting this back to PgBouncer (Phase 09) — diagnosing connection pool exhaustion in a small working example.']::text[], array['Submit a working pg_stat_activity example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m03-t04']::text[], '[]'::jsonb, 120, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-11-m04', 'zte-frontend-v1-core-phase-11', 4, 'Search', 'A genuinely independent theme from Stages 1–3, ordered from PostgreSQL''s built-in option (needing nothing new infrastructure-wise) to increasingly dedicated, heavyweight search engines.', 16, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m04-t01', 'zte-frontend-v1-core-phase-11-m04', 'PostgreSQL Full Text Search', array['Explain and apply null in PostgreSQL Full Text Search.', 'Use PostgreSQL Full Text Search to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate tsvector and tsquery — PostgreSQL''s text search data types in a small working example.', 'Demonstrate GIN indexes for full text search (connects back to Stage 2''s index depth) in a small working example.', 'Demonstrate Ranking search results (ts_rank) in a small working example.', 'Demonstrate Limitations — why PostgreSQL FTS eventually stops scaling for complex search needs, motivating dedicated search engines (14–16) in a small working example.']::text[], array['Submit a working PostgreSQL Full Text Search example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 540, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m04-t02', 'zte-frontend-v1-core-phase-11-m04', 'Meilisearch', array['Explain and apply null in Meilisearch.', 'Use Meilisearch to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Typo tolerance and instant search — the specific gaps PostgreSQL FTS (13) doesn''t fill well in a small working example.', 'Demonstrate Indexing documents from your PostgreSQL data (syncing strategy) in a small working example.', 'Demonstrate Filtering and faceted search in a small working example.', 'Demonstrate Meilisearch''s simplicity vs Elasticsearch''s power — the tradeoff this tool is positioned around in a small working example.']::text[], array['Submit a working Meilisearch example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m04-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m04-t03', 'zte-frontend-v1-core-phase-11-m04', 'Typesense', array['Explain and apply null in Typesense.', 'Use Typesense to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Core feature parity with Meilisearch — typo tolerance, instant search, faceting in a small working example.', 'Demonstrate Where Typesense differs — schema requirements, specific performance characteristics in a small working example.', 'Demonstrate Choosing between Meilisearch and Typesense for a given project in a small working example.']::text[], array['Submit a working Typesense example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m04-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-m04-t04', 'zte-frontend-v1-core-phase-11-m04', 'Elasticsearch', array['Explain and apply null in Elasticsearch.', 'Use Elasticsearch to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Inverted index — the core data structure behind Elasticsearch''s search performance in a small working example.', 'Demonstrate Documents, indices, mappings — Elasticsearch''s data model in a small working example.', 'Demonstrate Query DSL — structuring complex search queries in a small working example.', 'Demonstrate When Elasticsearch''s operational complexity (cluster management, resource requirements) is actually justified vs when Meilisearch/Typesense (14, 15) would have been enough in a small working example.']::text[], array['Submit a working Elasticsearch example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-frontend-v1-core-phase-11-m04-t03']::text[], '[]'::jsonb, 720, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-project-01', 'zte-frontend-v1-core-phase-11', 'Peer-to-Peer Video Chat', 'A 1:1 video call app using WebRTC with a signaling server (over WebSockets), including screen-share support and graceful handling of connection failures/ICE negotiation issues. Domain: communication tools.', array['Deliver the working outcome described in the Peer-to-Peer Video Chat brief.', 'Use at least two skills from Real-Time Communication.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Peer-to-Peer Video Chat', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Real-Time Communication']::text[], 'advanced', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-project-02', 'zte-frontend-v1-core-phase-11', 'Materialized View Reporting Dashboard', 'Build a reporting dashboard backed by materialized views for expensive aggregate queries (e.g., daily sales rollups), with a documented refresh strategy (scheduled vs on-demand) and a before/after query-time comparison vs. querying raw tables directly.', array['Deliver the working outcome described in the Materialized View Reporting Dashboard brief.', 'Use at least two skills from PostgreSQL Index Depth.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Materialized View Reporting Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'PostgreSQL Index Depth']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-project-03', 'zte-frontend-v1-core-phase-11', 'MVCC Behavior Demonstration Lab', 'A hands-on demo (two concurrent psql sessions) that reproduces and documents MVCC behavior: a long-running transaction not seeing another session’s committed changes, then explains what VACUUM is cleaning up afterward, with pg_stat_activity screenshots showing the live transaction state.', array['Deliver the working outcome described in the MVCC Behavior Demonstration Lab brief.', 'Use at least two skills from Storage & Concurrency Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working MVCC Behavior Demonstration Lab', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Storage & Concurrency Internals']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-project-04', 'zte-frontend-v1-core-phase-11', 'Read Replica Lag Simulation', 'Set up a primary + read replica PostgreSQL setup (locally via Docker), write to primary, read from replica, and deliberately induce and measure replication lag under write load, documenting a strategy for handling read-after-write consistency issues in application code.', array['Deliver the working outcome described in the Read Replica Lag Simulation brief.', 'Use at least two skills from Storage & Concurrency Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Read Replica Lag Simulation', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Storage & Concurrency Internals']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-project-05', 'zte-frontend-v1-core-phase-11', 'Instant Search-As-You-Type with Meilisearch', 'A product catalog with typo-tolerant, sub-50ms instant search using Meilisearch, including faceted filtering (category, price range) synced from the primary database. Domain: e-commerce.', array['Deliver the working outcome described in the Instant Search-As-You-Type with Meilisearch brief.', 'Use at least two skills from Search.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Instant Search-As-You-Type with Meilisearch', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Search']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-project-06', 'zte-frontend-v1-core-phase-11', 'Search Engine Bake-Off', 'Index the identical dataset (e.g., 50k products) into Postgres full-text search, Typesense, and Elasticsearch, then benchmark query latency, relevance quality, and typo tolerance across all three with a written recommendation for different use-case scales. Domain: search infrastructure / platform engineering.', array['Deliver the working outcome described in the Search Engine Bake-Off brief.', 'Use at least two skills from Search.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Search Engine Bake-Off', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Search']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-11-project-07', 'zte-frontend-v1-core-phase-11', 'A Real-Time Collaborative Marketplace with Enterprise-Grade Search', 'A live marketplace/auction-style platform combining: WebSocket-based real-time bidding with room-scoped broadcasts and an SSE-based public "live activity feed," a PostgreSQL schema tuned with composite and partial indexes validated via EXPLAIN ANALYZE, materialized-view-backed seller analytics dashboards, documented MVCC/replication behavior from a local primary+replica setup, and Elasticsearch-powered faceted, typo-tolerant listing search benchmarked against a Postgres full-text fallback. Domain: marketplace / e-commerce infrastructure. Why it matters: real-time interactivity and fast, relevant search are the two hardest-to-fake capabilities in consumer products — this project proves you can build both on solid database fundamentals, not just bolt on a SaaS widget.', array['Deliver the working outcome described in the A Real-Time Collaborative Marketplace with Enterprise-Grade Search brief.', 'Use at least two skills from Real-Time + Search + PostgreSQL Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Real-Time Collaborative Marketplace with Enterprise-Grade Search', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-12', 'zte-frontend-v1', id, '14', 'AI/RAG + Production AI Patterns', 'Advanced', 'Requires a real backend (Phase 05\\) to call these APIs from server-side, and background/job infrastructure context (Phase 09''s Redis) that Stage 4 will build on. OpenAI is placed first as the first provider learned; Anthropic follows as the second, before anything compares or routes between them.', 207, 13 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-12-m01', 'zte-frontend-v1-core-phase-12', 1, 'LLM API Foundations', 'Requires a real backend (Phase 05\\) to call these APIs from server-side, and background/job infrastructure context (Phase 09''s Redis) that Stage 4 will build on. OpenAI is placed first as the first provider learned; Anthropic follows as the second, before anything compares or routes between them.', 8.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m01-t01', 'zte-frontend-v1-core-phase-12-m01', 'OpenAI API', array['Explain and apply null in OpenAI API.', 'Use OpenAI API to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Authentication and client setup — API keys, environment variable handling (ties back to Phase 01''s Node.js env patterns) in a small working example.', 'Demonstrate Chat completions — the core request/response shape in a small working example.', 'Demonstrate Streaming responses — token-by-token output instead of waiting for the full completion in a small working example.', 'Demonstrate Function/tool definitions at the API level (foundational for Stage 6''s structured extraction) in a small working example.', 'Demonstrate Error handling — rate limits, context length errors, retries in a small working example.']::text[], array['Submit a working OpenAI API example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m01-t02', 'zte-frontend-v1-core-phase-12-m01', 'GPT-4o', array['Explain and apply null in GPT-4o.', 'Use GPT-4o to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate GPT-4o''s multimodal capabilities — text, image, audio input in one model in a small working example.', 'Demonstrate Context window size and practical implications for RAG (Stage 3) and long conversations in a small working example.', 'Demonstrate Where GPT-4o sits in OpenAI''s model lineup — cost/capability tradeoff vs smaller models in a small working example.']::text[], array['Submit a working GPT-4o example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m01-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m01-t03', 'zte-frontend-v1-core-phase-12-m01', 'Anthropic API', array['Explain and apply null in Anthropic API.', 'Use Anthropic API to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Authentication and client setup — parallels OpenAI (1), with real differences in request/response shape in a small working example.', 'Demonstrate Messages API — Anthropic''s core request format in a small working example.', 'Demonstrate Streaming responses in a small working example.', 'Demonstrate System prompts as a first-class, separate parameter — a structural difference from OpenAI''s message-array approach worth noting explicitly in a small working example.']::text[], array['Submit a working Anthropic API example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m01-t02']::text[], '[]'::jsonb, 300, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-12-m02', 'zte-frontend-v1-core-phase-12', 2, 'Embeddings & Vector Storage and RAG (The Synthesis)', 'Requires OpenAI API access (Stage 1\\) for the embedding model itself, and Phase 05/11''s PostgreSQL depth as the storage layer these vectors live in.', 9.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m02-t01', 'zte-frontend-v1-core-phase-12-m02', 'text-embedding-3-small', array['Explain and apply null in text-embedding-3-small.', 'Use text-embedding-3-small to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate What an embedding actually is — a fixed-length vector representing semantic meaning in a small working example.', 'Demonstrate Why "small" — the cost/dimensionality tradeoff vs larger embedding models in a small working example.', 'Demonstrate Cosine similarity as the standard way to compare two embeddings for semantic closeness in a small working example.', 'Demonstrate Batching embedding requests for efficiency in a small working example.']::text[], array['Submit a working text-embedding-3-small example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m02-t02', 'zte-frontend-v1-core-phase-12-m02', 'pgvector', array['Explain and apply null in pgvector.', 'Use pgvector to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate The vector column type — storing embeddings directly in PostgreSQL rows alongside relational data in a small working example.', 'Demonstrate Distance operators — L2, cosine distance, inner product — and which matches text-embedding-3-small''s intended usage in a small working example.', 'Demonstrate Why storing vectors in PostgreSQL (vs a dedicated vector database) is often the right call — no new infrastructure, joins with existing relational data (ties back to Phase 05''s schema design) in a small working example.', 'Demonstrate Basic similarity search — ORDER BY embedding <=> query_vector LIMIT n in a small working example.']::text[], array['Submit a working pgvector example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m02-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m02-t03', 'zte-frontend-v1-core-phase-12-m02', 'IVFFlat Index', array['Explain and apply null in IVFFlat Index.', 'Use IVFFlat Index to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Why a sequential scan becomes too slow for similarity search as a table grows — the same motivation as B-Tree indexes in Phase 11, applied to vectors in a small working example.', 'Demonstrate IVFFlat''s approach — clustering vectors into lists, searching only the nearest clusters in a small working example.', 'Demonstrate Tuning the lists parameter — the recall/speed tradeoff in a small working example.', 'Demonstrate When IVFFlat needs to be rebuilt as data grows in a small working example.']::text[], array['Submit a working IVFFlat Index example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m02-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m02-t04', 'zte-frontend-v1-core-phase-12-m02', 'HNSW Index', array['Explain and apply null in HNSW Index.', 'Use HNSW Index to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate HNSW''s approach — a navigable graph structure, vs IVFFlat''s clustering approach in a small working example.', 'Demonstrate Build time and memory cost — HNSW is typically more expensive to build than IVFFlat in a small working example.', 'Demonstrate Query performance and recall — why HNSW is often preferred despite the build cost in a small working example.', 'Demonstrate Choosing between IVFFlat and HNSW for a given dataset size and update frequency in a small working example.']::text[], array['Submit a working HNSW Index example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m02-t03']::text[], '[]'::jsonb, 240, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m02-t05', 'zte-frontend-v1-core-phase-12-m02', 'RAG Pattern', array['Explain and apply Core Pipeline in RAG Pattern.', 'Explain and apply Retrieval Quality in RAG Pattern.', 'Explain and apply Production Concerns in RAG Pattern.']::text[], array['Demonstrate Chunking strategy — fixed-size, semantic, and hierarchical chunking, and the tradeoffs between them in a small working example.', 'Demonstrate Embedding chunks and storing them via pgvector (Stage 2) in a small working example.', 'Demonstrate Retrieval — similarity search against the query''s embedding to find relevant chunks in a small working example.', 'Demonstrate Augmentation — inserting retrieved chunks into the LLM prompt as context in a small working example.', 'Demonstrate Generation — the LLM (Stage 1) producing a response grounded in retrieved context in a small working example.']::text[], array['Submit a working RAG Pattern example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m02-t04']::text[], '[]'::jsonb, 1440, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-12-m03', 'zte-frontend-v1-core-phase-12', 3, 'SDK & Background Jobs', 'Requires RAG (Stage 3\\) to exist as real work worth simplifying (Vercel AI SDK) and queuing (BullMQ) — introducing these tools before there''s a real pipeline to apply them to would make them abstract.', 8, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m03-t01', 'zte-frontend-v1-core-phase-12-m03', 'Vercel AI SDK', array['Explain and apply null in Vercel AI SDK.', 'Use Vercel AI SDK to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Unified interface across OpenAI and Anthropic (Stage 1) — one API surface for multiple providers in a small working example.', 'Demonstrate Streaming helpers — simplifying the token-by-token streaming already understood from Stage 1 in a small working example.', 'Demonstrate useChat and related React hooks (ties back to Phase 02) for wiring streaming responses into a UI in a small working example.', 'Demonstrate Tool calling support built into the SDK (foreshadows Stage 6) in a small working example.']::text[], array['Submit a working Vercel AI SDK example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 420, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m03-t02', 'zte-frontend-v1-core-phase-12-m03', 'BullMQ', array['Explain and apply null in BullMQ.', 'Use BullMQ to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Why embedding generation and document indexing belong in a background job, not an inline request/response cycle in a small working example.', 'Demonstrate Queue, worker, and job concepts — producer/consumer model in a small working example.', 'Demonstrate Job priority, concurrency limits, and rate limiting API calls to OpenAI/Anthropic (Stage 1) to avoid hitting provider rate limits in a small working example.', 'Demonstrate Retry strategies and dead-letter queues (DLQ) for jobs that fail repeatedly in a small working example.', 'Demonstrate Idempotency in job processing — ties back to Phase 09''s Razorpay webhook idempotency discussion, same underlying problem in a small working example.']::text[], array['Submit a working BullMQ example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m03-t01']::text[], '[]'::jsonb, 960, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m03-t03', 'zte-frontend-v1-core-phase-12-m03', 'Bull Board', array['Explain and apply null in Bull Board.', 'Use Bull Board to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Visualizing queue state — active, waiting, completed, failed jobs in a small working example.', 'Demonstrate Manually retrying or removing failed jobs from the dashboard in a small working example.', 'Demonstrate Using this for production AI job monitoring — a concrete artifact showing "production AI, not toy AI," per the official curriculum''s own framing in a small working example.']::text[], array['Submit a working Bull Board example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m03-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-12-m04', 'zte-frontend-v1-core-phase-12', 4, 'Claude-Specific Depth', 'Requires the Anthropic API (Stage 1, Topic 3\\) as the foundation — these three topics are all Claude-specific behavior on top of the basic Messages API already covered.', 5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m04-t01', 'zte-frontend-v1-core-phase-12-m04', 'Claude Model Tier Strategy', array['Explain and apply null in Claude Model Tier Strategy.', 'Use Claude Model Tier Strategy to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Haiku vs Sonnet vs Opus — the cost/capability/speed tradeoff across Anthropic''s model tiers in a small working example.', 'Demonstrate Matching a task to the right tier — classification/extraction (cheaper tier) vs complex generation (higher tier) in a small working example.', 'Demonstrate This is the first concrete decision-point that Stage 7''s cost tracking will later measure in a small working example.']::text[], array['Submit a working Claude Model Tier Strategy example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m04-t02', 'zte-frontend-v1-core-phase-12-m04', 'Extended Thinking', array['Explain and apply null in Extended Thinking.', 'Use Extended Thinking to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate What extended thinking does — allowing the model additional reasoning tokens before producing a final answer in a small working example.', 'Demonstrate When it measurably improves output quality — complex multi-step reasoning tasks in a small working example.', 'Demonstrate Cost and latency tradeoff of enabling it in a small working example.']::text[], array['Submit a working Extended Thinking example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m04-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m04-t03', 'zte-frontend-v1-core-phase-12-m04', 'Prompt Caching', array['Explain and apply null in Prompt Caching.', 'Use Prompt Caching to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate What gets cached — typically large, repeated portions of a prompt (system prompts, RAG context from Stage 3) in a small working example.', 'Demonstrate Cache hit economics — the cost reduction ROI for repeated context across requests in a small working example.', 'Demonstrate Cache invalidation — when cached content stops being reusable in a small working example.', 'Demonstrate Designing prompts specifically to maximize cacheable portions (structuring stable content before dynamic content) in a small working example.']::text[], array['Submit a working Prompt Caching example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m04-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-12-m05', 'zte-frontend-v1-core-phase-12', 5, 'Structured Output & Multi-Model Routing', 'Both topics require both providers (Stage 1\\) to be genuinely understood — tool calling is commonly needed across either provider, and routing is meaningless with only one model to route to.', 6, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m05-t01', 'zte-frontend-v1-core-phase-12-m05', 'Tool Calling for Structured Extraction', array['Explain and apply null in Tool Calling for Structured Extraction.', 'Use Tool Calling for Structured Extraction to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Defining tool/function schemas — parameter types, descriptions the model uses to decide when and how to call a tool in a small working example.', 'Demonstrate The extraction pattern — using tool calling not to actually call a function, but to force the model into producing structured JSON output in a small working example.', 'Demonstrate Validating tool call outputs — ties back to Zod (Phases 01/03/05) for runtime validation of what the model returns in a small working example.', 'Demonstrate Multi-turn tool use — handling a model''s tool call, executing it, and returning results for the model to continue reasoning with in a small working example.']::text[], array['Submit a working Tool Calling for Structured Extraction example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m05-t02', 'zte-frontend-v1-core-phase-12-m05', 'Multi-Model Routing', array['Explain and apply null in Multi-Model Routing.', 'Use Multi-Model Routing to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Routing logic — sending a request to the model best suited for it, not defaulting to one provider for everything in a small working example.', 'Demonstrate Common routing signals: task complexity, cost sensitivity, latency requirements, specific capability needs (e.g. Claude''s extended thinking, Stage 5, vs GPT-4o''s multimodal input, Stage 1) in a small working example.', 'Demonstrate Fallback strategies — routing to a secondary provider if the primary is rate-limited or down in a small working example.', 'Demonstrate This is the decision-making skill the official curriculum explicitly flags as what separates a real AI engineer from someone who can only call one API in a small working example.']::text[], array['Submit a working Multi-Model Routing example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m05-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-12-m06', 'zte-frontend-v1-core-phase-12', 6, 'Cost & Governance', 'Requires real multi-model usage (Stage 6\\) to have actual costs across providers worth tracking and governing — introducing cost tracking before there''s real usage would have nothing to measure.', 4, 5) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m06-t01', 'zte-frontend-v1-core-phase-12-m06', 'AI Cost Tracking', array['Explain and apply null in AI Cost Tracking.', 'Use AI Cost Tracking to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Token counting — input vs output tokens, and why output tokens typically cost more in a small working example.', 'Demonstrate Per-request cost calculation across different models/providers (Stage 1, Stage 5''s tier strategy, Stage 6''s routing) in a small working example.', 'Demonstrate Building a cost dashboard — the concrete artifact the official curriculum calls out as something to highlight in a portfolio in a small working example.', 'Demonstrate Attributing cost to specific features/users for accurate reporting in a small working example.']::text[], array['Submit a working AI Cost Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m06-t02', 'zte-frontend-v1-core-phase-12-m06', 'Token Budget Enforcement', array['Explain and apply null in Token Budget Enforcement.', 'Use Token Budget Enforcement to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Setting per-user or per-feature token budgets in a small working example.', 'Demonstrate Enforcing budgets before a request is sent (pre-flight estimation) vs after (post-hoc alerting) in a small working example.', 'Demonstrate Graceful degradation when a budget is exceeded — routing to a cheaper model (Stage 6) rather than simply failing in a small working example.']::text[], array['Submit a working Token Budget Enforcement example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m06-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-12-m07', 'zte-frontend-v1-core-phase-12', 7, 'Prompt Engineering & Evaluation', 'Requires real AI features to exist (RAG from Stage 3, tool calling from Stage 6\\) — both prompt engineering and evaluation are meaningfully practiced against real, built systems, not in the abstract. Evals are placed genuinely last since you need something built before you can evaluate it.', 9, 6) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m07-t01', 'zte-frontend-v1-core-phase-12-m07', 'System Prompt Engineering', array['Explain and apply null in System Prompt Engineering.', 'Use System Prompt Engineering to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Structuring system prompts — role definition, constraints, output format instructions in a small working example.', 'Demonstrate Few-shot examples within a prompt — when they measurably improve output vs adding noise in a small working example.', 'Demonstrate Prompt injection awareness — treating user input as untrusted within a prompt (security parallel to Phase 02''s XSS/sanitization concerns) in a small working example.', 'Demonstrate Iterating on prompts systematically rather than by trial and error — setting up the mindset Stage 8''s evals (20) will formalize in a small working example.']::text[], array['Submit a working System Prompt Engineering example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-m07-t02', 'zte-frontend-v1-core-phase-12-m07', 'Eval-Driven AI Development', array['Explain and apply null in Eval-Driven AI Development.', 'Use Eval-Driven AI Development to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Building an eval set — representative test cases with expected outputs or grading criteria in a small working example.', 'Demonstrate Metrics that matter beyond "it works": precision/recall for retrieval (Stage 3), exact-match or rubric-based scoring for generation in a small working example.', 'Demonstrate LLM-as-judge — using a model to grade another model''s output, and its limitations in a small working example.', 'Demonstrate Regression testing for prompts — catching quality drops when a prompt or model version changes (ties back to Phase 06''s CI/CD, running evals as part of a pipeline) in a small working example.', 'Demonstrate This is the practice the official curriculum frames as the actual differentiator in interviews — showing how you measure AI quality, not just that a feature works in a small working example.']::text[], array['Submit a working Eval-Driven AI Development example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-12-m07-t01']::text[], '[]'::jsonb, 960, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-01', 'zte-frontend-v1-core-phase-12', 'Multi-Provider Prompt Playground', 'A small internal tool that sends the same prompt to both the OpenAI API (GPT-4o) and the Anthropic API side-by-side, displaying responses, latency, and token usage for comparison. Domain: AI tooling / evaluation.', array['Deliver the working outcome described in the Multi-Provider Prompt Playground brief.', 'Use at least two skills from LLM API Foundations.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Provider Prompt Playground', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'LLM API Foundations']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-02', 'zte-frontend-v1-core-phase-12', 'Structured Support-Ticket Classifier', 'A backend service that classifies incoming support tickets (category, urgency, sentiment) using an LLM API call, with proper error handling for API failures/timeouts and a fallback rule-based classifier if the API is unavailable. Domain: customer support automation.', array['Deliver the working outcome described in the Structured Support-Ticket Classifier brief.', 'Use at least two skills from LLM API Foundations.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Structured Support-Ticket Classifier', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'LLM API Foundations']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-03', 'zte-frontend-v1-core-phase-12', 'Semantic Duplicate Detector', 'A tool that embeds a set of support tickets or forum posts (text-embedding-3-small) and finds semantic duplicates/near-duplicates using cosine similarity in pgvector, catching duplicates that keyword search would miss. Domain: content moderation / support tooling.', array['Deliver the working outcome described in the Semantic Duplicate Detector brief.', 'Use at least two skills from Embeddings & Vector Storage and RAG (The Synthesis).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Semantic Duplicate Detector', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Embeddings & Vector Storage and RAG (The Synthesis)']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-04', 'zte-frontend-v1-core-phase-12', 'HNSW vs IVFFlat Benchmark', 'Index the same 100k-vector embedding set with both IVFFlat and HNSW in pgvector, benchmarking query latency and recall accuracy tradeoffs at different index parameters, with a written recommendation document. Domain: vector search infrastructure.', array['Deliver the working outcome described in the HNSW vs IVFFlat Benchmark brief.', 'Use at least two skills from Embeddings & Vector Storage and RAG (The Synthesis).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working HNSW vs IVFFlat Benchmark', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Embeddings & Vector Storage and RAG (The Synthesis)']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-05', 'zte-frontend-v1-core-phase-12', 'Multi-Document Research Assistant with Chunking Strategy Comparison', 'A RAG pipeline over a corpus of long-form documents (e.g., legal or research PDFs) that compares 3 different chunking strategies (fixed-size, semantic, sliding-window-with-overlap) on retrieval quality for the same question set, with a written evaluation report. Domain: legal-tech / research tooling.', array['Deliver the working outcome described in the Multi-Document Research Assistant with Chunking Strategy Comparison brief.', 'Use at least two skills from RAG (The Synthesis).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Document Research Assistant with Chunking Strategy Comparison', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'RAG (The Synthesis)']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-06', 'zte-frontend-v1-core-phase-12', 'Streaming AI Chat UI', 'A chat interface using the Vercel AI SDK with true token-by-token streaming responses, stop/regenerate controls, and conversation history persistence. Domain: AI product UX. A system where users submit a batch of documents for AI summarization; jobs are queued in BullMQ (not processed synchronously in the request), with a Bull Board dashboard for monitoring job status, retries, and failures. Domain: AI infrastructure / batch processing.', array['Deliver the working outcome described in the Streaming AI Chat UI brief.', 'Use at least two skills from SDK & Background Jobs.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Streaming AI Chat UI', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'SDK & Background Jobs']::text[], 'intermediate', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-07', 'zte-frontend-v1-core-phase-12', 'Cost-Optimized Multi-Tier Support Bot', 'A support bot that routes simple questions to a smaller/cheaper Claude model tier and escalates complex questions to a larger tier, with prompt caching applied to the large, static system prompt/knowledge base portion to cut repeated-request cost. Domain: AI cost engineering.', array['Deliver the working outcome described in the Cost-Optimized Multi-Tier Support Bot brief.', 'Use at least two skills from Claude-Specific Depth.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cost-Optimized Multi-Tier Support Bot', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Claude-Specific Depth']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-08', 'zte-frontend-v1-core-phase-12', 'Receipt-to-Structured-Data Extractor', 'A tool that takes a photo/text of a receipt and uses tool calling to extract guaranteed-valid structured JSON (line items, totals, tax) validated against a schema, with a test suite of malformed/tricky receipts. Domain: fintech / expense automation.', array['Deliver the working outcome described in the Receipt-to-Structured-Data Extractor brief.', 'Use at least two skills from Structured Output & Multi-Model Routing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Receipt-to-Structured-Data Extractor', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Structured Output & Multi-Model Routing']::text[], 'intermediate', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-09', 'zte-frontend-v1-core-phase-12', 'Cost-Aware Multi-Model Router', 'A routing layer that sends each incoming request to the cheapest model capable of handling it correctly (classified by a lightweight pre-check), falling back to a stronger model on low-confidence responses, with logged cost savings versus an always-use-the-best-model baseline. Domain: AI infrastructure / cost engineering.', array['Deliver the working outcome described in the Cost-Aware Multi-Model Router brief.', 'Use at least two skills from Structured Output & Multi-Model Routing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cost-Aware Multi-Model Router', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Structured Output & Multi-Model Routing']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-10', 'zte-frontend-v1-core-phase-12', 'Prompt Version Control & Regression Suite', 'A system prompt library with versioned prompts and an automated eval suite (a fixed set of test inputs with expected-quality criteria) that runs on every prompt change to catch regressions before deploying a new prompt version. Domain: AI engineering / MLOps.', array['Deliver the working outcome described in the Prompt Version Control & Regression Suite brief.', 'Use at least two skills from Prompt Engineering & Evaluation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Prompt Version Control & Regression Suite', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Prompt Engineering & Evaluation']::text[], 'intermediate', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-11', 'zte-frontend-v1-core-phase-12', 'Eval-Driven Support Bot Improvement Cycle', 'Take the Stage 5 support bot, build a 30-example golden eval dataset with graded expected outputs, establish a baseline score, then iterate on the system prompt 3 times, re-running the eval each time and documenting the score progression and specific failure modes fixed. Domain: AI quality engineering.', array['Deliver the working outcome described in the Eval-Driven Support Bot Improvement Cycle brief.', 'Use at least two skills from Prompt Engineering & Evaluation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Eval-Driven Support Bot Improvement Cycle', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Prompt Engineering & Evaluation']::text[], 'advanced', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-12-project-12', 'zte-frontend-v1-core-phase-12', 'A Cost-Governed, Eval-Tested RAG Support Platform', 'A complete production-pattern AI support platform: a documentation-grounded RAG pipeline (pgvector, chunking strategy chosen via comparison testing, citation tracking), a cost-optimized multi-tier Claude routing layer with prompt caching on the static knowledge base, tool-calling-based structured ticket extraction validated with Zod, BullMQ-queued background processing for bulk document ingestion with a Bull Board monitoring dashboard, a real-time AI cost dashboard with hard budget enforcement per organization, and a versioned prompt library backed by an automated golden-dataset eval suite that must pass before any prompt change ships. Domain: enterprise AI / support automation. Why it matters: this is what separates "called an LLM API" from "built a production AI system" — grounding, cost control, and evaluation discipline are the actual hard parts.', array['Deliver the working outcome described in the A Cost-Governed, Eval-Tested RAG Support Platform brief.', 'Use at least two skills from AI/RAG + Production AI Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Cost-Governed, Eval-Tested RAG Support Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'engineering documentation']::text[], 'advanced', 11) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-13', 'zte-frontend-v1', id, '15', 'Advanced Browser APIs + Collaboration', 'Advanced', 'Requires Phase 02''s localStorage/sessionStorage as the point of comparison — IndexedDB is what those simpler APIs can''t handle: large, structured, queryable client-side data.', 137, 14 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-13-m01', 'zte-frontend-v1-core-phase-13', 1, 'Client-Side Storage', 'Requires Phase 02''s localStorage/sessionStorage as the point of comparison — IndexedDB is what those simpler APIs can''t handle: large, structured, queryable client-side data.', 5.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m01-t01', 'zte-frontend-v1-core-phase-13-m01', 'IndexedDB', array['Explain and apply Core Concepts in IndexedDB.', 'Explain and apply Working with Data in IndexedDB.', 'Explain and apply Practical Use in IndexedDB.']::text[], array['Demonstrate Why IndexedDB exists — localStorage''s synchronous, string-only, size-limited model breaks down for real offline-capable apps in a small working example.', 'Demonstrate Databases, object stores, and transactions — IndexedDB''s structural model in a small working example.', 'Demonstrate Keys and key paths — auto-incrementing keys vs application-defined keys in a small working example.', 'Demonstrate CRUD operations via the raw IndexedDB API — verbose, callback/event-based by design in a small working example.', 'Demonstrate Indexes — querying by a field other than the primary key in a small working example.']::text[], array['Submit a working IndexedDB example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m01-t02', 'zte-frontend-v1-core-phase-13-m01', 'idb', array['Explain and apply null in idb.', 'Use idb to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why idb exists — IndexedDB''s raw API is unusually verbose and callback-heavy for a modern codebase in a small working example.', 'Demonstrate Promise-based CRUD operations — the same concepts as Topic 1, with async/await instead of event listeners in a small working example.', 'Demonstrate When to use the raw API directly vs idb — idb covers the vast majority of real use cases in a small working example.']::text[], array['Submit a working idb example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m01-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-13-m02', 'zte-frontend-v1-core-phase-13', 2, 'Parallelism and Cross-Context Communication', 'Study and apply Parallelism and Cross-Context Communication in Advanced Browser APIs + Collaboration.', 4.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m02-t01', 'zte-frontend-v1-core-phase-13-m02', 'Web Workers', array['Explain and apply null in Web Workers.', 'Use Web Workers to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why the main thread matters — JavaScript''s single-threaded execution model and what blocks it (ties back to Phase 01''s event loop) in a small working example.', 'Demonstrate Creating a worker, postMessage/onmessage communication — the structured-clone messaging model in a small working example.', 'Demonstrate What workers can and can''t access — no DOM access, separate global scope in a small working example.', 'Demonstrate Use cases: expensive computation (parsing, image processing), keeping the UI responsive during heavy work in a small working example.']::text[], array['Submit a working Web Workers example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 600, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m02-t02', 'zte-frontend-v1-core-phase-13-m02', 'comlink', array['Explain and apply null in comlink.', 'Use comlink to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why raw postMessage-based worker communication gets unwieldy for anything beyond trivial message-passing in a small working example.', 'Demonstrate comlink''s proxy-based API — calling worker functions as if they were local async functions in a small working example.', 'Demonstrate When the raw API (3) is still clearer vs when comlink''s abstraction is worth adopting in a small working example.']::text[], array['Submit a working comlink example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m02-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m02-t03', 'zte-frontend-v1-core-phase-13-m02', 'Broadcast Channel API', array['Explain and apply null in Broadcast Channel API.', 'Use Broadcast Channel API to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Creating a named channel and posting messages to it in a small working example.', 'Demonstrate All same-origin tabs/windows/workers subscribed to the same channel receive the message — the key difference from postMessage''s point-to-point model in a small working example.', 'Demonstrate Use cases: syncing auth state across tabs (logging out in one tab logs out all tabs, ties back to Phase 05''s JWT/session handling), syncing UI state across multiple open windows of the same app in a small working example.']::text[], array['Submit a working Broadcast Channel API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m02-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-13-m03', 'zte-frontend-v1-core-phase-13', 3, 'Browser Rendering & Animation Internals', 'A cluster of APIs concerned with how and when the browser paints — ordered from the lowest-level timing primitive (rAF) to the most advanced/niche (CSS Houdini).', 7.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m03-t01', 'zte-frontend-v1-core-phase-13-m03', 'View Transitions API', array['Explain and apply null in View Transitions API.', 'Use View Transitions API to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate document.startViewTransition() — the core API for triggering a transition between two DOM states in a small working example.', 'Demonstrate How the browser captures before/after snapshots and animates between them automatically in a small working example.', 'Demonstrate Named transitions (view-transition-name) for controlling which elements get their own distinct animation in a small working example.', 'Demonstrate Use cases: page transitions in an SPA (Phase 02''s App Router), smooth state changes without hand-rolled animation logic in a small working example.']::text[], array['Submit a working View Transitions API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m03-t02', 'zte-frontend-v1-core-phase-13-m03', 'requestAnimationFrame', array['Explain and apply null in requestAnimationFrame.', 'Use requestAnimationFrame to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why requestAnimationFrame exists — syncing JavaScript-driven animation with the browser''s actual repaint cycle, instead of guessing with setTimeout (Phase 01) in a small working example.', 'Demonstrate The callback timing guarantee — running right before the next repaint in a small working example.', 'Demonstrate Canceling a scheduled frame (cancelAnimationFrame) in a small working example.', 'Demonstrate Common pattern: using rAF for smooth, manually-driven animations (scroll-linked effects, custom easing) in a small working example.']::text[], array['Submit a working requestAnimationFrame example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m03-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m03-t03', 'zte-frontend-v1-core-phase-13-m03', 'requestIdleCallback', array['Explain and apply null in requestIdleCallback.', 'Use requestIdleCallback to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate The difference from rAF — rIC runs when the browser is otherwise idle, not on every frame in a small working example.', 'Demonstrate Use cases: low-priority background work (analytics batching, prefetching) that shouldn''t compete with rendering or user input in a small working example.', 'Demonstrate The timeout option — forcing execution even if the browser never reports idle time in a small working example.', 'Demonstrate Browser support caveats and Safari''s lack of support (practical consideration) in a small working example.']::text[], array['Submit a working requestIdleCallback example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m03-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m03-t04', 'zte-frontend-v1-core-phase-13-m03', 'CSS Houdini', array['Explain and apply null in CSS Houdini.', 'Use CSS Houdini to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate What Houdini exposes — low-level access to the CSS rendering pipeline (paint, layout, properties) that was previously entirely opaque to developers in a small working example.', 'Demonstrate CSS Paint API — defining custom paint worklets for background-image-style custom rendering in a small working example.', 'Demonstrate Properties and Values API — registering custom CSS properties with actual types (not just strings), enabling smooth animation of previously non-animatable values in a small working example.', 'Demonstrate Realistic scope — Houdini''s browser support and practical adoption level today, versus its role as a forward-looking spec in a small working example.']::text[], array['Submit a working CSS Houdini example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m03-t03']::text[], '[]'::jsonb, 300, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-13-m04', 'zte-frontend-v1-core-phase-13', 4, 'Real-Time Collaboration: The Yjs Stack', 'The centerpiece of this phase, and the official curriculum''s designated Build in Public moment. Requires WebSockets and WebRTC (Phase 11\\) as transport context, and IndexedDB (Stage 1\\) as a persistence context — Yjs itself is transport- and storage-agnostic, and only makes sense once you understand what it''s being connected to.', 12.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m04-t01', 'zte-frontend-v1-core-phase-13-m04', 'Yjs', array['Explain and apply CRDT Fundamentals in Yjs.', 'Explain and apply Working with Yjs in Yjs.', 'Explain and apply Transport-Agnostic Design in Yjs.']::text[], array['Demonstrate What a CRDT (Conflict-free Replicated Data Type) is — data structures that can be modified concurrently by multiple users and always converge to the same state without central coordination in a small working example.', 'Demonstrate Why this matters for real-time collaboration — no server-side operational transform logic needed, unlike older collaborative editing approaches in a small working example.', 'Demonstrate Shared types — Y.Text, Y.Array, Y.Map — the building blocks for collaborative documents in a small working example.', 'Demonstrate Documents (Y.Doc) as the root container for shared state in a small working example.', 'Demonstrate Observing changes — subscribing to updates from remote peers in a small working example.']::text[], array['Submit a working Yjs example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 1140, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m04-t02', 'zte-frontend-v1-core-phase-13-m04', 'Hocuspocus', array['Explain and apply null in Hocuspocus.', 'Use Hocuspocus to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why a dedicated server framework — running y-websocket directly works for prototypes, but production use needs auth, persistence hooks, and scaling considerations Hocuspocus provides in a small working example.', 'Demonstrate Authentication hooks — connecting document access to your existing auth system (Phase 05''s JWT) in a small working example.', 'Demonstrate Persistence hooks — connecting Hocuspocus to a real database (PostgreSQL, Phase 05) instead of relying solely on in-memory or IndexedDB (13) state in a small working example.', 'Demonstrate Extensions — Hocuspocus''s plugin model for logging, webhooks, and custom persistence backends in a small working example.']::text[], array['Submit a working Hocuspocus example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m04-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m04-t03', 'zte-frontend-v1-core-phase-13-m04', 'y-websocket', array['Explain and apply null in y-websocket.', 'Use y-websocket to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Setting up a y-websocket server for centralized sync in a small working example.', 'Demonstrate Client-side connection and automatic reconnection in a small working example.', 'Demonstrate When a centralized WebSocket relay is the right transport choice — simpler infrastructure, works behind NATs without STUN/TURN in a small working example.']::text[], array['Submit a working y-websocket example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m04-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m04-t04', 'zte-frontend-v1-core-phase-13-m04', 'y-webrtc', array['Explain and apply null in y-webrtc.', 'Use y-webrtc to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Peer-to-peer document sync — no central server required for the actual data flow, only for signaling (ties directly back to Phase 11''s WebRTC signaling discussion) in a small working example.', 'Demonstrate Tradeoffs vs y-websocket: no server infrastructure cost, but NAT traversal reliability and scaling to many peers become harder in a small working example.']::text[], array['Submit a working y-webrtc example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m04-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m04-t05', 'zte-frontend-v1-core-phase-13-m04', 'y-indexeddb', array['Explain and apply null in y-indexeddb.', 'Use y-indexeddb to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Persisting a Y.Doc to IndexedDB (Stage 1) so document state survives a page reload or offline period in a small working example.', 'Demonstrate Combining with a transport provider (11 or 12) — local persistence and network sync are independent, composable concerns in Yjs''s design in a small working example.', 'Demonstrate Offline-first collaborative editing — making local edits while offline, syncing automatically once a transport reconnects in a small working example.']::text[], array['Submit a working y-indexeddb example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m04-t04']::text[], '[]'::jsonb, 120, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-13-m05', 'zte-frontend-v1-core-phase-13', 5, 'Rich Text Editors', 'Moved from the official ordering — ProseMirror is taught before Tiptap, not after, since Tiptap is a wrapper built directly on top of ProseMirror. This follows the same raw-before-wrapper pattern used throughout this series.', 9, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m05-t01', 'zte-frontend-v1-core-phase-13-m05', 'Tiptap', array['Explain and apply null in Tiptap.', 'Use Tiptap to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Extension-based architecture — composing an editor from discrete extensions (Bold, Heading, BulletList, etc.), each ultimately a ProseMirror node/mark/plugin under the hood in a small working example.', 'Demonstrate React integration (@tiptap/react) — wiring Tiptap into a component-based UI (Phase 02) in a small working example.', 'Demonstrate Collaborative editing extension — connecting Tiptap directly to Yjs (Stage 5), the practical convergence point of this entire phase: a rich text editor with live multi-cursor collaboration in a small working example.', 'Demonstrate Custom extensions — building your own when Tiptap''s built-in set isn''t enough, which requires the ProseMirror concepts (15) underneath in a small working example.', 'Demonstrate Post: a demo of real-time collaboration (Yjs) — two cursors editing the same document live. This is the direct payoff of Stage 5''s Awareness feature (Topic 10) combined with Stage 6''s Tiptap collaboration extension (Topic 16). in a small working example.']::text[], array['Submit a working Tiptap example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-m05-t02', 'zte-frontend-v1-core-phase-13-m05', 'ProseMirror', array['Explain and apply null in ProseMirror.', 'Use ProseMirror to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Document schema — ProseMirror''s strict, defined-in-advance model of what content is valid (a deliberate contrast to contentEditable''s anything-goes DOM) in a small working example.', 'Demonstrate Node views and marks — block-level content vs inline formatting in a small working example.', 'Demonstrate Transactions and plugins — ProseMirror''s model for making and intercepting document changes in a small working example.', 'Demonstrate Why ProseMirror is famously powerful but low-level — most teams don''t use it directly, which motivates Tiptap (16) in a small working example.']::text[], array['Submit a working ProseMirror example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-frontend-v1-core-phase-13-m05-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-project-01', 'zte-frontend-v1-core-phase-13', 'Local-First Bookmark Manager with Sync', 'A bookmark manager storing data primarily in IndexedDB with a background sync-to-server layer, handling the case where local and server data diverge while offline, including a documented conflict-resolution strategy. Domain: productivity tools.', array['Deliver the working outcome described in the Local-First Bookmark Manager with Sync brief.', 'Use at least two skills from Client-Side Storage.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Local-First Bookmark Manager with Sync', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Client-Side Storage']::text[], 'advanced', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-project-02', 'zte-frontend-v1-core-phase-13', 'CPU-Heavy Data Processing Without UI Freeze', 'A tool that processes a large CSV/JSON file (parsing, aggregation) entirely inside a Web Worker using comlink for clean async communication, keeping the UI thread responsive throughout — with a visible before/after (UI freezes without the worker, doesn’t with it).', array['Deliver the working outcome described in the CPU-Heavy Data Processing Without UI Freeze brief.', 'Use at least two skills from Parallelism and Cross-Context Communication.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CPU-Heavy Data Processing Without UI Freeze', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Parallelism and Cross-Context Communication']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-project-03', 'zte-frontend-v1-core-phase-13', 'Cross-Tab Session Sync', 'A demo app where logging out in one browser tab immediately logs the user out in all other open tabs of the same app, using the Broadcast Channel API. Domain: security/session management UX.', array['Deliver the working outcome described in the Cross-Tab Session Sync brief.', 'Use at least two skills from Cross-Context Communication.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cross-Tab Session Sync', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Cross-Context Communication']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-project-04', 'zte-frontend-v1-core-phase-13', 'Native Page Transition Gallery', 'A multi-page image gallery using the View Transitions API for smooth native page-to-page morph animations (image expanding into a detail view), with a custom CSS Houdini paint worklet used for one decorative element (e.g., a custom-drawn border or background pattern). Domain: creative/media portfolios.', array['Deliver the working outcome described in the Native Page Transition Gallery brief.', 'Use at least two skills from Browser Rendering & Animation Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Native Page Transition Gallery', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Browser Rendering & Animation Internals']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-project-05', 'zte-frontend-v1-core-phase-13', 'Offline-Capable Collaborative Doc with Peer Fallback', 'A collaborative text document combining y-indexeddb (offline persistence), y-websocket (primary sync via a Hocuspocus server), and y-webrtc as a peer-to-peer fallback when the server is unreachable, demonstrating that edits made offline merge correctly once any sync path reconnects. Domain: collaborative software infrastructure.', array['Deliver the working outcome described in the Offline-Capable Collaborative Doc with Peer Fallback brief.', 'Use at least two skills from Real-Time Collaboration: The Yjs Stack.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Offline-Capable Collaborative Doc with Peer Fallback', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Real-Time Collaboration: The Yjs Stack']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-project-06', 'zte-frontend-v1-core-phase-13', 'Notion-Style Block Editor', 'A rich text editor built with Tiptap (on ProseMirror) supporting headings, lists, code blocks, and a custom block type you build yourself (e.g., an embeddable "callout" box), with full keyboard shortcuts and markdown-style input rules (typing "# " converts to a heading). Domain: productivity / content tools. Integrate Tiptap with Yjs for real-time collaborative rich-text editing with live cursors showing collaborator names/colors — a genuine Google-Docs-style editing experience built from open primitives. Domain: collaborative software.', array['Deliver the working outcome described in the Notion-Style Block Editor brief.', 'Use at least two skills from Rich Text Editors.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Notion-Style Block Editor', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Rich Text Editors']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-13-project-07', 'zte-frontend-v1-core-phase-13', 'A Real-Time Collaborative Document Workspace', 'A Notion/Google-Docs-style collaborative workspace: a Tiptap-based rich text editor with custom block extensions, fully wired to Yjs for real-time collaborative editing (y-websocket primary sync via a Hocuspocus server, y-indexeddb for offline persistence, y-webrtc as a peer-to-peer fallback), live cursor presence, cross-tab session sync via Broadcast Channel, CPU-heavy operations (e.g., full-document search indexing) offloaded to a Web Worker via comlink so typing never lags, and smooth View-Transitions-powered navigation between documents. Domain: collaborative productivity software. Why it matters: real-time collaborative editing is one of the most technically demanding categories of web application — building a working version from open primitives (not a SaaS embed) is a genuine senior-level achievement.', array['Deliver the working outcome described in the A Real-Time Collaborative Document Workspace brief.', 'Use at least two skills from Advanced Browser APIs + Collaboration.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Real-Time Collaborative Document Workspace', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-14', 'zte-frontend-v1', id, '16', 'Load Testing + Security Deep Dive', 'Advanced', 'Requires a real, deployed app (Phase 06\\) — load testing has nothing to test against before then.', 89, 15 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-14-m01', 'zte-frontend-v1-core-phase-14', 1, 'Load Testing', 'Requires a real, deployed app (Phase 06\\) — load testing has nothing to test against before then.', 8.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m01-t01', 'zte-frontend-v1-core-phase-14-m01', 'k6', array['Explain and apply Core Concepts in k6.', 'Explain and apply Test Types in k6.', 'Explain and apply Analyzing Results in k6.']::text[], array['Demonstrate Virtual users (VUs) — simulating concurrent traffic, not just sequential requests in a small working example.', 'Demonstrate Writing test scripts in JavaScript — k6''s scripting model in a small working example.', 'Demonstrate Stages — ramping traffic up and down over the course of a test, rather than a flat constant load in a small working example.', 'Demonstrate Load testing — expected normal-to-peak traffic in a small working example.', 'Demonstrate Stress testing — pushing past expected capacity to find the breaking point in a small working example.']::text[], array['Submit a working k6 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 720, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m01-t02', 'zte-frontend-v1-core-phase-14-m01', 'k6 Cloud', array['Explain and apply null in k6 Cloud.', 'Use k6 Cloud to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Running k6 scripts from multiple geographic load zones — testing latency for real-world distributed users, not just from one machine in a small working example.', 'Demonstrate Result dashboards and historical trend comparison across test runs in a small working example.', 'Demonstrate When local k6 is sufficient vs when cloud-scale load generation is actually needed in a small working example.']::text[], array['Submit a working k6 Cloud example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m01-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m01-t03', 'zte-frontend-v1-core-phase-14-m01', 'Artillery', array['Explain and apply null in Artillery.', 'Use Artillery to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate YAML-based test definitions vs k6''s JavaScript scripting — a different authoring philosophy in a small working example.', 'Demonstrate Artillery''s plugin ecosystem for protocol support beyond plain HTTP (WebSockets, ties back to Phase 11/13''s real-time work) in a small working example.', 'Demonstrate When Artillery''s approach fits better than k6''s — teams preferring declarative config over scripted tests in a small working example.']::text[], array['Submit a working Artillery example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m01-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-14-m02', 'zte-frontend-v1-core-phase-14', 2, 'Security Threat Model & Scanning', 'OWASP Top 10 is placed first in this stage deliberately — it''s the threat model everything else in this stage addresses. Learning ZAP, CSP, or JWT pinning before understanding what threats they mitigate would teach tool operation without the reasoning behind it.', 12.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m02-t01', 'zte-frontend-v1-core-phase-14-m02', 'OWASP Top 10', array['Explain and apply null in OWASP Top 10.', 'Use OWASP Top 10 to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Broken Access Control — the most common real-world vulnerability, and how it shows up in practice (ties back to Phase 05''s auth/authorization patterns) in a small working example.', 'Demonstrate Cryptographic Failures — weak hashing, exposed secrets (foreshadows Stage 3) in a small working example.', 'Demonstrate Injection — SQL injection specifically (ties back to Phase 05''s Prisma usage, which parameterizes queries by default — understanding why that matters) in a small working example.', 'Demonstrate Insecure Design — a threat category about architecture decisions, not just code bugs in a small working example.', 'Demonstrate Security Misconfiguration — default credentials, verbose error messages, unnecessary exposed endpoints in a small working example.']::text[], array['Submit a working OWASP Top 10 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 1020, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m02-t02', 'zte-frontend-v1-core-phase-14-m02', 'OWASP ZAP', array['Explain and apply null in OWASP ZAP.', 'Use OWASP ZAP to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Automated vulnerability scanning — passive scanning (observing traffic) vs active scanning (actively probing for issues) in a small working example.', 'Demonstrate Running ZAP against your deployed app (Phase 06) or a staging environment — never production without deliberate care in a small working example.', 'Demonstrate Interpreting ZAP''s findings — triaging real vulnerabilities against false positives in a small working example.', 'Demonstrate Integrating ZAP into CI (Phase 06''s GitHub Actions) for continuous scanning in a small working example.']::text[], array['Submit a working OWASP ZAP example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m02-t01']::text[], '[]'::jsonb, 480, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m02-t03', 'zte-frontend-v1-core-phase-14-m02', 'Nonce-Based CSP', array['Explain and apply null in Nonce-Based CSP.', 'Use Nonce-Based CSP to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Content Security Policy recap from Phase 05''s Helmet.js — the baseline this topic extends in a small working example.', 'Demonstrate Why ''unsafe-inline'' defeats much of CSP''s protection, and why nonces exist to allow specific inline scripts without that blanket exception in a small working example.', 'Demonstrate Generating a per-request nonce and threading it through to both the CSP header and the script tags that need it (a real implementation challenge in a Next.js/Server Component context, Phase 02) in a small working example.', 'Demonstrate Testing that a nonce-based policy actually blocks unauthorized inline scripts in a small working example.']::text[], array['Submit a working Nonce-Based CSP example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m02-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m02-t04', 'zte-frontend-v1-core-phase-14-m02', 'JWT Algorithm Pinning', array['Explain and apply null in JWT Algorithm Pinning.', 'Use JWT Algorithm Pinning to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate The algorithm confusion attack — a token signed with a weaker or different algorithm than the server expects, and how naive verification code can be tricked into accepting it in a small working example.', 'Demonstrate Explicitly pinning the expected algorithm (e.g. only ever accepting HS256, never letting the token''s own header dictate which algorithm to verify with) — directly extends Phase 05''s HMAC-SHA256/JWT signing discussion in a small working example.', 'Demonstrate Why this matters specifically for the jose/jsonwebtoken libraries introduced in Phase 05 — checking that the algorithm allowlist is actually being enforced in your own auth code in a small working example.']::text[], array['Submit a working JWT Algorithm Pinning example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m02-t03']::text[], '[]'::jsonb, 180, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-14-m03', 'zte-frontend-v1-core-phase-14', 3, 'Secret Management', 'Ordered detection-before-prevention — establishing whether a leak has already happened (trufflehog) before setting up a mechanism to stop future ones (git-secrets), the same threat-first-then-tool logic used in Stage 2\.', 3, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m03-t01', 'zte-frontend-v1-core-phase-14-m03', 'trufflehog', array['Explain and apply null in trufflehog.', 'Use trufflehog to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Scanning git history — not just the current state of a repo, but every commit ever made, since a secret removed in a later commit is still recoverable from history in a small working example.', 'Demonstrate What trufflehog looks for — high-entropy strings, known credential patterns (API keys, private keys) in a small working example.', 'Demonstrate Running trufflehog against your own repos (all phases so far) as a real audit, not a hypothetical exercise in a small working example.', 'Demonstrate What to do if a real leak is found — rotating the credential immediately, not just removing it from the file (removing from a file does not remove it from git history) in a small working example.']::text[], array['Submit a working trufflehog example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m03-t02', 'zte-frontend-v1-core-phase-14-m03', 'git-secrets', array['Explain and apply null in git-secrets.', 'Use git-secrets to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Pre-commit hook that blocks a commit containing a pattern matching known secret formats in a small working example.', 'Demonstrate Configuring patterns — built-in AWS key patterns plus custom patterns for your own project''s secret formats in a small working example.', 'Demonstrate Combining with Husky (a natural extension of Phase 01''s Git tooling work) to enforce this automatically for every commit, not just when remembered manually in a small working example.']::text[], array['Submit a working git-secrets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m03-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-14-m04', 'zte-frontend-v1-core-phase-14', 4, 'Automated Security Monitoring', 'A cluster of small, lightweight tools — most are single-purpose checks that build on context established earlier in this phase.', 4.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m04-t01', 'zte-frontend-v1-core-phase-14-m04', 'securityheaders.com', array['Explain and apply null in securityheaders.com.', 'Use securityheaders.com to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Running your deployed app''s URL (Phase 06) through the scan in a small working example.', 'Demonstrate Reading the grade and understanding which specific headers are missing or misconfigured in a small working example.', 'Demonstrate Iterating — fixing flagged headers and re-scanning to confirm in a small working example.']::text[], array['Submit a working securityheaders.com example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m04-t02', 'zte-frontend-v1-core-phase-14-m04', 'CSP Evaluator', array['Explain and apply null in CSP Evaluator.', 'Use CSP Evaluator to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Google''s CSP Evaluator — analyzing a CSP policy specifically for bypasses and weaknesses, more detailed than securityheaders.com''s general header check in a small working example.', 'Demonstrate Common CSP mistakes it catches — overly permissive source lists, missing directives in a small working example.']::text[], array['Submit a working CSP Evaluator example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m04-t03', 'zte-frontend-v1-core-phase-14-m04', 'Dependabot', array['Explain and apply null in Dependabot.', 'Use Dependabot to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Automated pull requests for outdated/vulnerable dependencies — directly addresses the OWASP Top 10''s Vulnerable and Outdated Components category (Stage 2, Topic 4) in a small working example.', 'Demonstrate Configuring update frequency and which dependency types to monitor in a small working example.', 'Demonstrate Reviewing and merging Dependabot PRs safely — not blindly auto-merging without checking for breaking changes in a small working example.']::text[], array['Submit a working Dependabot example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m04-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m04-t04', 'zte-frontend-v1-core-phase-14-m04', 'npm audit', array['Explain and apply null in npm audit.', 'Use npm audit to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Running npm audit locally and interpreting severity levels in a small working example.', 'Demonstrate npm audit fix — automatic remediation, and its limits (not everything can be auto-fixed without a breaking change) in a small working example.', 'Demonstrate Running npm audit as a CI step (Phase 06''s GitHub Actions) — failing a build on high-severity vulnerabilities in a small working example.']::text[], array['Submit a working npm audit example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m04-t03']::text[], '[]'::jsonb, 60, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-14-m05', 'zte-frontend-v1-core-phase-14', 5, 'Compliance', 'Requires the practical security measures from Stages 1–4 as context — compliance frameworks attest to controls that need to actually exist first; learning the framework before the practice would be abstract.', 5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m05-t01', 'zte-frontend-v1-core-phase-14-m05', 'SOC 2 Basics', array['Explain and apply null in SOC 2 Basics.', 'Use SOC 2 Basics to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate What SOC 2 actually attests to — a third-party audit of an organization''s security controls, not a certification of a specific product feature in a small working example.', 'Demonstrate The five Trust Service Criteria — security, availability, processing integrity, confidentiality, privacy in a small working example.', 'Demonstrate Why SOC 2 matters commercially — many B2B/enterprise customers require a vendor''s SOC 2 report before signing a contract in a small working example.', 'Demonstrate Mapping this phase''s practical work (Stages 1–4: load testing, vulnerability scanning, secret management, header hardening) to what a SOC 2 audit would actually examine in a small working example.']::text[], array['Submit a working SOC 2 Basics example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-m05-t02', 'zte-frontend-v1-core-phase-14-m05', 'GDPR', array['Explain and apply null in GDPR.', 'Use GDPR to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Data subject rights — right to access, right to erasure ("right to be forgotten"), right to data portability, and what implementing each actually requires technically (e.g. can your Prisma/PostgreSQL schema from Phase 05 support exporting or deleting all of a single user''s data cleanly?) in a small working example.', 'Demonstrate Lawful basis for processing — consent (Phase 10) is only one of several lawful bases; understanding the others (contract, legitimate interest) in a small working example.', 'Demonstrate Breach notification requirements — the 72-hour reporting obligation, and why Phase 10''s monitoring/alerting stack is what makes detecting a breach in time even possible in a small working example.', 'Demonstrate Data Processing Agreements (DPAs) — the contractual layer between you and any third-party service handling user data on your behalf (Resend, PostHog, Razorpay — all from Phase 09/10) in a small working example.', 'Demonstrate Post: "I ran a load test on my own app and here''s what broke" — an honest post about a real weakness found and fixed. This is the direct payoff of Stage 1''s k6 work (Topic 1) combined with whatever it actually revealed once correlated against Phase 10''s observability stack. in a small working example.']::text[], array['Submit a working GDPR example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-frontend-v1-core-phase-14-m05-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-01', 'zte-frontend-v1-core-phase-14', 'API Breaking Point Report', 'Use k6 to load-test an earlier project’s API, ramping virtual users until it breaks, and produce a written report identifying the exact bottleneck (CPU, DB connections, memory) with graphs. Domain: performance engineering / SRE. Run a distributed load test from multiple geographic regions using k6 Cloud, comparing latency experienced by users in different regions and documenting a CDN/edge-caching recommendation based on findings.', array['Deliver the working outcome described in the API Breaking Point Report brief.', 'Use at least two skills from Load Testing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working API Breaking Point Report', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Load Testing']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-02', 'zte-frontend-v1-core-phase-14', 'Realistic User-Behavior Load Simulation with Artillery', 'Model a realistic multi-step user journey (browse → search → add to cart → checkout) as an Artillery scenario with weighted random behavior (not just hammering one endpoint), simulating a realistic traffic spike (e.g., a flash sale) and documenting system behavior under it.', array['Deliver the working outcome described in the Realistic User-Behavior Load Simulation with Artillery brief.', 'Use at least two skills from Load Testing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Realistic User-Behavior Load Simulation with Artillery', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Load Testing']::text[], 'advanced', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-03', 'zte-frontend-v1-core-phase-14', 'Automated Vulnerability Scanning Pipeline', 'Integrate OWASP ZAP into a CI pipeline to automatically scan a staging deployment on every merge, failing the build on high-severity findings. Domain: DevSecOps.', array['Deliver the working outcome described in the Automated Vulnerability Scanning Pipeline brief.', 'Use at least two skills from Security Threat Model & Scanning.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Automated Vulnerability Scanning Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Security Threat Model & Scanning']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-04', 'zte-frontend-v1-core-phase-14', 'Nonce-Based CSP Hardening', 'Implement a strict, nonce-based Content Security Policy on a real app (no unsafe-inline), correctly generating a fresh nonce per request and wiring it through server-rendered script tags, verified with a CSP evaluator and a deliberate XSS-attempt test that gets blocked.', array['Deliver the working outcome described in the Nonce-Based CSP Hardening brief.', 'Use at least two skills from Security Threat Model & Scanning.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Nonce-Based CSP Hardening', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Security Threat Model & Scanning']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-05', 'zte-frontend-v1-core-phase-14', 'Secret Leak Prevention Pipeline', 'Configure trufflehog and git-secrets to scan every commit (locally via pre-commit hook and in CI) for accidentally committed secrets, with a deliberate test commit containing a fake API key that gets correctly blocked.', array['Deliver the working outcome described in the Secret Leak Prevention Pipeline brief.', 'Use at least two skills from Secret Management.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Secret Leak Prevention Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Secret Management']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-06', 'zte-frontend-v1-core-phase-14', 'Continuous Security Posture Dashboard', 'A small internal report generator that runs securityheaders.com checks, CSP Evaluator, npm audit, and summarizes Dependabot alert status for a project into a single weekly security posture report. Domain: DevSecOps.', array['Deliver the working outcome described in the Continuous Security Posture Dashboard brief.', 'Use at least two skills from Automated Security Monitoring.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Continuous Security Posture Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Automated Security Monitoring']::text[], 'intermediate', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-07', 'zte-frontend-v1-core-phase-14', 'SOC 2 & GDPR Readiness Checklist Implementation', 'Produce a real, project-specific SOC 2-informed security control checklist and GDPR data-handling checklist for an earlier project, then implement the 5 highest-priority gaps found (e.g., access logging, data export/deletion endpoints) rather than just documenting them. Domain: compliance / security engineering.', array['Deliver the working outcome described in the SOC 2 & GDPR Readiness Checklist Implementation brief.', 'Use at least two skills from Compliance.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working SOC 2 & GDPR Readiness Checklist Implementation', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Compliance']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-14-project-08', 'zte-frontend-v1-core-phase-14', 'A Load-Tested, Security-Hardened Production Audit', 'A full offensive-and-defensive audit of an earlier full-stack project: k6 and Artillery load tests establishing real breaking points and p99 latency under realistic traffic simulation, a documented OWASP Top 10 self-audit with real vulnerabilities found and fixed, a nonce-based strict CSP and JWT algorithm pinning implemented and verified, automated secret scanning wired into CI, a continuous security-header/dependency-audit reporting pipeline, and a GDPR-compliant data export/deletion implementation backed by a written SOC 2-informed access control policy. Domain: application security / SRE. Why it matters: this is the project that proves you don’t just build features — you can find out where your own system breaks and where it’s vulnerable, and actually fix it, which is precisely what separates confident production engineers from tutorial-followers.', array['Deliver the working outcome described in the A Load-Tested, Security-Hardened Production Audit brief.', 'Use at least two skills from Load Testing + Security Deep Dive.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Load-Tested, Security-Hardened Production Audit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'engineering documentation']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-15', 'zte-frontend-v1', id, '17', 'Build Tooling + CSS-in-JS', 'Advanced', 'Foundational — everything else in this phase either analyzes what these tools produce (Stage 2\\) or measures the result of using them (Stage 3).', 44, 16 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-15-m01', 'zte-frontend-v1-core-phase-15', 1, 'Build Tools', 'Foundational — everything else in this phase either analyzes what these tools produce (Stage 2\\) or measures the result of using them (Stage 3).', 6, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m01-t01', 'zte-frontend-v1-core-phase-15-m01', 'Vite', array['Explain and apply Dev Server in Vite.', 'Explain and apply Production Builds in Vite.', 'Explain and apply Context Relative to Next.js in Vite.']::text[], array['Demonstrate Native ES modules in development — why Vite''s dev server starts almost instantly compared to bundler-based dev servers (no need to bundle the entire app before serving the first request) in a small working example.', 'Demonstrate Hot Module Replacement (HMR) — how Vite updates modules in the browser without a full page reload in a small working example.', 'Demonstrate Plugin system — Vite''s Rollup-compatible plugin API in a small working example.', 'Demonstrate Vite uses Rollup under the hood for production builds — a different tool than the dev server, worth knowing explicitly since it explains Stage 2''s rollup-plugin-visualizer relevance in a small working example.', 'Demonstrate Code splitting and chunk strategy in a Vite production build in a small working example.']::text[], array['Submit a working Vite example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array[]::text[], '[]'::jsonb, 540, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m01-t02', 'zte-frontend-v1-core-phase-15-m01', 'tsup', array['Explain and apply null in tsup.', 'Use tsup to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Why publishing a library needs different bundling concerns than shipping an app — multiple output formats (CJS, ESM), type declaration generation in a small working example.', 'Demonstrate tsup''s esbuild-based speed — fast builds for package authoring in a small working example.', 'Demonstrate Configuring entry points and output formats for a real npm-publishable package in a small working example.', 'Demonstrate When you''d actually need this — publishing a shared component library or utility package, not typical for a single product application in a small working example.']::text[], array['Submit a working tsup example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-frontend-v1-core-phase-15-m01-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-15-m02', 'zte-frontend-v1-core-phase-15', 2, 'Bundle Analysis and Performance Auditing', 'Three tools, each attached to a different build system — ordered by which build system context you already have: Next.js (Phase 02, long since known) first, Vite (Stage 1, just learned) second, and raw Rollup (the most general-purpose, underlying both Vite''s production build and usable standalone) last.', 3.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m02-t01', 'zte-frontend-v1-core-phase-15-m02', '@next/bundle-analyzer', array['Explain and apply null in @next/bundle-analyzer.', 'Use @next/bundle-analyzer to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Generating a visual treemap of what''s actually in your Next.js production bundle in a small working example.', 'Demonstrate Identifying unexpectedly large dependencies — a common discovery being an entire library imported for one small utility function in a small working example.', 'Demonstrate Connecting bundle size back to Phase 02''s code-splitting and dynamic import (React.lazy) discussion — bundle analysis is what tells you where those techniques would actually help in a small working example.']::text[], array['Submit a working @next/bundle-analyzer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m02-t02', 'zte-frontend-v1-core-phase-15-m02', 'vite-bundle-visualizer', array['Explain and apply null in vite-bundle-visualizer.', 'Use vite-bundle-visualizer to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Same treemap visualization concept as Topic 3, applied to a Vite production build in a small working example.', 'Demonstrate Differences in what''s typically visible — Vite''s more granular chunk splitting compared to Next.js''s conventions in a small working example.']::text[], array['Submit a working vite-bundle-visualizer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-frontend-v1-core-phase-15-m02-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m02-t03', 'zte-frontend-v1-core-phase-15-m02', 'rollup-plugin-visualizer', array['Explain and apply null in rollup-plugin-visualizer.', 'Use rollup-plugin-visualizer to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Using rollup-plugin-visualizer directly in a Rollup config (or via Vite''s Rollup-compatible plugin system, Stage 1) for finer-grained control than the wrapper tools (3, 4) offer in a small working example.', 'Demonstrate When to reach for the underlying Rollup tool directly instead of a framework-specific wrapper — custom build setups, library bundling scenarios (ties back to tsup, Stage 1, Topic 2) in a small working example.']::text[], array['Submit a working rollup-plugin-visualizer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-frontend-v1-core-phase-15-m02-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m02-t04', 'zte-frontend-v1-core-phase-15-m02', 'lighthouse-ci', array['Explain and apply null in lighthouse-ci.', 'Use lighthouse-ci to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Running Lighthouse audits automatically on every PR/deploy, instead of manually checking scores in Chrome DevTools in a small working example.', 'Demonstrate The four Lighthouse categories — performance, accessibility, best practices, SEO — and what each actually measures in a small working example.', 'Demonstrate Setting budgets — failing CI (Phase 06) if a score or specific metric (e.g. bundle size, connecting back to Stage 2) regresses below a threshold in a small working example.', 'Demonstrate Core Web Vitals specifically — LCP, INP, CLS — and why these are the metrics that actually correlate with user-perceived performance and search ranking in a small working example.']::text[], array['Submit a working lighthouse-ci example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-frontend-v1-core-phase-15-m02-t03']::text[], '[]'::jsonb, 180, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-15-m03', 'zte-frontend-v1-core-phase-15', 3, 'CSS-in-JS', 'An independent theme from Stages 1–3. Runtime-based libraries (styled-components, Emotion) are taught before the zero-runtime alternative (Linaria) so the tradeoff Linaria addresses — CSS-in-JS ergonomics without runtime cost — is understood as a response to a real limitation, not learned in isolation.', 7.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m03-t01', 'zte-frontend-v1-core-phase-15-m03', 'styled-components', array['Explain and apply null in styled-components.', 'Use styled-components to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Tagged template literals — writing actual CSS inside JavaScript, with real syntax highlighting and autocomplete support in most editors in a small working example.', 'Demonstrate Component-scoped styles — each styled component generates its own uniquely-scoped class, avoiding the global-namespace problem of plain CSS (Phase 03) in a small working example.', 'Demonstrate Dynamic styling based on props — styles that change based on component state, without manually toggling classNames (Phase 02/03''s clsx/CVA approach) in a small working example.', 'Demonstrate Theming via ThemeProvider — a runtime theming mechanism, contrasted with Phase 03''s CSS Custom Properties + next-themes approach in a small working example.', 'Demonstrate The runtime cost — styled-components generates and injects CSS at runtime in the browser, which is the specific tradeoff Stage 4''s later topics (Linaria) exist to avoid in a small working example.']::text[], array['Submit a working styled-components example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m03-t02', 'zte-frontend-v1-core-phase-15-m03', 'Emotion', array['Explain and apply null in Emotion.', 'Use Emotion to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate API parity with styled-components — tagged template literals and a similar component-scoping model in a small working example.', 'Demonstrate Emotion''s css prop — an alternative, slightly more flexible authoring style than styled-components'' component-wrapping pattern in a small working example.', 'Demonstrate Performance differences and bundle size comparison between the two libraries in a small working example.', 'Demonstrate Why teams pick one over the other in practice — largely ecosystem/preference rather than a sharp technical divide in a small working example.']::text[], array['Submit a working Emotion example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-frontend-v1-core-phase-15-m03-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-m03-t03', 'zte-frontend-v1-core-phase-15-m03', 'Linaria', array['Explain and apply null in Linaria.', 'Use Linaria to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate The zero-runtime approach — Linaria extracts styles to static CSS files at build time, using a build-time transform rather than generating styles in the browser in a small working example.', 'Demonstrate CSS-in-JS authoring syntax (similar to styled-components/Emotion) with none of their runtime cost — the specific gap this fills in a small working example.', 'Demonstrate Direct comparison to vanilla-extract (Phase 03) — both are zero-runtime, but Linaria keeps closer syntactic similarity to styled-components/Emotion, while vanilla-extract uses a more TypeScript-native styling API in a small working example.', 'Demonstrate Build tooling requirements — Linaria needs its own bundler integration (ties back to Stage 1''s Vite, or webpack/Next.js''s build pipeline) to perform the build-time extraction in a small working example.', 'Demonstrate Post: skipped deliberately — build tooling changes aren''t visible or interesting to an outside audience. in a small working example.']::text[], array['Submit a working Linaria example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-frontend-v1-core-phase-15-m03-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-project-01', 'zte-frontend-v1-core-phase-15', 'Framework-Free Vite App from Scratch', 'Configure a Vite project from an empty folder (no create-vite scaffold) with TypeScript, path aliases, and environment variable handling, understanding every config option added. Domain: build tooling literacy.', array['Deliver the working outcome described in the Framework-Free Vite App from Scratch brief.', 'Use at least two skills from Build Tools.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Framework-Free Vite App from Scratch', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'Build Tools']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-project-02', 'zte-frontend-v1-core-phase-15', 'Dual-Format Publishable Library with tsup', 'Take a utility library from Phase 1/4 and configure tsup to build it as both ESM and CJS output with generated type declarations, ready for real npm publishing. Domain: library authoring / open source.', array['Deliver the working outcome described in the Dual-Format Publishable Library with tsup brief.', 'Use at least two skills from Build Tools.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Dual-Format Publishable Library with tsup', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'Build Tools']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-project-03', 'zte-frontend-v1-core-phase-15', 'Bundle Size Audit & Diet', 'Take a real project, run @next/bundle-analyzer (or vite-bundle-visualizer for non-Next projects), identify the 3 largest unnecessary dependencies or duplicated code, and reduce total bundle size by a documented, measurable percentage.', array['Deliver the working outcome described in the Bundle Size Audit & Diet brief.', 'Use at least two skills from Bundle Analysis and Performance Auditing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Bundle Size Audit & Diet', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'Bundle Analysis and Performance Auditing']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-project-04', 'zte-frontend-v1-core-phase-15', 'Themeable Component Library, Three Ways', 'Rebuild the same 4-component set using styled-components, Emotion, and Linaria (zero-runtime) respectively, then write a hands-on comparison of DX, runtime performance cost, and SSR complexity for each. Domain: frontend architecture decision-making.', array['Deliver the working outcome described in the Themeable Component Library, Three Ways brief.', 'Use at least two skills from CSS-in-JS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Themeable Component Library, Three Ways', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'CSS-in-JS']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-15-project-05', 'zte-frontend-v1-core-phase-15', 'A Bundle-Size-Obsessed Component Library', 'Publish a small, genuinely optimized component library: authored and bundled with tsup (dual ESM/CJS \+ types), a documented before/after bundle-size reduction case study using bundle analyzers, a CI pipeline enforcing a Lighthouse performance budget on the accompanying demo site, and a written comparative report on styled-components vs. Emotion vs. Linaria implementations of the same components with real measured runtime cost differences. Domain: frontend performance / library engineering. Why it matters: most engineers never measure what their styling/build choices actually cost; this project builds the habit of verifying performance claims with real numbers instead of assumptions.', array['Deliver the working outcome described in the A Bundle-Size-Obsessed Component Library brief.', 'Use at least two skills from Build Tooling + CSS-in-JS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Bundle-Size-Obsessed Component Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'engineering documentation']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-16', 'zte-frontend-v1', id, '18', 'Infrastructure', 'Expert', 'Terraform doesn''t strictly require S3 (Stage 1), but S3 makes a concrete, already-understood resource to provision as a first real Terraform example rather than an abstract one.', 175, 17 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-16-m01', 'zte-frontend-v1-core-phase-16', 1, 'Infrastructure as Code and Cloud Object Storage', 'Terraform doesn''t strictly require S3 (Stage 1), but S3 makes a concrete, already-understood resource to provision as a first real Terraform example rather than an abstract one.', 11.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m01-t01', 'zte-frontend-v1-core-phase-16-m01', 'AWS S3', array['Explain and apply null in AWS S3.', 'Use AWS S3 to complete a practical task in Infrastructure.']::text[], array['Demonstrate Buckets and objects — S3''s flat storage model, and the folder-like prefix convention that simulates a directory structure in a small working example.', 'Demonstrate Storage classes — Standard, Infrequent Access, Glacier, and the cost/retrieval-time tradeoff between them in a small working example.', 'Demonstrate Access control — bucket policies vs IAM policies vs ACLs, and why misconfigured public buckets are a persistent real-world security failure (ties back to Phase 14''s OWASP Top 10, Security Misconfiguration category) in a small working example.', 'Demonstrate Presigned URLs — generating time-limited, credential-free access to a private object (a common pattern for direct client uploads, bypassing your own backend for large file transfer) in a small working example.', 'Demonstrate Common use cases: user-uploaded file storage (ties back to Phase 06b''s camera capture, Phase 05''s file handling), static asset hosting, backups in a small working example.']::text[], array['Submit a working AWS S3 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array[]::text[], '[]'::jsonb, 720, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m01-t02', 'zte-frontend-v1-core-phase-16-m01', 'Terraform', array['Explain and apply Core Concepts in Terraform.', 'Explain and apply Workflow in Terraform.', 'Explain and apply State Management in Terraform.']::text[], array['Demonstrate Declarative infrastructure — describing the desired end state, not the steps to get there (a contrast worth making explicit against imperative scripting) in a small working example.', 'Demonstrate Providers — the plugin model connecting Terraform to a specific cloud (AWS, in the context of Stage 1''s S3) in a small working example.', 'Demonstrate Resources and data sources — defining new infrastructure vs referencing existing infrastructure in a small working example.', 'Demonstrate State — what Terraform''s state file tracks, and why it''s the single most important (and most fragile) part of a Terraform setup in a small working example.', 'Demonstrate terraform init, plan, apply, destroy — the core command cycle in a small working example.']::text[], array['Submit a working Terraform example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-frontend-v1-core-phase-16-m01-t01']::text[], '[]'::jsonb, 1860, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m01-t03', 'zte-frontend-v1-core-phase-16-m01', 'Terraform Cloud', array['Explain and apply null in Terraform Cloud.', 'Use Terraform Cloud to complete a practical task in Infrastructure.']::text[], array['Demonstrate Remote execution — running plan/apply in Terraform Cloud instead of locally, with consistent environment and credentials in a small working example.', 'Demonstrate Managed state storage — removing the need to hand-configure a remote backend (contrasted with Terraform''s own remote state setup in Topic 2) in a small working example.', 'Demonstrate Team workflows — approval gates before apply, variable sets shared across configurations in a small working example.']::text[], array['Submit a working Terraform Cloud example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-frontend-v1-core-phase-16-m01-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m01-t04', 'zte-frontend-v1-core-phase-16-m01', 'tfsec', array['Explain and apply null in tfsec.', 'Use tfsec to complete a practical task in Infrastructure.']::text[], array['Demonstrate Static analysis of Terraform configs — catching misconfigurations before anything is ever applied (e.g. a publicly accessible S3 bucket, Stage 1, or an unencrypted resource) in a small working example.', 'Demonstrate Common findings — overly permissive IAM policies, missing encryption settings, open security groups in a small working example.', 'Demonstrate Integrating tfsec into CI (Phase 06''s GitHub Actions) — failing a pipeline before insecure infrastructure is ever provisioned, the IaC equivalent of Phase 14''s npm audit CI step in a small working example.']::text[], array['Submit a working tfsec example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-frontend-v1-core-phase-16-m01-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-16-m02', 'zte-frontend-v1-core-phase-16', 2, 'Kubernetes Core', 'Requires Docker (Phase 06\\) as a direct prerequisite — Kubernetes orchestrates containers, it doesn''t replace understanding what a container actually is.', 20, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m02-t01', 'zte-frontend-v1-core-phase-16-m02', 'Kubernetes', array['Explain and apply Core Objects in Kubernetes.', 'Explain and apply Cluster Architecture in Kubernetes.', 'Explain and apply Networking & Storage in Kubernetes.']::text[], array['Demonstrate Pods — the smallest deployable unit, and why it''s a pod (potentially multiple containers) rather than a single container directly in a small working example.', 'Demonstrate Deployments — declarative, self-healing management of a set of pod replicas in a small working example.', 'Demonstrate Services — stable networking identity for a set of pods whose individual IPs change constantly in a small working example.', 'Demonstrate ConfigMaps and Secrets — externalizing configuration and sensitive values from container images (foreshadows Stage 4''s external-secrets) in a small working example.', 'Demonstrate Control plane components — API server, scheduler, controller manager, etcd (conceptual) in a small working example.']::text[], array['Submit a working Kubernetes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array[]::text[], '[]'::jsonb, 2760, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m02-t02', 'zte-frontend-v1-core-phase-16-m02', 'kind (Kubernetes in Docker)', array['Explain and apply null in kind (Kubernetes in Docker).', 'Use kind (Kubernetes in Docker) to complete a practical task in Infrastructure.']::text[], array['Demonstrate Running a full local Kubernetes cluster using Docker as the underlying container runtime for cluster nodes themselves in a small working example.', 'Demonstrate Why kind exists — a lightweight alternative to Minikube or a real cloud cluster for local development and CI testing in a small working example.', 'Demonstrate Creating and tearing down clusters quickly for experimentation in a small working example.']::text[], array['Submit a working kind (Kubernetes in Docker) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-frontend-v1-core-phase-16-m02-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m02-t03', 'zte-frontend-v1-core-phase-16-m02', 'kubectl', array['Explain and apply null in kubectl.', 'Use kubectl to complete a practical task in Infrastructure.']::text[], array['Demonstrate Core commands — get, describe, apply, delete, logs, exec — for inspecting and managing every resource type from Topic 5 in a small working example.', 'Demonstrate Applying YAML manifests — the declarative resource definitions that map directly to the objects covered in Topic 5 in a small working example.', 'Demonstrate kubectl exec for shelling into a running pod, kubectl logs for reading container output — the K8s equivalents of Phase 06''s docker exec and docker logs in a small working example.', 'Demonstrate Contexts and namespaces — managing access to multiple clusters/environments from one kubectl installation in a small working example.']::text[], array['Submit a working kubectl example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-frontend-v1-core-phase-16-m02-t02']::text[], '[]'::jsonb, 420, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-16-m03', 'zte-frontend-v1-core-phase-16', 3, 'Kubernetes Ecosystem', 'All three topics require core Kubernetes concepts and kubectl (Stage 3\\) already in place — each is a specialized tool or resource type layered on top of that foundation.', 9.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m03-t01', 'zte-frontend-v1-core-phase-16-m03', 'Helm', array['Explain and apply null in Helm.', 'Use Helm to complete a practical task in Infrastructure.']::text[], array['Demonstrate Charts — packaged, versioned, parameterized collections of Kubernetes manifests in a small working example.', 'Demonstrate Why Helm exists — deploying a complex application (many interrelated K8s resources) via a single command instead of applying many YAML files by hand with kubectl (7) in a small working example.', 'Demonstrate Values files — parameterizing a chart for different environments without editing the chart itself in a small working example.', 'Demonstrate Installing, upgrading, and rolling back releases — Helm''s versioned deployment history as an advantage over raw kubectl apply in a small working example.']::text[], array['Submit a working Helm example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array[]::text[], '[]'::jsonb, 600, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m03-t02', 'zte-frontend-v1-core-phase-16-m03', 'HPA (Horizontal Pod Autoscaler)', array['Explain and apply null in HPA (Horizontal Pod Autoscaler).', 'Use HPA (Horizontal Pod Autoscaler) to complete a practical task in Infrastructure.']::text[], array['Demonstrate How HPA automatically scales the number of pod replicas (Stage 3''s Deployments) based on observed metrics — typically CPU or memory utilization in a small working example.', 'Demonstrate Configuring target thresholds and min/max replica bounds in a small working example.', 'Demonstrate Connecting this back to Phase 14''s k6 load testing — HPA is the mechanism that would actually respond to the kind of traffic spikes a load test simulates in a small working example.', 'Demonstrate Limitations — HPA reacts to current load rather than predicting it, and cold-start time for new pods matters for how quickly it can actually help in a small working example.']::text[], array['Submit a working HPA (Horizontal Pod Autoscaler) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-frontend-v1-core-phase-16-m03-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-m03-t03', 'zte-frontend-v1-core-phase-16-m03', 'external-secrets', array['Explain and apply null in external-secrets.', 'Use external-secrets to complete a practical task in Infrastructure.']::text[], array['Demonstrate The problem it solves — Kubernetes Secrets (Stage 3, Topic 5) are base64-encoded, not encrypted, and typically shouldn''t be the ultimate source of truth for sensitive values in a small working example.', 'Demonstrate Syncing secrets from an external source (AWS Secrets Manager, directly connecting back to Stage 1''s AWS/S3 context) into native Kubernetes Secret objects automatically in a small working example.', 'Demonstrate How this ties together the entire phase — AWS as the secret''s true source (Stage 1), Terraform potentially provisioning the AWS-side secret store (Stage 2), and external-secrets (installed via Helm, Topic 8) bridging it into the cluster in a small working example.', 'Demonstrate Post: your infrastructure diagram — the Terraform (Stage 2) + Kubernetes (Stages 3–4) setup, even a simple one. This is genuinely visualizable in a way build tooling (Phase 15) wasn''t, which is exactly why that phase skipped this section and this one doesn''t. in a small working example.', 'Demonstrate GitHub: add an infra/ or terraform/ folder with your IaC config — redact secrets before committing (directly connects to Phase 14''s trufflehog/git-secrets work; this is the exact kind of content those tools exist to catch before it happens). in a small working example.']::text[], array['Submit a working external-secrets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-frontend-v1-core-phase-16-m03-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-project-01', 'zte-frontend-v1-core-phase-16', 'Direct-to-S3 Upload System', 'A file upload feature using pre-signed S3 URLs so large files upload directly from the browser to S3 (not proxied through your server), with upload progress tracking and correct bucket policy/CORS configuration. Domain: media/file storage infrastructure.', array['Deliver the working outcome described in the Direct-to-S3 Upload System brief.', 'Use at least two skills from Cloud Object Storage.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Direct-to-S3 Upload System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Cloud Object Storage']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-project-02', 'zte-frontend-v1-core-phase-16', 'Terraform Security Scan Gate', 'Integrate tfsec into a CI pipeline that scans Terraform plans for security misconfigurations (e.g., a publicly-open security group) before allowing an apply, with a deliberately insecure resource that gets correctly blocked.', array['Deliver the working outcome described in the Terraform Security Scan Gate brief.', 'Use at least two skills from Infrastructure as Code and Cloud Object Storage.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Terraform Security Scan Gate', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Infrastructure as Code and Cloud Object Storage']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-project-03', 'zte-frontend-v1-core-phase-16', 'Local Kubernetes Deployment', 'Deploy a full-stack app (frontend + backend + database) to a local Kubernetes cluster using kind, with proper Deployments, Services, and ConfigMaps/Secrets, managed entirely via kubectl.', array['Deliver the working outcome described in the Local Kubernetes Deployment brief.', 'Use at least two skills from Kubernetes Core.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Local Kubernetes Deployment', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Core']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-project-04', 'zte-frontend-v1-core-phase-16', 'Zero-Downtime Rolling Update Demo', 'Configure a Kubernetes Deployment with proper readiness/liveness probes and rolling update strategy, then deploy a breaking change and demonstrate (with live traffic during the deploy) that users experience zero downtime, followed by a deliberately bad deploy that gets automatically rolled back.', array['Deliver the working outcome described in the Zero-Downtime Rolling Update Demo brief.', 'Use at least two skills from Kubernetes Core.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Zero-Downtime Rolling Update Demo', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Core']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-project-05', 'zte-frontend-v1-core-phase-16', 'Auto-Scaling Load Demonstration', 'Configure a Horizontal Pod Autoscaler on a deployed service, then load-test it (tying back to Phase 14’s k6 work) and record real pod-count scaling behavior as load increases and decreases.', array['Deliver the working outcome described in the Auto-Scaling Load Demonstration brief.', 'Use at least two skills from Kubernetes Ecosystem.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Auto-Scaling Load Demonstration', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Ecosystem']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-project-06', 'zte-frontend-v1-core-phase-16', 'Secure Secret Sync from Cloud Secret Manager', 'Configure external-secrets to sync secrets from a cloud secret manager (or a compatible local equivalent) into Kubernetes Secrets automatically, so no secret is ever manually kubectl-applied or committed anywhere.', array['Deliver the working outcome described in the Secure Secret Sync from Cloud Secret Manager brief.', 'Use at least two skills from Kubernetes Ecosystem.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Secure Secret Sync from Cloud Secret Manager', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Ecosystem']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-16-project-07', 'zte-frontend-v1-core-phase-16', 'A Fully Terraform-and-Kubernetes-Managed Production Platform', 'Take an earlier full-stack project and rebuild its entire infrastructure as code: S3 pre-signed direct uploads for media, all cloud resources defined in Terraform with tfsec-gated CI and Terraform Cloud remote state, the application itself packaged as a Helm chart deployed to Kubernetes with readiness/liveness probes enabling zero-downtime rolling updates, a Horizontal Pod Autoscaler validated under real k6 load, and external-secrets syncing all credentials so nothing sensitive is ever manually applied. Domain: platform engineering / DevOps infrastructure. Why it matters: this is genuine platform-engineer-level work — reproducible, auditable infrastructure is what lets a team scale past "it works on the one server I set up manually."', array['Deliver the working outcome described in the A Fully Terraform-and-Kubernetes-Managed Production Platform brief.', 'Use at least two skills from Infrastructure.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Fully Terraform-and-Kubernetes-Managed Production Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-17', 'zte-frontend-v1', id, '19', 'Architectural Patterns', 'Expert', 'Requires Phase 09''s Redis work as the caching substrate these patterns are named strategies for, and Phase 04''s TanStack Query as the client-side context Optimistic Updates most commonly applies to.', 178, 18 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-17-m01', 'zte-frontend-v1-core-phase-17', 1, 'Caching & Optimistic Update Patterns', 'Requires Phase 09''s Redis work as the caching substrate these patterns are named strategies for, and Phase 04''s TanStack Query as the client-side context Optimistic Updates most commonly applies to.', 6.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m01-t01', 'zte-frontend-v1-core-phase-17-m01', 'Optimistic Updates', array['Explain and apply null in Optimistic Updates.', 'Use Optimistic Updates to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — updating the UI immediately based on an assumed-successful outcome, before the server actually confirms it in a small working example.', 'Demonstrate Rollback handling — reverting the optimistic UI state if the server ultimately rejects the operation (ties directly back to Phase 04''s TanStack Query mutation rollback mechanics) in a small working example.', 'Demonstrate Why this matters for perceived performance — the user sees instant feedback even though the real round-trip hasn''t completed in a small working example.', 'Demonstrate Risk surface — optimistic updates assuming success for operations that are actually likely to fail (e.g. anything touching Stage 2''s concurrency control) can create a confusing UX when the rollback happens in a small working example.']::text[], array['Submit a working Optimistic Updates example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m01-t02', 'zte-frontend-v1-core-phase-17-m01', 'Cache-Aside Caching', array['Explain and apply null in Cache-Aside Caching.', 'Use Cache-Aside Caching to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern by name — application code owns cache population, checking cache first and falling back to the source of truth on a miss in a small working example.', 'Demonstrate Why this is the most common caching pattern in practice — simple, cache and DB can diverge briefly, but the application controls exactly when and what to cache in a small working example.', 'Demonstrate Failure modes — a cache-aside system serving stale data during the window between a DB write and cache invalidation in a small working example.']::text[], array['Submit a working Cache-Aside Caching example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m01-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m01-t03', 'zte-frontend-v1-core-phase-17-m01', 'Write-Through Caching', array['Explain and apply null in Write-Through Caching.', 'Use Write-Through Caching to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — every write goes through the cache layer first, which then writes to the underlying store, keeping cache and DB consistent by construction in a small working example.', 'Demonstrate Tradeoff against cache-aside (1) — write latency increases (every write touches the cache), but read-after-write staleness risk decreases in a small working example.', 'Demonstrate When write-through is worth the extra write latency — read-heavy workloads where consistency matters more than write speed in a small working example.']::text[], array['Submit a working Write-Through Caching example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m01-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-17-m02', 'zte-frontend-v1-core-phase-17', 2, 'Database Concurrency Control', 'Requires Phase 05''s transaction fundamentals and Phase 11''s MVCC deep dive — these two locking strategies are different answers to the same underlying concurrent-write problem MVCC exists to manage.', 7, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m02-t01', 'zte-frontend-v1-core-phase-17-m02', 'Idempotency', array['Explain and apply null in Idempotency.', 'Use Idempotency to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The core property — performing the same operation multiple times has the same effect as performing it once in a small working example.', 'Demonstrate Why this matters for retries specifically — a network failure after a write succeeds but before the client receives confirmation is genuinely ambiguous; the client can only recover safely by retrying, and retrying safely requires idempotency in a small working example.', 'Demonstrate Idempotency keys — a client-generated unique identifier attached to a request, letting the server recognize and safely ignore a duplicate (direct callback to Phase 09''s Razorpay webhook idempotency discussion) in a small working example.', 'Demonstrate Where this already showed up earlier in the curriculum without being named — Phase 09''s webhook handling, and now the formal foundation for Stage 3''s Saga, Outbox, and DLQ patterns, all of which assume retryable, idempotent steps in a small working example.']::text[], array['Submit a working Idempotency example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 420, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m02-t02', 'zte-frontend-v1-core-phase-17-m02', 'Optimistic Locking', array['Explain and apply null in Optimistic Locking.', 'Use Optimistic Locking to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Version-based conflict detection — attaching a version number (or timestamp) to a row, and rejecting a write if the version has changed since it was read in a small working example.', 'Demonstrate Why this is called "optimistic" — it assumes conflicts are rare and only pays the cost of detecting one when it actually happens in a small working example.', 'Demonstrate Implementation in Prisma (Phase 05) — a version column checked and incremented on update, application code handling the conflict when the check fails in a small working example.', 'Demonstrate When optimistic locking fits — low-contention scenarios where most writes don''t actually collide in a small working example.']::text[], array['Submit a working Optimistic Locking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m02-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m02-t03', 'zte-frontend-v1-core-phase-17-m02', 'Pessimistic Locking', array['Explain and apply null in Pessimistic Locking.', 'Use Pessimistic Locking to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Lock-based conflict prevention — acquiring a lock (SELECT ... FOR UPDATE in PostgreSQL, Phase 05) before reading, preventing any other transaction from modifying the same row until the lock is released in a small working example.', 'Demonstrate Why this is called "pessimistic" — it assumes conflicts are common enough that preventing them upfront is cheaper than detecting and retrying them in a small working example.', 'Demonstrate Deadlock risk — two transactions each holding a lock the other needs, and why lock ordering discipline matters in a small working example.', 'Demonstrate When pessimistic locking fits — high-contention scenarios (e.g. a limited-inventory checkout flow) where optimistic locking''s retry cost would be too high in a small working example.']::text[], array['Submit a working Pessimistic Locking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m02-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-17-m03', 'zte-frontend-v1-core-phase-17', 3, 'Distributed Transactions & Messaging Resilience', 'The largest cluster in the phase. Requires idempotency (Stage 2, Topic 6\\) as a hard prerequisite — every pattern here involves retries, and retries without idempotency cause duplicate side effects rather than fixing failures.', 11.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m03-t01', 'zte-frontend-v1-core-phase-17-m03', 'Saga Pattern', array['Explain and apply null in Saga Pattern.', 'Use Saga Pattern to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The problem — a business transaction spanning multiple services (no single database transaction can cover all of them, unlike Phase 05''s single-database ACID transactions) in a small working example.', 'Demonstrate Choreography vs orchestration — services reacting to each other''s events independently, vs a central coordinator directing each step in a small working example.', 'Demonstrate Compensating transactions — since there''s no rollback across services, failure requires explicitly undoing already-completed steps in reverse in a small working example.', 'Demonstrate Why each step must be idempotent (Stage 2, Topic 6) — a saga coordinator retrying a step after an ambiguous failure must not cause duplicate effects in a small working example.']::text[], array['Submit a working Saga Pattern example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m03-t02', 'zte-frontend-v1-core-phase-17-m03', 'Outbox Pattern', array['Explain and apply null in Outbox Pattern.', 'Use Outbox Pattern to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The problem it solves — reliably publishing an event as a consequence of a database write, when the write and the publish can''t be a single atomic operation across two different systems (the DB and the message broker) in a small working example.', 'Demonstrate The pattern — writing the event to an "outbox" table in the same database transaction as the actual data change, then a separate process reads and publishes from that table in a small working example.', 'Demonstrate Why this guarantees consistency — the event write and the data write either both commit or both roll back, since they''re the same PostgreSQL transaction (Phase 05) in a small working example.', 'Demonstrate Common use — implementing reliable saga (7) step completion events without a distributed transaction in a small working example.']::text[], array['Submit a working Outbox Pattern example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m03-t01']::text[], '[]'::jsonb, 600, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m03-t03', 'zte-frontend-v1-core-phase-17-m03', 'Dead Letter Queue', array['Explain and apply null in Dead Letter Queue.', 'Use Dead Letter Queue to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — after a message fails processing repeatedly (beyond a retry limit), routing it to a separate queue instead of retrying forever or silently dropping it in a small working example.', 'Demonstrate Why this matters operationally — a DLQ makes failures visible and inspectable instead of invisible (ties back to Phase 10''s monitoring/alerting stack — a DLQ with growing depth is exactly the kind of thing worth alerting on) in a small working example.', 'Demonstrate Reprocessing strategy — manually or automatically retrying DLQ messages once the underlying issue (a bug, an outage) is fixed in a small working example.']::text[], array['Submit a working Dead Letter Queue example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m03-t02']::text[], '[]'::jsonb, 300, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m03-t04', 'zte-frontend-v1-core-phase-17-m03', 'Circuit Breaker', array['Explain and apply null in Circuit Breaker.', 'Use Circuit Breaker to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — tracking failures when calling an unreliable dependency, and "opening" the circuit (failing fast without even attempting the call) once a failure threshold is crossed in a small working example.', 'Demonstrate The three states — closed (normal operation), open (failing fast), half-open (cautiously testing if the dependency has recovered) in a small working example.', 'Demonstrate Why this prevents cascading failures — a struggling downstream service getting hammered with retries from every caller is often what turns a partial outage into a total one in a small working example.', 'Demonstrate Combining with idempotency (Stage 2, Topic 6) — once a circuit closes again, retried calls must be safe to actually retry in a small working example.']::text[], array['Submit a working Circuit Breaker example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m03-t03']::text[], '[]'::jsonb, 480, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-17-m04', 'zte-frontend-v1-core-phase-17', 4, 'Architectural Styles and Multi-Tenancy', 'Both topics are broader architectural styles built from the messaging reliability patterns in Stage 3 — neither makes sense taught before Outbox and DLQ exist as the mechanisms that make them work in practice, not just in theory.', 7.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m04-t01', 'zte-frontend-v1-core-phase-17-m04', 'Event-Driven Architecture', array['Explain and apply null in Event-Driven Architecture.', 'Use Event-Driven Architecture to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Services communicating via events rather than direct synchronous calls — publishers don''t know or care who consumes an event in a small working example.', 'Demonstrate Loose coupling as the main benefit — and the corresponding cost: harder to trace a single business operation across many independently-reacting services in a small working example.', 'Demonstrate Event schema design and versioning — events are a long-lived contract between services, unlike an internal function signature that''s easy to change in a small working example.', 'Demonstrate Why this style needs Stage 3''s reliability patterns underneath it — an event-driven system without outbox-guaranteed publishing and DLQ-handled failures is one where events can silently go missing in a small working example.']::text[], array['Submit a working Event-Driven Architecture example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m04-t02', 'zte-frontend-v1-core-phase-17-m04', 'CQRS (Command Query Responsibility Segregation)', array['Explain and apply null in CQRS (Command Query Responsibility Segregation).', 'Use CQRS (Command Query Responsibility Segregation) to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The core split — a write model (commands) optimized for validating and applying changes, and a separate read model (queries) optimized for how data is actually displayed/queried in a small working example.', 'Demonstrate Why this can outperform a single shared model — the write model doesn''t need to support every query shape, and the read model can be denormalized however is fastest to read in a small working example.', 'Demonstrate Eventual consistency — the read model updates asynchronously as it consumes events (11) from the write side, meaning a query can briefly return stale data immediately after a write in a small working example.', 'Demonstrate When CQRS is worth the complexity — genuinely different read/write scaling needs or query shapes; explicitly not a default choice for most CRUD-shaped features in a small working example.']::text[], array['Submit a working CQRS (Command Query Responsibility Segregation) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m04-t03', 'zte-frontend-v1-core-phase-17-m04', 'Multi-Tenancy', array['Explain and apply null in Multi-Tenancy.', 'Use Multi-Tenancy to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Isolation strategies — separate databases per tenant, separate schemas per tenant, or shared schema with a tenant ID column, and the isolation/cost/operational-complexity tradeoff between them in a small working example.', 'Demonstrate Row-level security for shared-schema multi-tenancy — enforcing tenant isolation at the database layer itself (ties back to Phase 09''s Supabase RLS discussion) rather than trusting every query to remember a WHERE tenant_id = ? clause in a small working example.', 'Demonstrate Connection and resource considerations — how tenant count interacts with Phase 09''s PgBouncer connection pooling in a small working example.', 'Demonstrate Tenant-aware caching — extending Stage 1''s caching patterns with tenant-scoped cache keys to avoid one tenant''s cached data leaking into another''s response in a small working example.']::text[], array['Submit a working Multi-Tenancy example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m04-t02']::text[], '[]'::jsonb, 720, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-17-m05', 'zte-frontend-v1-core-phase-17', 5, 'Deployment Strategy & Resilience Validation', 'Requires a real, architecturally mature system (Stages 1–5) to deploy and test — both topics are about operating and validating what''s already been built, not new features in themselves.', 9.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m05-t01', 'zte-frontend-v1-core-phase-17-m05', 'Blue-Green Deployments', array['Explain and apply null in Blue-Green Deployments.', 'Use Blue-Green Deployments to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — running two identical production environments (blue and green), deploying to the idle one, then switching traffic over once the new version is verified in a small working example.', 'Demonstrate Why this enables near-zero-downtime deploys and instant rollback — switching traffic back to the previous environment is immediate if something''s wrong in a small working example.', 'Demonstrate Implementing this on Kubernetes (Phase 16) — using Service selectors or Ingress rules to control which environment receives traffic in a small working example.', 'Demonstrate Database migration considerations — blue-green deploys get complicated when a schema change (Phase 05) isn''t backward-compatible with the environment still serving traffic in a small working example.']::text[], array['Submit a working Blue-Green Deployments example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-m05-t02', 'zte-frontend-v1-core-phase-17-m05', 'Chaos Engineering', array['Explain and apply null in Chaos Engineering.', 'Use Chaos Engineering to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The core practice — deliberately injecting failure (killing a service, adding latency, dropping network connections) into a system to verify it degrades gracefully instead of catastrophically in a small working example.', 'Demonstrate Starting small — chaos experiments in a staging environment before ever considering production, and with a clear hypothesis about expected behavior before running one in a small working example.', 'Demonstrate What a chaos experiment actually validates — does the Circuit Breaker (Stage 3, Topic 10) actually open under real failure? Does a Saga (Stage 3, Topic 7) actually compensate correctly if a step fails mid-flight? Does the DLQ (Stage 3, Topic 9) actually catch what it''s supposed to? in a small working example.', 'Demonstrate Writing up results — documenting what was broken, what held, and what was fixed, which is directly the artifact this phase''s Build in Public section and Exit ★3''s portfolio checklist both call out in a small working example.', 'Demonstrate Post: "Why I used the Saga pattern instead of a distributed transaction" — one architectural pattern (Stage 3, Topic 7), explained simply, not the whole phase at once. in a small working example.']::text[], array['Submit a working Chaos Engineering example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-frontend-v1-core-phase-17-m05-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-01', 'zte-frontend-v1-core-phase-17', 'Optimistic Social Feed', 'A social-media-style feed where likes/comments appear instantly (optimistic update) with correct rollback on simulated server rejection, backed by a cache-aside and a write-through caching strategy compared side-by-side on two different data types in the same app.', array['Deliver the working outcome described in the Optimistic Social Feed brief.', 'Use at least two skills from Caching & Optimistic Update Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Optimistic Social Feed', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Caching & Optimistic Update Patterns']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-02', 'zte-frontend-v1-core-phase-17', 'Idempotent Payment Retry Handler', 'A payment processing endpoint that safely handles duplicate/retried requests (e.g., a client retrying after a timeout) using an idempotency key, proven with a test that fires the same request 10 times concurrently and confirms only one charge occurs.', array['Deliver the working outcome described in the Idempotent Payment Retry Handler brief.', 'Use at least two skills from Database Concurrency Control.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Idempotent Payment Retry Handler', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Database Concurrency Control']::text[], 'advanced', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-03', 'zte-frontend-v1-core-phase-17', 'Order Fulfillment Saga', 'Model a multi-step order fulfillment process (charge payment → reserve inventory → schedule shipping) as a Saga with proper compensating transactions for each step, demonstrated by deliberately failing the shipping step and proving payment gets correctly refunded and inventory released.', array['Deliver the working outcome described in the Order Fulfillment Saga brief.', 'Use at least two skills from Distributed Transactions & Messaging Resilience.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Order Fulfillment Saga', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Distributed Transactions & Messaging Resilience']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-04', 'zte-frontend-v1-core-phase-17', 'Resilient Event-Driven Order Pipeline', 'The same order pipeline rebuilt using the Outbox pattern (to guarantee at-least-once event publishing alongside the DB transaction), a Dead Letter Queue for messages that repeatedly fail processing, and a Circuit Breaker around a flaky downstream shipping-provider API call.', array['Deliver the working outcome described in the Resilient Event-Driven Order Pipeline brief.', 'Use at least two skills from Distributed Transactions & Messaging Resilience.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Resilient Event-Driven Order Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Distributed Transactions & Messaging Resilience']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-05', 'zte-frontend-v1-core-phase-17', 'CQRS-Based Reporting System', 'Split a write-heavy transactional data model from a read-optimized reporting model using CQRS — writes go through a normalized command model, reads are served from a denormalized, eventually-consistent query model — with documented consistency-lag behavior.', array['Deliver the working outcome described in the CQRS-Based Reporting System brief.', 'Use at least two skills from Architectural Styles and Multi-Tenancy.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CQRS-Based Reporting System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Architectural Styles and Multi-Tenancy']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-06', 'zte-frontend-v1-core-phase-17', 'Row-Level Multi-Tenant SaaS Data Layer', 'Implement multi-tenancy for a SaaS app using a shared-database, row-level isolation strategy (tenant_id on every table + enforced query scoping), with a deliberate test proving one tenant can never see another tenant’s data even under a crafted malicious query attempt.', array['Deliver the working outcome described in the Row-Level Multi-Tenant SaaS Data Layer brief.', 'Use at least two skills from Multi-Tenancy.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Row-Level Multi-Tenant SaaS Data Layer', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Multi-Tenancy']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-07', 'zte-frontend-v1-core-phase-17', 'Chaos Engineering Game Day', 'Run a real chaos engineering exercise against one of your deployed systems: deliberately kill a service instance, inject network latency, or fail a dependency mid-request, and document what broke, what didn’t, and what you fixed afterward. Domain: SRE / resilience engineering.', array['Deliver the working outcome described in the Chaos Engineering Game Day brief.', 'Use at least two skills from Deployment Strategy & Resilience Validation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Chaos Engineering Game Day', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Deployment Strategy & Resilience Validation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-17-project-08', 'zte-frontend-v1-core-phase-17', 'A Distributed, Multi-Tenant Order Platform', 'A multi-tenant e-commerce order platform combining every pattern in this phase: optimistic-locked inventory and idempotent payment handling preventing overselling and double-charges, a Saga-orchestrated fulfillment pipeline with the Outbox pattern for reliable event publishing, a Circuit Breaker and Dead Letter Queue protecting against a flaky shipping provider, an event-driven notification system decoupled via pub/sub, a CQRS-split reporting layer for seller analytics, strict row-level multi-tenant data isolation proven under adversarial testing, and a blue-green deployment pipeline validated with a real chaos engineering game day. Domain: e-commerce / distributed systems. Why it matters: this is the single most architecturally advanced project in the entire roadmap — it proves genuine distributed-systems thinking, not just feature-building.', array['Deliver the working outcome described in the A Distributed, Multi-Tenant Order Platform brief.', 'Use at least two skills from Architectural Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Distributed, Multi-Tenant Order Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'engineering documentation']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-18', 'zte-frontend-v1', id, '20', 'Engineering Craft + Package Publishing', 'Expert', 'Foundational to everything that follows in this phase — Stage 4''s documentation artifacts are largely the written record of the practices introduced here.', 62, 19 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-18-m01', 'zte-frontend-v1-core-phase-18', 1, 'Decision-Making Practices and Package Publishing', 'Foundational to everything that follows in this phase — Stage 4''s documentation artifacts are largely the written record of the practices introduced here.', 4.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m01-t01', 'zte-frontend-v1-core-phase-18-m01', 'Changesets', array['Explain and apply null in Changesets.', 'Use Changesets to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The problem — coordinating version bumps and changelog entries across a package (or monorepo of packages) without manually tracking what changed since the last release in a small working example.', 'Demonstrate Adding a changeset — a small markdown file describing a change and its semver impact (patch/minor/major), committed alongside the code change itself in a small working example.', 'Demonstrate Consuming changesets — a release step that reads all pending changesets, bumps versions accordingly, and generates a changelog automatically in a small working example.', 'Demonstrate Publishing workflow — combining Changesets with Phase 15''s tsup build step and Phase 06''s GitHub Actions to automate the actual npm publish in a small working example.', 'Demonstrate This is the direct mechanism behind this phase''s Build in Public goal — publishing a first real npm package in a small working example.']::text[], array['Submit a working Changesets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m01-t02', 'zte-frontend-v1-core-phase-18-m01', 'ADRs (Architectural Decision Records)', array['Explain and apply null in ADRs (Architectural Decision Records).', 'Use ADRs (Architectural Decision Records) to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The format — context (what problem/situation prompted this), decision (what was chosen), consequences (what tradeoffs follow from it) in a small working example.', 'Demonstrate Why ADRs matter more than comments or memory — a decision''s reasoning is often more valuable to a future reader than the decision itself, especially once circumstances have changed and someone''s questioning whether the original choice still makes sense in a small working example.', 'Demonstrate What''s actually worth writing one for — significant, hard-to-reverse decisions (Phase 12''s Exit D caution about documenting pgvector vs Pinecone, Haiku vs GPT-4o is exactly ADR-shaped content), not every minor implementation choice in a small working example.', 'Demonstrate Retroactively writing ADRs for major decisions already made across Phases 01–17 — this phase is a natural point to catch up the backlog, not just start going forward in a small working example.']::text[], array['Submit a working ADRs (Architectural Decision Records) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m01-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m01-t03', 'zte-frontend-v1-core-phase-18-m01', 'RFCs (Request for Comments)', array['Explain and apply null in RFCs (Request for Comments).', 'Use RFCs (Request for Comments) to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Structure — problem statement, proposed approach, alternatives considered, open questions for discussion in a small working example.', 'Demonstrate When an RFC is worth writing vs when a decision is small enough to just make and document via ADR (2) afterward in a small working example.', 'Demonstrate The lifecycle — an RFC that reaches consensus typically becomes the basis for one or more ADRs (2) once implemented in a small working example.', 'Demonstrate Solo-developer context — even without a team to actually comment on an RFC, writing one forces the same rigor of considering alternatives before committing, which matters for the kind of documented decision-making Exit ★3 (Phase 17) already flagged as a portfolio differentiator in a small working example.']::text[], array['Submit a working RFCs (Request for Comments) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m01-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-18-m02', 'zte-frontend-v1-core-phase-18', 2, 'Engineering Process Practices', 'A cluster of process disciplines, mostly independent of each other, but all downstream of having a real, deployed, monitored system (Phases 05–17) to actually apply them to.', 10, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m02-t01', 'zte-frontend-v1-core-phase-18-m02', 'DORA Metrics', array['Explain and apply null in DORA Metrics.', 'Use DORA Metrics to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The four key metrics — deployment frequency, lead time for changes, change failure rate, time to restore service in a small working example.', 'Demonstrate Why these specific four — they''re the metrics DORA''s research found actually correlate with high-performing engineering organizations, not an arbitrary dashboard in a small working example.', 'Demonstrate Measuring them from your own pipeline — deployment frequency and lead time are readable directly from Phase 06''s GitHub Actions history; change failure rate and time to restore need incident tracking (foreshadows Topic 5 and the incidents/ artifact, Stage 4) in a small working example.']::text[], array['Submit a working DORA Metrics example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m02-t02', 'zte-frontend-v1-core-phase-18-m02', 'Blameless Post-Mortems', array['Explain and apply null in Blameless Post-Mortems.', 'Use Blameless Post-Mortems to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The blameless framing — analyzing what happened and why the system allowed it, not who made a mistake; the practice exists because blame-oriented reviews make people hide information rather than surface it in a small working example.', 'Demonstrate Structure — timeline of events, root cause analysis, contributing factors, action items with owners in a small working example.', 'Demonstrate Using Phase 14/17''s chaos engineering experiments as low-stakes practice material — you already have a real "incident" (something you deliberately broke) to write a genuine post-mortem about in a small working example.', 'Demonstrate Directly feeds the incidents/ documentation artifact (Stage 4) in a small working example.']::text[], array['Submit a working Blameless Post-Mortems example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m02-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m02-t03', 'zte-frontend-v1-core-phase-18-m02', 'Technical Debt Tracking', array['Explain and apply null in Technical Debt Tracking.', 'Use Technical Debt Tracking to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Distinguishing technical debt from "code I''d write differently today" — debt implies a deliberate or understood tradeoff, not just hindsight in a small working example.', 'Demonstrate A lightweight tracking format — what was deferred, why, and what the cost of leaving it unaddressed actually is in a small working example.', 'Demonstrate Directly feeds the TECH_DEBT.md documentation artifact (Stage 4) in a small working example.']::text[], array['Submit a working Technical Debt Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m02-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m02-t04', 'zte-frontend-v1-core-phase-18-m02', 'Estimation Tracking', array['Explain and apply null in Estimation Tracking.', 'Use Estimation Tracking to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Recording estimates against actuals — the only way to actually improve at estimation is comparing predictions to outcomes over time in a small working example.', 'Demonstrate Common estimation failure patterns — optimism bias, ignoring integration/testing time, underestimating unfamiliar work in a small working example.', 'Demonstrate Using this phase''s own official-vs-actual hour discrepancies (flagged throughout every deep doc in this series) as a live, concrete example of estimation drift worth reflecting on in a small working example.']::text[], array['Submit a working Estimation Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m02-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m02-t05', 'zte-frontend-v1-core-phase-18-m02', 'Code Review Conventions', array['Explain and apply null in Code Review Conventions.', 'Use Code Review Conventions to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Establishing what a review is actually checking for — correctness, readability, adherence to existing patterns, not just "does it work" in a small working example.', 'Demonstrate Self-review discipline in a solo-developer context — reviewing your own PR with the same rigor you''d apply to someone else''s, before merging in a small working example.']::text[], array['Submit a working Code Review Conventions example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m02-t04']::text[], '[]'::jsonb, 120, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m02-t06', 'zte-frontend-v1-core-phase-18-m02', 'Ramp-Up Strategy', array['Explain and apply null in Ramp-Up Strategy.', 'Use Ramp-Up Strategy to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate What a new engineer (or a future version of yourself, returning to the project after months away) actually needs to become productive quickly in a small working example.', 'Demonstrate Structuring an onboarding path — which docs to read first, which parts of the codebase to explore, what NOT to worry about initially in a small working example.', 'Demonstrate The direct connection to Stage 4 — this practice is essentially designing the reading order for the documentation artifacts about to be built in a small working example.']::text[], array['Submit a working Ramp-Up Strategy example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m02-t05']::text[], '[]'::jsonb, 120, 'advanced', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-18-m03', 'zte-frontend-v1-core-phase-18', 3, 'Documentation Artifacts: Decisions & Architecture', 'These artifacts are downstream of Stage 2''s practices — the folder structure and files exist to hold the output of the ADR/RFC discipline, not as independent new concepts.', 4, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m03-t01', 'zte-frontend-v1-core-phase-18-m03', 'ARCHITECTURE.md', array['Explain and apply null in ARCHITECTURE.md.', 'Use ARCHITECTURE.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A high-level system overview — the map that makes docs/adr/''s (10) individual decisions make sense in context in a small working example.', 'Demonstrate Summarizing the major architectural patterns actually implemented (Phase 17''s Saga, Outbox, CQRS, Circuit Breaker, Multi-Tenancy) with links to the specific ADRs that decided them in a small working example.', 'Demonstrate Keeping this document high-level — detailed reasoning belongs in the individual ADRs (10), not duplicated here in a small working example.']::text[], array['Submit a working ARCHITECTURE.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m03-t02', 'zte-frontend-v1-core-phase-18-m03', 'DECISIONS.md', array['Explain and apply null in DECISIONS.md.', 'Use DECISIONS.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A single-file chronological or categorized index of decisions — useful as a fast-scan overview when docs/adr/''s individual files would be too slow to browse one by one in a small working example.', 'Demonstrate Where this differs from ARCHITECTURE.md (11) — DECISIONS.md is a log, ARCHITECTURE.md is a synthesized picture in a small working example.']::text[], array['Submit a working DECISIONS.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m03-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m03-t03', 'zte-frontend-v1-core-phase-18-m03', 'docs/adr/', array['Explain and apply null in docs/adr/.', 'Use docs/adr/ to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Numbered, sequential ADR files (0001-use-postgresql.md style naming) — a convention that preserves chronological decision history in a small working example.', 'Demonstrate Linking between related/superseding ADRs — architecture decisions evolve, and the record should show that evolution rather than silently overwriting old reasoning in a small working example.']::text[], array['Submit a working docs/adr/ example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m03-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-18-m04', 'zte-frontend-v1-core-phase-18', 4, 'Documentation Artifacts: Operational', 'Each artifact in this stage draws its actual content from a specific earlier phase''s work — these are downstream summaries, not new material to learn.', 8.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m04-t01', 'zte-frontend-v1-core-phase-18-m04', 'PERFORMANCE.md', array['Explain and apply null in PERFORMANCE.md.', 'Use PERFORMANCE.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Documenting real benchmark numbers — p95/p99 latency, throughput, error rate under load (the exact figures Exit ★3''s "what to highlight" checklist calls out) in a small working example.', 'Demonstrate Recording what was tuned and why — connecting a specific performance fix back to the k6 result that motivated it in a small working example.']::text[], array['Submit a working PERFORMANCE.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m04-t02', 'zte-frontend-v1-core-phase-18-m04', 'SECURITY.md', array['Explain and apply null in SECURITY.md.', 'Use SECURITY.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Documenting the OWASP Top 10 audit results (Phase 14) — what was checked, what was found, what was fixed in a small working example.', 'Demonstrate Recording the security tooling actually in place — ZAP scanning, CSP configuration, secret scanning (Phase 14''s full Stage 2–4 content) as a reference for what protections exist in a small working example.']::text[], array['Submit a working SECURITY.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m04-t03', 'zte-frontend-v1-core-phase-18-m04', 'MONITORING.md', array['Explain and apply null in MONITORING.md.', 'Use MONITORING.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Documenting what''s actually being monitored — which logs, which error tracking, which uptime checks, and where to find each dashboard in a small working example.', 'Demonstrate Runbook-adjacent content — what a specific alert actually means and what the first response step should be in a small working example.']::text[], array['Submit a working MONITORING.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m04-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m04-t04', 'zte-frontend-v1-core-phase-18-m04', 'OPERATIONS.md', array['Explain and apply null in OPERATIONS.md.', 'Use OPERATIONS.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Deployment process — how a release actually goes out (Phase 06''s CI/CD, Phase 17''s blue-green strategy) in a small working example.', 'Demonstrate Infrastructure overview — the Terraform/Kubernetes setup (Phase 16) at an operational, "how do I actually work with this" level of detail, distinct from ARCHITECTURE.md''s (11) higher-level why in a small working example.']::text[], array['Submit a working OPERATIONS.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m04-t03']::text[], '[]'::jsonb, 60, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m04-t05', 'zte-frontend-v1-core-phase-18-m04', 'TECH_DEBT.md', array['Explain and apply null in TECH_DEBT.md.', 'Use TECH_DEBT.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The running list itself, in the format established in Topic 6 in a small working example.', 'Demonstrate Prioritization — not every debt item needs fixing immediately; documenting the reasoning for what''s deliberately left alone is as valuable as documenting what needs attention in a small working example.']::text[], array['Submit a working TECH_DEBT.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m04-t04']::text[], '[]'::jsonb, 60, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m04-t06', 'zte-frontend-v1-core-phase-18-m04', 'incidents/', array['Explain and apply null in incidents/.', 'Use incidents/ to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate One file per incident, following the post-mortem structure from Topic 5 in a small working example.', 'Demonstrate Including the chaos engineering experiment writeups from Phase 14/17 here as genuine, if deliberately-caused, incident records in a small working example.']::text[], array['Submit a working incidents/ example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m04-t05']::text[], '[]'::jsonb, 60, 'advanced', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-18-m05', 'zte-frontend-v1-core-phase-18', 5, 'Documentation Artifacts: Product & Personal', 'The two most independent artifacts in the phase — neither draws on a specific prior phase''s technical content the way Stage 5''s artifacts do.', 2.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m05-t01', 'zte-frontend-v1-core-phase-18-m05', 'PRODUCT_DECISIONS.md', array['Explain and apply null in PRODUCT_DECISIONS.md.', 'Use PRODUCT_DECISIONS.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A decision log at the product level rather than the architecture level — why a feature works the way it does, not why a technology was chosen (the ADR/docs-adr distinction from Stage 2/4, applied to product rather than engineering choices) in a small working example.', 'Demonstrate Especially relevant for a project like ClientSync with real product-shape decisions (onboarding flow design, what the two-sided portal actually needs) worth recording alongside the purely technical ADRs in a small working example.']::text[], array['Submit a working PRODUCT_DECISIONS.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-m05-t02', 'zte-frontend-v1-core-phase-18-m05', 'READING_NOTES.md', array['Explain and apply null in READING_NOTES.md.', 'Use READING_NOTES.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Capturing what was actually learned while building — the kind of reflection that makes the difference between having built something and being able to explain why it was built that way in an interview in a small working example.', 'Demonstrate A natural home for the reasoning behind choices flagged throughout this entire deep-doc series — every SCOPE NOTICE, every ORDERING CORRECTION, every source discrepancy caught along the way is exactly the kind of reading-notes-worthy reflection this file is for in a small working example.', 'Demonstrate Post: your first published npm package, however small — the direct output of Stage 1''s Changesets work (Topic 1). in a small working example.', 'Demonstrate GitHub: actually publish it. Add ADRs (Stage 2, Topic 2 / Stage 4, Topic 10) to the repo — not just this package''s repo, but ideally backfilled onto ClientSync''s major decisions too. in a small working example.', 'Demonstrate Where + when: LinkedIn + dev.to, the day you publish — timed to the actual event, not batched with unrelated updates. in a small working example.']::text[], array['Submit a working READING_NOTES.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-frontend-v1-core-phase-18-m05-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-project-01', 'zte-frontend-v1-core-phase-18', 'Semantic-Release-Ready Open Source Package', 'Publish a real npm package (one of your earlier utility libraries) with Changesets managing version bumps and changelogs, wired into CI so merging a changeset automatically publishes a new version. Domain: open source maintenance.', array['Deliver the working outcome described in the Semantic-Release-Ready Open Source Package brief.', 'Use at least two skills from Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Semantic-Release-Ready Open Source Package', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Package Publishing']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-project-02', 'zte-frontend-v1-core-phase-18', 'Architecture Decision Record Backfill', 'Go back through 3 major decisions made earlier in this roadmap (e.g., "why Zustand over Redux," "why row-level multi-tenancy over schema-per-tenant") and write proper retroactive ADRs for each, following a consistent template (context, decision, consequences, alternatives considered).', array['Deliver the working outcome described in the Architecture Decision Record Backfill brief.', 'Use at least two skills from Decision-Making Practices and Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Architecture Decision Record Backfill', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Decision-Making Practices and Package Publishing']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-project-03', 'zte-frontend-v1-core-phase-18', 'RFC for a Real Architecture Change', 'Write a full RFC proposing a genuine architectural change to one of your existing projects (e.g., migrating from REST to GraphQL, or adding multi-region support), including alternatives considered and a rollout plan, as if presenting to a real engineering team.', array['Deliver the working outcome described in the RFC for a Real Architecture Change brief.', 'Use at least two skills from Decision-Making Practices and Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working RFC for a Real Architecture Change', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Decision-Making Practices and Package Publishing']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-project-04', 'zte-frontend-v1-core-phase-18', 'Personal DORA Metrics Tracker', 'A small tool/dashboard that tracks your own deployment frequency, lead time for changes, change failure rate, and time to restore across this roadmap’s projects, pulled from real Git/CI history, not estimated.', array['Deliver the working outcome described in the Personal DORA Metrics Tracker brief.', 'Use at least two skills from Engineering Process Practices.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Personal DORA Metrics Tracker', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Engineering Process Practices']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-project-05', 'zte-frontend-v1-core-phase-18', 'Blameless Post-Mortem for a Real Bug', 'Write a full blameless post-mortem for a real bug or outage you caused somewhere in this roadmap (there will be one), following a proper template: timeline, impact, root cause, contributing factors, and concrete action items.', array['Deliver the working outcome described in the Blameless Post-Mortem for a Real Bug brief.', 'Use at least two skills from Engineering Process Practices.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Blameless Post-Mortem for a Real Bug', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Engineering Process Practices']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-18-project-06', 'zte-frontend-v1-core-phase-18', 'A Fully Documented, Publishable Engineering Portfolio Project', 'Take your single most impressive project from anywhere in this roadmap and bring its engineering craft to a publishable standard: a Changesets-managed, auto-published package extracted from its reusable internals, a complete ADR history and RFC for its next proposed evolution, real DORA metrics pulled from its Git/CI history, a blameless post-mortem for a genuine incident, and the full documentation set (ARCHITECTURE.md, DECISIONS.md, PERFORMANCE.md, SECURITY.md, MONITORING.md, OPERATIONS.md, TECH\\\_DEBT.md, PRODUCT\\\_DECISIONS.md) written to a standard where a stranger engineer could fully onboard and operate it without ever talking to you. Domain: engineering craft / technical leadership. Why it matters: documentation and process discipline is what makes an individual’s work into an organization’s asset — this is the artifact that signals senior/staff-level maturity, not just coding ability.', array['Deliver the working outcome described in the A Fully Documented, Publishable Engineering Portfolio Project brief.', 'Use at least two skills from Engineering Craft + Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Fully Documented, Publishable Engineering Portfolio Project', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'engineering documentation']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-frontend-v1-core-phase-19', 'zte-frontend-v1', id, '21', 'Career & Community', 'Expert', 'The only genuinely technical stage in this phase — placed first, trivial before real, as a warm-up before the career/community-focused stages that make up the rest of the phase.', 29, 20 from public.roadmap_versions where roadmap_id='zte-frontend-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-19-m01', 'zte-frontend-v1-core-phase-19', 1, 'API Practice', 'The only genuinely technical stage in this phase — placed first, trivial before real, as a warm-up before the career/community-focused stages that make up the rest of the phase.', 3.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m01-t01', 'zte-frontend-v1-core-phase-19-m01', 'JSONPlaceholder API', array['Explain and apply null in JSONPlaceholder API.', 'Use JSONPlaceholder API to complete a practical task in Career & Community.']::text[], array['Demonstrate Making requests against a free, no-auth-required fake REST API — useful for quickly demoing an integration pattern without needing real credentials or a real backend in a small working example.', 'Demonstrate Common use: prototyping a UI against realistic-shaped data before a real API (Phase 05) exists or is ready in a small working example.']::text[], array['Submit a working JSONPlaceholder API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m01-t02', 'zte-frontend-v1-core-phase-19-m01', 'GitHub API', array['Explain and apply null in GitHub API.', 'Use GitHub API to complete a practical task in Career & Community.']::text[], array['Demonstrate Authentication — personal access tokens vs GitHub Apps vs OAuth, and which fits a given use case in a small working example.', 'Demonstrate Common operations — reading repo data, creating issues/PRs programmatically, managing releases (directly relevant to automating parts of Phase 18''s Changesets-driven publish workflow) in a small working example.', 'Demonstrate Rate limiting — GitHub''s API limits and how authenticated vs unauthenticated requests differ in a small working example.', 'Demonstrate Practical use: building a small tool or script that interacts with your own repos — a genuinely useful capstone exercise combining this phase''s API practice with Phase 18''s documentation/publishing work in a small working example.']::text[], array['Submit a working GitHub API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-frontend-v1-core-phase-19-m01-t01']::text[], '[]'::jsonb, 360, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-19-m02', 'zte-frontend-v1-core-phase-19', 2, 'Job & Talent Platforms', 'Requires a complete portfolio (effectively all of Phases 01–18) to have a profile worth putting on any of these platforms. Ordered niche-to-broad: the two India/startup-focused platforms first, LinkedIn last since its payoff specifically depends on the accumulated 17-month posting history Exit E''s own description assumes already exists.', 6, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m02-t01', 'zte-frontend-v1-core-phase-19-m02', 'Wellfound (formerly AngelList)', array['Explain and apply null in Wellfound (formerly AngelList).', 'Use Wellfound (formerly AngelList) to complete a practical task in Career & Community.']::text[], array['Demonstrate Building a profile optimized for startup hiring — different norms than a traditional corporate resume in a small working example.', 'Demonstrate Filtering strategy — searching by "founding engineer" + stage + equity range, the exact filter Exit E''s own guidance recommends in a small working example.', 'Demonstrate What startups actually look for here — evidence of building and shipping (ClientSync, the published npm package from Phase 18), not just a credentials list in a small working example.']::text[], array['Submit a working Wellfound (formerly AngelList) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m02-t02', 'zte-frontend-v1-core-phase-19-m02', 'Instahyre', array['Explain and apply null in Instahyre.', 'Use Instahyre to complete a practical task in Career & Community.']::text[], array['Demonstrate Profile optimization specifically for the Indian product/startup hiring market in a small working example.', 'Demonstrate How Instahyre''s matching differs from Wellfound''s more founder-direct model — recruiter-mediated vs direct outreach in a small working example.']::text[], array['Submit a working Instahyre example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-frontend-v1-core-phase-19-m02-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m02-t03', 'zte-frontend-v1-core-phase-19-m02', 'LinkedIn', array['Explain and apply null in LinkedIn.', 'Use LinkedIn to complete a practical task in Career & Community.']::text[], array['Demonstrate Profile optimization — headline, about section, and featured section built around what''s actually been shipped (ClientSync, the npm package), not generic self-description in a small working example.', 'Demonstrate Why this phase treats LinkedIn last, not first — a strong profile with zero posting history undersells 17 months of real work; the accumulated content from every prior phase''s Build in Public section is what makes the profile credible in a small working example.', 'Demonstrate Thought leadership positioning — Exit E explicitly notes that if you''ve been posting consistently, inbound interest starts here in a small working example.', 'Demonstrate Direct outreach — messaging engineering managers with a specific technical observation about their stack, the exact tactic Exit ★3 (Phase 17) already flagged as more effective than cold applications at senior level in a small working example.']::text[], array['Submit a working LinkedIn example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-frontend-v1-core-phase-19-m02-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-19-m03', 'zte-frontend-v1-core-phase-19', 3, 'Product Launch & Community', 'Requires a genuinely complete, demo-able product — ClientSync, after 18 phases of work — to have anything worth launching or discussing.', 5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m03-t01', 'zte-frontend-v1-core-phase-19-m03', 'Product Hunt', array['Explain and apply null in Product Hunt.', 'Use Product Hunt to complete a practical task in Career & Community.']::text[], array['Demonstrate Preparing a launch — assets, a compelling tagline, timing (Product Hunt''s day-of-week and timezone dynamics affect visibility) in a small working example.', 'Demonstrate Engaging during launch day — responding to comments and feedback in real time, which Exit E''s own "what to highlight" list calls out specifically (upvotes, comments, feedback received and acted on) in a small working example.', 'Demonstrate What a launch actually demonstrates to a hiring manager — not just that a product exists, but that you can ship something real people react to in a small working example.']::text[], array['Submit a working Product Hunt example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m03-t02', 'zte-frontend-v1-core-phase-19-m03', 'Indie Hackers', array['Explain and apply null in Indie Hackers.', 'Use Indie Hackers to complete a practical task in Career & Community.']::text[], array['Demonstrate Sharing the journey, not just the launch — Indie Hackers'' culture rewards process and lessons-learned content over pure announcement posts in a small working example.', 'Demonstrate Cross-posting the Product Hunt launch (6) here for a different, builder-focused audience in a small working example.']::text[], array['Submit a working Indie Hackers example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-frontend-v1-core-phase-19-m03-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m03-t03', 'zte-frontend-v1-core-phase-19-m03', 'SaaS India Slack', array['Explain and apply null in SaaS India Slack.', 'Use SaaS India Slack to complete a practical task in Career & Community.']::text[], array['Demonstrate A smaller, higher-signal community compared to Product Hunt''s broad public audience in a small working example.', 'Demonstrate Networking value specifically relevant to your stated target companies (Bangalore product startups) — the people in this community may overlap directly with your actual target employer list in a small working example.']::text[], array['Submit a working SaaS India Slack example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-frontend-v1-core-phase-19-m03-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-frontend-v1-core-phase-19-m04', 'zte-frontend-v1-core-phase-19', 4, 'Technical Writing Platforms', 'dev.to has already been used informally throughout nearly every Build in Public section since Phase 06 — this stage is about formal platform mastery and audience-building, not the first introduction to posting there.', 3.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m04-t01', 'zte-frontend-v1-core-phase-19-m04', 'dev.to', array['Explain and apply null in dev.to.', 'Use dev.to to complete a practical task in Career & Community.']::text[], array['Demonstrate Series and tagging strategy — organizing the 17-month posting history (every phase''s Build in Public output) into a coherent, discoverable body of work rather than scattered individual posts in a small working example.', 'Demonstrate Engagement patterns — what actually drives readership on dev.to specifically, distinct from LinkedIn''s algorithm (Stage 2, Topic 5) in a small working example.', 'Demonstrate This phase''s own retrospective post (see Build in Public below) as the capstone piece tying the whole series together in a small working example.']::text[], array['Submit a working dev.to example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-m04-t02', 'zte-frontend-v1-core-phase-19-m04', 'Hashnode', array['Explain and apply null in Hashnode.', 'Use Hashnode to complete a practical task in Career & Community.']::text[], array['Demonstrate Feature comparison with dev.to — custom domains, newsletter integration, and other differences worth knowing in a small working example.', 'Demonstrate Cross-posting strategy — publishing the same retrospective content (Build in Public below) to both platforms to maximize reach, rather than choosing one exclusively in a small working example.', 'Demonstrate Post: the full journey — a genuine retrospective. What was built, what was surprising, what would be done differently. Not a highlight reel; the honest version is more credible and more useful to write. in a small working example.', 'Demonstrate GitHub: a final README pass on ClientSync — this is explicitly called out as the actual artifact recruiters click through to, more than any individual phase''s work. in a small working example.', 'Demonstrate Where + when: LinkedIn (long-form retrospective) + dev.to (the technical version, Stage 4) + shared on Indie Hackers (Stage 3, Topic 7) — one piece of writing, three audiences. in a small working example.']::text[], array['Submit a working Hashnode example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-frontend-v1-core-phase-19-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-project-01', 'zte-frontend-v1-core-phase-19', 'Portfolio-to-Application Pipeline', 'A polished, professional profile presence across Wellfound, Instahyre, and LinkedIn, each tailored to its audience (startup-focused vs. broad), all linking back to a coherent personal portfolio site showcasing this roadmap’s best 4–5 capstone projects with real metrics (not just screenshots).', array['Deliver the working outcome described in the Portfolio-to-Application Pipeline brief.', 'Use at least two skills from Job & Talent Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Portfolio-to-Application Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Career & Community', 'Job & Talent Platforms']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-project-02', 'zte-frontend-v1-core-phase-19', 'Technical Deep-Dive Article Series', 'Write and publish 3 genuinely useful technical articles (on dev.to and cross-posted to Hashnode) documenting real, hard-won lessons from this roadmap — e.g., "What actually breaks when you load-test a Node API," "I built the same feature with REST and GraphQL, here’s the real difference" — not generic tutorials.', array['Deliver the working outcome described in the Technical Deep-Dive Article Series brief.', 'Use at least two skills from Technical Writing Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Technical Deep-Dive Article Series', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Career & Community', 'Technical Writing Platforms']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-frontend-v1-core-phase-19-project-03', 'zte-frontend-v1-core-phase-19', 'A Complete Public Engineering Presence', 'Synthesize the entire roadmap into a real public footprint: a portfolio site (built with everything learned in Phases 1–3) showcasing your 5 strongest capstones with real architecture docs linked in, a genuine Product Hunt launch of your best project with measured traction, a 3-part technical article series published across dev.to and Hashnode documenting real lessons learned (load testing failures, security findings, architectural tradeoffs — not tutorials), and tailored, live profiles on LinkedIn/Wellfound/Instahyre driving toward real conversations. Domain: career development / developer relations. Why it matters: an extraordinary body of technical work that nobody knows about has zero career leverage — this final phase converts 1,159.5 hours of deep engineering work into a visible, credible, discoverable professional presence.', array['Deliver the working outcome described in the A Complete Public Engineering Presence brief.', 'Use at least two skills from Career & Community.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Complete Public Engineering Presence', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Career & Community', 'engineering documentation']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmaps (id, title, track, description, is_public) values ('zte-backend-java-v1', 'ZTE Backend Engineering with Java', 'backend', 'A production-oriented Java backend path covering language depth, APIs, data modeling, distributed systems, cloud operations, and system design.', true) on conflict (id) do update set title=excluded.title, track=excluded.track, description=excluded.description, is_public=true;
insert into public.roadmap_versions (roadmap_id, version_number, label, is_current) values ('zte-backend-java-v1', 2, 'v2.0', true) on conflict (roadmap_id, version_number) do update set label=excluded.label, is_current=true returning id;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-01', 'zte-backend-java-v1', id, '01', 'Developer Environment & Foundations', 'Foundation', 'You cannot learn to code without a place to write it, run it, and save it. This stage exists so every topic after it has a working environment underneath it.', 204, 0 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
