insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-01-m02', 'zte-backend-java-v1-core-phase-01', 2, 'Behavior: JavaScript (Full Sequence, dependency-ordered)', 'JavaScript comes after HTML/CSS because its most motivating use case (manipulating the page) needs a page to exist. Ordered in true dependency order — language core → functions → scope/execution → closures/this/memory → data structures → strings/numbers/dates → error handling → regex → OOP → iteration → meta-programming → modules → async → HTTP → DOM/browser → performance/security → functional patterns → architecture → algorithms → tooling/testing/debugging → engine internals/spec. Topics that could otherwise appear in more than one place (e.g. spread/rest appearing under both Functions and Advanced Operators) are merged at first occurrence.', 162, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
