insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-20', 'zte-backend-java-v1-core-phase-01', 'Functional Data Pipeline Library', 'Build your own functional utility library (pipe, compose, curry, memoize, immutable update helpers) from scratch, fully unit-tested, then use it to process a real CSV dataset end-to-end. Domain: data processing / dev tools. A single documented codebase implementing 8 classic design patterns (Observer, Factory, Singleton, Strategy, Decorator, Command, Module, Facade), each solving a real mini-problem, with tests and a written doc explaining when to use each. Domain: software architecture. Why it’s real: genuinely useful as a portfolio artifact demonstrating architectural maturity.', array['Deliver the working outcome described in the Functional Data Pipeline Library brief.', 'Use at least two skills from Behavior: JavaScript (Full Sequence, dependency-ordered).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Functional Data Pipeline Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Behavior: JavaScript (Full Sequence, dependency-ordered)']::text[], 'advanced', 19) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-21', 'zte-backend-java-v1-core-phase-01', 'Type-Safe Config Loader', 'A small library that loads and validates environment-variable-based app config, using discriminated unions for different deploy environments and strict TypeScript to make invalid states unrepresentable. Domain: dev tooling.', array['Deliver the working outcome described in the Type-Safe Config Loader brief.', 'Use at least two skills from Adding Types: TypeScript and Data: SQL Fundamentals and Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Type-Safe Config Loader', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Adding Types: TypeScript and Data: SQL Fundamentals and Data: SQL Fundamentals']::text[], 'beginner', 20) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-22', 'zte-backend-java-v1-core-phase-01', 'Generic Data Table Library', 'Build a fully generic, reusable data-table utility (sort/filter/paginate) typed with generics so it works correctly for any row shape (DataTable<User>, DataTable<Order>) with full autocomplete and compile-time safety on column keys. Domain: frontend infrastructure.', array['Deliver the working outcome described in the Generic Data Table Library brief.', 'Use at least two skills from Adding Types: TypeScript and Data: SQL Fundamentals and Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Generic Data Table Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Adding Types: TypeScript and Data: SQL Fundamentals and Data: SQL Fundamentals']::text[], 'intermediate', 21) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-23', 'zte-backend-java-v1-core-phase-01', 'Typed API Client Generator', 'Given an OpenAPI-like JSON schema, generate fully-typed TypeScript API client functions using mapped types, conditional types, and template literal types (e.g. typed route strings), plus a Zod runtime validator layer so types are enforced at compile time and runtime. Domain: API tooling / codegen. Why it’s real: this is essentially what openapi-typescript and tRPC do internally.', array['Deliver the working outcome described in the Typed API Client Generator brief.', 'Use at least two skills from Adding Types: TypeScript and Data: SQL Fundamentals and Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Typed API Client Generator', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Adding Types: TypeScript and Data: SQL Fundamentals and Data: SQL Fundamentals']::text[], 'advanced', 22) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-24', 'zte-backend-java-v1-core-phase-01', 'Library Fine Calculator, In Pure SQL', 'Design a normalized schema (Books, Members, Loans) and write pure SQL queries (joins, aggregates) to calculate overdue fines, most-borrowed books, and member activity reports. Domain: civic/library systems.', array['Deliver the working outcome described in the Library Fine Calculator, In Pure SQL brief.', 'Use at least two skills from Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Library Fine Calculator, In Pure SQL', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Data: SQL Fundamentals']::text[], 'beginner', 23) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-25', 'zte-backend-java-v1-core-phase-01', 'E-commerce Analytics Query Pack', 'Given a realistic multi-table e-commerce schema, write 15 real analytical queries a business would actually ask for: cohort retention, top products by margin, customers at risk of churn via window functions/RFM logic. Domain: e-commerce analytics.', array['Deliver the working outcome described in the E-commerce Analytics Query Pack brief.', 'Use at least two skills from Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working E-commerce Analytics Query Pack', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Data: SQL Fundamentals']::text[], 'intermediate', 24) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-26', 'zte-backend-java-v1-core-phase-01', 'Query Optimization Challenge', 'Given a deliberately slow, badly-indexed schema and slow queries, rewrite/optimize each (correct indexes, restructuring subqueries into joins/CTEs) and document before/after EXPLAIN plans and execution time. Domain: database performance.', array['Deliver the working outcome described in the Query Optimization Challenge brief.', 'Use at least two skills from Data: SQL Fundamentals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Query Optimization Challenge', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Data: SQL Fundamentals']::text[], 'advanced', 25) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-27', 'zte-backend-java-v1-core-phase-01', 'Open-Source-Style Contribution Simulation', 'Take any earlier stage project and simulate a full open-source contribution workflow solo: feature branch, Conventional Commits, a PR description template, a CHANGELOG.md generated from commit history. Domain: OSS practice.', array['Deliver the working outcome described in the Open-Source-Style Contribution Simulation brief.', 'Use at least two skills from Collaboration & Code Quality.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Open-Source-Style Contribution Simulation', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Collaboration & Code Quality']::text[], 'beginner', 26) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-28', 'zte-backend-java-v1-core-phase-01', 'Team Code Quality Gate', 'Configure a shared ESLint + Prettier config as its own publishable npm package (@yourname/eslint-config) that multiple projects could extend, including at least one custom lint rule for a project-specific convention. Domain: engineering tooling.', array['Deliver the working outcome described in the Team Code Quality Gate brief.', 'Use at least two skills from Collaboration & Code Quality.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Team Code Quality Gate', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Collaboration & Code Quality']::text[], 'intermediate', 27) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-29', 'zte-backend-java-v1-core-phase-01', 'Git Archaeology Report', 'Pick a real open-source repo, use git log, git blame, and git bisect to trace the history of a specific bug fix or feature through its evolution, and write a technical report, including reconstructing a rebase/merge scenario locally. Domain: software forensics.', array['Deliver the working outcome described in the Git Archaeology Report brief.', 'Use at least two skills from Collaboration & Code Quality.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Git Archaeology Report', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'Collaboration & Code Quality']::text[], 'advanced', 28) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-30', 'zte-backend-java-v1-core-phase-01', 'A Personal Developer Journal & Snippet Manager', 'Build a complete, deployable application that: is scaffolded with a proper dotfiles-provisioned dev environment (Stage 1); has full semantic, accessible HTML structure (Stage 2); is responsively styled with hand-written CSS Grid/Flexbox, no framework (Stage 3); implements all core logic in strict TypeScript compiled from scratch, covering async data fetching from a raw Node http server, custom iterators for browsing entries, a Proxy-based reactive UI updater, Web Worker-based full-text search indexing, and IndexedDB or a JSON file store for persistence (Stages 4–5); uses a real SQL database (SQLite is fine) with a normalized schema for entries/tags/snippets and at least 3 non-trivial analytical queries (Stage 6); and is version-controlled with clean Conventional Commit history, a CONTRIBUTING.md, linting, and a documented Git workflow (Stage 7). Deliverable: a working local-first journal/snippet app plus a written architecture doc explaining every technical decision. Domain: developer productivity tools. Why it matters: this project alone demonstrates command of the entire JS/TS/SQL/Git foundation without leaning on any framework crutch.', array['Deliver the working outcome described in the A Personal Developer Journal & Snippet Manager brief.', 'Use at least two skills from Developer Environment & Foundations.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Personal Developer Journal & Snippet Manager', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Developer Environment & Foundations', 'engineering documentation']::text[], 'advanced', 29) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-01-project-31', 'zte-backend-java-v1-core-phase-01', 'Reliable command-line data processor', 'Import, validate, transform, and export a realistic dataset with clear failure reporting.', array['Typed domain model', 'Validation and useful diagnostics', 'Streaming or bounded memory behavior', 'Automated test coverage']::text[], array['Input contract', 'Transformation rules', 'Failure handling', 'Packaging and documentation']::text[], array['Runnable application', 'Sample fixtures', 'Test report and design note']::text[], array['Java', 'collections', 'testing', 'build tools', 'backend', 'engineering delivery']::text[], 'beginner', 30) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
