insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-02', 'zte-backend-java-v1', id, '03', 'React + Next.js Core', 'Foundation', 'Everything else in Phase 02 sits on top of React. Next.js is a framework around React, not a replacement for it — so React must be solid, and deep, first.', 213, 2 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
