insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-01', 'zte-backend-java-v1-core-phase-02', 'Habit Tracker with Streaks', 'A single-page habit tracker using function components, hooks (useState/useEffect), controlled forms, and localStorage persistence. Domain: personal wellness.', array['Deliver the working outcome described in the Habit Tracker with Streaks brief.', 'Use at least two skills from React 18 (Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Habit Tracker with Streaks', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'React 18 (Foundation)']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-02', 'zte-backend-java-v1-core-phase-02', 'Multi-Step Job Application Wizard', 'A polished multi-step form (resume upload, work history, review) using component composition patterns (compound components), error boundaries per step, and portals for a confirmation modal. Domain: HR tech / recruiting.', array['Deliver the working outcome described in the Multi-Step Job Application Wizard brief.', 'Use at least two skills from React 18 (Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Step Job Application Wizard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'React 18 (Foundation)']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-03', 'zte-backend-java-v1-core-phase-02', 'Concurrent Rendering Image Gallery', 'A masonry image gallery that uses Suspense for image loading, startTransition for non-blocking filter/search updates, and an error boundary fallback per image tile. Includes a deliberate slow-network simulation to demonstrate concurrent rendering benefits visibly. Domain: media/photography platforms.', array['Deliver the working outcome described in the Concurrent Rendering Image Gallery brief.', 'Use at least two skills from React 18 (Foundation).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Concurrent Rendering Image Gallery', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'React 18 (Foundation)']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-04', 'zte-backend-java-v1-core-phase-02', 'Local Business Directory', 'A statically generated directory of local businesses (seeded JSON/CSV data) using file-based routing, dynamic segments, and generateStaticParams. Domain: local commerce.', array['Deliver the working outcome described in the Local Business Directory brief.', 'Use at least two skills from Next.js 15 App Router (Core Framework).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Local Business Directory', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Next.js 15 App Router (Core Framework)']::text[], 'beginner', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-05', 'zte-backend-java-v1-core-phase-02', 'Newsroom CMS Front-End', 'A news site pulling articles from a headless data source, mixing Server and Client Components correctly (interactive comment section as client, article body as server), using Server Actions for comment submission, and ISR for article freshness. Domain: media/publishing.', array['Deliver the working outcome described in the Newsroom CMS Front-End brief.', 'Use at least two skills from Next.js 15 App Router (Core Framework).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Newsroom CMS Front-End', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Next.js 15 App Router (Core Framework)']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-06', 'zte-backend-java-v1-core-phase-02', 'Multi-Tenant SaaS Marketing Site \+ Dashboard Shell', 'A realistic SaaS product shell: public marketing pages (fully static, optimized metadata/SEO), an authenticated dashboard area using middleware for route protection, Route Handlers acting as a lightweight BFF, and a caching strategy documented per route (static / ISR / dynamic). Domain: B2B SaaS.', array['Deliver the working outcome described in the Multi-Tenant SaaS Marketing Site \+ Dashboard Shell brief.', 'Use at least two skills from Next.js 15 App Router (Core Framework).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Tenant SaaS Marketing Site \+ Dashboard Shell', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Next.js 15 App Router (Core Framework)']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-07', 'zte-backend-java-v1-core-phase-02', 'Photo App with Modal Routes', 'An Instagram-style photo grid where clicking a photo opens it in a modal (intercepting routes) but a direct URL visit renders the full page — correct back/forward browser behavior included. Domain: social/media. An admin panel using parallel routes to simultaneously render independent panels (e.g., analytics + recent activity + alerts) that load and error independently, plus route groups to separate authenticated vs public layouts. Domain: internal tools/admin.', array['Deliver the working outcome described in the Photo App with Modal Routes brief.', 'Use at least two skills from App Router: Advanced Routing Features.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Photo App with Modal Routes', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'App Router: Advanced Routing Features']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-08', 'zte-backend-java-v1-core-phase-02', 'Selective Cache-Busting Content Platform', 'A content platform where editors can trigger revalidatePath for a single article or revalidateTag for an entire content category, with a small internal "publish" UI that demonstrates surgical cache invalidation and a notFound() fallback for unpublished/deleted content. Domain: publishing/CMS.', array['Deliver the working outcome described in the Selective Cache-Busting Content Platform brief.', 'Use at least two skills from App Router: Advanced Routing Features.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Selective Cache-Busting Content Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'App Router: Advanced Routing Features']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-09', 'zte-backend-java-v1-core-phase-02', 'Persistent Shopping Cart', 'A shopping cart that survives page reloads and tab closes using browser storage with a clean abstraction layer (not raw localStorage calls scattered everywhere). Domain: e-commerce.', array['Deliver the working outcome described in the Persistent Shopping Cart brief.', 'Use at least two skills from Client-Side Concerns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Persistent Shopping Cart', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Client-Side Concerns']::text[], 'beginner', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-10', 'zte-backend-java-v1-core-phase-02', 'Non-Next.js SPA Router Migration Demo', 'Take a small existing feature and implement it twice: once with Next.js file-based routing, once as a standalone SPA using React Router v6, documenting the API and mental-model differences (loaders, nested routes, navigation guards). Domain: educational/comparative engineering.', array['Deliver the working outcome described in the Non-Next.js SPA Router Migration Demo brief.', 'Use at least two skills from Client-Side Concerns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Non-Next.js SPA Router Migration Demo', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Client-Side Concerns']::text[], 'intermediate', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-11', 'zte-backend-java-v1-core-phase-02', 'Server-to-Client Hydration Demo Dashboard', 'A dashboard that prefetches data on the server, dehydrates it, and hydrates a client-side query cache (HydrationBoundary) so the first paint is instant and subsequent interactions are fully client-cached. Domain: analytics/SaaS. Build the client-side data-fetching foundation (before the full offline sync work happens later in the roadmap) for a notes app: a documented conceptual comparison of fetch-based, SWR-style, and query-cache-based approaches, implemented as 3 small parallel prototypes of the same feature. Domain: productivity tools.', array['Deliver the working outcome described in the Server-to-Client Hydration Demo Dashboard brief.', 'Use at least two skills from Data Layer Integration.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Server-to-Client Hydration Demo Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Data Layer Integration']::text[], 'intermediate', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-12', 'zte-backend-java-v1-core-phase-02', 'Portfolio Site, Two Ways', 'Deploy the same static portfolio site to both Vercel and GitHub Pages, documenting configuration differences (base path, environment variables, build commands). Domain: personal branding.', array['Deliver the working outcome described in the Portfolio Site, Two Ways brief.', 'Use at least two skills from Deployment.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Portfolio Site, Two Ways', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Deployment']::text[], 'beginner', 11) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-13', 'zte-backend-java-v1-core-phase-02', 'Edge-Personalized Landing Page', 'A marketing landing page that uses a Vercel Edge Function to personalize content based on geolocation/headers (e.g., currency or language hint) with near-zero latency, benchmarked against a non-edge equivalent. Domain: marketing/growth. A photography/blog site using blur placeholders (plaiceholder) generated at build time, deployed on Vercel with documented Core Web Vitals before/after optimization. Domain: media/publishing.', array['Deliver the working outcome described in the Edge-Personalized Landing Page brief.', 'Use at least two skills from Deployment.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Edge-Personalized Landing Page', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'Deployment']::text[], 'intermediate', 12) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-02-project-14', 'zte-backend-java-v1-core-phase-02', 'A Server-Rendered Local Government Issue Tracker', 'A full Next.js 15 App Router application where citizens report local issues (potholes, broken streetlights) and track status. Combines: static public pages for browsing resolved/open issues (ISR), a Server Action-powered report submission form, an authenticated admin dashboard behind middleware with parallel routes (queue / map view / stats), intercepting routes for a "quick view" issue modal, edge-personalized location defaults, and a deployed, benchmarked production build on Vercel with documented caching strategy per route. Domain: civic tech. Why it matters: this is a realistic, socially useful full-stack Next.js app that exercises nearly every App Router feature in one coherent product rather than in isolation.', array['Deliver the working outcome described in the A Server-Rendered Local Government Issue Tracker brief.', 'Use at least two skills from React + Next.js Core.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Server-Rendered Local Government Issue Tracker', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React + Next.js Core', 'engineering documentation']::text[], 'advanced', 13) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-03', 'zte-backend-java-v1', id, '04', 'UI System & Styling', 'Foundation', 'Phase 01''s CSS3 stage covered the box model, flexbox, grid, and responsive basics. This stage picks up where that left off — the modern CSS features that Tailwind, theming, and design-token tooling all build on.', 135, 3 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-03-m01', 'zte-backend-java-v1-core-phase-03', 1, 'CSS Foundations (Beyond Phase 01''s CSS3 Basics) and Tailwind CSS (Utility-First Foundation) and Tailwind CSS (Utility-First Foundation)', 'Phase 01''s CSS3 stage covered the box model, flexbox, grid, and responsive basics. This stage picks up where that left off — the modern CSS features that Tailwind, theming, and design-token tooling all build on.', 7.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-03-m01-t01', 'zte-backend-java-v1-core-phase-03-m01', 'Tailwind CSS', array['Explain and apply Core Utility Model in Tailwind CSS.', 'Explain and apply Layout Utilities in Tailwind CSS.', 'Explain and apply Configuration & Theming in Tailwind CSS.', 'Explain and apply Build & Optimization in Tailwind CSS.']::text[], array['Demonstrate Utility-first philosophy — styling via composed classes, not custom CSS in a small working example.', 'Demonstrate Spacing, sizing, color, typography utility scales in a small working example.', 'Demonstrate Responsive prefixes (sm:, md:, lg:, etc.) and mobile-first breakpoints in a small working example.', 'Demonstrate State variants (hover:, focus:, active:, disabled:, group-hover:, peer-*) in a small working example.', 'Demonstrate Dark mode variant (dark:) in a small working example.']::text[], array['Submit a working Tailwind CSS example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array[]::text[], '[]'::jsonb, 1320, 'beginner', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-03-m01-t02', 'zte-backend-java-v1-core-phase-03-m01', 'CSS @layer (Cascade Layers)', array['Explain and apply null in CSS @layer (Cascade Layers).', 'Use CSS @layer (Cascade Layers) to complete a practical task in UI System & Styling.']::text[], array['Demonstrate @layer syntax — declaring and ordering layers in a small working example.', 'Demonstrate Layer precedence: later-declared layers win regardless of selector specificity in a small working example.', 'Demonstrate Unlayered styles vs layered styles (unlayered always wins) in a small working example.', 'Demonstrate Why component libraries (Tailwind, shadcn) use @layer internally to avoid specificity wars in a small working example.', 'Demonstrate Practical use: layering reset → base → components → utilities in a small working example.']::text[], array['Submit a working CSS @layer (Cascade Layers) example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-backend-java-v1-core-phase-03-m01-t01']::text[], '[]'::jsonb, 60, 'beginner', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-03-m01-t03', 'zte-backend-java-v1-core-phase-03-m01', 'CSS Modules', array['Explain and apply null in CSS Modules.', 'Use CSS Modules to complete a practical task in UI System & Styling.']::text[], array['Demonstrate *.module.css file convention and automatic scoping in a small working example.', 'Demonstrate Composing classes (composes: keyword) in a small working example.', 'Demonstrate CSS Modules with dynamic class names in JS/JSX in a small working example.', 'Demonstrate When CSS Modules are preferable to utility-first CSS (complex one-off components, gradual migration) in a small working example.', 'Demonstrate Limitations: no true dynamic values without JS interpolation in a small working example.']::text[], array['Submit a working CSS Modules example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-backend-java-v1-core-phase-03-m01-t02']::text[], '[]'::jsonb, 180, 'beginner', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-03-m01-t04', 'zte-backend-java-v1-core-phase-03-m01', 'CSS Custom Properties', array['Explain and apply null in CSS Custom Properties.', 'Use CSS Custom Properties to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Declaring custom properties (--variable-name) at :root and scoped to selectors in a small working example.', 'Demonstrate var() with fallback values in a small working example.', 'Demonstrate Custom properties vs Sass/Less variables — computed at runtime, not compile time in a small working example.', 'Demonstrate Using custom properties for theming (light/dark values swapped at a scope) in a small working example.', 'Demonstrate Cascading and inheritance behavior of custom properties in a small working example.']::text[], array['Submit a working CSS Custom Properties example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-backend-java-v1-core-phase-03-m01-t03']::text[], '[]'::jsonb, 180, 'beginner', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-03-m01-t05', 'zte-backend-java-v1-core-phase-03-m01', 'BEM (Block Element Modifier)', array['Explain and apply null in BEM (Block Element Modifier).', 'Use BEM (Block Element Modifier) to complete a practical task in UI System & Styling.']::text[], array['Demonstrate Block, Element, Modifier naming convention (.block__element--modifier) in a small working example.', 'Demonstrate Why BEM exists — solving specificity and naming collisions at scale in a small working example.', 'Demonstrate BEM''s tradeoffs: verbosity vs predictability in a small working example.', 'Demonstrate How BEM relates to (and contrasts with) utility-first CSS philosophy in a small working example.']::text[], array['Submit a working BEM (Block Element Modifier) example and explain the key decisions.', 'Record a short review showing how the example satisfies the UI System & Styling learning goal.']::text[], array['zte-backend-java-v1-core-phase-03-m01-t04']::text[], '[]'::jsonb, 120, 'beginner', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-03-m02', 'zte-backend-java-v1-core-phase-03', 2, 'Class Composition Utilities', 'These three tools exist specifically to manage Tailwind utility classes at scale — none of them are useful without Tailwind (Stage 2\\) already in place, and each builds on the previous.', 5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
