insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-06-m01-t07', 'zte-backend-java-v1-core-phase-06-m01', 'Playwright', array['Explain and apply Core Concepts in Playwright.', 'Explain and apply Writing Real E2E Flows in Playwright.', 'Explain and apply Tooling in Playwright.']::text[], array['Demonstrate Browser automation model — Playwright drives real browsers (Chromium, Firefox, WebKit) in a small working example.', 'Demonstrate page.goto(), locators, and Playwright''s auto-waiting (vs manual waits/sleeps) in a small working example.', 'Demonstrate Assertions with expect() in a Playwright context in a small working example.', 'Demonstrate Testing full user journeys: signup → login → core app action (ties directly to the JWT auth flow from Phase 05) in a small working example.', 'Demonstrate Handling authentication state across tests (storageState, reusing a logged-in session) in a small working example.']::text[], array['Submit a working Playwright example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-backend-java-v1-core-phase-06-m01-t06']::text[], '[]'::jsonb, 1080, 'intermediate', 6) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-06-m01-t08', 'zte-backend-java-v1-core-phase-06-m01', 'GitHub Actions', array['Explain and apply Workflow Fundamentals in GitHub Actions.', 'Explain and apply Building a Real CI Pipeline in GitHub Actions.', 'Explain and apply Secrets & Environments in GitHub Actions.']::text[], array['Demonstrate Workflow YAML structure — on, jobs, steps in a small working example.', 'Demonstrate Triggers: push, pull_request, schedule, workflow_dispatch in a small working example.', 'Demonstrate Runners — GitHub-hosted vs self-hosted (conceptual) in a small working example.', 'Demonstrate Actions marketplace — using pre-built actions (checkout, setup-node) in a small working example.', 'Demonstrate Running Vitest (Stage 1) and Playwright (Stage 2) in CI in a small working example.']::text[], array['Submit a working GitHub Actions example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-backend-java-v1-core-phase-06-m01-t07']::text[], '[]'::jsonb, 960, 'intermediate', 7) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-06-m02', 'zte-backend-java-v1-core-phase-06', 2, 'Containerization', 'Independent of testing/CI conceptually, but placed here because Docker images are what CI will build and what deployment (Stage 5\\) will run — this stage sits at the intersection.', 18, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-06-m02-t01', 'zte-backend-java-v1-core-phase-06-m02', 'Docker', array['Explain and apply Core Concepts in Docker.', 'Explain and apply Building for a Real App in Docker.', 'Explain and apply Running Containers in Docker.']::text[], array['Demonstrate Images vs containers — the class/instance analogy in a small working example.', 'Demonstrate Dockerfile syntax: FROM, WORKDIR, COPY, RUN, CMD/ENTRYPOINT in a small working example.', 'Demonstrate Layers and layer caching — why instruction order in a Dockerfile affects build speed in a small working example.', 'Demonstrate Multi-stage builds — separating build dependencies from the final runtime image in a small working example.', 'Demonstrate Dockerizing a Next.js app — the standalone output mode and its Dockerfile implications in a small working example.']::text[], array['Submit a working Docker example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array[]::text[], '[]'::jsonb, 1500, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-06-m02-t02', 'zte-backend-java-v1-core-phase-06-m02', 'Docker Compose', array['Explain and apply null in Docker Compose.', 'Use Docker Compose to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate docker-compose.yml structure — services, networks, volumes in a small working example.', 'Demonstrate Running a full local stack: app + Postgres (Phase 05) + Redis (later phase) in one command in a small working example.', 'Demonstrate depends_on and service startup ordering in a small working example.', 'Demonstrate Local development workflow — hot-reloading inside containers vs running natively in a small working example.']::text[], array['Submit a working Docker Compose example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-backend-java-v1-core-phase-06-m02-t01']::text[], '[]'::jsonb, 600, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
