insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-06b-m03-t01', 'zte-backend-java-v1-core-phase-06b-m03', 'Native APIs (Camera, Push, Permissions)', array['Explain and apply Permissions Model in Native APIs (Camera, Push, Permissions).', 'Explain and apply Camera in Native APIs (Camera, Push, Permissions).', 'Explain and apply Push Notifications in Native APIs (Camera, Push, Permissions).']::text[], array['Demonstrate Requesting permissions at runtime (camera, notifications, location) in a small working example.', 'Demonstrate Handling permission denial gracefully — a required UX pattern, not optional in a small working example.', 'Demonstrate expo-camera — capturing photos/video in a small working example.', 'Demonstrate Common use case: document/ID capture for onboarding flows (ties to ClientSync''s onboarding domain) in a small working example.', 'Demonstrate Expo push notification service — registering a device token in a small working example.']::text[], array['Submit a working Native APIs (Camera, Push, Permissions) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
