insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-m04-t03', 'zte-backend-java-v1-core-phase-10-m04', 'posthog-node', array['Explain and apply null in posthog-node.', 'Use posthog-node to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Server-side event capture — tracking events that happen outside the browser (webhook-triggered actions, background jobs) in a small working example.', 'Demonstrate Combining client and server events into a single coherent user timeline in a small working example.']::text[], array['Submit a working posthog-node example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-backend-java-v1-core-phase-10-m04-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-10-m05', 'zte-backend-java-v1-core-phase-10', 5, 'Analytics-Driven Features and Compliance and Compliance', 'All four topics require the PostHog foundation (Stage 4\\) — none of these features exist without an analytics platform and event pipeline already in place.', 8.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
