insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-m05-t03', 'zte-backend-java-v1-core-phase-10-m05', 'Funnel Analysis', array['Explain and apply null in Funnel Analysis.', 'Use Funnel Analysis to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Defining a funnel — an ordered sequence of events representing a user journey (e.g. signup → onboarding → first action) in a small working example.', 'Demonstrate Drop-off analysis — identifying where users abandon the journey in a small working example.', 'Demonstrate Connecting funnel insights back to real product decisions in a small working example.']::text[], array['Submit a working Funnel Analysis example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-backend-java-v1-core-phase-10-m05-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-m05-t04', 'zte-backend-java-v1-core-phase-10-m05', 'Session Recording', array['Explain and apply null in Session Recording.', 'Use Session Recording to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate What session recording captures — DOM mutations replayed as a video-like session, not actual video in a small working example.', 'Demonstrate Privacy implications and masking sensitive input fields (direct segue into Stage 6''s GDPR topic) in a small working example.', 'Demonstrate Using recordings alongside funnel drop-off points (17) to see exactly why users abandoned a flow in a small working example.']::text[], array['Submit a working Session Recording example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-backend-java-v1-core-phase-10-m05-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-m05-t05', 'zte-backend-java-v1-core-phase-10-m05', 'GDPR Consent Mode', array['Explain and apply null in GDPR Consent Mode.', 'Use GDPR Consent Mode to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate What GDPR requires for analytics/tracking consent — opt-in before tracking, not opt-out after in a small working example.', 'Demonstrate Consent banners and their effect on PostHog initialization — delaying or conditionally enabling tracking (Stage 4) based on consent state in a small working example.', 'Demonstrate Handling session recording (18) specifically — masking or disabling entirely without consent in a small working example.', 'Demonstrate Cookie-less/anonymous tracking modes as a partial compliance strategy before consent is granted in a small working example.', 'Demonstrate Documenting what''s collected — the practical deliverable a real compliance review would ask for in a small working example.']::text[], array['Submit a working GDPR Consent Mode example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-backend-java-v1-core-phase-10-m05-t04']::text[], '[]'::jsonb, 180, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-project-01', 'zte-backend-java-v1-core-phase-10', 'Request-Traceable Logging System', 'Add structured logging (pino) to an earlier API with a request ID propagated via AsyncLocalStorage through every log line of a request’s lifecycle, so any single request’s full log trail can be grepped by ID. Domain: observability / SRE.', array['Deliver the working outcome described in the Request-Traceable Logging System brief.', 'Use at least two skills from Request Context & Structured Logging.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Request-Traceable Logging System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Request Context & Structured Logging']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-project-02', 'zte-backend-java-v1-core-phase-10', 'Dual-Transport Logging Setup', 'Configure winston with two transports (console for dev, file/JSON for production) and demonstrate log-level filtering (debug locally, warn+ in production) driven by environment config. Domain: observability.', array['Deliver the working outcome described in the Dual-Transport Logging Setup brief.', 'Use at least two skills from Request Context & Structured Logging.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Dual-Transport Logging Setup', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Request Context & Structured Logging']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-project-03', 'zte-backend-java-v1-core-phase-10', 'Production Error Triage Dashboard', 'Integrate Sentry into a full-stack app (both frontend and backend), including source maps for readable stack traces, user context attachment, and custom error grouping/tagging for a specific error-prone feature. Domain: SRE / observability. Set up UptimeRobot monitors for a deployed project’s critical endpoints and build a small public status page that reflects real uptime data. Domain: SRE / product trust.', array['Deliver the working outcome described in the Production Error Triage Dashboard brief.', 'Use at least two skills from Error Tracking & Uptime.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Production Error Triage Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Error Tracking & Uptime']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-project-04', 'zte-backend-java-v1-core-phase-10', 'Unified Observability Stack Comparison', 'Ship the same application’s logs to 3 different platforms in parallel (e.g., Better Stack, Axiom, and Grafana Cloud + Loki) and write a hands-on comparison covering query experience, retention/pricing, and alerting capability. Domain: infrastructure decision-making.', array['Deliver the working outcome described in the Unified Observability Stack Comparison brief.', 'Use at least two skills from Log Aggregation & Observability Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Unified Observability Stack Comparison', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Log Aggregation & Observability Platforms']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-project-05', 'zte-backend-java-v1-core-phase-10', 'CloudWatch-Based AWS Monitoring Setup', 'For any component deployed with AWS involvement, configure CloudWatch log groups, metric filters, and a basic alarm (e.g., error-rate spike) that would page a real on-call engineer. Domain: AWS/SRE.', array['Deliver the working outcome described in the CloudWatch-Based AWS Monitoring Setup brief.', 'Use at least two skills from Log Aggregation & Observability Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CloudWatch-Based AWS Monitoring Setup', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Log Aggregation & Observability Platforms']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-project-06', 'zte-backend-java-v1-core-phase-10', 'Feature-Flagged A/B Pricing Experiment', 'Run a real (or realistic simulated) A/B test on a pricing page using PostHog feature flags to split traffic, tracked through to a conversion event, with statistical significance discussed in a written results report. Domain: growth engineering / experimentation. Use funnel analysis and session recordings to identify the exact step where users abandon an onboarding flow, propose and implement a fix, then re-measure the funnel to validate improvement. Domain: product/UX engineering.', array['Deliver the working outcome described in the Feature-Flagged A/B Pricing Experiment brief.', 'Use at least two skills from Analytics-Driven Features and Compliance and Compliance.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Feature-Flagged A/B Pricing Experiment', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'Analytics-Driven Features and Compliance and Compliance']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-10-project-07', 'zte-backend-java-v1-core-phase-10', 'A Full Observability & Analytics Platform for a Production App', 'Wrap a complete observability and analytics layer around an earlier full-stack project: AsyncLocalStorage-propagated structured logging (pino) shipped to a real aggregation platform (Grafana Cloud \+ Loki), Sentry error tracking with source maps on both frontend and backend, UptimeRobot-backed public status page, full PostHog funnel instrumentation from landing to conversion with an active feature-flagged A/B experiment, session-recording-driven UX fixes with before/after funnel data, and a GDPR-compliant consent system that actually gates tracking. Domain: SRE / product analytics / privacy engineering. Why it matters: shipping a feature is half the job; knowing whether it works, why it breaks, and whether users actually use it is the other half — this project proves that operational maturity.', array['Deliver the working outcome described in the A Full Observability & Analytics Platform for a Production App brief.', 'Use at least two skills from Monitoring & Analytics.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Full Observability & Analytics Platform for a Production App', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Monitoring & Analytics', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-11', 'zte-backend-java-v1', id, '13', 'Real-Time + Search + PostgreSQL Internals', 'Advanced', 'Ordered by mechanism complexity — each topic''s limitations motivate the next. Requires a real deployed app (Phase 06\\) and backend (Phase 05\\) to build real-time features on top of.', 164, 12 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-11-m01', 'zte-backend-java-v1-core-phase-11', 1, 'Real-Time Communication', 'Ordered by mechanism complexity — each topic''s limitations motivate the next. Requires a real deployed app (Phase 06\\) and backend (Phase 05\\) to build real-time features on top of.', 15, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m01-t01', 'zte-backend-java-v1-core-phase-11-m01', 'SSE (EventSource)', array['Explain and apply null in SSE (EventSource).', 'Use SSE (EventSource) to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate The EventSource API — how a client subscribes to a stream of server-sent events in a small working example.', 'Demonstrate Server-side implementation — keeping an HTTP connection open and writing event-formatted chunks in a small working example.', 'Demonstrate Automatic reconnection behavior built into EventSource in a small working example.', 'Demonstrate When SSE is sufficient: notifications, live feeds, progress updates — anything server-to-client only in a small working example.', 'Demonstrate The limitation that motivates WebSockets next: no client-to-server messages over the same connection in a small working example.']::text[], array['Submit a working SSE (EventSource) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m01-t02', 'zte-backend-java-v1-core-phase-11-m01', 'WebSockets', array['Explain and apply Protocol Fundamentals in WebSockets.', 'Explain and apply Implementation in WebSockets.', 'Explain and apply Common Use Cases in WebSockets.']::text[], array['Demonstrate The WebSocket handshake — upgrading from HTTP to a persistent WebSocket connection in a small working example.', 'Demonstrate Frames, message types (text/binary), ping/pong keepalive in a small working example.', 'Demonstrate Setting up a WebSocket server (ws library or Socket.IO) alongside Express (Phase 05) in a small working example.', 'Demonstrate Client-side connection management — reconnection strategies, connection state in a small working example.', 'Demonstrate Broadcasting to multiple clients, rooms/channels for scoped broadcasts (Socket.IO-specific) in a small working example.']::text[], array['Submit a working WebSockets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m01-t01']::text[], '[]'::jsonb, 1200, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m01-t03', 'zte-backend-java-v1-core-phase-11-m01', 'WebRTC', array['Explain and apply Core Concepts in WebRTC.', 'Explain and apply Data & Media Channels in WebRTC.']::text[], array['Demonstrate Peer-to-peer connections — why WebRTC bypasses the server for the actual media/data stream after setup in a small working example.', 'Demonstrate ICE, STUN, and TURN — how two peers behind NATs actually find and connect to each other in a small working example.', 'Demonstrate Signaling — the offer/answer exchange (SDP) that happens over WebSockets (2) before the peer connection is established in a small working example.', 'Demonstrate RTCDataChannel — peer-to-peer data transfer (not just audio/video) in a small working example.', 'Demonstrate MediaStream API — capturing camera/microphone for video calls in a small working example.']::text[], array['Submit a working WebRTC example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m01-t02']::text[], '[]'::jsonb, 1080, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-11-m02', 'zte-backend-java-v1-core-phase-11', 2, 'PostgreSQL Index Depth', 'Requires Phase 05''s PostgreSQL fundamentals — this stage goes deeper into exactly the index/EXPLAIN ANALYZE territory Phase 05 introduced at a basic level.', 9.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m02-t01', 'zte-backend-java-v1-core-phase-11-m02', 'B-Tree Indexes', array['Explain and apply null in B-Tree Indexes.', 'Use B-Tree Indexes to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate B-Tree structure — why it''s the default, and what "balanced tree" actually means for lookup performance in a small working example.', 'Demonstrate When a B-Tree index helps: equality and range queries, sorting in a small working example.', 'Demonstrate When a B-Tree index does NOT help — and gets ignored by the planner (ties back to Phase 05''s EXPLAIN ANALYZE) in a small working example.']::text[], array['Submit a working B-Tree Indexes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m02-t02', 'zte-backend-java-v1-core-phase-11-m02', 'Composite Indexes', array['Explain and apply null in Composite Indexes.', 'Use Composite Indexes to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Column order matters — why an index on (a, b) doesn''t help a query filtering only on b in a small working example.', 'Demonstrate Covering indexes — when an index alone satisfies a query without touching the table in a small working example.', 'Demonstrate Multi-column index design in practice, for the Prisma schemas built in Phase 05 in a small working example.']::text[], array['Submit a working Composite Indexes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m02-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m02-t03', 'zte-backend-java-v1-core-phase-11-m02', 'Partial Indexes', array['Explain and apply null in Partial Indexes.', 'Use Partial Indexes to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate WHERE clause on the index definition itself — indexing only rows matching a condition in a small working example.', 'Demonstrate Use case: indexing only active/non-deleted rows for a soft-delete pattern in a small working example.', 'Demonstrate Smaller index size and faster writes vs a full-table index, at the cost of only helping queries matching that same condition in a small working example.']::text[], array['Submit a working Partial Indexes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m02-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m02-t04', 'zte-backend-java-v1-core-phase-11-m02', 'Materialized Views', array['Explain and apply null in Materialized Views.', 'Use Materialized Views to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Regular views vs materialized views — the difference between a saved query and a saved, physically-stored result in a small working example.', 'Demonstrate REFRESH MATERIALIZED VIEW — manual vs scheduled refresh strategies in a small working example.', 'Demonstrate When a materialized view beats indexing alone: expensive aggregations/joins queried repeatedly with acceptable staleness in a small working example.']::text[], array['Submit a working Materialized Views example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m02-t03']::text[], '[]'::jsonb, 240, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-11-m03', 'zte-backend-java-v1-core-phase-11', 3, 'Storage & Concurrency Internals', 'The deepest topics in the phase. Ordered so MVCC comes first (it explains what VACUUM cleans up), then WAL (which read replicas directly depend on for replication), then monitoring (most useful once there''s real concurrent/replicated activity to observe).', 13.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m03-t01', 'zte-backend-java-v1-core-phase-11-m03', 'VACUUM', array['Explain and apply null in VACUUM.', 'Use VACUUM to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate What VACUUM actually does — reclaiming space from dead tuples, updating statistics for the query planner in a small working example.', 'Demonstrate Autovacuum — PostgreSQL''s automatic background process, and when its defaults need tuning in a small working example.', 'Demonstrate VACUUM FULL — the more aggressive, table-locking variant, and why it''s rarely run casually in a small working example.', 'Demonstrate Table bloat — what happens when VACUUM falls behind on a high-write table in a small working example.']::text[], array['Submit a working VACUUM example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m03-t02', 'zte-backend-java-v1-core-phase-11-m03', 'MVCC (Multi-Version Concurrency Control)', array['Explain and apply null in MVCC (Multi-Version Concurrency Control).', 'Use MVCC (Multi-Version Concurrency Control) to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Why PostgreSQL doesn''t use simple read locks — readers never block writers and vice versa in a small working example.', 'Demonstrate Row versioning — an UPDATE creates a new row version rather than overwriting in place; a DELETE marks a row dead rather than removing it immediately in a small working example.', 'Demonstrate Transaction visibility — how PostgreSQL determines which row versions a given transaction can see in a small working example.', 'Demonstrate Dead tuples — the direct consequence of MVCC''s versioning approach, and exactly what VACUUM (9) is for in a small working example.', 'Demonstrate Connecting this back to the isolation levels covered in Phase 05 — MVCC is the mechanism underneath them in a small working example.']::text[], array['Submit a working MVCC (Multi-Version Concurrency Control) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m03-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m03-t03', 'zte-backend-java-v1-core-phase-11-m03', 'WAL (Write-Ahead Log)', array['Explain and apply null in WAL (Write-Ahead Log).', 'Use WAL (Write-Ahead Log) to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate The write-ahead logging principle — changes are logged before they''re applied to the actual data files, guaranteeing crash recovery in a small working example.', 'Demonstrate How WAL enables point-in-time recovery in a small working example.', 'Demonstrate WAL as the mechanism underlying replication (11) — replicas are built by streaming and replaying the WAL in a small working example.']::text[], array['Submit a working WAL (Write-Ahead Log) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m03-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m03-t04', 'zte-backend-java-v1-core-phase-11-m03', 'Read Replicas', array['Explain and apply null in Read Replicas.', 'Use Read Replicas to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Streaming replication — how a replica stays in sync via WAL (10) in a small working example.', 'Demonstrate Read replicas for scaling read-heavy workloads — directing SELECT queries away from the primary in a small working example.', 'Demonstrate Replication lag — why replicas aren''t perfectly real-time, and the consistency implications in a small working example.', 'Demonstrate Failover concepts — promoting a replica to primary (conceptual) in a small working example.']::text[], array['Submit a working Read Replicas example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m03-t03']::text[], '[]'::jsonb, 240, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m03-t05', 'zte-backend-java-v1-core-phase-11-m03', 'pg_stat_activity', array['Explain and apply null in pg_stat_activity.', 'Use pg_stat_activity to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Querying pg_stat_activity to see currently running queries and connections in a small working example.', 'Demonstrate Identifying long-running or blocked queries in real time in a small working example.', 'Demonstrate Connecting this back to PgBouncer (Phase 09) — diagnosing connection pool exhaustion in a small working example.']::text[], array['Submit a working pg_stat_activity example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m03-t04']::text[], '[]'::jsonb, 120, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-11-m04', 'zte-backend-java-v1-core-phase-11', 4, 'Search', 'A genuinely independent theme from Stages 1–3, ordered from PostgreSQL''s built-in option (needing nothing new infrastructure-wise) to increasingly dedicated, heavyweight search engines.', 16, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m04-t01', 'zte-backend-java-v1-core-phase-11-m04', 'PostgreSQL Full Text Search', array['Explain and apply null in PostgreSQL Full Text Search.', 'Use PostgreSQL Full Text Search to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate tsvector and tsquery — PostgreSQL''s text search data types in a small working example.', 'Demonstrate GIN indexes for full text search (connects back to Stage 2''s index depth) in a small working example.', 'Demonstrate Ranking search results (ts_rank) in a small working example.', 'Demonstrate Limitations — why PostgreSQL FTS eventually stops scaling for complex search needs, motivating dedicated search engines (14–16) in a small working example.']::text[], array['Submit a working PostgreSQL Full Text Search example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array[]::text[], '[]'::jsonb, 540, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m04-t02', 'zte-backend-java-v1-core-phase-11-m04', 'Meilisearch', array['Explain and apply null in Meilisearch.', 'Use Meilisearch to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Typo tolerance and instant search — the specific gaps PostgreSQL FTS (13) doesn''t fill well in a small working example.', 'Demonstrate Indexing documents from your PostgreSQL data (syncing strategy) in a small working example.', 'Demonstrate Filtering and faceted search in a small working example.', 'Demonstrate Meilisearch''s simplicity vs Elasticsearch''s power — the tradeoff this tool is positioned around in a small working example.']::text[], array['Submit a working Meilisearch example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m04-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m04-t03', 'zte-backend-java-v1-core-phase-11-m04', 'Typesense', array['Explain and apply null in Typesense.', 'Use Typesense to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Core feature parity with Meilisearch — typo tolerance, instant search, faceting in a small working example.', 'Demonstrate Where Typesense differs — schema requirements, specific performance characteristics in a small working example.', 'Demonstrate Choosing between Meilisearch and Typesense for a given project in a small working example.']::text[], array['Submit a working Typesense example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m04-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-m04-t04', 'zte-backend-java-v1-core-phase-11-m04', 'Elasticsearch', array['Explain and apply null in Elasticsearch.', 'Use Elasticsearch to complete a practical task in Real-Time + Search + PostgreSQL Internals.']::text[], array['Demonstrate Inverted index — the core data structure behind Elasticsearch''s search performance in a small working example.', 'Demonstrate Documents, indices, mappings — Elasticsearch''s data model in a small working example.', 'Demonstrate Query DSL — structuring complex search queries in a small working example.', 'Demonstrate When Elasticsearch''s operational complexity (cluster management, resource requirements) is actually justified vs when Meilisearch/Typesense (14, 15) would have been enough in a small working example.']::text[], array['Submit a working Elasticsearch example and explain the key decisions.', 'Record a short review showing how the example satisfies the Real-Time + Search + PostgreSQL Internals learning goal.']::text[], array['zte-backend-java-v1-core-phase-11-m04-t03']::text[], '[]'::jsonb, 720, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-project-01', 'zte-backend-java-v1-core-phase-11', 'Peer-to-Peer Video Chat', 'A 1:1 video call app using WebRTC with a signaling server (over WebSockets), including screen-share support and graceful handling of connection failures/ICE negotiation issues. Domain: communication tools.', array['Deliver the working outcome described in the Peer-to-Peer Video Chat brief.', 'Use at least two skills from Real-Time Communication.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Peer-to-Peer Video Chat', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Real-Time Communication']::text[], 'advanced', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-project-02', 'zte-backend-java-v1-core-phase-11', 'Materialized View Reporting Dashboard', 'Build a reporting dashboard backed by materialized views for expensive aggregate queries (e.g., daily sales rollups), with a documented refresh strategy (scheduled vs on-demand) and a before/after query-time comparison vs. querying raw tables directly.', array['Deliver the working outcome described in the Materialized View Reporting Dashboard brief.', 'Use at least two skills from PostgreSQL Index Depth.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Materialized View Reporting Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'PostgreSQL Index Depth']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-project-03', 'zte-backend-java-v1-core-phase-11', 'MVCC Behavior Demonstration Lab', 'A hands-on demo (two concurrent psql sessions) that reproduces and documents MVCC behavior: a long-running transaction not seeing another session’s committed changes, then explains what VACUUM is cleaning up afterward, with pg_stat_activity screenshots showing the live transaction state.', array['Deliver the working outcome described in the MVCC Behavior Demonstration Lab brief.', 'Use at least two skills from Storage & Concurrency Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working MVCC Behavior Demonstration Lab', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Storage & Concurrency Internals']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-project-04', 'zte-backend-java-v1-core-phase-11', 'Read Replica Lag Simulation', 'Set up a primary + read replica PostgreSQL setup (locally via Docker), write to primary, read from replica, and deliberately induce and measure replication lag under write load, documenting a strategy for handling read-after-write consistency issues in application code.', array['Deliver the working outcome described in the Read Replica Lag Simulation brief.', 'Use at least two skills from Storage & Concurrency Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Read Replica Lag Simulation', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Storage & Concurrency Internals']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-project-05', 'zte-backend-java-v1-core-phase-11', 'Instant Search-As-You-Type with Meilisearch', 'A product catalog with typo-tolerant, sub-50ms instant search using Meilisearch, including faceted filtering (category, price range) synced from the primary database. Domain: e-commerce.', array['Deliver the working outcome described in the Instant Search-As-You-Type with Meilisearch brief.', 'Use at least two skills from Search.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Instant Search-As-You-Type with Meilisearch', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Search']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-project-06', 'zte-backend-java-v1-core-phase-11', 'Search Engine Bake-Off', 'Index the identical dataset (e.g., 50k products) into Postgres full-text search, Typesense, and Elasticsearch, then benchmark query latency, relevance quality, and typo tolerance across all three with a written recommendation for different use-case scales. Domain: search infrastructure / platform engineering.', array['Deliver the working outcome described in the Search Engine Bake-Off brief.', 'Use at least two skills from Search.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Search Engine Bake-Off', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'Search']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-11-project-07', 'zte-backend-java-v1-core-phase-11', 'A Real-Time Collaborative Marketplace with Enterprise-Grade Search', 'A live marketplace/auction-style platform combining: WebSocket-based real-time bidding with room-scoped broadcasts and an SSE-based public "live activity feed," a PostgreSQL schema tuned with composite and partial indexes validated via EXPLAIN ANALYZE, materialized-view-backed seller analytics dashboards, documented MVCC/replication behavior from a local primary+replica setup, and Elasticsearch-powered faceted, typo-tolerant listing search benchmarked against a Postgres full-text fallback. Domain: marketplace / e-commerce infrastructure. Why it matters: real-time interactivity and fast, relevant search are the two hardest-to-fake capabilities in consumer products — this project proves you can build both on solid database fundamentals, not just bolt on a SaaS widget.', array['Deliver the working outcome described in the A Real-Time Collaborative Marketplace with Enterprise-Grade Search brief.', 'Use at least two skills from Real-Time + Search + PostgreSQL Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Real-Time Collaborative Marketplace with Enterprise-Grade Search', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Real-Time + Search + PostgreSQL Internals', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-12', 'zte-backend-java-v1', id, '14', 'AI/RAG + Production AI Patterns', 'Advanced', 'Requires a real backend (Phase 05\\) to call these APIs from server-side, and background/job infrastructure context (Phase 09''s Redis) that Stage 4 will build on. OpenAI is placed first as the first provider learned; Anthropic follows as the second, before anything compares or routes between them.', 207, 13 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-12-m01', 'zte-backend-java-v1-core-phase-12', 1, 'LLM API Foundations', 'Requires a real backend (Phase 05\\) to call these APIs from server-side, and background/job infrastructure context (Phase 09''s Redis) that Stage 4 will build on. OpenAI is placed first as the first provider learned; Anthropic follows as the second, before anything compares or routes between them.', 8.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m01-t01', 'zte-backend-java-v1-core-phase-12-m01', 'OpenAI API', array['Explain and apply null in OpenAI API.', 'Use OpenAI API to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Authentication and client setup — API keys, environment variable handling (ties back to Phase 01''s Node.js env patterns) in a small working example.', 'Demonstrate Chat completions — the core request/response shape in a small working example.', 'Demonstrate Streaming responses — token-by-token output instead of waiting for the full completion in a small working example.', 'Demonstrate Function/tool definitions at the API level (foundational for Stage 6''s structured extraction) in a small working example.', 'Demonstrate Error handling — rate limits, context length errors, retries in a small working example.']::text[], array['Submit a working OpenAI API example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m01-t02', 'zte-backend-java-v1-core-phase-12-m01', 'GPT-4o', array['Explain and apply null in GPT-4o.', 'Use GPT-4o to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate GPT-4o''s multimodal capabilities — text, image, audio input in one model in a small working example.', 'Demonstrate Context window size and practical implications for RAG (Stage 3) and long conversations in a small working example.', 'Demonstrate Where GPT-4o sits in OpenAI''s model lineup — cost/capability tradeoff vs smaller models in a small working example.']::text[], array['Submit a working GPT-4o example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m01-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m01-t03', 'zte-backend-java-v1-core-phase-12-m01', 'Anthropic API', array['Explain and apply null in Anthropic API.', 'Use Anthropic API to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Authentication and client setup — parallels OpenAI (1), with real differences in request/response shape in a small working example.', 'Demonstrate Messages API — Anthropic''s core request format in a small working example.', 'Demonstrate Streaming responses in a small working example.', 'Demonstrate System prompts as a first-class, separate parameter — a structural difference from OpenAI''s message-array approach worth noting explicitly in a small working example.']::text[], array['Submit a working Anthropic API example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m01-t02']::text[], '[]'::jsonb, 300, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-12-m02', 'zte-backend-java-v1-core-phase-12', 2, 'Embeddings & Vector Storage and RAG (The Synthesis) and RAG (The Synthesis)', 'Requires OpenAI API access (Stage 1\\) for the embedding model itself, and Phase 05/11''s PostgreSQL depth as the storage layer these vectors live in.', 9.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m02-t01', 'zte-backend-java-v1-core-phase-12-m02', 'text-embedding-3-small', array['Explain and apply null in text-embedding-3-small.', 'Use text-embedding-3-small to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate What an embedding actually is — a fixed-length vector representing semantic meaning in a small working example.', 'Demonstrate Why "small" — the cost/dimensionality tradeoff vs larger embedding models in a small working example.', 'Demonstrate Cosine similarity as the standard way to compare two embeddings for semantic closeness in a small working example.', 'Demonstrate Batching embedding requests for efficiency in a small working example.']::text[], array['Submit a working text-embedding-3-small example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m02-t02', 'zte-backend-java-v1-core-phase-12-m02', 'pgvector', array['Explain and apply null in pgvector.', 'Use pgvector to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate The vector column type — storing embeddings directly in PostgreSQL rows alongside relational data in a small working example.', 'Demonstrate Distance operators — L2, cosine distance, inner product — and which matches text-embedding-3-small''s intended usage in a small working example.', 'Demonstrate Why storing vectors in PostgreSQL (vs a dedicated vector database) is often the right call — no new infrastructure, joins with existing relational data (ties back to Phase 05''s schema design) in a small working example.', 'Demonstrate Basic similarity search — ORDER BY embedding <=> query_vector LIMIT n in a small working example.']::text[], array['Submit a working pgvector example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m02-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m02-t03', 'zte-backend-java-v1-core-phase-12-m02', 'IVFFlat Index', array['Explain and apply null in IVFFlat Index.', 'Use IVFFlat Index to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Why a sequential scan becomes too slow for similarity search as a table grows — the same motivation as B-Tree indexes in Phase 11, applied to vectors in a small working example.', 'Demonstrate IVFFlat''s approach — clustering vectors into lists, searching only the nearest clusters in a small working example.', 'Demonstrate Tuning the lists parameter — the recall/speed tradeoff in a small working example.', 'Demonstrate When IVFFlat needs to be rebuilt as data grows in a small working example.']::text[], array['Submit a working IVFFlat Index example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m02-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m02-t04', 'zte-backend-java-v1-core-phase-12-m02', 'HNSW Index', array['Explain and apply null in HNSW Index.', 'Use HNSW Index to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate HNSW''s approach — a navigable graph structure, vs IVFFlat''s clustering approach in a small working example.', 'Demonstrate Build time and memory cost — HNSW is typically more expensive to build than IVFFlat in a small working example.', 'Demonstrate Query performance and recall — why HNSW is often preferred despite the build cost in a small working example.', 'Demonstrate Choosing between IVFFlat and HNSW for a given dataset size and update frequency in a small working example.']::text[], array['Submit a working HNSW Index example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m02-t03']::text[], '[]'::jsonb, 240, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m02-t05', 'zte-backend-java-v1-core-phase-12-m02', 'RAG Pattern', array['Explain and apply Core Pipeline in RAG Pattern.', 'Explain and apply Retrieval Quality in RAG Pattern.', 'Explain and apply Production Concerns in RAG Pattern.']::text[], array['Demonstrate Chunking strategy — fixed-size, semantic, and hierarchical chunking, and the tradeoffs between them in a small working example.', 'Demonstrate Embedding chunks and storing them via pgvector (Stage 2) in a small working example.', 'Demonstrate Retrieval — similarity search against the query''s embedding to find relevant chunks in a small working example.', 'Demonstrate Augmentation — inserting retrieved chunks into the LLM prompt as context in a small working example.', 'Demonstrate Generation — the LLM (Stage 1) producing a response grounded in retrieved context in a small working example.']::text[], array['Submit a working RAG Pattern example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m02-t04']::text[], '[]'::jsonb, 1440, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-12-m03', 'zte-backend-java-v1-core-phase-12', 3, 'SDK & Background Jobs', 'Requires RAG (Stage 3\\) to exist as real work worth simplifying (Vercel AI SDK) and queuing (BullMQ) — introducing these tools before there''s a real pipeline to apply them to would make them abstract.', 8, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m03-t01', 'zte-backend-java-v1-core-phase-12-m03', 'Vercel AI SDK', array['Explain and apply null in Vercel AI SDK.', 'Use Vercel AI SDK to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Unified interface across OpenAI and Anthropic (Stage 1) — one API surface for multiple providers in a small working example.', 'Demonstrate Streaming helpers — simplifying the token-by-token streaming already understood from Stage 1 in a small working example.', 'Demonstrate useChat and related React hooks (ties back to Phase 02) for wiring streaming responses into a UI in a small working example.', 'Demonstrate Tool calling support built into the SDK (foreshadows Stage 6) in a small working example.']::text[], array['Submit a working Vercel AI SDK example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 420, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m03-t02', 'zte-backend-java-v1-core-phase-12-m03', 'BullMQ', array['Explain and apply null in BullMQ.', 'Use BullMQ to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Why embedding generation and document indexing belong in a background job, not an inline request/response cycle in a small working example.', 'Demonstrate Queue, worker, and job concepts — producer/consumer model in a small working example.', 'Demonstrate Job priority, concurrency limits, and rate limiting API calls to OpenAI/Anthropic (Stage 1) to avoid hitting provider rate limits in a small working example.', 'Demonstrate Retry strategies and dead-letter queues (DLQ) for jobs that fail repeatedly in a small working example.', 'Demonstrate Idempotency in job processing — ties back to Phase 09''s Razorpay webhook idempotency discussion, same underlying problem in a small working example.']::text[], array['Submit a working BullMQ example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m03-t01']::text[], '[]'::jsonb, 960, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m03-t03', 'zte-backend-java-v1-core-phase-12-m03', 'Bull Board', array['Explain and apply null in Bull Board.', 'Use Bull Board to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Visualizing queue state — active, waiting, completed, failed jobs in a small working example.', 'Demonstrate Manually retrying or removing failed jobs from the dashboard in a small working example.', 'Demonstrate Using this for production AI job monitoring — a concrete artifact showing "production AI, not toy AI," per the official curriculum''s own framing in a small working example.']::text[], array['Submit a working Bull Board example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m03-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-12-m04', 'zte-backend-java-v1-core-phase-12', 4, 'Claude-Specific Depth', 'Requires the Anthropic API (Stage 1, Topic 3\\) as the foundation — these three topics are all Claude-specific behavior on top of the basic Messages API already covered.', 5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m04-t01', 'zte-backend-java-v1-core-phase-12-m04', 'Claude Model Tier Strategy', array['Explain and apply null in Claude Model Tier Strategy.', 'Use Claude Model Tier Strategy to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Haiku vs Sonnet vs Opus — the cost/capability/speed tradeoff across Anthropic''s model tiers in a small working example.', 'Demonstrate Matching a task to the right tier — classification/extraction (cheaper tier) vs complex generation (higher tier) in a small working example.', 'Demonstrate This is the first concrete decision-point that Stage 7''s cost tracking will later measure in a small working example.']::text[], array['Submit a working Claude Model Tier Strategy example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m04-t02', 'zte-backend-java-v1-core-phase-12-m04', 'Extended Thinking', array['Explain and apply null in Extended Thinking.', 'Use Extended Thinking to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate What extended thinking does — allowing the model additional reasoning tokens before producing a final answer in a small working example.', 'Demonstrate When it measurably improves output quality — complex multi-step reasoning tasks in a small working example.', 'Demonstrate Cost and latency tradeoff of enabling it in a small working example.']::text[], array['Submit a working Extended Thinking example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m04-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m04-t03', 'zte-backend-java-v1-core-phase-12-m04', 'Prompt Caching', array['Explain and apply null in Prompt Caching.', 'Use Prompt Caching to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate What gets cached — typically large, repeated portions of a prompt (system prompts, RAG context from Stage 3) in a small working example.', 'Demonstrate Cache hit economics — the cost reduction ROI for repeated context across requests in a small working example.', 'Demonstrate Cache invalidation — when cached content stops being reusable in a small working example.', 'Demonstrate Designing prompts specifically to maximize cacheable portions (structuring stable content before dynamic content) in a small working example.']::text[], array['Submit a working Prompt Caching example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m04-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-12-m05', 'zte-backend-java-v1-core-phase-12', 5, 'Structured Output & Multi-Model Routing', 'Both topics require both providers (Stage 1\\) to be genuinely understood — tool calling is commonly needed across either provider, and routing is meaningless with only one model to route to.', 6, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m05-t01', 'zte-backend-java-v1-core-phase-12-m05', 'Tool Calling for Structured Extraction', array['Explain and apply null in Tool Calling for Structured Extraction.', 'Use Tool Calling for Structured Extraction to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Defining tool/function schemas — parameter types, descriptions the model uses to decide when and how to call a tool in a small working example.', 'Demonstrate The extraction pattern — using tool calling not to actually call a function, but to force the model into producing structured JSON output in a small working example.', 'Demonstrate Validating tool call outputs — ties back to Zod (Phases 01/03/05) for runtime validation of what the model returns in a small working example.', 'Demonstrate Multi-turn tool use — handling a model''s tool call, executing it, and returning results for the model to continue reasoning with in a small working example.']::text[], array['Submit a working Tool Calling for Structured Extraction example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m05-t02', 'zte-backend-java-v1-core-phase-12-m05', 'Multi-Model Routing', array['Explain and apply null in Multi-Model Routing.', 'Use Multi-Model Routing to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Routing logic — sending a request to the model best suited for it, not defaulting to one provider for everything in a small working example.', 'Demonstrate Common routing signals: task complexity, cost sensitivity, latency requirements, specific capability needs (e.g. Claude''s extended thinking, Stage 5, vs GPT-4o''s multimodal input, Stage 1) in a small working example.', 'Demonstrate Fallback strategies — routing to a secondary provider if the primary is rate-limited or down in a small working example.', 'Demonstrate This is the decision-making skill the official curriculum explicitly flags as what separates a real AI engineer from someone who can only call one API in a small working example.']::text[], array['Submit a working Multi-Model Routing example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m05-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-12-m06', 'zte-backend-java-v1-core-phase-12', 6, 'Cost & Governance', 'Requires real multi-model usage (Stage 6\\) to have actual costs across providers worth tracking and governing — introducing cost tracking before there''s real usage would have nothing to measure.', 4, 5) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m06-t01', 'zte-backend-java-v1-core-phase-12-m06', 'AI Cost Tracking', array['Explain and apply null in AI Cost Tracking.', 'Use AI Cost Tracking to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Token counting — input vs output tokens, and why output tokens typically cost more in a small working example.', 'Demonstrate Per-request cost calculation across different models/providers (Stage 1, Stage 5''s tier strategy, Stage 6''s routing) in a small working example.', 'Demonstrate Building a cost dashboard — the concrete artifact the official curriculum calls out as something to highlight in a portfolio in a small working example.', 'Demonstrate Attributing cost to specific features/users for accurate reporting in a small working example.']::text[], array['Submit a working AI Cost Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m06-t02', 'zte-backend-java-v1-core-phase-12-m06', 'Token Budget Enforcement', array['Explain and apply null in Token Budget Enforcement.', 'Use Token Budget Enforcement to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Setting per-user or per-feature token budgets in a small working example.', 'Demonstrate Enforcing budgets before a request is sent (pre-flight estimation) vs after (post-hoc alerting) in a small working example.', 'Demonstrate Graceful degradation when a budget is exceeded — routing to a cheaper model (Stage 6) rather than simply failing in a small working example.']::text[], array['Submit a working Token Budget Enforcement example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m06-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-12-m07', 'zte-backend-java-v1-core-phase-12', 7, 'Prompt Engineering & Evaluation', 'Requires real AI features to exist (RAG from Stage 3, tool calling from Stage 6\\) — both prompt engineering and evaluation are meaningfully practiced against real, built systems, not in the abstract. Evals are placed genuinely last since you need something built before you can evaluate it.', 9, 6) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m07-t01', 'zte-backend-java-v1-core-phase-12-m07', 'System Prompt Engineering', array['Explain and apply null in System Prompt Engineering.', 'Use System Prompt Engineering to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Structuring system prompts — role definition, constraints, output format instructions in a small working example.', 'Demonstrate Few-shot examples within a prompt — when they measurably improve output vs adding noise in a small working example.', 'Demonstrate Prompt injection awareness — treating user input as untrusted within a prompt (security parallel to Phase 02''s XSS/sanitization concerns) in a small working example.', 'Demonstrate Iterating on prompts systematically rather than by trial and error — setting up the mindset Stage 8''s evals (20) will formalize in a small working example.']::text[], array['Submit a working System Prompt Engineering example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-m07-t02', 'zte-backend-java-v1-core-phase-12-m07', 'Eval-Driven AI Development', array['Explain and apply null in Eval-Driven AI Development.', 'Use Eval-Driven AI Development to complete a practical task in AI/RAG + Production AI Patterns.']::text[], array['Demonstrate Building an eval set — representative test cases with expected outputs or grading criteria in a small working example.', 'Demonstrate Metrics that matter beyond "it works": precision/recall for retrieval (Stage 3), exact-match or rubric-based scoring for generation in a small working example.', 'Demonstrate LLM-as-judge — using a model to grade another model''s output, and its limitations in a small working example.', 'Demonstrate Regression testing for prompts — catching quality drops when a prompt or model version changes (ties back to Phase 06''s CI/CD, running evals as part of a pipeline) in a small working example.', 'Demonstrate This is the practice the official curriculum frames as the actual differentiator in interviews — showing how you measure AI quality, not just that a feature works in a small working example.']::text[], array['Submit a working Eval-Driven AI Development example and explain the key decisions.', 'Record a short review showing how the example satisfies the AI/RAG + Production AI Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-12-m07-t01']::text[], '[]'::jsonb, 960, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-01', 'zte-backend-java-v1-core-phase-12', 'Multi-Provider Prompt Playground', 'A small internal tool that sends the same prompt to both the OpenAI API (GPT-4o) and the Anthropic API side-by-side, displaying responses, latency, and token usage for comparison. Domain: AI tooling / evaluation.', array['Deliver the working outcome described in the Multi-Provider Prompt Playground brief.', 'Use at least two skills from LLM API Foundations.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Provider Prompt Playground', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'LLM API Foundations']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-02', 'zte-backend-java-v1-core-phase-12', 'Structured Support-Ticket Classifier', 'A backend service that classifies incoming support tickets (category, urgency, sentiment) using an LLM API call, with proper error handling for API failures/timeouts and a fallback rule-based classifier if the API is unavailable. Domain: customer support automation.', array['Deliver the working outcome described in the Structured Support-Ticket Classifier brief.', 'Use at least two skills from LLM API Foundations.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Structured Support-Ticket Classifier', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'LLM API Foundations']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-03', 'zte-backend-java-v1-core-phase-12', 'Semantic Duplicate Detector', 'A tool that embeds a set of support tickets or forum posts (text-embedding-3-small) and finds semantic duplicates/near-duplicates using cosine similarity in pgvector, catching duplicates that keyword search would miss. Domain: content moderation / support tooling.', array['Deliver the working outcome described in the Semantic Duplicate Detector brief.', 'Use at least two skills from Embeddings & Vector Storage and RAG (The Synthesis) and RAG (The Synthesis).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Semantic Duplicate Detector', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Embeddings & Vector Storage and RAG (The Synthesis) and RAG (The Synthesis)']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-04', 'zte-backend-java-v1-core-phase-12', 'HNSW vs IVFFlat Benchmark', 'Index the same 100k-vector embedding set with both IVFFlat and HNSW in pgvector, benchmarking query latency and recall accuracy tradeoffs at different index parameters, with a written recommendation document. Domain: vector search infrastructure.', array['Deliver the working outcome described in the HNSW vs IVFFlat Benchmark brief.', 'Use at least two skills from Embeddings & Vector Storage and RAG (The Synthesis) and RAG (The Synthesis).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working HNSW vs IVFFlat Benchmark', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Embeddings & Vector Storage and RAG (The Synthesis) and RAG (The Synthesis)']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-05', 'zte-backend-java-v1-core-phase-12', 'Multi-Document Research Assistant with Chunking Strategy Comparison', 'A RAG pipeline over a corpus of long-form documents (e.g., legal or research PDFs) that compares 3 different chunking strategies (fixed-size, semantic, sliding-window-with-overlap) on retrieval quality for the same question set, with a written evaluation report. Domain: legal-tech / research tooling.', array['Deliver the working outcome described in the Multi-Document Research Assistant with Chunking Strategy Comparison brief.', 'Use at least two skills from RAG (The Synthesis).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Document Research Assistant with Chunking Strategy Comparison', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'RAG (The Synthesis)']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-06', 'zte-backend-java-v1-core-phase-12', 'Streaming AI Chat UI', 'A chat interface using the Vercel AI SDK with true token-by-token streaming responses, stop/regenerate controls, and conversation history persistence. Domain: AI product UX. A system where users submit a batch of documents for AI summarization; jobs are queued in BullMQ (not processed synchronously in the request), with a Bull Board dashboard for monitoring job status, retries, and failures. Domain: AI infrastructure / batch processing.', array['Deliver the working outcome described in the Streaming AI Chat UI brief.', 'Use at least two skills from SDK & Background Jobs.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Streaming AI Chat UI', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'SDK & Background Jobs']::text[], 'intermediate', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-07', 'zte-backend-java-v1-core-phase-12', 'Cost-Optimized Multi-Tier Support Bot', 'A support bot that routes simple questions to a smaller/cheaper Claude model tier and escalates complex questions to a larger tier, with prompt caching applied to the large, static system prompt/knowledge base portion to cut repeated-request cost. Domain: AI cost engineering.', array['Deliver the working outcome described in the Cost-Optimized Multi-Tier Support Bot brief.', 'Use at least two skills from Claude-Specific Depth.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cost-Optimized Multi-Tier Support Bot', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Claude-Specific Depth']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-08', 'zte-backend-java-v1-core-phase-12', 'Receipt-to-Structured-Data Extractor', 'A tool that takes a photo/text of a receipt and uses tool calling to extract guaranteed-valid structured JSON (line items, totals, tax) validated against a schema, with a test suite of malformed/tricky receipts. Domain: fintech / expense automation.', array['Deliver the working outcome described in the Receipt-to-Structured-Data Extractor brief.', 'Use at least two skills from Structured Output & Multi-Model Routing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Receipt-to-Structured-Data Extractor', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Structured Output & Multi-Model Routing']::text[], 'intermediate', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-09', 'zte-backend-java-v1-core-phase-12', 'Cost-Aware Multi-Model Router', 'A routing layer that sends each incoming request to the cheapest model capable of handling it correctly (classified by a lightweight pre-check), falling back to a stronger model on low-confidence responses, with logged cost savings versus an always-use-the-best-model baseline. Domain: AI infrastructure / cost engineering.', array['Deliver the working outcome described in the Cost-Aware Multi-Model Router brief.', 'Use at least two skills from Structured Output & Multi-Model Routing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cost-Aware Multi-Model Router', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Structured Output & Multi-Model Routing']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-10', 'zte-backend-java-v1-core-phase-12', 'Prompt Version Control & Regression Suite', 'A system prompt library with versioned prompts and an automated eval suite (a fixed set of test inputs with expected-quality criteria) that runs on every prompt change to catch regressions before deploying a new prompt version. Domain: AI engineering / MLOps.', array['Deliver the working outcome described in the Prompt Version Control & Regression Suite brief.', 'Use at least two skills from Prompt Engineering & Evaluation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Prompt Version Control & Regression Suite', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Prompt Engineering & Evaluation']::text[], 'intermediate', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-11', 'zte-backend-java-v1-core-phase-12', 'Eval-Driven Support Bot Improvement Cycle', 'Take the Stage 5 support bot, build a 30-example golden eval dataset with graded expected outputs, establish a baseline score, then iterate on the system prompt 3 times, re-running the eval each time and documenting the score progression and specific failure modes fixed. Domain: AI quality engineering.', array['Deliver the working outcome described in the Eval-Driven Support Bot Improvement Cycle brief.', 'Use at least two skills from Prompt Engineering & Evaluation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Eval-Driven Support Bot Improvement Cycle', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'Prompt Engineering & Evaluation']::text[], 'advanced', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-12-project-12', 'zte-backend-java-v1-core-phase-12', 'A Cost-Governed, Eval-Tested RAG Support Platform', 'A complete production-pattern AI support platform: a documentation-grounded RAG pipeline (pgvector, chunking strategy chosen via comparison testing, citation tracking), a cost-optimized multi-tier Claude routing layer with prompt caching on the static knowledge base, tool-calling-based structured ticket extraction validated with Zod, BullMQ-queued background processing for bulk document ingestion with a Bull Board monitoring dashboard, a real-time AI cost dashboard with hard budget enforcement per organization, and a versioned prompt library backed by an automated golden-dataset eval suite that must pass before any prompt change ships. Domain: enterprise AI / support automation. Why it matters: this is what separates "called an LLM API" from "built a production AI system" — grounding, cost control, and evaluation discipline are the actual hard parts.', array['Deliver the working outcome described in the A Cost-Governed, Eval-Tested RAG Support Platform brief.', 'Use at least two skills from AI/RAG + Production AI Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Cost-Governed, Eval-Tested RAG Support Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['AI/RAG + Production AI Patterns', 'engineering documentation']::text[], 'advanced', 11) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-13', 'zte-backend-java-v1', id, '15', 'Advanced Browser APIs + Collaboration', 'Advanced', 'Requires Phase 02''s localStorage/sessionStorage as the point of comparison — IndexedDB is what those simpler APIs can''t handle: large, structured, queryable client-side data.', 137, 14 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-13-m01', 'zte-backend-java-v1-core-phase-13', 1, 'Client-Side Storage', 'Requires Phase 02''s localStorage/sessionStorage as the point of comparison — IndexedDB is what those simpler APIs can''t handle: large, structured, queryable client-side data.', 5.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m01-t01', 'zte-backend-java-v1-core-phase-13-m01', 'IndexedDB', array['Explain and apply Core Concepts in IndexedDB.', 'Explain and apply Working with Data in IndexedDB.', 'Explain and apply Practical Use in IndexedDB.']::text[], array['Demonstrate Why IndexedDB exists — localStorage''s synchronous, string-only, size-limited model breaks down for real offline-capable apps in a small working example.', 'Demonstrate Databases, object stores, and transactions — IndexedDB''s structural model in a small working example.', 'Demonstrate Keys and key paths — auto-incrementing keys vs application-defined keys in a small working example.', 'Demonstrate CRUD operations via the raw IndexedDB API — verbose, callback/event-based by design in a small working example.', 'Demonstrate Indexes — querying by a field other than the primary key in a small working example.']::text[], array['Submit a working IndexedDB example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m01-t02', 'zte-backend-java-v1-core-phase-13-m01', 'idb', array['Explain and apply null in idb.', 'Use idb to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why idb exists — IndexedDB''s raw API is unusually verbose and callback-heavy for a modern codebase in a small working example.', 'Demonstrate Promise-based CRUD operations — the same concepts as Topic 1, with async/await instead of event listeners in a small working example.', 'Demonstrate When to use the raw API directly vs idb — idb covers the vast majority of real use cases in a small working example.']::text[], array['Submit a working idb example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m01-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-13-m02', 'zte-backend-java-v1-core-phase-13', 2, 'Parallelism and Cross-Context Communication and Cross-Context Communication', 'Study and apply Parallelism and Cross-Context Communication and Cross-Context Communication in Advanced Browser APIs + Collaboration.', 4.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m02-t01', 'zte-backend-java-v1-core-phase-13-m02', 'Web Workers', array['Explain and apply null in Web Workers.', 'Use Web Workers to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why the main thread matters — JavaScript''s single-threaded execution model and what blocks it (ties back to Phase 01''s event loop) in a small working example.', 'Demonstrate Creating a worker, postMessage/onmessage communication — the structured-clone messaging model in a small working example.', 'Demonstrate What workers can and can''t access — no DOM access, separate global scope in a small working example.', 'Demonstrate Use cases: expensive computation (parsing, image processing), keeping the UI responsive during heavy work in a small working example.']::text[], array['Submit a working Web Workers example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 600, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m02-t02', 'zte-backend-java-v1-core-phase-13-m02', 'comlink', array['Explain and apply null in comlink.', 'Use comlink to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why raw postMessage-based worker communication gets unwieldy for anything beyond trivial message-passing in a small working example.', 'Demonstrate comlink''s proxy-based API — calling worker functions as if they were local async functions in a small working example.', 'Demonstrate When the raw API (3) is still clearer vs when comlink''s abstraction is worth adopting in a small working example.']::text[], array['Submit a working comlink example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m02-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m02-t03', 'zte-backend-java-v1-core-phase-13-m02', 'Broadcast Channel API', array['Explain and apply null in Broadcast Channel API.', 'Use Broadcast Channel API to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Creating a named channel and posting messages to it in a small working example.', 'Demonstrate All same-origin tabs/windows/workers subscribed to the same channel receive the message — the key difference from postMessage''s point-to-point model in a small working example.', 'Demonstrate Use cases: syncing auth state across tabs (logging out in one tab logs out all tabs, ties back to Phase 05''s JWT/session handling), syncing UI state across multiple open windows of the same app in a small working example.']::text[], array['Submit a working Broadcast Channel API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m02-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-13-m03', 'zte-backend-java-v1-core-phase-13', 3, 'Browser Rendering & Animation Internals', 'A cluster of APIs concerned with how and when the browser paints — ordered from the lowest-level timing primitive (rAF) to the most advanced/niche (CSS Houdini).', 7.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m03-t01', 'zte-backend-java-v1-core-phase-13-m03', 'View Transitions API', array['Explain and apply null in View Transitions API.', 'Use View Transitions API to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate document.startViewTransition() — the core API for triggering a transition between two DOM states in a small working example.', 'Demonstrate How the browser captures before/after snapshots and animates between them automatically in a small working example.', 'Demonstrate Named transitions (view-transition-name) for controlling which elements get their own distinct animation in a small working example.', 'Demonstrate Use cases: page transitions in an SPA (Phase 02''s App Router), smooth state changes without hand-rolled animation logic in a small working example.']::text[], array['Submit a working View Transitions API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m03-t02', 'zte-backend-java-v1-core-phase-13-m03', 'requestAnimationFrame', array['Explain and apply null in requestAnimationFrame.', 'Use requestAnimationFrame to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why requestAnimationFrame exists — syncing JavaScript-driven animation with the browser''s actual repaint cycle, instead of guessing with setTimeout (Phase 01) in a small working example.', 'Demonstrate The callback timing guarantee — running right before the next repaint in a small working example.', 'Demonstrate Canceling a scheduled frame (cancelAnimationFrame) in a small working example.', 'Demonstrate Common pattern: using rAF for smooth, manually-driven animations (scroll-linked effects, custom easing) in a small working example.']::text[], array['Submit a working requestAnimationFrame example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m03-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m03-t03', 'zte-backend-java-v1-core-phase-13-m03', 'requestIdleCallback', array['Explain and apply null in requestIdleCallback.', 'Use requestIdleCallback to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate The difference from rAF — rIC runs when the browser is otherwise idle, not on every frame in a small working example.', 'Demonstrate Use cases: low-priority background work (analytics batching, prefetching) that shouldn''t compete with rendering or user input in a small working example.', 'Demonstrate The timeout option — forcing execution even if the browser never reports idle time in a small working example.', 'Demonstrate Browser support caveats and Safari''s lack of support (practical consideration) in a small working example.']::text[], array['Submit a working requestIdleCallback example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m03-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m03-t04', 'zte-backend-java-v1-core-phase-13-m03', 'CSS Houdini', array['Explain and apply null in CSS Houdini.', 'Use CSS Houdini to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate What Houdini exposes — low-level access to the CSS rendering pipeline (paint, layout, properties) that was previously entirely opaque to developers in a small working example.', 'Demonstrate CSS Paint API — defining custom paint worklets for background-image-style custom rendering in a small working example.', 'Demonstrate Properties and Values API — registering custom CSS properties with actual types (not just strings), enabling smooth animation of previously non-animatable values in a small working example.', 'Demonstrate Realistic scope — Houdini''s browser support and practical adoption level today, versus its role as a forward-looking spec in a small working example.']::text[], array['Submit a working CSS Houdini example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m03-t03']::text[], '[]'::jsonb, 300, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-13-m04', 'zte-backend-java-v1-core-phase-13', 4, 'Real-Time Collaboration: The Yjs Stack', 'The centerpiece of this phase, and the official curriculum''s designated Build in Public moment. Requires WebSockets and WebRTC (Phase 11\\) as transport context, and IndexedDB (Stage 1\\) as a persistence context — Yjs itself is transport- and storage-agnostic, and only makes sense once you understand what it''s being connected to.', 12.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m04-t01', 'zte-backend-java-v1-core-phase-13-m04', 'Yjs', array['Explain and apply CRDT Fundamentals in Yjs.', 'Explain and apply Working with Yjs in Yjs.', 'Explain and apply Transport-Agnostic Design in Yjs.']::text[], array['Demonstrate What a CRDT (Conflict-free Replicated Data Type) is — data structures that can be modified concurrently by multiple users and always converge to the same state without central coordination in a small working example.', 'Demonstrate Why this matters for real-time collaboration — no server-side operational transform logic needed, unlike older collaborative editing approaches in a small working example.', 'Demonstrate Shared types — Y.Text, Y.Array, Y.Map — the building blocks for collaborative documents in a small working example.', 'Demonstrate Documents (Y.Doc) as the root container for shared state in a small working example.', 'Demonstrate Observing changes — subscribing to updates from remote peers in a small working example.']::text[], array['Submit a working Yjs example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 1140, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m04-t02', 'zte-backend-java-v1-core-phase-13-m04', 'Hocuspocus', array['Explain and apply null in Hocuspocus.', 'Use Hocuspocus to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Why a dedicated server framework — running y-websocket directly works for prototypes, but production use needs auth, persistence hooks, and scaling considerations Hocuspocus provides in a small working example.', 'Demonstrate Authentication hooks — connecting document access to your existing auth system (Phase 05''s JWT) in a small working example.', 'Demonstrate Persistence hooks — connecting Hocuspocus to a real database (PostgreSQL, Phase 05) instead of relying solely on in-memory or IndexedDB (13) state in a small working example.', 'Demonstrate Extensions — Hocuspocus''s plugin model for logging, webhooks, and custom persistence backends in a small working example.']::text[], array['Submit a working Hocuspocus example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m04-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m04-t03', 'zte-backend-java-v1-core-phase-13-m04', 'y-websocket', array['Explain and apply null in y-websocket.', 'Use y-websocket to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Setting up a y-websocket server for centralized sync in a small working example.', 'Demonstrate Client-side connection and automatic reconnection in a small working example.', 'Demonstrate When a centralized WebSocket relay is the right transport choice — simpler infrastructure, works behind NATs without STUN/TURN in a small working example.']::text[], array['Submit a working y-websocket example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m04-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m04-t04', 'zte-backend-java-v1-core-phase-13-m04', 'y-webrtc', array['Explain and apply null in y-webrtc.', 'Use y-webrtc to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Peer-to-peer document sync — no central server required for the actual data flow, only for signaling (ties directly back to Phase 11''s WebRTC signaling discussion) in a small working example.', 'Demonstrate Tradeoffs vs y-websocket: no server infrastructure cost, but NAT traversal reliability and scaling to many peers become harder in a small working example.']::text[], array['Submit a working y-webrtc example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m04-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m04-t05', 'zte-backend-java-v1-core-phase-13-m04', 'y-indexeddb', array['Explain and apply null in y-indexeddb.', 'Use y-indexeddb to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Persisting a Y.Doc to IndexedDB (Stage 1) so document state survives a page reload or offline period in a small working example.', 'Demonstrate Combining with a transport provider (11 or 12) — local persistence and network sync are independent, composable concerns in Yjs''s design in a small working example.', 'Demonstrate Offline-first collaborative editing — making local edits while offline, syncing automatically once a transport reconnects in a small working example.']::text[], array['Submit a working y-indexeddb example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m04-t04']::text[], '[]'::jsonb, 120, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-13-m05', 'zte-backend-java-v1-core-phase-13', 5, 'Rich Text Editors', 'Moved from the official ordering — ProseMirror is taught before Tiptap, not after, since Tiptap is a wrapper built directly on top of ProseMirror. This follows the same raw-before-wrapper pattern used throughout this series.', 9, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m05-t01', 'zte-backend-java-v1-core-phase-13-m05', 'Tiptap', array['Explain and apply null in Tiptap.', 'Use Tiptap to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Extension-based architecture — composing an editor from discrete extensions (Bold, Heading, BulletList, etc.), each ultimately a ProseMirror node/mark/plugin under the hood in a small working example.', 'Demonstrate React integration (@tiptap/react) — wiring Tiptap into a component-based UI (Phase 02) in a small working example.', 'Demonstrate Collaborative editing extension — connecting Tiptap directly to Yjs (Stage 5), the practical convergence point of this entire phase: a rich text editor with live multi-cursor collaboration in a small working example.', 'Demonstrate Custom extensions — building your own when Tiptap''s built-in set isn''t enough, which requires the ProseMirror concepts (15) underneath in a small working example.', 'Demonstrate Post: a demo of real-time collaboration (Yjs) — two cursors editing the same document live. This is the direct payoff of Stage 5''s Awareness feature (Topic 10) combined with Stage 6''s Tiptap collaboration extension (Topic 16). in a small working example.']::text[], array['Submit a working Tiptap example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-m05-t02', 'zte-backend-java-v1-core-phase-13-m05', 'ProseMirror', array['Explain and apply null in ProseMirror.', 'Use ProseMirror to complete a practical task in Advanced Browser APIs + Collaboration.']::text[], array['Demonstrate Document schema — ProseMirror''s strict, defined-in-advance model of what content is valid (a deliberate contrast to contentEditable''s anything-goes DOM) in a small working example.', 'Demonstrate Node views and marks — block-level content vs inline formatting in a small working example.', 'Demonstrate Transactions and plugins — ProseMirror''s model for making and intercepting document changes in a small working example.', 'Demonstrate Why ProseMirror is famously powerful but low-level — most teams don''t use it directly, which motivates Tiptap (16) in a small working example.']::text[], array['Submit a working ProseMirror example and explain the key decisions.', 'Record a short review showing how the example satisfies the Advanced Browser APIs + Collaboration learning goal.']::text[], array['zte-backend-java-v1-core-phase-13-m05-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-project-01', 'zte-backend-java-v1-core-phase-13', 'Local-First Bookmark Manager with Sync', 'A bookmark manager storing data primarily in IndexedDB with a background sync-to-server layer, handling the case where local and server data diverge while offline, including a documented conflict-resolution strategy. Domain: productivity tools.', array['Deliver the working outcome described in the Local-First Bookmark Manager with Sync brief.', 'Use at least two skills from Client-Side Storage.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Local-First Bookmark Manager with Sync', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Client-Side Storage']::text[], 'advanced', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-project-02', 'zte-backend-java-v1-core-phase-13', 'CPU-Heavy Data Processing Without UI Freeze', 'A tool that processes a large CSV/JSON file (parsing, aggregation) entirely inside a Web Worker using comlink for clean async communication, keeping the UI thread responsive throughout — with a visible before/after (UI freezes without the worker, doesn’t with it).', array['Deliver the working outcome described in the CPU-Heavy Data Processing Without UI Freeze brief.', 'Use at least two skills from Parallelism and Cross-Context Communication and Cross-Context Communication.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CPU-Heavy Data Processing Without UI Freeze', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Parallelism and Cross-Context Communication and Cross-Context Communication']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-project-03', 'zte-backend-java-v1-core-phase-13', 'Cross-Tab Session Sync', 'A demo app where logging out in one browser tab immediately logs the user out in all other open tabs of the same app, using the Broadcast Channel API. Domain: security/session management UX.', array['Deliver the working outcome described in the Cross-Tab Session Sync brief.', 'Use at least two skills from Cross-Context Communication.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cross-Tab Session Sync', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Cross-Context Communication']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-project-04', 'zte-backend-java-v1-core-phase-13', 'Native Page Transition Gallery', 'A multi-page image gallery using the View Transitions API for smooth native page-to-page morph animations (image expanding into a detail view), with a custom CSS Houdini paint worklet used for one decorative element (e.g., a custom-drawn border or background pattern). Domain: creative/media portfolios.', array['Deliver the working outcome described in the Native Page Transition Gallery brief.', 'Use at least two skills from Browser Rendering & Animation Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Native Page Transition Gallery', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Browser Rendering & Animation Internals']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-project-05', 'zte-backend-java-v1-core-phase-13', 'Offline-Capable Collaborative Doc with Peer Fallback', 'A collaborative text document combining y-indexeddb (offline persistence), y-websocket (primary sync via a Hocuspocus server), and y-webrtc as a peer-to-peer fallback when the server is unreachable, demonstrating that edits made offline merge correctly once any sync path reconnects. Domain: collaborative software infrastructure.', array['Deliver the working outcome described in the Offline-Capable Collaborative Doc with Peer Fallback brief.', 'Use at least two skills from Real-Time Collaboration: The Yjs Stack.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Offline-Capable Collaborative Doc with Peer Fallback', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Real-Time Collaboration: The Yjs Stack']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-project-06', 'zte-backend-java-v1-core-phase-13', 'Notion-Style Block Editor', 'A rich text editor built with Tiptap (on ProseMirror) supporting headings, lists, code blocks, and a custom block type you build yourself (e.g., an embeddable "callout" box), with full keyboard shortcuts and markdown-style input rules (typing "# " converts to a heading). Domain: productivity / content tools. Integrate Tiptap with Yjs for real-time collaborative rich-text editing with live cursors showing collaborator names/colors — a genuine Google-Docs-style editing experience built from open primitives. Domain: collaborative software.', array['Deliver the working outcome described in the Notion-Style Block Editor brief.', 'Use at least two skills from Rich Text Editors.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Notion-Style Block Editor', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'Rich Text Editors']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-13-project-07', 'zte-backend-java-v1-core-phase-13', 'A Real-Time Collaborative Document Workspace', 'A Notion/Google-Docs-style collaborative workspace: a Tiptap-based rich text editor with custom block extensions, fully wired to Yjs for real-time collaborative editing (y-websocket primary sync via a Hocuspocus server, y-indexeddb for offline persistence, y-webrtc as a peer-to-peer fallback), live cursor presence, cross-tab session sync via Broadcast Channel, CPU-heavy operations (e.g., full-document search indexing) offloaded to a Web Worker via comlink so typing never lags, and smooth View-Transitions-powered navigation between documents. Domain: collaborative productivity software. Why it matters: real-time collaborative editing is one of the most technically demanding categories of web application — building a working version from open primitives (not a SaaS embed) is a genuine senior-level achievement.', array['Deliver the working outcome described in the A Real-Time Collaborative Document Workspace brief.', 'Use at least two skills from Advanced Browser APIs + Collaboration.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Real-Time Collaborative Document Workspace', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Advanced Browser APIs + Collaboration', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-14', 'zte-backend-java-v1', id, '16', 'Load Testing + Security Deep Dive', 'Advanced', 'Requires a real, deployed app (Phase 06\\) — load testing has nothing to test against before then.', 89, 15 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-14-m01', 'zte-backend-java-v1-core-phase-14', 1, 'Load Testing', 'Requires a real, deployed app (Phase 06\\) — load testing has nothing to test against before then.', 8.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m01-t01', 'zte-backend-java-v1-core-phase-14-m01', 'k6', array['Explain and apply Core Concepts in k6.', 'Explain and apply Test Types in k6.', 'Explain and apply Analyzing Results in k6.']::text[], array['Demonstrate Virtual users (VUs) — simulating concurrent traffic, not just sequential requests in a small working example.', 'Demonstrate Writing test scripts in JavaScript — k6''s scripting model in a small working example.', 'Demonstrate Stages — ramping traffic up and down over the course of a test, rather than a flat constant load in a small working example.', 'Demonstrate Load testing — expected normal-to-peak traffic in a small working example.', 'Demonstrate Stress testing — pushing past expected capacity to find the breaking point in a small working example.']::text[], array['Submit a working k6 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 720, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m01-t02', 'zte-backend-java-v1-core-phase-14-m01', 'k6 Cloud', array['Explain and apply null in k6 Cloud.', 'Use k6 Cloud to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Running k6 scripts from multiple geographic load zones — testing latency for real-world distributed users, not just from one machine in a small working example.', 'Demonstrate Result dashboards and historical trend comparison across test runs in a small working example.', 'Demonstrate When local k6 is sufficient vs when cloud-scale load generation is actually needed in a small working example.']::text[], array['Submit a working k6 Cloud example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m01-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m01-t03', 'zte-backend-java-v1-core-phase-14-m01', 'Artillery', array['Explain and apply null in Artillery.', 'Use Artillery to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate YAML-based test definitions vs k6''s JavaScript scripting — a different authoring philosophy in a small working example.', 'Demonstrate Artillery''s plugin ecosystem for protocol support beyond plain HTTP (WebSockets, ties back to Phase 11/13''s real-time work) in a small working example.', 'Demonstrate When Artillery''s approach fits better than k6''s — teams preferring declarative config over scripted tests in a small working example.']::text[], array['Submit a working Artillery example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m01-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-14-m02', 'zte-backend-java-v1-core-phase-14', 2, 'Security Threat Model & Scanning', 'OWASP Top 10 is placed first in this stage deliberately — it''s the threat model everything else in this stage addresses. Learning ZAP, CSP, or JWT pinning before understanding what threats they mitigate would teach tool operation without the reasoning behind it.', 12.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m02-t01', 'zte-backend-java-v1-core-phase-14-m02', 'OWASP Top 10', array['Explain and apply null in OWASP Top 10.', 'Use OWASP Top 10 to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Broken Access Control — the most common real-world vulnerability, and how it shows up in practice (ties back to Phase 05''s auth/authorization patterns) in a small working example.', 'Demonstrate Cryptographic Failures — weak hashing, exposed secrets (foreshadows Stage 3) in a small working example.', 'Demonstrate Injection — SQL injection specifically (ties back to Phase 05''s Prisma usage, which parameterizes queries by default — understanding why that matters) in a small working example.', 'Demonstrate Insecure Design — a threat category about architecture decisions, not just code bugs in a small working example.', 'Demonstrate Security Misconfiguration — default credentials, verbose error messages, unnecessary exposed endpoints in a small working example.']::text[], array['Submit a working OWASP Top 10 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 1020, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m02-t02', 'zte-backend-java-v1-core-phase-14-m02', 'OWASP ZAP', array['Explain and apply null in OWASP ZAP.', 'Use OWASP ZAP to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Automated vulnerability scanning — passive scanning (observing traffic) vs active scanning (actively probing for issues) in a small working example.', 'Demonstrate Running ZAP against your deployed app (Phase 06) or a staging environment — never production without deliberate care in a small working example.', 'Demonstrate Interpreting ZAP''s findings — triaging real vulnerabilities against false positives in a small working example.', 'Demonstrate Integrating ZAP into CI (Phase 06''s GitHub Actions) for continuous scanning in a small working example.']::text[], array['Submit a working OWASP ZAP example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m02-t01']::text[], '[]'::jsonb, 480, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m02-t03', 'zte-backend-java-v1-core-phase-14-m02', 'Nonce-Based CSP', array['Explain and apply null in Nonce-Based CSP.', 'Use Nonce-Based CSP to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Content Security Policy recap from Phase 05''s Helmet.js — the baseline this topic extends in a small working example.', 'Demonstrate Why ''unsafe-inline'' defeats much of CSP''s protection, and why nonces exist to allow specific inline scripts without that blanket exception in a small working example.', 'Demonstrate Generating a per-request nonce and threading it through to both the CSP header and the script tags that need it (a real implementation challenge in a Next.js/Server Component context, Phase 02) in a small working example.', 'Demonstrate Testing that a nonce-based policy actually blocks unauthorized inline scripts in a small working example.']::text[], array['Submit a working Nonce-Based CSP example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m02-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m02-t04', 'zte-backend-java-v1-core-phase-14-m02', 'JWT Algorithm Pinning', array['Explain and apply null in JWT Algorithm Pinning.', 'Use JWT Algorithm Pinning to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate The algorithm confusion attack — a token signed with a weaker or different algorithm than the server expects, and how naive verification code can be tricked into accepting it in a small working example.', 'Demonstrate Explicitly pinning the expected algorithm (e.g. only ever accepting HS256, never letting the token''s own header dictate which algorithm to verify with) — directly extends Phase 05''s HMAC-SHA256/JWT signing discussion in a small working example.', 'Demonstrate Why this matters specifically for the jose/jsonwebtoken libraries introduced in Phase 05 — checking that the algorithm allowlist is actually being enforced in your own auth code in a small working example.']::text[], array['Submit a working JWT Algorithm Pinning example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m02-t03']::text[], '[]'::jsonb, 180, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-14-m03', 'zte-backend-java-v1-core-phase-14', 3, 'Secret Management', 'Ordered detection-before-prevention — establishing whether a leak has already happened (trufflehog) before setting up a mechanism to stop future ones (git-secrets), the same threat-first-then-tool logic used in Stage 2\.', 3, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m03-t01', 'zte-backend-java-v1-core-phase-14-m03', 'trufflehog', array['Explain and apply null in trufflehog.', 'Use trufflehog to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Scanning git history — not just the current state of a repo, but every commit ever made, since a secret removed in a later commit is still recoverable from history in a small working example.', 'Demonstrate What trufflehog looks for — high-entropy strings, known credential patterns (API keys, private keys) in a small working example.', 'Demonstrate Running trufflehog against your own repos (all phases so far) as a real audit, not a hypothetical exercise in a small working example.', 'Demonstrate What to do if a real leak is found — rotating the credential immediately, not just removing it from the file (removing from a file does not remove it from git history) in a small working example.']::text[], array['Submit a working trufflehog example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m03-t02', 'zte-backend-java-v1-core-phase-14-m03', 'git-secrets', array['Explain and apply null in git-secrets.', 'Use git-secrets to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Pre-commit hook that blocks a commit containing a pattern matching known secret formats in a small working example.', 'Demonstrate Configuring patterns — built-in AWS key patterns plus custom patterns for your own project''s secret formats in a small working example.', 'Demonstrate Combining with Husky (a natural extension of Phase 01''s Git tooling work) to enforce this automatically for every commit, not just when remembered manually in a small working example.']::text[], array['Submit a working git-secrets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m03-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-14-m04', 'zte-backend-java-v1-core-phase-14', 4, 'Automated Security Monitoring', 'A cluster of small, lightweight tools — most are single-purpose checks that build on context established earlier in this phase.', 4.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m04-t01', 'zte-backend-java-v1-core-phase-14-m04', 'securityheaders.com', array['Explain and apply null in securityheaders.com.', 'Use securityheaders.com to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Running your deployed app''s URL (Phase 06) through the scan in a small working example.', 'Demonstrate Reading the grade and understanding which specific headers are missing or misconfigured in a small working example.', 'Demonstrate Iterating — fixing flagged headers and re-scanning to confirm in a small working example.']::text[], array['Submit a working securityheaders.com example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m04-t02', 'zte-backend-java-v1-core-phase-14-m04', 'CSP Evaluator', array['Explain and apply null in CSP Evaluator.', 'Use CSP Evaluator to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Google''s CSP Evaluator — analyzing a CSP policy specifically for bypasses and weaknesses, more detailed than securityheaders.com''s general header check in a small working example.', 'Demonstrate Common CSP mistakes it catches — overly permissive source lists, missing directives in a small working example.']::text[], array['Submit a working CSP Evaluator example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m04-t03', 'zte-backend-java-v1-core-phase-14-m04', 'Dependabot', array['Explain and apply null in Dependabot.', 'Use Dependabot to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Automated pull requests for outdated/vulnerable dependencies — directly addresses the OWASP Top 10''s Vulnerable and Outdated Components category (Stage 2, Topic 4) in a small working example.', 'Demonstrate Configuring update frequency and which dependency types to monitor in a small working example.', 'Demonstrate Reviewing and merging Dependabot PRs safely — not blindly auto-merging without checking for breaking changes in a small working example.']::text[], array['Submit a working Dependabot example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m04-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m04-t04', 'zte-backend-java-v1-core-phase-14-m04', 'npm audit', array['Explain and apply null in npm audit.', 'Use npm audit to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Running npm audit locally and interpreting severity levels in a small working example.', 'Demonstrate npm audit fix — automatic remediation, and its limits (not everything can be auto-fixed without a breaking change) in a small working example.', 'Demonstrate Running npm audit as a CI step (Phase 06''s GitHub Actions) — failing a build on high-severity vulnerabilities in a small working example.']::text[], array['Submit a working npm audit example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m04-t03']::text[], '[]'::jsonb, 60, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-14-m05', 'zte-backend-java-v1-core-phase-14', 5, 'Compliance', 'Requires the practical security measures from Stages 1–4 as context — compliance frameworks attest to controls that need to actually exist first; learning the framework before the practice would be abstract.', 5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m05-t01', 'zte-backend-java-v1-core-phase-14-m05', 'SOC 2 Basics', array['Explain and apply null in SOC 2 Basics.', 'Use SOC 2 Basics to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate What SOC 2 actually attests to — a third-party audit of an organization''s security controls, not a certification of a specific product feature in a small working example.', 'Demonstrate The five Trust Service Criteria — security, availability, processing integrity, confidentiality, privacy in a small working example.', 'Demonstrate Why SOC 2 matters commercially — many B2B/enterprise customers require a vendor''s SOC 2 report before signing a contract in a small working example.', 'Demonstrate Mapping this phase''s practical work (Stages 1–4: load testing, vulnerability scanning, secret management, header hardening) to what a SOC 2 audit would actually examine in a small working example.']::text[], array['Submit a working SOC 2 Basics example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-m05-t02', 'zte-backend-java-v1-core-phase-14-m05', 'GDPR', array['Explain and apply null in GDPR.', 'Use GDPR to complete a practical task in Load Testing + Security Deep Dive.']::text[], array['Demonstrate Data subject rights — right to access, right to erasure ("right to be forgotten"), right to data portability, and what implementing each actually requires technically (e.g. can your Prisma/PostgreSQL schema from Phase 05 support exporting or deleting all of a single user''s data cleanly?) in a small working example.', 'Demonstrate Lawful basis for processing — consent (Phase 10) is only one of several lawful bases; understanding the others (contract, legitimate interest) in a small working example.', 'Demonstrate Breach notification requirements — the 72-hour reporting obligation, and why Phase 10''s monitoring/alerting stack is what makes detecting a breach in time even possible in a small working example.', 'Demonstrate Data Processing Agreements (DPAs) — the contractual layer between you and any third-party service handling user data on your behalf (Resend, PostHog, Razorpay — all from Phase 09/10) in a small working example.', 'Demonstrate Post: "I ran a load test on my own app and here''s what broke" — an honest post about a real weakness found and fixed. This is the direct payoff of Stage 1''s k6 work (Topic 1) combined with whatever it actually revealed once correlated against Phase 10''s observability stack. in a small working example.']::text[], array['Submit a working GDPR example and explain the key decisions.', 'Record a short review showing how the example satisfies the Load Testing + Security Deep Dive learning goal.']::text[], array['zte-backend-java-v1-core-phase-14-m05-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-01', 'zte-backend-java-v1-core-phase-14', 'API Breaking Point Report', 'Use k6 to load-test an earlier project’s API, ramping virtual users until it breaks, and produce a written report identifying the exact bottleneck (CPU, DB connections, memory) with graphs. Domain: performance engineering / SRE. Run a distributed load test from multiple geographic regions using k6 Cloud, comparing latency experienced by users in different regions and documenting a CDN/edge-caching recommendation based on findings.', array['Deliver the working outcome described in the API Breaking Point Report brief.', 'Use at least two skills from Load Testing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working API Breaking Point Report', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Load Testing']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-02', 'zte-backend-java-v1-core-phase-14', 'Realistic User-Behavior Load Simulation with Artillery', 'Model a realistic multi-step user journey (browse → search → add to cart → checkout) as an Artillery scenario with weighted random behavior (not just hammering one endpoint), simulating a realistic traffic spike (e.g., a flash sale) and documenting system behavior under it.', array['Deliver the working outcome described in the Realistic User-Behavior Load Simulation with Artillery brief.', 'Use at least two skills from Load Testing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Realistic User-Behavior Load Simulation with Artillery', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Load Testing']::text[], 'advanced', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-03', 'zte-backend-java-v1-core-phase-14', 'Automated Vulnerability Scanning Pipeline', 'Integrate OWASP ZAP into a CI pipeline to automatically scan a staging deployment on every merge, failing the build on high-severity findings. Domain: DevSecOps.', array['Deliver the working outcome described in the Automated Vulnerability Scanning Pipeline brief.', 'Use at least two skills from Security Threat Model & Scanning.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Automated Vulnerability Scanning Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Security Threat Model & Scanning']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-04', 'zte-backend-java-v1-core-phase-14', 'Nonce-Based CSP Hardening', 'Implement a strict, nonce-based Content Security Policy on a real app (no unsafe-inline), correctly generating a fresh nonce per request and wiring it through server-rendered script tags, verified with a CSP evaluator and a deliberate XSS-attempt test that gets blocked.', array['Deliver the working outcome described in the Nonce-Based CSP Hardening brief.', 'Use at least two skills from Security Threat Model & Scanning.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Nonce-Based CSP Hardening', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Security Threat Model & Scanning']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-05', 'zte-backend-java-v1-core-phase-14', 'Secret Leak Prevention Pipeline', 'Configure trufflehog and git-secrets to scan every commit (locally via pre-commit hook and in CI) for accidentally committed secrets, with a deliberate test commit containing a fake API key that gets correctly blocked.', array['Deliver the working outcome described in the Secret Leak Prevention Pipeline brief.', 'Use at least two skills from Secret Management.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Secret Leak Prevention Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Secret Management']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-06', 'zte-backend-java-v1-core-phase-14', 'Continuous Security Posture Dashboard', 'A small internal report generator that runs securityheaders.com checks, CSP Evaluator, npm audit, and summarizes Dependabot alert status for a project into a single weekly security posture report. Domain: DevSecOps.', array['Deliver the working outcome described in the Continuous Security Posture Dashboard brief.', 'Use at least two skills from Automated Security Monitoring.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Continuous Security Posture Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Automated Security Monitoring']::text[], 'intermediate', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-07', 'zte-backend-java-v1-core-phase-14', 'SOC 2 & GDPR Readiness Checklist Implementation', 'Produce a real, project-specific SOC 2-informed security control checklist and GDPR data-handling checklist for an earlier project, then implement the 5 highest-priority gaps found (e.g., access logging, data export/deletion endpoints) rather than just documenting them. Domain: compliance / security engineering.', array['Deliver the working outcome described in the SOC 2 & GDPR Readiness Checklist Implementation brief.', 'Use at least two skills from Compliance.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working SOC 2 & GDPR Readiness Checklist Implementation', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'Compliance']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-14-project-08', 'zte-backend-java-v1-core-phase-14', 'A Load-Tested, Security-Hardened Production Audit', 'A full offensive-and-defensive audit of an earlier full-stack project: k6 and Artillery load tests establishing real breaking points and p99 latency under realistic traffic simulation, a documented OWASP Top 10 self-audit with real vulnerabilities found and fixed, a nonce-based strict CSP and JWT algorithm pinning implemented and verified, automated secret scanning wired into CI, a continuous security-header/dependency-audit reporting pipeline, and a GDPR-compliant data export/deletion implementation backed by a written SOC 2-informed access control policy. Domain: application security / SRE. Why it matters: this is the project that proves you don’t just build features — you can find out where your own system breaks and where it’s vulnerable, and actually fix it, which is precisely what separates confident production engineers from tutorial-followers.', array['Deliver the working outcome described in the A Load-Tested, Security-Hardened Production Audit brief.', 'Use at least two skills from Load Testing + Security Deep Dive.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Load-Tested, Security-Hardened Production Audit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Load Testing + Security Deep Dive', 'engineering documentation']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-15', 'zte-backend-java-v1', id, '17', 'Build Tooling + CSS-in-JS', 'Advanced', 'Foundational — everything else in this phase either analyzes what these tools produce (Stage 2\\) or measures the result of using them (Stage 3).', 65, 16 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-15-m01', 'zte-backend-java-v1-core-phase-15', 1, 'Build Tools', 'Foundational — everything else in this phase either analyzes what these tools produce (Stage 2\\) or measures the result of using them (Stage 3).', 6, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m01-t01', 'zte-backend-java-v1-core-phase-15-m01', 'Vite', array['Explain and apply Dev Server in Vite.', 'Explain and apply Production Builds in Vite.', 'Explain and apply Context Relative to Next.js in Vite.']::text[], array['Demonstrate Native ES modules in development — why Vite''s dev server starts almost instantly compared to bundler-based dev servers (no need to bundle the entire app before serving the first request) in a small working example.', 'Demonstrate Hot Module Replacement (HMR) — how Vite updates modules in the browser without a full page reload in a small working example.', 'Demonstrate Plugin system — Vite''s Rollup-compatible plugin API in a small working example.', 'Demonstrate Vite uses Rollup under the hood for production builds — a different tool than the dev server, worth knowing explicitly since it explains Stage 2''s rollup-plugin-visualizer relevance in a small working example.', 'Demonstrate Code splitting and chunk strategy in a Vite production build in a small working example.']::text[], array['Submit a working Vite example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array[]::text[], '[]'::jsonb, 540, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m01-t02', 'zte-backend-java-v1-core-phase-15-m01', 'tsup', array['Explain and apply null in tsup.', 'Use tsup to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Why publishing a library needs different bundling concerns than shipping an app — multiple output formats (CJS, ESM), type declaration generation in a small working example.', 'Demonstrate tsup''s esbuild-based speed — fast builds for package authoring in a small working example.', 'Demonstrate Configuring entry points and output formats for a real npm-publishable package in a small working example.', 'Demonstrate When you''d actually need this — publishing a shared component library or utility package, not typical for a single product application in a small working example.']::text[], array['Submit a working tsup example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-backend-java-v1-core-phase-15-m01-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-15-m02', 'zte-backend-java-v1-core-phase-15', 2, 'Bundle Analysis and Performance Auditing and Performance Auditing', 'Three tools, each attached to a different build system — ordered by which build system context you already have: Next.js (Phase 02, long since known) first, Vite (Stage 1, just learned) second, and raw Rollup (the most general-purpose, underlying both Vite''s production build and usable standalone) last.', 3.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m02-t01', 'zte-backend-java-v1-core-phase-15-m02', '@next/bundle-analyzer', array['Explain and apply null in @next/bundle-analyzer.', 'Use @next/bundle-analyzer to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Generating a visual treemap of what''s actually in your Next.js production bundle in a small working example.', 'Demonstrate Identifying unexpectedly large dependencies — a common discovery being an entire library imported for one small utility function in a small working example.', 'Demonstrate Connecting bundle size back to Phase 02''s code-splitting and dynamic import (React.lazy) discussion — bundle analysis is what tells you where those techniques would actually help in a small working example.']::text[], array['Submit a working @next/bundle-analyzer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m02-t02', 'zte-backend-java-v1-core-phase-15-m02', 'vite-bundle-visualizer', array['Explain and apply null in vite-bundle-visualizer.', 'Use vite-bundle-visualizer to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Same treemap visualization concept as Topic 3, applied to a Vite production build in a small working example.', 'Demonstrate Differences in what''s typically visible — Vite''s more granular chunk splitting compared to Next.js''s conventions in a small working example.']::text[], array['Submit a working vite-bundle-visualizer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-backend-java-v1-core-phase-15-m02-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m02-t03', 'zte-backend-java-v1-core-phase-15-m02', 'rollup-plugin-visualizer', array['Explain and apply null in rollup-plugin-visualizer.', 'Use rollup-plugin-visualizer to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Using rollup-plugin-visualizer directly in a Rollup config (or via Vite''s Rollup-compatible plugin system, Stage 1) for finer-grained control than the wrapper tools (3, 4) offer in a small working example.', 'Demonstrate When to reach for the underlying Rollup tool directly instead of a framework-specific wrapper — custom build setups, library bundling scenarios (ties back to tsup, Stage 1, Topic 2) in a small working example.']::text[], array['Submit a working rollup-plugin-visualizer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-backend-java-v1-core-phase-15-m02-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m02-t04', 'zte-backend-java-v1-core-phase-15-m02', 'lighthouse-ci', array['Explain and apply null in lighthouse-ci.', 'Use lighthouse-ci to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Running Lighthouse audits automatically on every PR/deploy, instead of manually checking scores in Chrome DevTools in a small working example.', 'Demonstrate The four Lighthouse categories — performance, accessibility, best practices, SEO — and what each actually measures in a small working example.', 'Demonstrate Setting budgets — failing CI (Phase 06) if a score or specific metric (e.g. bundle size, connecting back to Stage 2) regresses below a threshold in a small working example.', 'Demonstrate Core Web Vitals specifically — LCP, INP, CLS — and why these are the metrics that actually correlate with user-perceived performance and search ranking in a small working example.']::text[], array['Submit a working lighthouse-ci example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-backend-java-v1-core-phase-15-m02-t03']::text[], '[]'::jsonb, 180, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-15-m03', 'zte-backend-java-v1-core-phase-15', 3, 'CSS-in-JS', 'An independent theme from Stages 1–3. Runtime-based libraries (styled-components, Emotion) are taught before the zero-runtime alternative (Linaria) so the tradeoff Linaria addresses — CSS-in-JS ergonomics without runtime cost — is understood as a response to a real limitation, not learned in isolation.', 7.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m03-t01', 'zte-backend-java-v1-core-phase-15-m03', 'styled-components', array['Explain and apply null in styled-components.', 'Use styled-components to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate Tagged template literals — writing actual CSS inside JavaScript, with real syntax highlighting and autocomplete support in most editors in a small working example.', 'Demonstrate Component-scoped styles — each styled component generates its own uniquely-scoped class, avoiding the global-namespace problem of plain CSS (Phase 03) in a small working example.', 'Demonstrate Dynamic styling based on props — styles that change based on component state, without manually toggling classNames (Phase 02/03''s clsx/CVA approach) in a small working example.', 'Demonstrate Theming via ThemeProvider — a runtime theming mechanism, contrasted with Phase 03''s CSS Custom Properties + next-themes approach in a small working example.', 'Demonstrate The runtime cost — styled-components generates and injects CSS at runtime in the browser, which is the specific tradeoff Stage 4''s later topics (Linaria) exist to avoid in a small working example.']::text[], array['Submit a working styled-components example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m03-t02', 'zte-backend-java-v1-core-phase-15-m03', 'Emotion', array['Explain and apply null in Emotion.', 'Use Emotion to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate API parity with styled-components — tagged template literals and a similar component-scoping model in a small working example.', 'Demonstrate Emotion''s css prop — an alternative, slightly more flexible authoring style than styled-components'' component-wrapping pattern in a small working example.', 'Demonstrate Performance differences and bundle size comparison between the two libraries in a small working example.', 'Demonstrate Why teams pick one over the other in practice — largely ecosystem/preference rather than a sharp technical divide in a small working example.']::text[], array['Submit a working Emotion example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-backend-java-v1-core-phase-15-m03-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m03-t03', 'zte-backend-java-v1-core-phase-15-m03', 'Linaria', array['Explain and apply null in Linaria.', 'Use Linaria to complete a practical task in Build Tooling + CSS-in-JS.']::text[], array['Demonstrate The zero-runtime approach — Linaria extracts styles to static CSS files at build time, using a build-time transform rather than generating styles in the browser in a small working example.', 'Demonstrate CSS-in-JS authoring syntax (similar to styled-components/Emotion) with none of their runtime cost — the specific gap this fills in a small working example.', 'Demonstrate Direct comparison to vanilla-extract (Phase 03) — both are zero-runtime, but Linaria keeps closer syntactic similarity to styled-components/Emotion, while vanilla-extract uses a more TypeScript-native styling API in a small working example.', 'Demonstrate Build tooling requirements — Linaria needs its own bundler integration (ties back to Stage 1''s Vite, or webpack/Next.js''s build pipeline) to perform the build-time extraction in a small working example.', 'Demonstrate Post: skipped deliberately — build tooling changes aren''t visible or interesting to an outside audience. in a small working example.']::text[], array['Submit a working Linaria example and explain the key decisions.', 'Record a short review showing how the example satisfies the Build Tooling + CSS-in-JS learning goal.']::text[], array['zte-backend-java-v1-core-phase-15-m03-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-15-m04', 'zte-backend-java-v1-core-phase-15', 4, 'ZTE Backend Engineering with Java: Service and event architecture', 'Service and event architecture focus for the ZTE Backend Engineering with Java pathway.', 13, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-m04-t01', 'zte-backend-java-v1-core-phase-15-m04', 'Service boundaries and domain ownership', array['Choose service boundaries based on change and data ownership', 'Identify when a modular monolith is preferable']::text[], array['Split a bounded context on paper', 'Compare deployment and operational cost']::text[], array['Architecture decision record with alternatives and tradeoffs']::text[], array[]::text[], '[]'::jsonb, 210, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
