insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-project-01', 'zte-backend-java-v1-core-phase-15', 'Framework-Free Vite App from Scratch', 'Configure a Vite project from an empty folder (no create-vite scaffold) with TypeScript, path aliases, and environment variable handling, understanding every config option added. Domain: build tooling literacy.', array['Deliver the working outcome described in the Framework-Free Vite App from Scratch brief.', 'Use at least two skills from Build Tools.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Framework-Free Vite App from Scratch', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'Build Tools']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-project-02', 'zte-backend-java-v1-core-phase-15', 'Dual-Format Publishable Library with tsup', 'Take a utility library from Phase 1/4 and configure tsup to build it as both ESM and CJS output with generated type declarations, ready for real npm publishing. Domain: library authoring / open source.', array['Deliver the working outcome described in the Dual-Format Publishable Library with tsup brief.', 'Use at least two skills from Build Tools.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Dual-Format Publishable Library with tsup', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'Build Tools']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-project-03', 'zte-backend-java-v1-core-phase-15', 'Bundle Size Audit & Diet', 'Take a real project, run @next/bundle-analyzer (or vite-bundle-visualizer for non-Next projects), identify the 3 largest unnecessary dependencies or duplicated code, and reduce total bundle size by a documented, measurable percentage.', array['Deliver the working outcome described in the Bundle Size Audit & Diet brief.', 'Use at least two skills from Bundle Analysis and Performance Auditing and Performance Auditing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Bundle Size Audit & Diet', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'Bundle Analysis and Performance Auditing and Performance Auditing']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-project-04', 'zte-backend-java-v1-core-phase-15', 'Themeable Component Library, Three Ways', 'Rebuild the same 4-component set using styled-components, Emotion, and Linaria (zero-runtime) respectively, then write a hands-on comparison of DX, runtime performance cost, and SSR complexity for each. Domain: frontend architecture decision-making.', array['Deliver the working outcome described in the Themeable Component Library, Three Ways brief.', 'Use at least two skills from CSS-in-JS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Themeable Component Library, Three Ways', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'CSS-in-JS']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-project-05', 'zte-backend-java-v1-core-phase-15', 'A Bundle-Size-Obsessed Component Library', 'Publish a small, genuinely optimized component library: authored and bundled with tsup (dual ESM/CJS \+ types), a documented before/after bundle-size reduction case study using bundle analyzers, a CI pipeline enforcing a Lighthouse performance budget on the accompanying demo site, and a written comparative report on styled-components vs. Emotion vs. Linaria implementations of the same components with real measured runtime cost differences. Domain: frontend performance / library engineering. Why it matters: most engineers never measure what their styling/build choices actually cost; this project builds the habit of verifying performance claims with real numbers instead of assumptions.', array['Deliver the working outcome described in the A Bundle-Size-Obsessed Component Library brief.', 'Use at least two skills from Build Tooling + CSS-in-JS.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Bundle-Size-Obsessed Component Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Build Tooling + CSS-in-JS', 'engineering documentation']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-15-project-06', 'zte-backend-java-v1-core-phase-15', 'Event-driven order processing platform', 'Process orders across payment, inventory, and fulfillment despite retries and partial failure.', array['Outbox and idempotent consumers', 'Explicit state machine', 'Replay and reconciliation tools', 'Tracing and operational SLOs']::text[], array['Consistency model', 'Message workflow', 'Failure/replay handling', 'Load and incident exercises']::text[], array['Architecture and sequence diagrams', 'Service implementation', 'Failure injection report', 'Runbook']::text[], array['messaging', 'distributed transactions', 'observability', 'reliability', 'backend', 'engineering delivery']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-16', 'zte-backend-java-v1', id, '18', 'Infrastructure', 'Expert', 'Terraform doesn''t strictly require S3 (Stage 1), but S3 makes a concrete, already-understood resource to provision as a first real Terraform example rather than an abstract one.', 175, 17 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-16-m01', 'zte-backend-java-v1-core-phase-16', 1, 'Infrastructure as Code and Cloud Object Storage and Cloud Object Storage', 'Terraform doesn''t strictly require S3 (Stage 1), but S3 makes a concrete, already-understood resource to provision as a first real Terraform example rather than an abstract one.', 11.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m01-t01', 'zte-backend-java-v1-core-phase-16-m01', 'AWS S3', array['Explain and apply null in AWS S3.', 'Use AWS S3 to complete a practical task in Infrastructure.']::text[], array['Demonstrate Buckets and objects — S3''s flat storage model, and the folder-like prefix convention that simulates a directory structure in a small working example.', 'Demonstrate Storage classes — Standard, Infrequent Access, Glacier, and the cost/retrieval-time tradeoff between them in a small working example.', 'Demonstrate Access control — bucket policies vs IAM policies vs ACLs, and why misconfigured public buckets are a persistent real-world security failure (ties back to Phase 14''s OWASP Top 10, Security Misconfiguration category) in a small working example.', 'Demonstrate Presigned URLs — generating time-limited, credential-free access to a private object (a common pattern for direct client uploads, bypassing your own backend for large file transfer) in a small working example.', 'Demonstrate Common use cases: user-uploaded file storage (ties back to Phase 06b''s camera capture, Phase 05''s file handling), static asset hosting, backups in a small working example.']::text[], array['Submit a working AWS S3 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array[]::text[], '[]'::jsonb, 720, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m01-t02', 'zte-backend-java-v1-core-phase-16-m01', 'Terraform', array['Explain and apply Core Concepts in Terraform.', 'Explain and apply Workflow in Terraform.', 'Explain and apply State Management in Terraform.']::text[], array['Demonstrate Declarative infrastructure — describing the desired end state, not the steps to get there (a contrast worth making explicit against imperative scripting) in a small working example.', 'Demonstrate Providers — the plugin model connecting Terraform to a specific cloud (AWS, in the context of Stage 1''s S3) in a small working example.', 'Demonstrate Resources and data sources — defining new infrastructure vs referencing existing infrastructure in a small working example.', 'Demonstrate State — what Terraform''s state file tracks, and why it''s the single most important (and most fragile) part of a Terraform setup in a small working example.', 'Demonstrate terraform init, plan, apply, destroy — the core command cycle in a small working example.']::text[], array['Submit a working Terraform example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-backend-java-v1-core-phase-16-m01-t01']::text[], '[]'::jsonb, 1860, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m01-t03', 'zte-backend-java-v1-core-phase-16-m01', 'Terraform Cloud', array['Explain and apply null in Terraform Cloud.', 'Use Terraform Cloud to complete a practical task in Infrastructure.']::text[], array['Demonstrate Remote execution — running plan/apply in Terraform Cloud instead of locally, with consistent environment and credentials in a small working example.', 'Demonstrate Managed state storage — removing the need to hand-configure a remote backend (contrasted with Terraform''s own remote state setup in Topic 2) in a small working example.', 'Demonstrate Team workflows — approval gates before apply, variable sets shared across configurations in a small working example.']::text[], array['Submit a working Terraform Cloud example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-backend-java-v1-core-phase-16-m01-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m01-t04', 'zte-backend-java-v1-core-phase-16-m01', 'tfsec', array['Explain and apply null in tfsec.', 'Use tfsec to complete a practical task in Infrastructure.']::text[], array['Demonstrate Static analysis of Terraform configs — catching misconfigurations before anything is ever applied (e.g. a publicly accessible S3 bucket, Stage 1, or an unencrypted resource) in a small working example.', 'Demonstrate Common findings — overly permissive IAM policies, missing encryption settings, open security groups in a small working example.', 'Demonstrate Integrating tfsec into CI (Phase 06''s GitHub Actions) — failing a pipeline before insecure infrastructure is ever provisioned, the IaC equivalent of Phase 14''s npm audit CI step in a small working example.']::text[], array['Submit a working tfsec example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-backend-java-v1-core-phase-16-m01-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-16-m02', 'zte-backend-java-v1-core-phase-16', 2, 'Kubernetes Core', 'Requires Docker (Phase 06\\) as a direct prerequisite — Kubernetes orchestrates containers, it doesn''t replace understanding what a container actually is.', 20, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m02-t01', 'zte-backend-java-v1-core-phase-16-m02', 'Kubernetes', array['Explain and apply Core Objects in Kubernetes.', 'Explain and apply Cluster Architecture in Kubernetes.', 'Explain and apply Networking & Storage in Kubernetes.']::text[], array['Demonstrate Pods — the smallest deployable unit, and why it''s a pod (potentially multiple containers) rather than a single container directly in a small working example.', 'Demonstrate Deployments — declarative, self-healing management of a set of pod replicas in a small working example.', 'Demonstrate Services — stable networking identity for a set of pods whose individual IPs change constantly in a small working example.', 'Demonstrate ConfigMaps and Secrets — externalizing configuration and sensitive values from container images (foreshadows Stage 4''s external-secrets) in a small working example.', 'Demonstrate Control plane components — API server, scheduler, controller manager, etcd (conceptual) in a small working example.']::text[], array['Submit a working Kubernetes example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array[]::text[], '[]'::jsonb, 2760, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m02-t02', 'zte-backend-java-v1-core-phase-16-m02', 'kind (Kubernetes in Docker)', array['Explain and apply null in kind (Kubernetes in Docker).', 'Use kind (Kubernetes in Docker) to complete a practical task in Infrastructure.']::text[], array['Demonstrate Running a full local Kubernetes cluster using Docker as the underlying container runtime for cluster nodes themselves in a small working example.', 'Demonstrate Why kind exists — a lightweight alternative to Minikube or a real cloud cluster for local development and CI testing in a small working example.', 'Demonstrate Creating and tearing down clusters quickly for experimentation in a small working example.']::text[], array['Submit a working kind (Kubernetes in Docker) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-backend-java-v1-core-phase-16-m02-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m02-t03', 'zte-backend-java-v1-core-phase-16-m02', 'kubectl', array['Explain and apply null in kubectl.', 'Use kubectl to complete a practical task in Infrastructure.']::text[], array['Demonstrate Core commands — get, describe, apply, delete, logs, exec — for inspecting and managing every resource type from Topic 5 in a small working example.', 'Demonstrate Applying YAML manifests — the declarative resource definitions that map directly to the objects covered in Topic 5 in a small working example.', 'Demonstrate kubectl exec for shelling into a running pod, kubectl logs for reading container output — the K8s equivalents of Phase 06''s docker exec and docker logs in a small working example.', 'Demonstrate Contexts and namespaces — managing access to multiple clusters/environments from one kubectl installation in a small working example.']::text[], array['Submit a working kubectl example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-backend-java-v1-core-phase-16-m02-t02']::text[], '[]'::jsonb, 420, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-16-m03', 'zte-backend-java-v1-core-phase-16', 3, 'Kubernetes Ecosystem', 'All three topics require core Kubernetes concepts and kubectl (Stage 3\\) already in place — each is a specialized tool or resource type layered on top of that foundation.', 9.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m03-t01', 'zte-backend-java-v1-core-phase-16-m03', 'Helm', array['Explain and apply null in Helm.', 'Use Helm to complete a practical task in Infrastructure.']::text[], array['Demonstrate Charts — packaged, versioned, parameterized collections of Kubernetes manifests in a small working example.', 'Demonstrate Why Helm exists — deploying a complex application (many interrelated K8s resources) via a single command instead of applying many YAML files by hand with kubectl (7) in a small working example.', 'Demonstrate Values files — parameterizing a chart for different environments without editing the chart itself in a small working example.', 'Demonstrate Installing, upgrading, and rolling back releases — Helm''s versioned deployment history as an advantage over raw kubectl apply in a small working example.']::text[], array['Submit a working Helm example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array[]::text[], '[]'::jsonb, 600, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m03-t02', 'zte-backend-java-v1-core-phase-16-m03', 'HPA (Horizontal Pod Autoscaler)', array['Explain and apply null in HPA (Horizontal Pod Autoscaler).', 'Use HPA (Horizontal Pod Autoscaler) to complete a practical task in Infrastructure.']::text[], array['Demonstrate How HPA automatically scales the number of pod replicas (Stage 3''s Deployments) based on observed metrics — typically CPU or memory utilization in a small working example.', 'Demonstrate Configuring target thresholds and min/max replica bounds in a small working example.', 'Demonstrate Connecting this back to Phase 14''s k6 load testing — HPA is the mechanism that would actually respond to the kind of traffic spikes a load test simulates in a small working example.', 'Demonstrate Limitations — HPA reacts to current load rather than predicting it, and cold-start time for new pods matters for how quickly it can actually help in a small working example.']::text[], array['Submit a working HPA (Horizontal Pod Autoscaler) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-backend-java-v1-core-phase-16-m03-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-m03-t03', 'zte-backend-java-v1-core-phase-16-m03', 'external-secrets', array['Explain and apply null in external-secrets.', 'Use external-secrets to complete a practical task in Infrastructure.']::text[], array['Demonstrate The problem it solves — Kubernetes Secrets (Stage 3, Topic 5) are base64-encoded, not encrypted, and typically shouldn''t be the ultimate source of truth for sensitive values in a small working example.', 'Demonstrate Syncing secrets from an external source (AWS Secrets Manager, directly connecting back to Stage 1''s AWS/S3 context) into native Kubernetes Secret objects automatically in a small working example.', 'Demonstrate How this ties together the entire phase — AWS as the secret''s true source (Stage 1), Terraform potentially provisioning the AWS-side secret store (Stage 2), and external-secrets (installed via Helm, Topic 8) bridging it into the cluster in a small working example.', 'Demonstrate Post: your infrastructure diagram — the Terraform (Stage 2) + Kubernetes (Stages 3–4) setup, even a simple one. This is genuinely visualizable in a way build tooling (Phase 15) wasn''t, which is exactly why that phase skipped this section and this one doesn''t. in a small working example.', 'Demonstrate GitHub: add an infra/ or terraform/ folder with your IaC config — redact secrets before committing (directly connects to Phase 14''s trufflehog/git-secrets work; this is the exact kind of content those tools exist to catch before it happens). in a small working example.']::text[], array['Submit a working external-secrets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Infrastructure learning goal.']::text[], array['zte-backend-java-v1-core-phase-16-m03-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-project-01', 'zte-backend-java-v1-core-phase-16', 'Direct-to-S3 Upload System', 'A file upload feature using pre-signed S3 URLs so large files upload directly from the browser to S3 (not proxied through your server), with upload progress tracking and correct bucket policy/CORS configuration. Domain: media/file storage infrastructure.', array['Deliver the working outcome described in the Direct-to-S3 Upload System brief.', 'Use at least two skills from Cloud Object Storage.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Direct-to-S3 Upload System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Cloud Object Storage']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-project-02', 'zte-backend-java-v1-core-phase-16', 'Terraform Security Scan Gate', 'Integrate tfsec into a CI pipeline that scans Terraform plans for security misconfigurations (e.g., a publicly-open security group) before allowing an apply, with a deliberately insecure resource that gets correctly blocked.', array['Deliver the working outcome described in the Terraform Security Scan Gate brief.', 'Use at least two skills from Infrastructure as Code and Cloud Object Storage and Cloud Object Storage.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Terraform Security Scan Gate', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Infrastructure as Code and Cloud Object Storage and Cloud Object Storage']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-project-03', 'zte-backend-java-v1-core-phase-16', 'Local Kubernetes Deployment', 'Deploy a full-stack app (frontend + backend + database) to a local Kubernetes cluster using kind, with proper Deployments, Services, and ConfigMaps/Secrets, managed entirely via kubectl.', array['Deliver the working outcome described in the Local Kubernetes Deployment brief.', 'Use at least two skills from Kubernetes Core.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Local Kubernetes Deployment', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Core']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-project-04', 'zte-backend-java-v1-core-phase-16', 'Zero-Downtime Rolling Update Demo', 'Configure a Kubernetes Deployment with proper readiness/liveness probes and rolling update strategy, then deploy a breaking change and demonstrate (with live traffic during the deploy) that users experience zero downtime, followed by a deliberately bad deploy that gets automatically rolled back.', array['Deliver the working outcome described in the Zero-Downtime Rolling Update Demo brief.', 'Use at least two skills from Kubernetes Core.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Zero-Downtime Rolling Update Demo', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Core']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-project-05', 'zte-backend-java-v1-core-phase-16', 'Auto-Scaling Load Demonstration', 'Configure a Horizontal Pod Autoscaler on a deployed service, then load-test it (tying back to Phase 14’s k6 work) and record real pod-count scaling behavior as load increases and decreases.', array['Deliver the working outcome described in the Auto-Scaling Load Demonstration brief.', 'Use at least two skills from Kubernetes Ecosystem.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Auto-Scaling Load Demonstration', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Ecosystem']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-project-06', 'zte-backend-java-v1-core-phase-16', 'Secure Secret Sync from Cloud Secret Manager', 'Configure external-secrets to sync secrets from a cloud secret manager (or a compatible local equivalent) into Kubernetes Secrets automatically, so no secret is ever manually kubectl-applied or committed anywhere.', array['Deliver the working outcome described in the Secure Secret Sync from Cloud Secret Manager brief.', 'Use at least two skills from Kubernetes Ecosystem.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Secure Secret Sync from Cloud Secret Manager', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'Kubernetes Ecosystem']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-16-project-07', 'zte-backend-java-v1-core-phase-16', 'A Fully Terraform-and-Kubernetes-Managed Production Platform', 'Take an earlier full-stack project and rebuild its entire infrastructure as code: S3 pre-signed direct uploads for media, all cloud resources defined in Terraform with tfsec-gated CI and Terraform Cloud remote state, the application itself packaged as a Helm chart deployed to Kubernetes with readiness/liveness probes enabling zero-downtime rolling updates, a Horizontal Pod Autoscaler validated under real k6 load, and external-secrets syncing all credentials so nothing sensitive is ever manually applied. Domain: platform engineering / DevOps infrastructure. Why it matters: this is genuine platform-engineer-level work — reproducible, auditable infrastructure is what lets a team scale past "it works on the one server I set up manually."', array['Deliver the working outcome described in the A Fully Terraform-and-Kubernetes-Managed Production Platform brief.', 'Use at least two skills from Infrastructure.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Fully Terraform-and-Kubernetes-Managed Production Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Infrastructure', 'engineering documentation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-17', 'zte-backend-java-v1', id, '19', 'Architectural Patterns', 'Expert', 'Requires Phase 09''s Redis work as the caching substrate these patterns are named strategies for, and Phase 04''s TanStack Query as the client-side context Optimistic Updates most commonly applies to.', 193, 18 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-17-m01', 'zte-backend-java-v1-core-phase-17', 1, 'Caching & Optimistic Update Patterns', 'Requires Phase 09''s Redis work as the caching substrate these patterns are named strategies for, and Phase 04''s TanStack Query as the client-side context Optimistic Updates most commonly applies to.', 6.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m01-t01', 'zte-backend-java-v1-core-phase-17-m01', 'Optimistic Updates', array['Explain and apply null in Optimistic Updates.', 'Use Optimistic Updates to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — updating the UI immediately based on an assumed-successful outcome, before the server actually confirms it in a small working example.', 'Demonstrate Rollback handling — reverting the optimistic UI state if the server ultimately rejects the operation (ties directly back to Phase 04''s TanStack Query mutation rollback mechanics) in a small working example.', 'Demonstrate Why this matters for perceived performance — the user sees instant feedback even though the real round-trip hasn''t completed in a small working example.', 'Demonstrate Risk surface — optimistic updates assuming success for operations that are actually likely to fail (e.g. anything touching Stage 2''s concurrency control) can create a confusing UX when the rollback happens in a small working example.']::text[], array['Submit a working Optimistic Updates example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m01-t02', 'zte-backend-java-v1-core-phase-17-m01', 'Cache-Aside Caching', array['Explain and apply null in Cache-Aside Caching.', 'Use Cache-Aside Caching to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern by name — application code owns cache population, checking cache first and falling back to the source of truth on a miss in a small working example.', 'Demonstrate Why this is the most common caching pattern in practice — simple, cache and DB can diverge briefly, but the application controls exactly when and what to cache in a small working example.', 'Demonstrate Failure modes — a cache-aside system serving stale data during the window between a DB write and cache invalidation in a small working example.']::text[], array['Submit a working Cache-Aside Caching example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m01-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m01-t03', 'zte-backend-java-v1-core-phase-17-m01', 'Write-Through Caching', array['Explain and apply null in Write-Through Caching.', 'Use Write-Through Caching to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — every write goes through the cache layer first, which then writes to the underlying store, keeping cache and DB consistent by construction in a small working example.', 'Demonstrate Tradeoff against cache-aside (1) — write latency increases (every write touches the cache), but read-after-write staleness risk decreases in a small working example.', 'Demonstrate When write-through is worth the extra write latency — read-heavy workloads where consistency matters more than write speed in a small working example.']::text[], array['Submit a working Write-Through Caching example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m01-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-17-m02', 'zte-backend-java-v1-core-phase-17', 2, 'Database Concurrency Control', 'Requires Phase 05''s transaction fundamentals and Phase 11''s MVCC deep dive — these two locking strategies are different answers to the same underlying concurrent-write problem MVCC exists to manage.', 7, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m02-t01', 'zte-backend-java-v1-core-phase-17-m02', 'Idempotency', array['Explain and apply null in Idempotency.', 'Use Idempotency to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The core property — performing the same operation multiple times has the same effect as performing it once in a small working example.', 'Demonstrate Why this matters for retries specifically — a network failure after a write succeeds but before the client receives confirmation is genuinely ambiguous; the client can only recover safely by retrying, and retrying safely requires idempotency in a small working example.', 'Demonstrate Idempotency keys — a client-generated unique identifier attached to a request, letting the server recognize and safely ignore a duplicate (direct callback to Phase 09''s Razorpay webhook idempotency discussion) in a small working example.', 'Demonstrate Where this already showed up earlier in the curriculum without being named — Phase 09''s webhook handling, and now the formal foundation for Stage 3''s Saga, Outbox, and DLQ patterns, all of which assume retryable, idempotent steps in a small working example.']::text[], array['Submit a working Idempotency example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 420, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m02-t02', 'zte-backend-java-v1-core-phase-17-m02', 'Optimistic Locking', array['Explain and apply null in Optimistic Locking.', 'Use Optimistic Locking to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Version-based conflict detection — attaching a version number (or timestamp) to a row, and rejecting a write if the version has changed since it was read in a small working example.', 'Demonstrate Why this is called "optimistic" — it assumes conflicts are rare and only pays the cost of detecting one when it actually happens in a small working example.', 'Demonstrate Implementation in Prisma (Phase 05) — a version column checked and incremented on update, application code handling the conflict when the check fails in a small working example.', 'Demonstrate When optimistic locking fits — low-contention scenarios where most writes don''t actually collide in a small working example.']::text[], array['Submit a working Optimistic Locking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m02-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m02-t03', 'zte-backend-java-v1-core-phase-17-m02', 'Pessimistic Locking', array['Explain and apply null in Pessimistic Locking.', 'Use Pessimistic Locking to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Lock-based conflict prevention — acquiring a lock (SELECT ... FOR UPDATE in PostgreSQL, Phase 05) before reading, preventing any other transaction from modifying the same row until the lock is released in a small working example.', 'Demonstrate Why this is called "pessimistic" — it assumes conflicts are common enough that preventing them upfront is cheaper than detecting and retrying them in a small working example.', 'Demonstrate Deadlock risk — two transactions each holding a lock the other needs, and why lock ordering discipline matters in a small working example.', 'Demonstrate When pessimistic locking fits — high-contention scenarios (e.g. a limited-inventory checkout flow) where optimistic locking''s retry cost would be too high in a small working example.']::text[], array['Submit a working Pessimistic Locking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m02-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-17-m03', 'zte-backend-java-v1-core-phase-17', 3, 'Distributed Transactions & Messaging Resilience', 'The largest cluster in the phase. Requires idempotency (Stage 2, Topic 6\\) as a hard prerequisite — every pattern here involves retries, and retries without idempotency cause duplicate side effects rather than fixing failures.', 11.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m03-t01', 'zte-backend-java-v1-core-phase-17-m03', 'Saga Pattern', array['Explain and apply null in Saga Pattern.', 'Use Saga Pattern to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The problem — a business transaction spanning multiple services (no single database transaction can cover all of them, unlike Phase 05''s single-database ACID transactions) in a small working example.', 'Demonstrate Choreography vs orchestration — services reacting to each other''s events independently, vs a central coordinator directing each step in a small working example.', 'Demonstrate Compensating transactions — since there''s no rollback across services, failure requires explicitly undoing already-completed steps in reverse in a small working example.', 'Demonstrate Why each step must be idempotent (Stage 2, Topic 6) — a saga coordinator retrying a step after an ambiguous failure must not cause duplicate effects in a small working example.']::text[], array['Submit a working Saga Pattern example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m03-t02', 'zte-backend-java-v1-core-phase-17-m03', 'Outbox Pattern', array['Explain and apply null in Outbox Pattern.', 'Use Outbox Pattern to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The problem it solves — reliably publishing an event as a consequence of a database write, when the write and the publish can''t be a single atomic operation across two different systems (the DB and the message broker) in a small working example.', 'Demonstrate The pattern — writing the event to an "outbox" table in the same database transaction as the actual data change, then a separate process reads and publishes from that table in a small working example.', 'Demonstrate Why this guarantees consistency — the event write and the data write either both commit or both roll back, since they''re the same PostgreSQL transaction (Phase 05) in a small working example.', 'Demonstrate Common use — implementing reliable saga (7) step completion events without a distributed transaction in a small working example.']::text[], array['Submit a working Outbox Pattern example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m03-t01']::text[], '[]'::jsonb, 600, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m03-t03', 'zte-backend-java-v1-core-phase-17-m03', 'Dead Letter Queue', array['Explain and apply null in Dead Letter Queue.', 'Use Dead Letter Queue to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — after a message fails processing repeatedly (beyond a retry limit), routing it to a separate queue instead of retrying forever or silently dropping it in a small working example.', 'Demonstrate Why this matters operationally — a DLQ makes failures visible and inspectable instead of invisible (ties back to Phase 10''s monitoring/alerting stack — a DLQ with growing depth is exactly the kind of thing worth alerting on) in a small working example.', 'Demonstrate Reprocessing strategy — manually or automatically retrying DLQ messages once the underlying issue (a bug, an outage) is fixed in a small working example.']::text[], array['Submit a working Dead Letter Queue example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m03-t02']::text[], '[]'::jsonb, 300, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m03-t04', 'zte-backend-java-v1-core-phase-17-m03', 'Circuit Breaker', array['Explain and apply null in Circuit Breaker.', 'Use Circuit Breaker to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — tracking failures when calling an unreliable dependency, and "opening" the circuit (failing fast without even attempting the call) once a failure threshold is crossed in a small working example.', 'Demonstrate The three states — closed (normal operation), open (failing fast), half-open (cautiously testing if the dependency has recovered) in a small working example.', 'Demonstrate Why this prevents cascading failures — a struggling downstream service getting hammered with retries from every caller is often what turns a partial outage into a total one in a small working example.', 'Demonstrate Combining with idempotency (Stage 2, Topic 6) — once a circuit closes again, retried calls must be safe to actually retry in a small working example.']::text[], array['Submit a working Circuit Breaker example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m03-t03']::text[], '[]'::jsonb, 480, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-17-m04', 'zte-backend-java-v1-core-phase-17', 4, 'Architectural Styles and Multi-Tenancy and Multi-Tenancy', 'Both topics are broader architectural styles built from the messaging reliability patterns in Stage 3 — neither makes sense taught before Outbox and DLQ exist as the mechanisms that make them work in practice, not just in theory.', 7.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m04-t01', 'zte-backend-java-v1-core-phase-17-m04', 'Event-Driven Architecture', array['Explain and apply null in Event-Driven Architecture.', 'Use Event-Driven Architecture to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Services communicating via events rather than direct synchronous calls — publishers don''t know or care who consumes an event in a small working example.', 'Demonstrate Loose coupling as the main benefit — and the corresponding cost: harder to trace a single business operation across many independently-reacting services in a small working example.', 'Demonstrate Event schema design and versioning — events are a long-lived contract between services, unlike an internal function signature that''s easy to change in a small working example.', 'Demonstrate Why this style needs Stage 3''s reliability patterns underneath it — an event-driven system without outbox-guaranteed publishing and DLQ-handled failures is one where events can silently go missing in a small working example.']::text[], array['Submit a working Event-Driven Architecture example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 780, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m04-t02', 'zte-backend-java-v1-core-phase-17-m04', 'CQRS (Command Query Responsibility Segregation)', array['Explain and apply null in CQRS (Command Query Responsibility Segregation).', 'Use CQRS (Command Query Responsibility Segregation) to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The core split — a write model (commands) optimized for validating and applying changes, and a separate read model (queries) optimized for how data is actually displayed/queried in a small working example.', 'Demonstrate Why this can outperform a single shared model — the write model doesn''t need to support every query shape, and the read model can be denormalized however is fastest to read in a small working example.', 'Demonstrate Eventual consistency — the read model updates asynchronously as it consumes events (11) from the write side, meaning a query can briefly return stale data immediately after a write in a small working example.', 'Demonstrate When CQRS is worth the complexity — genuinely different read/write scaling needs or query shapes; explicitly not a default choice for most CRUD-shaped features in a small working example.']::text[], array['Submit a working CQRS (Command Query Responsibility Segregation) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m04-t03', 'zte-backend-java-v1-core-phase-17-m04', 'Multi-Tenancy', array['Explain and apply null in Multi-Tenancy.', 'Use Multi-Tenancy to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate Isolation strategies — separate databases per tenant, separate schemas per tenant, or shared schema with a tenant ID column, and the isolation/cost/operational-complexity tradeoff between them in a small working example.', 'Demonstrate Row-level security for shared-schema multi-tenancy — enforcing tenant isolation at the database layer itself (ties back to Phase 09''s Supabase RLS discussion) rather than trusting every query to remember a WHERE tenant_id = ? clause in a small working example.', 'Demonstrate Connection and resource considerations — how tenant count interacts with Phase 09''s PgBouncer connection pooling in a small working example.', 'Demonstrate Tenant-aware caching — extending Stage 1''s caching patterns with tenant-scoped cache keys to avoid one tenant''s cached data leaking into another''s response in a small working example.']::text[], array['Submit a working Multi-Tenancy example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m04-t02']::text[], '[]'::jsonb, 720, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-17-m05', 'zte-backend-java-v1-core-phase-17', 5, 'Deployment Strategy & Resilience Validation', 'Requires a real, architecturally mature system (Stages 1–5) to deploy and test — both topics are about operating and validating what''s already been built, not new features in themselves.', 9.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m05-t01', 'zte-backend-java-v1-core-phase-17-m05', 'Blue-Green Deployments', array['Explain and apply null in Blue-Green Deployments.', 'Use Blue-Green Deployments to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The pattern — running two identical production environments (blue and green), deploying to the idle one, then switching traffic over once the new version is verified in a small working example.', 'Demonstrate Why this enables near-zero-downtime deploys and instant rollback — switching traffic back to the previous environment is immediate if something''s wrong in a small working example.', 'Demonstrate Implementing this on Kubernetes (Phase 16) — using Service selectors or Ingress rules to control which environment receives traffic in a small working example.', 'Demonstrate Database migration considerations — blue-green deploys get complicated when a schema change (Phase 05) isn''t backward-compatible with the environment still serving traffic in a small working example.']::text[], array['Submit a working Blue-Green Deployments example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m05-t02', 'zte-backend-java-v1-core-phase-17-m05', 'Chaos Engineering', array['Explain and apply null in Chaos Engineering.', 'Use Chaos Engineering to complete a practical task in Architectural Patterns.']::text[], array['Demonstrate The core practice — deliberately injecting failure (killing a service, adding latency, dropping network connections) into a system to verify it degrades gracefully instead of catastrophically in a small working example.', 'Demonstrate Starting small — chaos experiments in a staging environment before ever considering production, and with a clear hypothesis about expected behavior before running one in a small working example.', 'Demonstrate What a chaos experiment actually validates — does the Circuit Breaker (Stage 3, Topic 10) actually open under real failure? Does a Saga (Stage 3, Topic 7) actually compensate correctly if a step fails mid-flight? Does the DLQ (Stage 3, Topic 9) actually catch what it''s supposed to? in a small working example.', 'Demonstrate Writing up results — documenting what was broken, what held, and what was fixed, which is directly the artifact this phase''s Build in Public section and Exit ★3''s portfolio checklist both call out in a small working example.', 'Demonstrate Post: "Why I used the Saga pattern instead of a distributed transaction" — one architectural pattern (Stage 3, Topic 7), explained simply, not the whole phase at once. in a small working example.']::text[], array['Submit a working Chaos Engineering example and explain the key decisions.', 'Record a short review showing how the example satisfies the Architectural Patterns learning goal.']::text[], array['zte-backend-java-v1-core-phase-17-m05-t01']::text[], '[]'::jsonb, 540, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-17-m06', 'zte-backend-java-v1-core-phase-17', 6, 'ZTE Backend Engineering with Java: Cloud and delivery', 'Cloud and delivery focus for the ZTE Backend Engineering with Java pathway.', 8, 5) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
