insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m07-t01', 'zte-backend-java-v1-core-phase-17-m07', 'Capacity estimation and data partitioning', array['Estimate throughput, storage, and hot-key risk', 'Choose indexes, partitions, and retention policies']::text[], array['Estimate a notification service at target volume', 'Model growth and operational cost']::text[], array['Design includes assumptions, calculations, and bottleneck plan']::text[], array[]::text[], '[]'::jsonb, 240, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-m07-t02', 'zte-backend-java-v1-core-phase-17-m07', 'Backend interview communication', array['Clarify requirements before proposing architecture', 'Explain tradeoffs and failure handling under time pressure']::text[], array['Run a timed API and system-design mock', 'Review answer against a structured rubric']::text[], array['Recorded mock review with concrete follow-up actions']::text[], array['zte-backend-java-v1-core-phase-17-m07-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-01', 'zte-backend-java-v1-core-phase-17', 'Optimistic Social Feed', 'A social-media-style feed where likes/comments appear instantly (optimistic update) with correct rollback on simulated server rejection, backed by a cache-aside and a write-through caching strategy compared side-by-side on two different data types in the same app.', array['Deliver the working outcome described in the Optimistic Social Feed brief.', 'Use at least two skills from Caching & Optimistic Update Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Optimistic Social Feed', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Caching & Optimistic Update Patterns']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-02', 'zte-backend-java-v1-core-phase-17', 'Idempotent Payment Retry Handler', 'A payment processing endpoint that safely handles duplicate/retried requests (e.g., a client retrying after a timeout) using an idempotency key, proven with a test that fires the same request 10 times concurrently and confirms only one charge occurs.', array['Deliver the working outcome described in the Idempotent Payment Retry Handler brief.', 'Use at least two skills from Database Concurrency Control.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Idempotent Payment Retry Handler', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Database Concurrency Control']::text[], 'advanced', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-03', 'zte-backend-java-v1-core-phase-17', 'Order Fulfillment Saga', 'Model a multi-step order fulfillment process (charge payment → reserve inventory → schedule shipping) as a Saga with proper compensating transactions for each step, demonstrated by deliberately failing the shipping step and proving payment gets correctly refunded and inventory released.', array['Deliver the working outcome described in the Order Fulfillment Saga brief.', 'Use at least two skills from Distributed Transactions & Messaging Resilience.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Order Fulfillment Saga', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Distributed Transactions & Messaging Resilience']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-04', 'zte-backend-java-v1-core-phase-17', 'Resilient Event-Driven Order Pipeline', 'The same order pipeline rebuilt using the Outbox pattern (to guarantee at-least-once event publishing alongside the DB transaction), a Dead Letter Queue for messages that repeatedly fail processing, and a Circuit Breaker around a flaky downstream shipping-provider API call.', array['Deliver the working outcome described in the Resilient Event-Driven Order Pipeline brief.', 'Use at least two skills from Distributed Transactions & Messaging Resilience.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Resilient Event-Driven Order Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Distributed Transactions & Messaging Resilience']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-05', 'zte-backend-java-v1-core-phase-17', 'CQRS-Based Reporting System', 'Split a write-heavy transactional data model from a read-optimized reporting model using CQRS — writes go through a normalized command model, reads are served from a denormalized, eventually-consistent query model — with documented consistency-lag behavior.', array['Deliver the working outcome described in the CQRS-Based Reporting System brief.', 'Use at least two skills from Architectural Styles and Multi-Tenancy and Multi-Tenancy.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CQRS-Based Reporting System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Architectural Styles and Multi-Tenancy and Multi-Tenancy']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-06', 'zte-backend-java-v1-core-phase-17', 'Row-Level Multi-Tenant SaaS Data Layer', 'Implement multi-tenancy for a SaaS app using a shared-database, row-level isolation strategy (tenant_id on every table + enforced query scoping), with a deliberate test proving one tenant can never see another tenant’s data even under a crafted malicious query attempt.', array['Deliver the working outcome described in the Row-Level Multi-Tenant SaaS Data Layer brief.', 'Use at least two skills from Multi-Tenancy.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Row-Level Multi-Tenant SaaS Data Layer', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Multi-Tenancy']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-07', 'zte-backend-java-v1-core-phase-17', 'Chaos Engineering Game Day', 'Run a real chaos engineering exercise against one of your deployed systems: deliberately kill a service instance, inject network latency, or fail a dependency mid-request, and document what broke, what didn’t, and what you fixed afterward. Domain: SRE / resilience engineering.', array['Deliver the working outcome described in the Chaos Engineering Game Day brief.', 'Use at least two skills from Deployment Strategy & Resilience Validation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Chaos Engineering Game Day', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Deployment Strategy & Resilience Validation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-08', 'zte-backend-java-v1-core-phase-17', 'A Distributed, Multi-Tenant Order Platform', 'A multi-tenant e-commerce order platform combining every pattern in this phase: optimistic-locked inventory and idempotent payment handling preventing overselling and double-charges, a Saga-orchestrated fulfillment pipeline with the Outbox pattern for reliable event publishing, a Circuit Breaker and Dead Letter Queue protecting against a flaky shipping provider, an event-driven notification system decoupled via pub/sub, a CQRS-split reporting layer for seller analytics, strict row-level multi-tenant data isolation proven under adversarial testing, and a blue-green deployment pipeline validated with a real chaos engineering game day. Domain: e-commerce / distributed systems. Why it matters: this is the single most architecturally advanced project in the entire roadmap — it proves genuine distributed-systems thinking, not just feature-building.', array['Deliver the working outcome described in the A Distributed, Multi-Tenant Order Platform brief.', 'Use at least two skills from Architectural Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Distributed, Multi-Tenant Order Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'engineering documentation']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-backend-java-v1-core-phase-17-project-09', 'zte-backend-java-v1-core-phase-17', 'Production-ready backend capstone', 'Deliver a service that solves a real workflow and can be operated by another engineer.', array['Secure API and clear data model', 'Automated tests and safe migrations', 'Deployment and observability', 'Documented failure and recovery behavior']::text[], array['Requirements and architecture', 'Implementation and data integrity', 'Security/reliability review', 'Deployment and operational exercise']::text[], array['Running service', 'Design and API docs', 'Test and load evidence', 'Runbook and interview narrative']::text[], array['system design', 'cloud', 'security', 'communication', 'backend', 'engineering delivery']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-backend-java-v1-core-phase-18', 'zte-backend-java-v1', id, '20', 'Engineering Craft + Package Publishing', 'Expert', 'Foundational to everything that follows in this phase — Stage 4''s documentation artifacts are largely the written record of the practices introduced here.', 62, 19 from public.roadmap_versions where roadmap_id='zte-backend-java-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-18-m01', 'zte-backend-java-v1-core-phase-18', 1, 'Decision-Making Practices and Package Publishing and Package Publishing', 'Foundational to everything that follows in this phase — Stage 4''s documentation artifacts are largely the written record of the practices introduced here.', 4.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m01-t01', 'zte-backend-java-v1-core-phase-18-m01', 'Changesets', array['Explain and apply null in Changesets.', 'Use Changesets to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The problem — coordinating version bumps and changelog entries across a package (or monorepo of packages) without manually tracking what changed since the last release in a small working example.', 'Demonstrate Adding a changeset — a small markdown file describing a change and its semver impact (patch/minor/major), committed alongside the code change itself in a small working example.', 'Demonstrate Consuming changesets — a release step that reads all pending changesets, bumps versions accordingly, and generates a changelog automatically in a small working example.', 'Demonstrate Publishing workflow — combining Changesets with Phase 15''s tsup build step and Phase 06''s GitHub Actions to automate the actual npm publish in a small working example.', 'Demonstrate This is the direct mechanism behind this phase''s Build in Public goal — publishing a first real npm package in a small working example.']::text[], array['Submit a working Changesets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m01-t02', 'zte-backend-java-v1-core-phase-18-m01', 'ADRs (Architectural Decision Records)', array['Explain and apply null in ADRs (Architectural Decision Records).', 'Use ADRs (Architectural Decision Records) to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The format — context (what problem/situation prompted this), decision (what was chosen), consequences (what tradeoffs follow from it) in a small working example.', 'Demonstrate Why ADRs matter more than comments or memory — a decision''s reasoning is often more valuable to a future reader than the decision itself, especially once circumstances have changed and someone''s questioning whether the original choice still makes sense in a small working example.', 'Demonstrate What''s actually worth writing one for — significant, hard-to-reverse decisions (Phase 12''s Exit D caution about documenting pgvector vs Pinecone, Haiku vs GPT-4o is exactly ADR-shaped content), not every minor implementation choice in a small working example.', 'Demonstrate Retroactively writing ADRs for major decisions already made across Phases 01–17 — this phase is a natural point to catch up the backlog, not just start going forward in a small working example.']::text[], array['Submit a working ADRs (Architectural Decision Records) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m01-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m01-t03', 'zte-backend-java-v1-core-phase-18-m01', 'RFCs (Request for Comments)', array['Explain and apply null in RFCs (Request for Comments).', 'Use RFCs (Request for Comments) to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Structure — problem statement, proposed approach, alternatives considered, open questions for discussion in a small working example.', 'Demonstrate When an RFC is worth writing vs when a decision is small enough to just make and document via ADR (2) afterward in a small working example.', 'Demonstrate The lifecycle — an RFC that reaches consensus typically becomes the basis for one or more ADRs (2) once implemented in a small working example.', 'Demonstrate Solo-developer context — even without a team to actually comment on an RFC, writing one forces the same rigor of considering alternatives before committing, which matters for the kind of documented decision-making Exit ★3 (Phase 17) already flagged as a portfolio differentiator in a small working example.']::text[], array['Submit a working RFCs (Request for Comments) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m01-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-18-m02', 'zte-backend-java-v1-core-phase-18', 2, 'Engineering Process Practices', 'A cluster of process disciplines, mostly independent of each other, but all downstream of having a real, deployed, monitored system (Phases 05–17) to actually apply them to.', 10, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m02-t01', 'zte-backend-java-v1-core-phase-18-m02', 'DORA Metrics', array['Explain and apply null in DORA Metrics.', 'Use DORA Metrics to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The four key metrics — deployment frequency, lead time for changes, change failure rate, time to restore service in a small working example.', 'Demonstrate Why these specific four — they''re the metrics DORA''s research found actually correlate with high-performing engineering organizations, not an arbitrary dashboard in a small working example.', 'Demonstrate Measuring them from your own pipeline — deployment frequency and lead time are readable directly from Phase 06''s GitHub Actions history; change failure rate and time to restore need incident tracking (foreshadows Topic 5 and the incidents/ artifact, Stage 4) in a small working example.']::text[], array['Submit a working DORA Metrics example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m02-t02', 'zte-backend-java-v1-core-phase-18-m02', 'Blameless Post-Mortems', array['Explain and apply null in Blameless Post-Mortems.', 'Use Blameless Post-Mortems to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The blameless framing — analyzing what happened and why the system allowed it, not who made a mistake; the practice exists because blame-oriented reviews make people hide information rather than surface it in a small working example.', 'Demonstrate Structure — timeline of events, root cause analysis, contributing factors, action items with owners in a small working example.', 'Demonstrate Using Phase 14/17''s chaos engineering experiments as low-stakes practice material — you already have a real "incident" (something you deliberately broke) to write a genuine post-mortem about in a small working example.', 'Demonstrate Directly feeds the incidents/ documentation artifact (Stage 4) in a small working example.']::text[], array['Submit a working Blameless Post-Mortems example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m02-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m02-t03', 'zte-backend-java-v1-core-phase-18-m02', 'Technical Debt Tracking', array['Explain and apply null in Technical Debt Tracking.', 'Use Technical Debt Tracking to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Distinguishing technical debt from "code I''d write differently today" — debt implies a deliberate or understood tradeoff, not just hindsight in a small working example.', 'Demonstrate A lightweight tracking format — what was deferred, why, and what the cost of leaving it unaddressed actually is in a small working example.', 'Demonstrate Directly feeds the TECH_DEBT.md documentation artifact (Stage 4) in a small working example.']::text[], array['Submit a working Technical Debt Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m02-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m02-t04', 'zte-backend-java-v1-core-phase-18-m02', 'Estimation Tracking', array['Explain and apply null in Estimation Tracking.', 'Use Estimation Tracking to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Recording estimates against actuals — the only way to actually improve at estimation is comparing predictions to outcomes over time in a small working example.', 'Demonstrate Common estimation failure patterns — optimism bias, ignoring integration/testing time, underestimating unfamiliar work in a small working example.', 'Demonstrate Using this phase''s own official-vs-actual hour discrepancies (flagged throughout every deep doc in this series) as a live, concrete example of estimation drift worth reflecting on in a small working example.']::text[], array['Submit a working Estimation Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m02-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m02-t05', 'zte-backend-java-v1-core-phase-18-m02', 'Code Review Conventions', array['Explain and apply null in Code Review Conventions.', 'Use Code Review Conventions to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Establishing what a review is actually checking for — correctness, readability, adherence to existing patterns, not just "does it work" in a small working example.', 'Demonstrate Self-review discipline in a solo-developer context — reviewing your own PR with the same rigor you''d apply to someone else''s, before merging in a small working example.']::text[], array['Submit a working Code Review Conventions example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m02-t04']::text[], '[]'::jsonb, 120, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m02-t06', 'zte-backend-java-v1-core-phase-18-m02', 'Ramp-Up Strategy', array['Explain and apply null in Ramp-Up Strategy.', 'Use Ramp-Up Strategy to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate What a new engineer (or a future version of yourself, returning to the project after months away) actually needs to become productive quickly in a small working example.', 'Demonstrate Structuring an onboarding path — which docs to read first, which parts of the codebase to explore, what NOT to worry about initially in a small working example.', 'Demonstrate The direct connection to Stage 4 — this practice is essentially designing the reading order for the documentation artifacts about to be built in a small working example.']::text[], array['Submit a working Ramp-Up Strategy example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m02-t05']::text[], '[]'::jsonb, 120, 'advanced', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-backend-java-v1-core-phase-18-m03', 'zte-backend-java-v1-core-phase-18', 3, 'Documentation Artifacts: Decisions & Architecture', 'These artifacts are downstream of Stage 2''s practices — the folder structure and files exist to hold the output of the ADR/RFC discipline, not as independent new concepts.', 4, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m03-t01', 'zte-backend-java-v1-core-phase-18-m03', 'ARCHITECTURE.md', array['Explain and apply null in ARCHITECTURE.md.', 'Use ARCHITECTURE.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A high-level system overview — the map that makes docs/adr/''s (10) individual decisions make sense in context in a small working example.', 'Demonstrate Summarizing the major architectural patterns actually implemented (Phase 17''s Saga, Outbox, CQRS, Circuit Breaker, Multi-Tenancy) with links to the specific ADRs that decided them in a small working example.', 'Demonstrate Keeping this document high-level — detailed reasoning belongs in the individual ADRs (10), not duplicated here in a small working example.']::text[], array['Submit a working ARCHITECTURE.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m03-t02', 'zte-backend-java-v1-core-phase-18-m03', 'DECISIONS.md', array['Explain and apply null in DECISIONS.md.', 'Use DECISIONS.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A single-file chronological or categorized index of decisions — useful as a fast-scan overview when docs/adr/''s individual files would be too slow to browse one by one in a small working example.', 'Demonstrate Where this differs from ARCHITECTURE.md (11) — DECISIONS.md is a log, ARCHITECTURE.md is a synthesized picture in a small working example.']::text[], array['Submit a working DECISIONS.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m03-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-backend-java-v1-core-phase-18-m03-t03', 'zte-backend-java-v1-core-phase-18-m03', 'docs/adr/', array['Explain and apply null in docs/adr/.', 'Use docs/adr/ to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Numbered, sequential ADR files (0001-use-postgresql.md style naming) — a convention that preserves chronological decision history in a small working example.', 'Demonstrate Linking between related/superseding ADRs — architecture decisions evolve, and the record should show that evolution rather than silently overwriting old reasoning in a small working example.']::text[], array['Submit a working docs/adr/ example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-backend-java-v1-core-phase-18-m03-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
