insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-01-m02', 'zte-fullstack-v1-core-phase-01', 2, 'Behavior: JavaScript (Full Sequence, dependency-ordered)', 'JavaScript comes after HTML/CSS because its most motivating use case (manipulating the page) needs a page to exist. Ordered in true dependency order — language core → functions → scope/execution → closures/this/memory → data structures → strings/numbers/dates → error handling → regex → OOP → iteration → meta-programming → modules → async → HTTP → DOM/browser → performance/security → functional patterns → architecture → algorithms → tooling/testing/debugging → engine internals/spec. Topics that could otherwise appear in more than one place (e.g. spread/rest appearing under both Functions and Advanced Operators) are merged at first occurrence.', 162, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-01-m02-t01', 'zte-fullstack-v1-core-phase-01-m02', 'JavaScript — Language Core', array['Explain and apply 8.1 — Fundamentals in JavaScript — Language Core.', 'Explain and apply 8.2 — Control Flow in JavaScript — Language Core.', 'Explain and apply 8.3 — Functions in JavaScript — Language Core.', 'Explain and apply 8.4 — Scope in JavaScript — Language Core.', 'Explain and apply 8.5 — Execution Context in JavaScript — Language Core.']::text[], array['Demonstrate What is JavaScript / JS Engine / JS Runtime / How JavaScript Runs in a small working example.', 'Demonstrate Variables: var, let, const and their differences in a small working example.', 'Demonstrate Data types: Number, String, Boolean, Null, Undefined, Symbol, BigInt in a small working example.', 'Demonstrate Dynamic typing, type conversion, type coercion in a small working example.', 'Demonstrate Operators: arithmetic, assignment, comparison, logical, bitwise, ternary in a small working example.']::text[], array['Submit a working JavaScript — Language Core example and explain the key decisions.', 'Record a short review showing how the example satisfies the Developer Environment & Foundations learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'beginner', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
