insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-m08-t02', 'zte-fullstack-v1-core-phase-04-m08', 'Authentication, authorization, and tenant isolation', array['Distinguish authentication from permission', 'Enforce ownership and role checks at every data boundary']::text[], array['Test forged IDs and cross-account access attempts', 'Review query, API, and database policy behavior']::text[], array['Two-account negative tests prove record isolation']::text[], array['zte-fullstack-v1-core-phase-04-m08-t01']::text[], '[]'::jsonb, 300, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-01', 'zte-fullstack-v1-core-phase-04', 'Context Meltdown Demo', 'Deliberately build a deeply nested component tree relying only on Context for frequently-changing state, profile the re-render cascade with React DevTools, then document exactly where and why it breaks down. Domain: educational / performance engineering.', array['Deliver the working outcome described in the Context Meltdown Demo brief.', 'Use at least two skills from Client State: Context''s Limits, Then Zustand.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Context Meltdown Demo', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Client State: Context''s Limits, Then Zustand']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-02', 'zte-fullstack-v1-core-phase-04', 'Multi-Store Zustand Task Manager', 'A task/project manager using multiple focused Zustand stores (not one giant store), with selectors to prevent unnecessary re-renders, persisted to localStorage via Zustand middleware. Domain: productivity tools.', array['Deliver the working outcome described in the Multi-Store Zustand Task Manager brief.', 'Use at least two skills from Client State: Context''s Limits, Then Zustand.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Store Zustand Task Manager', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Client State: Context''s Limits, Then Zustand']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-03', 'zte-fullstack-v1-core-phase-04', 'Undo/Redo Design Tool State Engine', 'The state layer for a simple design/whiteboard tool (shapes, position, color) using Zustand with a custom undo/redo middleware (command history), demonstrating advanced store composition. Domain: creative tools.', array['Deliver the working outcome described in the Undo/Redo Design Tool State Engine brief.', 'Use at least two skills from Client State: Context''s Limits, Then Zustand.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Undo/Redo Design Tool State Engine', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Client State: Context''s Limits, Then Zustand']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-04', 'zte-fullstack-v1-core-phase-04', 'Paginated \+ Infinite Product Catalog', 'A product listing using TanStack Query with both classic pagination and infinite scroll variants, optimistic updates for "add to wishlist," and proper cache invalidation on mutation. Domain: e-commerce. A full-stack todo app where the client calls the backend via tRPC with zero manual type duplication — renaming a backend field breaks the frontend build immediately, proving end-to-end type safety. Domain: full-stack tooling demonstration.', array['Deliver the working outcome described in the Paginated \+ Infinite Product Catalog brief.', 'Use at least two skills from Server State: TanStack Query, Then tRPC.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Paginated \+ Infinite Product Catalog', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Server State: TanStack Query, Then tRPC']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-05', 'zte-fullstack-v1-core-phase-04', 'Real-Time-Feeling Dashboard via Query Polling \+ Optimistic UI', 'A support-ticket dashboard where status changes feel instant via optimistic updates, with automatic rollback on server rejection, background refetching, and stale-time tuning documented per query type. Domain: customer support / SaaS.', array['Deliver the working outcome described in the Real-Time-Feeling Dashboard via Query Polling \+ Optimistic UI brief.', 'Use at least two skills from Server State: TanStack Query, Then tRPC.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Real-Time-Feeling Dashboard via Query Polling \+ Optimistic UI', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Server State: TanStack Query, Then tRPC']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-06', 'zte-fullstack-v1-core-phase-04', 'Traffic Light & Turnstile State Machines', 'Two classic finite state machines implemented in XState v5 to build fluency with the model before tackling something real. Domain: educational / systems modeling. A checkout flow (cart → shipping → payment → confirm) modeled explicitly as a state machine with guards (e.g., can’t proceed to payment without valid address) and visualized in Stately Studio, catching impossible states that a boolean-flag approach would allow. Domain: e-commerce.', array['Deliver the working outcome described in the Traffic Light & Turnstile State Machines brief.', 'Use at least two skills from State Machines.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Traffic Light & Turnstile State Machines', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'State Machines']::text[], 'beginner', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-07', 'zte-fullstack-v1-core-phase-04', 'Video Upload Pipeline State Machine', 'Model a video upload/processing pipeline (idle → uploading → processing → ready/failed, with retry and cancel) as a state machine with parallel states for "upload progress" and "processing progress" tracked independently. Domain: media platforms.', array['Deliver the working outcome described in the Video Upload Pipeline State Machine brief.', 'Use at least two skills from State Machines.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Video Upload Pipeline State Machine', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'State Machines']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-08', 'zte-fullstack-v1-core-phase-04', 'Route-Level Code Splitting Audit', 'Take a multi-page app and apply React.lazy + Suspense at route boundaries, measuring bundle size and load time before/after with real numbers. Domain: performance engineering. A dashboard of independent widgets where each widget has its own Suspense boundary and its own react-error-boundary fallback, so one failing widget (simulated) never crashes the whole page — with a portal-based "widget detail" modal on click.', array['Deliver the working outcome described in the Route-Level Code Splitting Audit brief.', 'Use at least two skills from Rendering & Resilience Primitives (Applied Depth).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Route-Level Code Splitting Audit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Rendering & Resilience Primitives (Applied Depth)']::text[], 'intermediate', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-09', 'zte-fullstack-v1-core-phase-04', 'Scroll-Triggered Storytelling Page', 'A scrollytelling landing page (like a data-journalism piece) where sections animate/reveal using Intersection Observer as the user scrolls. Domain: media/journalism.', array['Deliver the working outcome described in the Scroll-Triggered Storytelling Page brief.', 'Use at least two skills from Browser Observation APIs.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Scroll-Triggered Storytelling Page', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Browser Observation APIs']::text[], 'intermediate', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-10', 'zte-fullstack-v1-core-phase-04', 'Responsive Chart Container System', 'A set of chart containers that resize their internal SVG/canvas rendering correctly using ResizeObserver, avoiding the common bug of charts not resizing on sidebar collapse. Domain: analytics/dashboards.', array['Deliver the working outcome described in the Responsive Chart Container System brief.', 'Use at least two skills from Browser Observation APIs.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Responsive Chart Container System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Browser Observation APIs']::text[], 'intermediate', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-11', 'zte-fullstack-v1-core-phase-04', '100,000-Row Virtualized Table', 'A data table that renders 100,000 rows smoothly using TanStack Virtual, with sorting/filtering that stays performant, profiled and documented with React DevTools Profiler flame charts before/after virtualization. Domain: enterprise data tools / fintech dashboards.', array['Deliver the working outcome described in the 100,000-Row Virtualized Table brief.', 'Use at least two skills from Virtualization & Profiling (Capstone).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working 100,000-Row Virtualized Table', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Virtualization & Profiling (Capstone)']::text[], 'advanced', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-12', 'zte-fullstack-v1-core-phase-04', 'Chat App Virtualized Message List', 'A chat interface with a virtualized, variable-height message list (some messages have images, some are one line) that maintains correct scroll position when new messages arrive at the bottom. Domain: messaging/social.', array['Deliver the working outcome described in the Chat App Virtualized Message List brief.', 'Use at least two skills from Virtualization & Profiling (Capstone).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Chat App Virtualized Message List', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'Virtualization & Profiling (Capstone)']::text[], 'advanced', 11) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-13', 'zte-fullstack-v1-core-phase-04', 'A Real-Time Support Ticket Dashboard', 'A support-ticket triage dashboard combining every Phase 4 concept: Zustand for UI-local state (filters, selected ticket), TanStack Query \+ tRPC for fully type-safe server state with optimistic status updates and rollback, an XState machine governing the ticket lifecycle (new → assigned → in-progress → resolved → reopened) with guards preventing invalid transitions, Suspense \+ error boundaries per panel so one broken widget never takes down the dashboard, Intersection/ResizeObserver-driven responsive charts, and a virtualized ticket list handling 50,000+ rows without jank, profiled and documented. Domain: customer support / SaaS operations tooling. Why it matters: this is a realistic "senior front-end engineer" artifact — the kind of dashboard that separates people who know individual libraries from people who can architect a resilient, performant system out of them.', array['Deliver the working outcome described in the A Real-Time Support Ticket Dashboard brief.', 'Use at least two skills from State, Data Fetching & Advanced React.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Real-Time Support Ticket Dashboard', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['State, Data Fetching & Advanced React', 'engineering documentation']::text[], 'advanced', 12) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-04-project-14', 'zte-fullstack-v1-core-phase-04', 'Secure multi-user project API', 'Expose project and work-item workflows for separate user accounts without leaking data.', array['Authenticated API', 'Relational schema and migrations', 'Owner-scoped operations', 'Input validation and audit-friendly errors']::text[], array['Threat model and schema', 'CRUD contract', 'Authentication/authorization', 'Isolation test and deployment']::text[], array['API service', 'Schema and API documentation', 'Two-user test report']::text[], array['HTTP', 'SQL', 'authentication', 'authorization', 'testing', 'full-stack', 'engineering delivery']::text[], 'intermediate', 13) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-fullstack-v1-core-phase-05', 'zte-fullstack-v1', id, '06', 'Backend + Database + Auth', 'Core', 'Everything in this phase runs on top of Node.js and, for routing, Express — both must be solid before anything else here makes sense.', 333, 5 from public.roadmap_versions where roadmap_id='zte-fullstack-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-05-m01', 'zte-fullstack-v1-core-phase-05', 1, 'Server Runtime & Framework', 'Everything in this phase runs on top of Node.js and, for routing, Express — both must be solid before anything else here makes sense.', 17, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m01-t01', 'zte-fullstack-v1-core-phase-05-m01', 'Node.js', array['Explain and apply Runtime Fundamentals in Node.js.', 'Explain and apply File System & Streams in Node.js.', 'Explain and apply The http Module (Before Express) in Node.js.', 'Explain and apply Process & Environment in Node.js.', 'Explain and apply Package Management (Node Context) in Node.js.']::text[], array['Demonstrate The event loop in a server context (contrasted with the browser event loop from Phase 01) in a small working example.', 'Demonstrate CommonJS vs ES Modules in Node — require vs import, package.json "type" field in a small working example.', 'Demonstrate Global objects: process, __dirname/__filename (or import.meta.url in ESM), Buffer in a small working example.', 'Demonstrate Module system: built-in modules (fs, path, http, crypto, os) in a small working example.', 'Demonstrate fs module — sync vs async vs promise-based APIs in a small working example.']::text[], array['Submit a working Node.js example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array[]::text[], '[]'::jsonb, 2040, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m01-t02', 'zte-fullstack-v1-core-phase-05-m01', 'Express.js', array['Explain and apply Core Routing in Express.js.', 'Explain and apply Middleware in Express.js.', 'Explain and apply Routers & Structure in Express.js.', 'Explain and apply Error Handling in Express.js.']::text[], array['Demonstrate app.get/post/put/patch/delete — route handlers in a small working example.', 'Demonstrate Route parameters (:id) and query strings in a small working example.', 'Demonstrate Request and Response objects — req.body, req.params, req.query, res.json/send/status in a small working example.', 'Demonstrate Middleware function signature (req, res, next) in a small working example.', 'Demonstrate Application-level vs router-level vs error-handling middleware in a small working example.']::text[], array['Submit a working Express.js example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m01-t01']::text[], '[]'::jsonb, 1500, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-05-m02', 'zte-fullstack-v1-core-phase-05', 2, 'API Design & Hardening and Testing the API and Testing the API and Testing the API', 'Requires Express (Stage 1\\) — REST conventions are applied through Express routes, and every hardening middleware in this stage attaches to that same Express app.', 15, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t01', 'zte-fullstack-v1-core-phase-05-m02', 'REST APIs', array['Explain and apply REST Principles in REST APIs.', 'Explain and apply API Design Practice in REST APIs.', 'Explain and apply Validation in REST APIs.']::text[], array['Demonstrate Resources and URIs — nouns, not verbs, in endpoint paths in a small working example.', 'Demonstrate HTTP methods mapped to CRUD operations in a small working example.', 'Demonstrate Statelessness — why REST APIs shouldn''t rely on server-side session state (motivates token-based auth in Stage 5) in a small working example.', 'Demonstrate HATEOAS (concept, rarely fully implemented — worth knowing why) in a small working example.', 'Demonstrate Status codes — using them correctly (200 vs 201 vs 204, 400 vs 401 vs 403 vs 404 vs 422, 500) in a small working example.']::text[], array['Submit a working REST APIs example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array[]::text[], '[]'::jsonb, 1020, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t02', 'zte-fullstack-v1-core-phase-05-m02', 'express-async-errors', array['Explain and apply null in express-async-errors.', 'Use express-async-errors to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate The problem: unhandled promise rejections in async route handlers bypass Express''s error handler by default in a small working example.', 'Demonstrate How express-async-errors patches this (or the manual try/catch-and-next(err) alternative, for understanding what it automates) in a small working example.']::text[], array['Submit a working express-async-errors example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m02-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t03', 'zte-fullstack-v1-core-phase-05-m02', 'CORS', array['Explain and apply null in CORS.', 'Use CORS to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Same-Origin Policy recap (from Phase 02''s security stage) and why CORS exists to relax it selectively in a small working example.', 'Demonstrate Configuring the cors middleware — origin, credentials, allowed methods/headers in a small working example.', 'Demonstrate CORS and cookies (credentials: true) — foreshadows httpOnly cookie auth in Stage 5 in a small working example.']::text[], array['Submit a working CORS example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m02-t02']::text[], '[]'::jsonb, 120, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t04', 'zte-fullstack-v1-core-phase-05-m02', 'Helmet.js', array['Explain and apply null in Helmet.js.', 'Use Helmet.js to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Setting secure HTTP headers by default (CSP, X-Frame-Options, HSTS, etc.) in a small working example.', 'Demonstrate Which headers matter most and why in a small working example.', 'Demonstrate Customizing Helmet''s defaults for an app''s specific needs in a small working example.']::text[], array['Submit a working Helmet.js example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m02-t03']::text[], '[]'::jsonb, 60, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t05', 'zte-fullstack-v1-core-phase-05-m02', 'express-rate-limit', array['Explain and apply null in express-rate-limit.', 'Use express-rate-limit to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Configuring windowMs and max request limits in a small working example.', 'Demonstrate Per-route vs global rate limiting in a small working example.', 'Demonstrate Rate limiting login endpoints specifically — foreshadows brute-force protection relevant to Stage 5''s auth work in a small working example.']::text[], array['Submit a working express-rate-limit example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m02-t04']::text[], '[]'::jsonb, 180, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t06', 'zte-fullstack-v1-core-phase-05-m02', 'DOMPurify (Server-Side Sanitization)', array['Explain and apply null in DOMPurify (Server-Side Sanitization).', 'Use DOMPurify (Server-Side Sanitization) to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Sanitizing user-generated HTML/rich text input server-side before persistence in a small working example.', 'Demonstrate XSS prevention at the data layer, complementing Helmet''s header-based protections (Topic 6) in a small working example.', 'Demonstrate When sanitization belongs server-side vs client-side (defense in depth — both, not either/or) in a small working example.']::text[], array['Submit a working DOMPurify (Server-Side Sanitization) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m02-t05']::text[], '[]'::jsonb, 60, 'intermediate', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t07', 'zte-fullstack-v1-core-phase-05-m02', 'compression', array['Explain and apply null in compression.', 'Use compression to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate gzip/brotli response compression middleware in a small working example.', 'Demonstrate Tradeoffs: CPU cost of compression vs bandwidth savings in a small working example.', 'Demonstrate When to skip compression (already-compressed assets, small responses) in a small working example.']::text[], array['Submit a working compression example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m02-t06']::text[], '[]'::jsonb, 60, 'intermediate', 6) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m02-t08', 'zte-fullstack-v1-core-phase-05-m02', 'Supertest', array['Explain and apply null in Supertest.', 'Use Supertest to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate HTTP assertion testing — making real requests against an Express app in tests in a small working example.', 'Demonstrate Integration with a test runner (Jest/Vitest, from Phase 01''s testing stage) in a small working example.', 'Demonstrate Testing status codes, response bodies, headers in a small working example.', 'Demonstrate Testing middleware behavior — rate limits, CORS rejections, validation errors in a small working example.', 'Demonstrate Setting up a test database or mocking the DB layer (bridges to Stage 4) in a small working example.']::text[], array['Submit a working Supertest example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m02-t07']::text[], '[]'::jsonb, 360, 'intermediate', 7) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-05-m03', 'zte-fullstack-v1-core-phase-05', 3, 'Database Layer', 'Independent of Express/Node conceptually, but placed here because a real backend needs persistence, and the API/testing layer built in Stages 1–3 is what will consume this data.', 26.5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m03-t01', 'zte-fullstack-v1-core-phase-05-m03', 'PostgreSQL', array['Explain and apply Beyond Phase 01''s SQL Basics in PostgreSQL.', 'Explain and apply Data Types & Schema Design in PostgreSQL.', 'Explain and apply Transactions in PostgreSQL.', 'Explain and apply Advanced Querying in PostgreSQL.', 'Explain and apply JSONB in PostgreSQL.']::text[], array['Demonstrate Recap: Phase 01 covered basic SELECT/JOIN/GROUP BY — this goes into PostgreSQL specifically in a small working example.', 'Demonstrate PostgreSQL-specific types: UUID, JSONB, ARRAY, ENUM in a small working example.', 'Demonstrate Normalization — 1NF/2NF/3NF in practice, and when to deliberately denormalize in a small working example.', 'Demonstrate Constraints: foreign keys, unique, check constraints in depth in a small working example.', 'Demonstrate Indexes — B-tree by default, when to add one, composite indexes in a small working example.']::text[], array['Submit a working PostgreSQL example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array[]::text[], '[]'::jsonb, 3120, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m03-t02', 'zte-fullstack-v1-core-phase-05-m03', 'Prisma', array['Explain and apply Schema & Migrations in Prisma.', 'Explain and apply Prisma Client in Prisma.', 'Explain and apply Advanced Prisma in Prisma.']::text[], array['Demonstrate schema.prisma — models, fields, relations in a small working example.', 'Demonstrate prisma migrate dev / deploy workflow in a small working example.', 'Demonstrate Migration history and rollback considerations in a small working example.', 'Demonstrate CRUD operations via the generated client in a small working example.', 'Demonstrate Relations — include vs select, nested writes/reads in a small working example.']::text[], array['Submit a working Prisma example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m03-t01']::text[], '[]'::jsonb, 1500, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m03-t03', 'zte-fullstack-v1-core-phase-05-m03', 'Supabase', array['Explain and apply null in Supabase.', 'Use Supabase to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Supabase as hosted PostgreSQL + auth + storage + realtime, in one platform in a small working example.', 'Demonstrate Row Level Security (RLS) policies — PostgreSQL-native access control enforced at the database layer in a small working example.', 'Demonstrate Supabase''s client libraries vs going through Prisma/Express directly in a small working example.', 'Demonstrate When Supabase''s built-in auth/storage make sense vs building your own with Stage 5''s tools in a small working example.']::text[], array['Submit a working Supabase example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m03-t02']::text[], '[]'::jsonb, 420, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m03-t04', 'zte-fullstack-v1-core-phase-05-m03', 'Neon', array['Explain and apply null in Neon.', 'Use Neon to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Serverless Postgres — branching databases like Git branches in a small working example.', 'Demonstrate Connection pooling considerations for serverless/edge environments (ties to Phase 02''s Edge Runtime) in a small working example.', 'Demonstrate Neon vs Supabase — when to choose one over the other (Neon: pure Postgres hosting; Supabase: Postgres + platform features) in a small working example.']::text[], array['Submit a working Neon example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m03-t03']::text[], '[]'::jsonb, 120, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m03-t05', 'zte-fullstack-v1-core-phase-05-m03', 'EXPLAIN ANALYZE', array['Explain and apply null in EXPLAIN ANALYZE.', 'Use EXPLAIN ANALYZE to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Reading query plans — seq scan vs index scan vs index-only scan in a small working example.', 'Demonstrate Understanding cost estimates vs actual execution time (the ANALYZE part) in a small working example.', 'Demonstrate Identifying missing indexes from a plan in a small working example.', 'Demonstrate Common fixes: adding an index, rewriting a query, denormalizing a hot path in a small working example.']::text[], array['Submit a working EXPLAIN ANALYZE example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m03-t04']::text[], '[]'::jsonb, 540, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-05-m04', 'zte-fullstack-v1-core-phase-05', 4, 'Authentication & Token Security', 'Requires the database layer (Stage 4\\) — auth needs somewhere to store users and their credentials. Internally reordered from the official list: HMAC-SHA256 moved ahead of JWT, since HS256 (HMAC-SHA256) is one of JWT''s standard signing algorithms — teaching JWT first would mean explaining "the token is signed" without the mechanism underneath it.', 16, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m04-t01', 'zte-fullstack-v1-core-phase-05-m04', 'bcrypt', array['Explain and apply null in bcrypt.', 'Use bcrypt to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Why passwords are never stored in plaintext or with reversible encryption in a small working example.', 'Demonstrate Hashing vs encryption — a critical distinction in a small working example.', 'Demonstrate Salt — why bcrypt generates one automatically per hash in a small working example.', 'Demonstrate Cost factor (rounds) — the time/security tradeoff in a small working example.', 'Demonstrate Hashing on signup, comparing on login (bcrypt.compare) in a small working example.']::text[], array['Submit a working bcrypt example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m04-t02', 'zte-fullstack-v1-core-phase-05-m04', 'JWT (JSON Web Tokens)', array['Explain and apply Structure & Signing in JWT (JSON Web Tokens).', 'Explain and apply Auth Flow in JWT (JSON Web Tokens).', 'Explain and apply Security Considerations in JWT (JSON Web Tokens).']::text[], array['Demonstrate Header.Payload.Signature structure in a small working example.', 'Demonstrate Claims — registered (exp, iat, sub) vs custom claims in a small working example.', 'Demonstrate Signing algorithms — HS256 (HMAC-SHA256, Topic 17) vs RS256 (asymmetric, public/private key pairs) in a small working example.', 'Demonstrate Why the signature prevents tampering but does NOT encrypt the payload (JWTs are readable, not secret) in a small working example.', 'Demonstrate Login → verify password (bcrypt) → issue JWT in a small working example.']::text[], array['Submit a working JWT (JSON Web Tokens) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m04-t01']::text[], '[]'::jsonb, 900, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m04-t03', 'zte-fullstack-v1-core-phase-05-m04', 'jose', array['Explain and apply null in jose.', 'Use jose to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Why jose over jsonwebtoken for Edge-compatible code (Middleware, Edge Functions) in a small working example.', 'Demonstrate Signing and verifying tokens with jose''s API in a small working example.', 'Demonstrate Key generation and management with jose in a small working example.']::text[], array['Submit a working jose example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m04-t02']::text[], '[]'::jsonb, 180, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m04-t04', 'zte-fullstack-v1-core-phase-05-m04', 'httpOnly Cookies', array['Explain and apply null in httpOnly Cookies.', 'Use httpOnly Cookies to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Setting cookies with the httpOnly flag — inaccessible to JavaScript, mitigating XSS-based token theft in a small working example.', 'Demonstrate Secure flag — cookie only sent over HTTPS in a small working example.', 'Demonstrate Cookie-based token flow in Express (res.cookie, reading from req.cookies) in a small working example.', 'Demonstrate CSRF implications of cookie-based auth — sets up SameSite (Topic 21) as part of the mitigation in a small working example.']::text[], array['Submit a working httpOnly Cookies example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m04-t03']::text[], '[]'::jsonb, 180, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m04-t05', 'zte-fullstack-v1-core-phase-05-m04', 'SameSite=Lax', array['Explain and apply null in SameSite=Lax.', 'Use SameSite=Lax to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate SameSite=Strict vs Lax vs None — what cross-site request scenarios each allows or blocks in a small working example.', 'Demonstrate Why Lax is the practical default for auth cookies (allows top-level navigation, blocks cross-site form/fetch requests) in a small working example.', 'Demonstrate SameSite as CSRF mitigation, completing the cookie security picture started in Topic 20 in a small working example.']::text[], array['Submit a working SameSite=Lax example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m04-t04']::text[], '[]'::jsonb, 60, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-05-m04-t06', 'zte-fullstack-v1-core-phase-05-m04', 'HMAC-SHA256', array['Explain and apply null in HMAC-SHA256.', 'Use HMAC-SHA256 to complete a practical task in Backend + Database + Auth.']::text[], array['Demonstrate Hash functions recap (SHA-256) vs keyed hash functions (HMAC) in a small working example.', 'Demonstrate Why a shared secret key changes a hash function into a message authentication code in a small working example.', 'Demonstrate HMAC''s role: proving a message wasn''t tampered with and came from someone holding the secret in a small working example.', 'Demonstrate Where this shows up directly in JWT''s HS256 signing (Topic 18) in a small working example.']::text[], array['Submit a working HMAC-SHA256 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Backend + Database + Auth learning goal.']::text[], array['zte-fullstack-v1-core-phase-05-m04-t05']::text[], '[]'::jsonb, 180, 'intermediate', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
