insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-m01-t07', 'zte-fullstack-v1-core-phase-06-m01', 'Playwright', array['Explain and apply Core Concepts in Playwright.', 'Explain and apply Writing Real E2E Flows in Playwright.', 'Explain and apply Tooling in Playwright.']::text[], array['Demonstrate Browser automation model — Playwright drives real browsers (Chromium, Firefox, WebKit) in a small working example.', 'Demonstrate page.goto(), locators, and Playwright''s auto-waiting (vs manual waits/sleeps) in a small working example.', 'Demonstrate Assertions with expect() in a Playwright context in a small working example.', 'Demonstrate Testing full user journeys: signup → login → core app action (ties directly to the JWT auth flow from Phase 05) in a small working example.', 'Demonstrate Handling authentication state across tests (storageState, reusing a logged-in session) in a small working example.']::text[], array['Submit a working Playwright example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-fullstack-v1-core-phase-06-m01-t06']::text[], '[]'::jsonb, 1080, 'intermediate', 6) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
