insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-m02-t04', 'zte-fullstack-v1-core-phase-06-m02', 'docker/build-push-action', array['Explain and apply null in docker/build-push-action.', 'Use docker/build-push-action to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate Configuring the action: context, tags, push conditions in a small working example.', 'Demonstrate Building and pushing on merge to main, not on every PR (deployment discipline) in a small working example.', 'Demonstrate Connecting this to a deployment trigger on Render (Stage 5) in a small working example.']::text[], array['Submit a working docker/build-push-action example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-fullstack-v1-core-phase-06-m02-t03']::text[], '[]'::jsonb, 120, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-06-m03', 'zte-fullstack-v1-core-phase-06', 3, 'Deployment & Exit A Polish', 'Deliberately last. Deployment needs a tested, containerized, CI-integrated app (Stages 1–4) to deploy. The CI badge (shields.io) is the final topic since it''s a status indicator for a pipeline that must already be working.', 6, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-m03-t01', 'zte-fullstack-v1-core-phase-06-m03', 'Render', array['Explain and apply null in Render.', 'Use Render to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate Connecting a GitHub repo or GHCR image to a Render service in a small working example.', 'Demonstrate Web Services vs Background Workers vs Static Sites on Render in a small working example.', 'Demonstrate Environment variables and secrets in Render''s dashboard in a small working example.', 'Demonstrate Auto-deploy on push vs manual deploys in a small working example.', 'Demonstrate Health checks — Render''s mechanism for verifying a deploy succeeded before routing traffic to it in a small working example.']::text[], array['Submit a working Render example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
