insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-m03-t03', 'zte-fullstack-v1-core-phase-06-m03', 'HTTP/2', array['Explain and apply null in HTTP/2.', 'Use HTTP/2 to complete a practical task in Testing + CI/CD + Deployment.']::text[], array['Demonstrate HTTP/1.1 limitations HTTP/2 addresses: head-of-line blocking, connection overhead in a small working example.', 'Demonstrate Multiplexing — multiple requests over a single connection in a small working example.', 'Demonstrate Server push (concept, largely deprecated in practice) and header compression (HPACK) in a small working example.', 'Demonstrate How this relates to what Render/Vercel (Phase 02) provide automatically — usually nothing to configure manually, but worth understanding what''s happening in a small working example.']::text[], array['Submit a working HTTP/2 example and explain the key decisions.', 'Record a short review showing how the example satisfies the Testing + CI/CD + Deployment learning goal.']::text[], array['zte-fullstack-v1-core-phase-06-m03-t02']::text[], '[]'::jsonb, 120, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-01', 'zte-fullstack-v1-core-phase-06', 'Fully-Tested Utility Library', 'Take a utility library from an earlier phase and bring it to 100% meaningful coverage with Vitest, including edge cases, with a coverage report published via Codecov. Domain: dev tooling.', array['Deliver the working outcome described in the Fully-Tested Utility Library brief.', 'Use at least two skills from Unit & Component Testing and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Fully-Tested Utility Library', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Unit & Component Testing and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-02', 'zte-fullstack-v1-core-phase-06', 'Mocked API Component Test Suite', 'A React component suite (forms, data tables) tested with React Testing Library + @testing-library/user-event for realistic interactions, and MSW to mock network requests so tests never hit a real backend. Domain: frontend QA.', array['Deliver the working outcome described in the Mocked API Component Test Suite brief.', 'Use at least two skills from Unit & Component Testing and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Mocked API Component Test Suite', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Unit & Component Testing and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-03', 'zte-fullstack-v1-core-phase-06', 'Regression-Proof Checkout Flow Tests', 'A full test suite for a multi-step checkout component (from Phase 4’s state machine work) covering every state transition, error path, and MSW-simulated payment failure, with coverage thresholds enforced in CI and tracked over time in Codecov. Domain: e-commerce QA engineering.', array['Deliver the working outcome described in the Regression-Proof Checkout Flow Tests brief.', 'Use at least two skills from Unit & Component Testing and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Regression-Proof Checkout Flow Tests', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Unit & Component Testing and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration and End-to-End Testing and Continuous Integration']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-04', 'zte-fullstack-v1-core-phase-06', 'Critical User Journey E2E Suite', 'Playwright tests covering the 3 most critical user journeys of any earlier full-stack project (signup → login → core action), running against a real (test) database. Domain: QA engineering.', array['Deliver the working outcome described in the Critical User Journey E2E Suite brief.', 'Use at least two skills from End-to-End Testing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Critical User Journey E2E Suite', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'End-to-End Testing']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-05', 'zte-fullstack-v1-core-phase-06', 'Cross-Browser Visual Regression Suite', 'Playwright tests that run across Chromium, Firefox, and WebKit, include visual snapshot comparisons for key pages, and are wired to fail CI on unexpected visual diffs. Domain: QA / design systems.', array['Deliver the working outcome described in the Cross-Browser Visual Regression Suite brief.', 'Use at least two skills from End-to-End Testing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cross-Browser Visual Regression Suite', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'End-to-End Testing']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-06', 'zte-fullstack-v1-core-phase-06', 'Matrix-Tested Cross-Version CI', 'A CI workflow using a build matrix to test a library across multiple Node.js versions and operating systems simultaneously, with a status badge reflecting real pass/fail state. Domain: open-source maintenance / library engineering.', array['Deliver the working outcome described in the Matrix-Tested Cross-Version CI brief.', 'Use at least two skills from Continuous Integration.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Matrix-Tested Cross-Version CI', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Continuous Integration']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-07', 'zte-fullstack-v1-core-phase-06', 'Multi-Stage Dockerized Full-Stack App', 'Dockerize a full-stack app (Phase 5 backend + a frontend build) using multi-stage builds to keep the final image small, with a documented image-size before/after comparison. Domain: DevOps.', array['Deliver the working outcome described in the Multi-Stage Dockerized Full-Stack App brief.', 'Use at least two skills from Containerization.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Multi-Stage Dockerized Full-Stack App', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Containerization']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-08', 'zte-fullstack-v1-core-phase-06', 'Local Dev Environment via Docker Compose', 'A docker-compose.yml that spins up the app, a Postgres database, and Redis together with one command, including healthchecks and proper service dependency ordering. Domain: developer experience / infra.', array['Deliver the working outcome described in the Local Dev Environment via Docker Compose brief.', 'Use at least two skills from Containerization.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Local Dev Environment via Docker Compose', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Containerization']::text[], 'intermediate', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-09', 'zte-fullstack-v1-core-phase-06', 'Automated Image Publishing Pipeline', 'A GitHub Actions workflow using docker/build-push-action to build and publish a versioned, tagged image to GitHub Container Registry on every merge to main, including a documented rollback procedure using a previous tag. Domain: DevOps / release engineering.', array['Deliver the working outcome described in the Automated Image Publishing Pipeline brief.', 'Use at least two skills from Containerization.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Automated Image Publishing Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Containerization']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-10', 'zte-fullstack-v1-core-phase-06', 'HTTP/2 Performance Verification', 'Deploy the same app behind both HTTP/1.1 and HTTP/2 configurations (or verify Render’s default) and document real measured differences in multiplexed asset loading via browser waterfall charts. Domain: web performance / infra.', array['Deliver the working outcome described in the HTTP/2 Performance Verification brief.', 'Use at least two skills from Deployment & Exit A Polish.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working HTTP/2 Performance Verification', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'Deployment & Exit A Polish']::text[], 'intermediate', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06-project-11', 'zte-fullstack-v1-core-phase-06', 'A Fully CI/CD-Automated, Containerized SaaS Deployment Pipeline', 'Take any earlier full-stack project (Phase 5’s "Ledger" is a good candidate) and build the complete professional delivery pipeline around it: Vitest \+ React Testing Library \+ MSW unit/component coverage with enforced thresholds, a Playwright E2E suite covering critical journeys across 3 browsers with visual regression checks, a multi-stage Dockerfile and docker-compose local dev environment, a full GitHub Actions pipeline (parallel lint/typecheck/test/E2E jobs, matrix-tested, cached, auto-publishing tagged images to GHCR on merge), and a live production deployment on Render with real status/coverage badges in the README. Domain: DevOps / release engineering. Why it matters: this is the artifact that proves you can ship software professionally, not just write it — the single most common gap between bootcamp-level and production-level engineers.', array['Deliver the working outcome described in the A Fully CI/CD-Automated, Containerized SaaS Deployment Pipeline brief.', 'Use at least two skills from Testing + CI/CD + Deployment.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Fully CI/CD-Automated, Containerized SaaS Deployment Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Testing + CI/CD + Deployment', 'engineering documentation']::text[], 'advanced', 10) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
