insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-06b-m01', 'zte-fullstack-v1-core-phase-06b', 1, 'React Native Foundation', 'Requires React (Phase 02\\) as a direct prerequisite — React Native uses the same component/hooks model, with a different rendering target (native views instead of the DOM).', 16, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m01-t01', 'zte-fullstack-v1-core-phase-06b-m01', 'React Native Fundamentals', array['Explain and apply Core Model in React Native Fundamentals.', 'Explain and apply Touch & Interaction in React Native Fundamentals.', 'Explain and apply Lists & Scrolling in React Native Fundamentals.']::text[], array['Demonstrate Native components (View, Text, Image, ScrollView) as RN''s equivalent to HTML elements in a small working example.', 'Demonstrate Why there''s no DOM — RN renders to native platform views, not a browser in a small working example.', 'Demonstrate StyleSheet API — CSS-like styling, but a real subset of CSS properties, not the full web spec in a small working example.', 'Demonstrate Same React mental model: components, props, state, hooks all transfer directly from Phase 02 in a small working example.', 'Demonstrate Touchable components (Pressable, TouchableOpacity) — RN''s equivalent to onClick handlers in a small working example.']::text[], array['Submit a working React Native Fundamentals example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m01-t02', 'zte-fullstack-v1-core-phase-06b-m01', 'Expo + EAS Build', array['Explain and apply null in Expo + EAS Build.', 'Use Expo + EAS Build to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate Expo managed workflow vs bare React Native — why Expo is the recommended starting point in a small working example.', 'Demonstrate Expo Go — running an app on a physical device instantly during development in a small working example.', 'Demonstrate EAS Build — cloud-based native builds without needing local Xcode/Android Studio setup in a small working example.', 'Demonstrate expo-cli commands for scaffolding and running a project in a small working example.', 'Demonstrate app.json/app.config.js — app metadata, icons, splash screens in a small working example.']::text[], array['Submit a working Expo + EAS Build example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m01-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m01-t03', 'zte-fullstack-v1-core-phase-06b-m01', 'React Navigation', array['Explain and apply null in React Navigation.', 'Use React Navigation to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate Stack navigator — push/pop screen transitions in a small working example.', 'Demonstrate Tab navigator, drawer navigator in a small working example.', 'Demonstrate Passing params between screens in a small working example.', 'Demonstrate Deep linking (conceptual — connecting a URL scheme to a specific screen) in a small working example.', 'Demonstrate Contrasting with Phase 02''s file-based App Router — RN navigation is configured, not file-system-driven in a small working example.']::text[], array['Submit a working React Navigation example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m01-t02']::text[], '[]'::jsonb, 60, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m01-t04', 'zte-fullstack-v1-core-phase-06b-m01', 'Flexbox Layout Differences (RN vs Web)', array['Explain and apply null in Flexbox Layout Differences (RN vs Web).', 'Use Flexbox Layout Differences (RN vs Web) to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate Default flexDirection: column in RN (vs row on web) — the single most common source of layout confusion for web developers in a small working example.', 'Demonstrate Which CSS properties don''t exist in RN (no CSS Grid, no float, limited selector model) in a small working example.', 'Demonstrate Percentage-based vs flex-based sizing in RN in a small working example.', 'Demonstrate Platform differences in flexbox behavior between iOS and Android (minor but real) in a small working example.']::text[], array['Submit a working Flexbox Layout Differences (RN vs Web) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m01-t03']::text[], '[]'::jsonb, 60, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-06b-m02', 'zte-fullstack-v1-core-phase-06b', 2, 'Storage & Secure Token Handling', 'Requires RN fundamentals and navigation (Stage 1\\) — a real app with multiple screens is what makes persistent storage meaningful.', 6, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m02-t01', 'zte-fullstack-v1-core-phase-06b-m02', 'AsyncStorage + Offline-First Sync', array['Explain and apply null in AsyncStorage + Offline-First Sync.', 'Use AsyncStorage + Offline-First Sync to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate AsyncStorage API — get/set/remove, all promise-based in a small working example.', 'Demonstrate Why RN has no synchronous storage equivalent to web''s localStorage in a small working example.', 'Demonstrate Offline-first architecture — queuing writes locally when offline, syncing when connectivity returns in a small working example.', 'Demonstrate Conflict resolution strategies for offline sync (last-write-wins vs merge strategies) in a small working example.', 'Demonstrate Connecting offline sync to the TanStack Query patterns from Phase 04 — persisting query cache for offline access in a small working example.']::text[], array['Submit a working AsyncStorage + Offline-First Sync example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m02-t02', 'zte-fullstack-v1-core-phase-06b-m02', 'expo-secure-store', array['Explain and apply null in expo-secure-store.', 'Use expo-secure-store to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate Why AsyncStorage is unencrypted and unsuitable for tokens — the specific gap this fills in a small working example.', 'Demonstrate Platform-backed secure storage (Keychain on iOS, Keystore on Android) in a small working example.', 'Demonstrate Storing JWT access/refresh tokens (Phase 05) securely on-device in a small working example.', 'Demonstrate API parity with AsyncStorage but with encryption guarantees in a small working example.']::text[], array['Submit a working expo-secure-store example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m02-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-06b-m03', 'zte-fullstack-v1-core-phase-06b', 3, 'Native Device Capabilities', 'Requires Expo (Stage 1, Topic 2\\) — most native capabilities are exposed through Expo''s SDK modules.', 8, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m03-t01', 'zte-fullstack-v1-core-phase-06b-m03', 'Native APIs (Camera, Push, Permissions)', array['Explain and apply Permissions Model in Native APIs (Camera, Push, Permissions).', 'Explain and apply Camera in Native APIs (Camera, Push, Permissions).', 'Explain and apply Push Notifications in Native APIs (Camera, Push, Permissions).']::text[], array['Demonstrate Requesting permissions at runtime (camera, notifications, location) in a small working example.', 'Demonstrate Handling permission denial gracefully — a required UX pattern, not optional in a small working example.', 'Demonstrate expo-camera — capturing photos/video in a small working example.', 'Demonstrate Common use case: document/ID capture for onboarding flows (ties to ClientSync''s onboarding domain) in a small working example.', 'Demonstrate Expo push notification service — registering a device token in a small working example.']::text[], array['Submit a working Native APIs (Camera, Push, Permissions) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m03-t02', 'zte-fullstack-v1-core-phase-06b-m03', 'Platform-Specific Code (iOS vs Android)', array['Explain and apply null in Platform-Specific Code (iOS vs Android).', 'Use Platform-Specific Code (iOS vs Android) to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate Platform.OS and Platform.select() for conditional logic in a small working example.', 'Demonstrate File naming conventions for platform-specific implementations (.ios.tsx, .android.tsx) in a small working example.', 'Demonstrate Common divergences: safe area handling, status bar behavior, back button handling on Android in a small working example.']::text[], array['Submit a working Platform-Specific Code (iOS vs Android) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m03-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
