insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m04-t01', 'zte-fullstack-v1-core-phase-06b-m04', 'FlatList Performance + Virtualization', array['Explain and apply null in FlatList Performance + Virtualization.', 'Use FlatList Performance + Virtualization to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate getItemLayout for fixed-height items — skipping expensive layout measurement in a small working example.', 'Demonstrate keyExtractor and why stable keys matter as much here as in web React (Phase 02) in a small working example.', 'Demonstrate windowSize, initialNumToRender, maxToRenderPerBatch — tuning virtualization aggressiveness in a small working example.', 'Demonstrate When to reach for a dedicated virtualization library vs FlatList''s built-in behavior in a small working example.']::text[], array['Submit a working FlatList Performance + Virtualization example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m04-t02', 'zte-fullstack-v1-core-phase-06b-m04', 'Hermes Engine', array['Explain and apply null in Hermes Engine.', 'Use Hermes Engine to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate What Hermes is — a JS engine built specifically for React Native (vs JavaScriptCore) in a small working example.', 'Demonstrate Bytecode precompilation — why this improves app startup time in a small working example.', 'Demonstrate Enabling/verifying Hermes is active in a project in a small working example.']::text[], array['Submit a working Hermes Engine example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m04-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m04-t03', 'zte-fullstack-v1-core-phase-06b-m04', 'New Architecture (Fabric + TurboModules)', array['Explain and apply null in New Architecture (Fabric + TurboModules).', 'Use New Architecture (Fabric + TurboModules) to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate The old bridge architecture and its performance limitations (async, serialized JSON messaging) in a small working example.', 'Demonstrate Fabric — the new rendering system, enabling synchronous layout measurement in a small working example.', 'Demonstrate TurboModules — lazy-loaded native modules with direct JS-to-native calls, replacing the bridge in a small working example.', 'Demonstrate Practical implication: most apps don''t need to think about this directly, but library compatibility increasingly assumes it in a small working example.']::text[], array['Submit a working New Architecture (Fabric + TurboModules) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m04-t02']::text[], '[]'::jsonb, 60, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-06b-m05', 'zte-fullstack-v1-core-phase-06b', 5, 'Shipping', 'Deliberately last. Requires a working, tested app (Stages 1–4) and EAS Build (Stage 1, Topic 2\\) as the build pipeline that makes submission possible.', 8, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m05-t01', 'zte-fullstack-v1-core-phase-06b-m05', 'App Store + Play Store Submission', array['Explain and apply Preparing for Submission in App Store + Play Store Submission.', 'Explain and apply Submission Process in App Store + Play Store Submission.']::text[], array['Demonstrate App signing — certificates and provisioning profiles (iOS), keystores (Android) in a small working example.', 'Demonstrate App Store Connect setup, Google Play Console setup in a small working example.', 'Demonstrate Required assets: icons, screenshots, privacy policy, app description in a small working example.', 'Demonstrate Building a production binary with EAS Build (Stage 1, Topic 2) in a small working example.', 'Demonstrate Submitting via EAS Submit or manual upload in a small working example.']::text[], array['Submit a working App Store + Play Store Submission example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-m05-t02', 'zte-fullstack-v1-core-phase-06b-m05', 'EAS Update (OTA Updates)', array['Explain and apply null in EAS Update (OTA Updates).', 'Use EAS Update (OTA Updates) to complete a practical task in React Native (Mobile).']::text[], array['Demonstrate What EAS Update enables — pushing JS/asset changes without a full app store review cycle in a small working example.', 'Demonstrate What CANNOT be updated OTA — native code changes still require a full resubmission in a small working example.', 'Demonstrate Update channels — staging vs production update tracks in a small working example.', 'Demonstrate Rollback strategy if a bad update ships in a small working example.']::text[], array['Submit a working EAS Update (OTA Updates) example and explain the key decisions.', 'Record a short review showing how the example satisfies the React Native (Mobile) learning goal.']::text[], array['zte-fullstack-v1-core-phase-06b-m05-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-01', 'zte-fullstack-v1-core-phase-06b', 'Cross-Platform Habit Tracker', 'Rebuild Phase 2’s habit tracker as a React Native + Expo app, documenting layout differences (Flexbox defaults differ from web) and navigation using React Navigation (stack + tabs). Domain: personal wellness / mobile.', array['Deliver the working outcome described in the Cross-Platform Habit Tracker brief.', 'Use at least two skills from React Native Foundation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cross-Platform Habit Tracker', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'React Native Foundation']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-02', 'zte-fullstack-v1-core-phase-06b', 'Recipe Browser with Deep Linking', 'A recipe browsing app with nested navigation (stack inside tabs), deep linking support (opening a specific recipe from a shared URL), and platform-aware layout adjustments for notches/safe areas. Domain: lifestyle/food.', array['Deliver the working outcome described in the Recipe Browser with Deep Linking brief.', 'Use at least two skills from React Native Foundation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Recipe Browser with Deep Linking', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'React Native Foundation']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-03', 'zte-fullstack-v1-core-phase-06b', 'EAS-Built Multi-Environment App', 'An app configured with separate dev/staging/production build profiles via EAS Build, each pointing to a different API environment, with a documented build-and-distribute workflow for internal testers. Domain: mobile release engineering.', array['Deliver the working outcome described in the EAS-Built Multi-Environment App brief.', 'Use at least two skills from React Native Foundation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working EAS-Built Multi-Environment App', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'React Native Foundation']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-04', 'zte-fullstack-v1-core-phase-06b', 'Offline-First Grocery List', 'A grocery list app that works fully offline using AsyncStorage, queues changes made offline, and syncs to a backend when connectivity returns, with conflict resolution for simultaneous edits. Domain: productivity / offline-first apps. A mobile login flow storing tokens in expo-secure-store (not AsyncStorage) with biometric-gated access to sensitive actions, and a documented threat-model comparison of AsyncStorage vs. secure-store. Domain: mobile security.', array['Deliver the working outcome described in the Offline-First Grocery List brief.', 'Use at least two skills from Storage & Secure Token Handling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Offline-First Grocery List', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Storage & Secure Token Handling']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-05', 'zte-fullstack-v1-core-phase-06b', 'Receipt Scanner Utility', 'An app using the camera API to photograph receipts, request the correct permissions gracefully (with a fallback UI if denied), and save images locally. Domain: personal finance / utility apps. A reminders app sending real push notifications (via Expo push service) with platform-specific permission flows for iOS vs Android documented and handled distinctly. Domain: productivity.', array['Deliver the working outcome described in the Receipt Scanner Utility brief.', 'Use at least two skills from Native Device Capabilities.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Receipt Scanner Utility', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Native Device Capabilities']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-06', 'zte-fullstack-v1-core-phase-06b', '10,000-Item Contact List', 'A contacts app rendering a very large list using FlatList performance best practices (getItemLayout, windowing tuning) profiled before/after optimization. Domain: productivity / performance engineering.', array['Deliver the working outcome described in the 10,000-Item Contact List brief.', 'Use at least two skills from Performance & Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working 10,000-Item Contact List', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Performance & Internals']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-07', 'zte-fullstack-v1-core-phase-06b', 'Hermes vs JSC Benchmark Report', 'Build a CPU-intensive screen (e.g., client-side image filtering) and benchmark its performance under the Hermes engine vs JSC, documenting startup time and runtime differences with real numbers. Domain: mobile performance engineering.', array['Deliver the working outcome described in the Hermes vs JSC Benchmark Report brief.', 'Use at least two skills from Performance & Internals.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Hermes vs JSC Benchmark Report', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Performance & Internals']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-08', 'zte-fullstack-v1-core-phase-06b', 'Zero-Downtime OTA Update Demo', 'Ship a bug fix to a live-installed app using EAS Update (over-the-air) without requiring users to redownload from the store, with a before/after demonstration and a documented rollback plan if the OTA update itself is broken. Domain: mobile release engineering.', array['Deliver the working outcome described in the Zero-Downtime OTA Update Demo brief.', 'Use at least two skills from Shipping.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Zero-Downtime OTA Update Demo', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'Shipping']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-06b-project-09', 'zte-fullstack-v1-core-phase-06b', 'An Offline-First Field Reporting App', 'A mobile app for field workers (e.g., inspectors, delivery drivers) who often lack connectivity: photo capture with camera permissions handled gracefully, offline-first data entry via AsyncStorage with a sync queue and conflict resolution on reconnect, secure token storage via expo-secure-store, push notifications for assignment updates, a FlatList-based large history view tuned for performance, multi-environment EAS build profiles, and a full store-submission-ready asset package plus at least one OTA update shipped to a test build. Domain: field service / logistics mobile tooling. Why it matters: offline-first, secure, store-ready mobile apps are a distinct and valuable skill set from web development — this proves end-to-end mobile shipping competence.', array['Deliver the working outcome described in the An Offline-First Field Reporting App brief.', 'Use at least two skills from React Native (Mobile).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working An Offline-First Field Reporting App', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['React Native (Mobile)', 'engineering documentation']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-fullstack-v1-core-phase-07', 'zte-fullstack-v1', id, '09', 'API Documentation & Developer Tooling', 'Core', 'Requires a real API to hit (Phase 05\\) — these tools exist to inspect, test, and debug HTTP requests/responses by hand, before any documentation layer is added on top.', 71, 8 from public.roadmap_versions where roadmap_id='zte-fullstack-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-07-m01', 'zte-fullstack-v1-core-phase-07', 1, 'Manual HTTP Tooling', 'Requires a real API to hit (Phase 05\\) — these tools exist to inspect, test, and debug HTTP requests/responses by hand, before any documentation layer is added on top.', 6, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-m01-t01', 'zte-fullstack-v1-core-phase-07-m01', 'Postman', array['Explain and apply null in Postman.', 'Use Postman to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Building and sending requests — the GUI equivalent of curl''s flags in a small working example.', 'Demonstrate Collections — organizing related requests together in a small working example.', 'Demonstrate Environments and variables — swapping base URLs/tokens between dev/staging/prod without editing every request in a small working example.', 'Demonstrate Scripting: pre-request scripts and tests (JavaScript) for automated checks on responses in a small working example.', 'Demonstrate Exporting a Postman collection — this is the literal artifact Exit B''s checklist wants linked in your README in a small working example.']::text[], array['Submit a working Postman example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-m01-t02', 'zte-fullstack-v1-core-phase-07-m01', 'Insomnia', array['Explain and apply null in Insomnia.', 'Use Insomnia to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Core workflow parity with Postman — requests, environments, collections (called "workspaces") in a small working example.', 'Demonstrate Where Insomnia differs: simpler interface, native GraphQL support (foreshadows Stage 3) in a small working example.', 'Demonstrate When to reach for Insomnia over Postman — personal/lightweight use vs Postman''s team-collaboration features in a small working example.']::text[], array['Submit a working Insomnia example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-fullstack-v1-core-phase-07-m01-t01']::text[], '[]'::jsonb, 60, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-m01-t03', 'zte-fullstack-v1-core-phase-07-m01', 'curl', array['Explain and apply null in curl.', 'Use curl to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Basic syntax — curl <url>, -X for method, -H for headers, -d for body in a small working example.', 'Demonstrate Sending JSON payloads (-H "Content-Type: application/json" -d ''{...}'') in a small working example.', 'Demonstrate Inspecting response headers (-i, -I) and verbose output (-v) for debugging in a small working example.', 'Demonstrate Authentication — sending a Bearer token (ties back to Phase 05''s JWT), Basic auth in a small working example.', 'Demonstrate Saving/loading cookies (-c, -b) — relevant given Phase 05''s httpOnly cookie auth flow in a small working example.']::text[], array['Submit a working curl example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-fullstack-v1-core-phase-07-m01-t02']::text[], '[]'::jsonb, 180, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-07-m02', 'zte-fullstack-v1-core-phase-07', 2, 'API Documentation and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm)', 'Requires a real, stable API (Phase 05\\) and familiarity with inspecting requests/responses (Stage 1\\) — you can''t document an API accurately without having manually explored its behavior first.', 9, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-m02-t01', 'zte-fullstack-v1-core-phase-07-m02', 'OpenAPI 3.0', array['Explain and apply Specification Fundamentals in OpenAPI 3.0.', 'Explain and apply Writing a Real Spec in OpenAPI 3.0.']::text[], array['Demonstrate The OpenAPI spec as a language-agnostic contract for describing a REST API in a small working example.', 'Demonstrate Structure: paths, operations, parameters, requestBody, responses in a small working example.', 'Demonstrate Schema objects — describing request/response shapes (conceptually parallel to the Zod schemas from Phases 01/03/05) in a small working example.', 'Demonstrate Reusable components — $ref for shared schemas, parameters, responses in a small working example.', 'Demonstrate Documenting authentication (JWT Bearer scheme, ties to Phase 05) in a small working example.']::text[], array['Submit a working OpenAPI 3.0 example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array[]::text[], '[]'::jsonb, 720, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-m02-t02', 'zte-fullstack-v1-core-phase-07-m02', 'Swagger UI', array['Explain and apply null in Swagger UI.', 'Use Swagger UI to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Serving Swagger UI from your API (as a route, e.g. /docs) in a small working example.', 'Demonstrate Interactive "Try it out" — making real requests from the docs page itself in a small working example.', 'Demonstrate Why a live Swagger UI link (not a screenshot) is what Exit B''s checklist specifically wants in your portfolio in a small working example.', 'Demonstrate Customizing Swagger UI branding/appearance (minor, but relevant for portfolio polish) in a small working example.']::text[], array['Submit a working Swagger UI example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-fullstack-v1-core-phase-07-m02-t01']::text[], '[]'::jsonb, 240, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-m02-t03', 'zte-fullstack-v1-core-phase-07-m02', 'Mermaid', array['Explain and apply null in Mermaid.', 'Use Mermaid to complete a practical task in API Documentation & Developer Tooling.']::text[], array['Demonstrate Mermaid syntax basics — flowcharts, sequence diagrams, ER diagrams in a small working example.', 'Demonstrate Sequence diagrams for documenting an auth flow (login → JWT issuance → protected route, ties to Phase 05) in a small working example.', 'Demonstrate ER diagrams for documenting a database schema (ties to Phase 05''s PostgreSQL/Prisma schema) in a small working example.', 'Demonstrate Rendering Mermaid directly in GitHub READMEs — no external tooling needed in a small working example.']::text[], array['Submit a working Mermaid example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-fullstack-v1-core-phase-07-m02-t02']::text[], '[]'::jsonb, 120, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-m02-t04', 'zte-fullstack-v1-core-phase-07-m02', 'GraphQL', array['Explain and apply Core Concepts in GraphQL.', 'Explain and apply Building a GraphQL API in GraphQL.', 'Explain and apply Client-Side GraphQL in GraphQL.', 'Explain and apply REST vs GraphQL — The Interview-Ready Comparison in GraphQL.']::text[], array['Demonstrate Single endpoint, client-specified queries — the central contrast with REST''s multiple resource endpoints in a small working example.', 'Demonstrate Schema Definition Language (SDL) — types, queries, mutations, resolvers in a small working example.', 'Demonstrate Over-fetching and under-fetching — the specific REST pain points GraphQL addresses in a small working example.', 'Demonstrate N+1 query problem in GraphQL resolvers (ties back to the same problem flagged for Prisma in Phase 05) and DataLoader as the standard fix in a small working example.', 'Demonstrate Defining a schema — types, Query, Mutation root types in a small working example.']::text[], array['Submit a working GraphQL example and explain the key decisions.', 'Record a short review showing how the example satisfies the API Documentation & Developer Tooling learning goal.']::text[], array['zte-fullstack-v1-core-phase-07-m02-t03']::text[], '[]'::jsonb, 1560, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-01', 'zte-fullstack-v1-core-phase-07', 'Zero-GUI API Debugging Toolkit', 'A personal collection of curl scripts (with a Makefile or shell aliases) that fully exercise every endpoint of an earlier project’s API, usable by teammates with no GUI tool installed. Domain: developer tooling.', array['Deliver the working outcome described in the Zero-GUI API Debugging Toolkit brief.', 'Use at least two skills from Manual HTTP Tooling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Zero-GUI API Debugging Toolkit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'Manual HTTP Tooling']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-02', 'zte-fullstack-v1-core-phase-07', 'Shared Postman Collection with Environments', 'A Postman collection for a full-stack project with dev/staging/prod environments, pre-request scripts for auth token refresh, and automated test assertions per request, exported and version-controlled alongside the code. Domain: API QA/tooling.', array['Deliver the working outcome described in the Shared Postman Collection with Environments brief.', 'Use at least two skills from Manual HTTP Tooling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Shared Postman Collection with Environments', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'Manual HTTP Tooling']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-03', 'zte-fullstack-v1-core-phase-07', 'Auto-Generated OpenAPI Docs Site', 'Write a complete OpenAPI 3.0 spec for an earlier project’s API by hand, render it with Swagger UI, and verify every documented example actually matches real API behavior (no doc drift). Domain: API developer experience.', array['Deliver the working outcome described in the Auto-Generated OpenAPI Docs Site brief.', 'Use at least two skills from API Documentation and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Auto-Generated OpenAPI Docs Site', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'API Documentation and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm)']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-04', 'zte-fullstack-v1-core-phase-07', 'Architecture Diagrams as Code', 'Document a full-stack project’s system architecture (request flow, database relationships, deployment topology) entirely using Mermaid diagrams embedded in markdown, version-controlled alongside the code. Domain: technical documentation / architecture.', array['Deliver the working outcome described in the Architecture Diagrams as Code brief.', 'Use at least two skills from API Documentation and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Architecture Diagrams as Code', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'API Documentation and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm)']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-05', 'zte-fullstack-v1-core-phase-07', 'Public-Facing Developer Portal', 'A polished, standalone documentation site for a public API combining OpenAPI-generated Swagger UI, hand-written getting-started guides, and Mermaid sequence diagrams showing common integration flows (e.g., OAuth handshake). Domain: developer relations / API products.', array['Deliver the working outcome described in the Public-Facing Developer Portal brief.', 'Use at least two skills from API Documentation and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Public-Facing Developer Portal', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'API Documentation and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm) and GraphQL (Alternative API Paradigm)']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-06', 'zte-fullstack-v1-core-phase-07', 'Blog GraphQL API', 'A GraphQL API (posts, authors, comments) with proper resolver structure, demonstrating the N+1 problem occurring naturally, then fixed with DataLoader-style batching. Domain: publishing/content. Implement the identical feature (a nested product/reviews/author data fetch) as both a REST endpoint and a GraphQL query, measuring over-fetching/under-fetching and request-count differences with real network data, and write a decision-framework document for when to choose each. Domain: API architecture.', array['Deliver the working outcome described in the Blog GraphQL API brief.', 'Use at least two skills from GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Blog GraphQL API', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'GraphQL (Alternative API Paradigm)']::text[], 'intermediate', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-07', 'zte-fullstack-v1-core-phase-07', 'Federated Multi-Service GraphQL Gateway', 'Split a schema across 2 independent services (e.g., Users service and Orders service) and compose them behind a single gateway, demonstrating schema federation concepts. Domain: microservices/API architecture.', array['Deliver the working outcome described in the Federated Multi-Service GraphQL Gateway brief.', 'Use at least two skills from GraphQL (Alternative API Paradigm).', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Federated Multi-Service GraphQL Gateway', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'GraphQL (Alternative API Paradigm)']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-07-project-08', 'zte-fullstack-v1-core-phase-07', 'A Fully Documented, Dual-Paradigm Public API Product', 'Take an existing backend (Phase 5’s "Ledger" works well) and ship it as a genuine API product: a complete hand-written OpenAPI 3.0 spec rendered via Swagger UI, Mermaid-diagrammed architecture and auth-flow documentation, a parallel GraphQL interface over the same data exposing at least one N+1-fixed resolver, a curated Postman collection with environments and auto-refreshing auth, and a written REST-vs-GraphQL decision document explaining which consumers should use which interface and why. Domain: developer platforms / API products. Why it matters: documenting and exposing an API well is a distinct, high-value skill from building it — this proves you can make your work usable by other engineers, not just functional.', array['Deliver the working outcome described in the A Fully Documented, Dual-Paradigm Public API Product brief.', 'Use at least two skills from API Documentation & Developer Tooling.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Fully Documented, Dual-Paradigm Public API Product', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['API Documentation & Developer Tooling', 'engineering documentation']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-fullstack-v1-core-phase-08', 'zte-fullstack-v1', id, '10', 'DSA & Interview Preparation', 'Core', 'The simplest pattern family — each operates directly on arrays/strings using nothing but the loop and indexing fundamentals from Phase 01\. No data structure beyond an array is required.', 331, 9 from public.roadmap_versions where roadmap_id='zte-fullstack-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-08-m01', 'zte-fullstack-v1-core-phase-08', 1, 'Array & String Scanning Techniques and Hashing and Hashing and Hashing', 'The simplest pattern family — each operates directly on arrays/strings using nothing but the loop and indexing fundamentals from Phase 01\. No data structure beyond an array is required.', 14, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m01-t01', 'zte-fullstack-v1-core-phase-08-m01', 'Two Pointers', array['Explain and apply null in Two Pointers.', 'Use Two Pointers to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate The pattern: two indices moving through a structure, either toward each other or in the same direction in a small working example.', 'Demonstrate Classic problems: pair sum in a sorted array, reversing in place, removing duplicates in place in a small working example.', 'Demonstrate Recognizing when a problem is a two-pointer candidate: sorted or orderable data, looking for pairs/triplets in a small working example.']::text[], array['Submit a working Two Pointers example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 1080, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m01-t02', 'zte-fullstack-v1-core-phase-08-m01', 'Sliding Window', array['Explain and apply null in Sliding Window.', 'Use Sliding Window to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Fixed-size window vs variable-size (expand/shrink) window in a small working example.', 'Demonstrate Classic problems: longest substring without repeating characters, maximum sum subarray of size k in a small working example.', 'Demonstrate Recognizing sliding window candidates: contiguous subarray/substring problems with a size or condition constraint in a small working example.']::text[], array['Submit a working Sliding Window example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m01-t01']::text[], '[]'::jsonb, 1080, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m01-t03', 'zte-fullstack-v1-core-phase-08-m01', 'Binary Search', array['Explain and apply null in Binary Search.', 'Use Binary Search to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Classic binary search — search space, mid calculation, avoiding overflow/off-by-one errors in a small working example.', 'Demonstrate Binary search on answer — a common advanced pattern where the search space isn''t the array itself but a range of possible answers in a small working example.', 'Demonstrate Recognizing binary search candidates: sorted data, or a monotonic condition that lets you eliminate half the search space in a small working example.']::text[], array['Submit a working Binary Search example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m01-t02']::text[], '[]'::jsonb, 1080, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m01-t04', 'zte-fullstack-v1-core-phase-08-m01', 'HashMap / Frequency Count Patterns', array['Explain and apply null in HashMap / Frequency Count Patterns.', 'Use HashMap / Frequency Count Patterns to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Using a hash map to achieve O(n) where a naive approach would be O(n²) — the single most common optimization pattern in interviews in a small working example.', 'Demonstrate Frequency counting — character/element counts for anagram, majority element, and grouping problems in a small working example.', 'Demonstrate Combining hashing with two pointers/sliding window (Stage 1) — e.g. tracking window contents in a hash map while sliding in a small working example.', 'Demonstrate Set vs Map — when you only need existence checks vs when you need counts/associated values in a small working example.']::text[], array['Submit a working HashMap / Frequency Count Patterns example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m01-t03']::text[], '[]'::jsonb, 900, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m01-t05', 'zte-fullstack-v1-core-phase-08-m01', 'Kadane''s Algorithm', array['Explain and apply null in Kadane''s Algorithm.', 'Use Kadane''s Algorithm to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Maximum subarray sum — the canonical Kadane''s problem in a small working example.', 'Demonstrate The core insight: at each position, either extend the previous subarray or start fresh in a small working example.', 'Demonstrate Why this is DP in miniature — one state variable, one transition — worth recognizing explicitly before Stage 6 introduces DP formally in a small working example.']::text[], array['Submit a working Kadane''s Algorithm example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m01-t04']::text[], '[]'::jsonb, 300, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-08-m02', 'zte-fullstack-v1-core-phase-08', 2, 'Linear Structures: Stack & Queue', 'Both structures are prerequisites for Stage 4''s traversal algorithms — DFS is naturally expressed with a stack (or recursion, which uses the call stack implicitly), BFS requires a queue. This stage must come before Stage 4\.', 9, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m02-t01', 'zte-fullstack-v1-core-phase-08-m02', 'Stack Patterns', array['Explain and apply null in Stack Patterns.', 'Use Stack Patterns to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate LIFO mechanics and where a stack beats an array for a given problem in a small working example.', 'Demonstrate Classic problems: valid parentheses matching, evaluating expressions, undo/redo-style problems in a small working example.', 'Demonstrate Using a stack to track "most recent unmatched" state — the general shape of most stack problems in a small working example.']::text[], array['Submit a working Stack Patterns example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 900, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m02-t02', 'zte-fullstack-v1-core-phase-08-m02', 'Monotonic Stack', array['Explain and apply null in Monotonic Stack.', 'Use Monotonic Stack to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Maintaining a stack in increasing or decreasing order, popping elements that violate the order in a small working example.', 'Demonstrate Classic problems: next greater element, daily temperatures, largest rectangle in histogram in a small working example.', 'Demonstrate Recognizing monotonic stack candidates: "next greater/smaller element" style problems in a small working example.']::text[], array['Submit a working Monotonic Stack example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m02-t01']::text[], '[]'::jsonb, 900, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m02-t03', 'zte-fullstack-v1-core-phase-08-m02', 'Queue / Deque Patterns', array['Explain and apply null in Queue / Deque Patterns.', 'Use Queue / Deque Patterns to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate FIFO mechanics — where a queue is the natural fit (level-by-level processing, foreshadows BFS in Stage 4) in a small working example.', 'Demonstrate Deque (double-ended queue) — sliding window maximum/minimum using a monotonic deque (combines Stage 1''s sliding window with Stage 3''s monotonic stack idea) in a small working example.', 'Demonstrate Circular queue implementation (conceptual) in a small working example.']::text[], array['Submit a working Queue / Deque Patterns example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m02-t02']::text[], '[]'::jsonb, 660, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-08-m03', 'zte-fullstack-v1-core-phase-08', 3, 'Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming', 'Directly requires the queue (Stage 3, Topic 8\\) for BFS and the stack/recursion model (Stage 3, Topic 6\\) for DFS — cannot be taught before those exist.', 14, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m03-t01', 'zte-fullstack-v1-core-phase-08-m03', 'BFS / DFS', array['Explain and apply Depth-First Search in BFS / DFS.', 'Explain and apply Breadth-First Search in BFS / DFS.', 'Explain and apply Choosing Between Them in BFS / DFS.']::text[], array['Demonstrate Recursive DFS — using the call stack implicitly in a small working example.', 'Demonstrate Iterative DFS — using an explicit stack (direct application of Stage 3, Topic 6) in a small working example.', 'Demonstrate Graph representations: adjacency list vs adjacency matrix in a small working example.', 'Demonstrate Visited-set tracking to avoid infinite loops in cyclic graphs in a small working example.', 'Demonstrate Queue-based level-by-level traversal (direct application of Stage 3, Topic 8) in a small working example.']::text[], array['Submit a working BFS / DFS example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 1800, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m03-t02', 'zte-fullstack-v1-core-phase-08-m03', 'Dynamic Programming (Memoization + Tabulation)', array['Explain and apply Core Concepts in Dynamic Programming (Memoization + Tabulation).', 'Explain and apply Common DP Shapes in Dynamic Programming (Memoization + Tabulation).', 'Explain and apply Recognizing DP Candidates in Dynamic Programming (Memoization + Tabulation).']::text[], array['Demonstrate Overlapping subproblems and optimal substructure — the two properties that make a problem DP-solvable in a small working example.', 'Demonstrate Memoization (top-down) — recursion plus a cache in a small working example.', 'Demonstrate Tabulation (bottom-up) — building the solution iteratively from base cases in a small working example.', 'Demonstrate Converting between the two approaches in a small working example.', 'Demonstrate 1D DP — climbing stairs, house robber, fibonacci-style problems in a small working example.']::text[], array['Submit a working Dynamic Programming (Memoization + Tabulation) example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m03-t01']::text[], '[]'::jsonb, 3480, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m03-t03', 'zte-fullstack-v1-core-phase-08-m03', 'Tree Traversal', array['Explain and apply null in Tree Traversal.', 'Use Tree Traversal to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate In-order, pre-order, post-order traversal — all DFS variants, differing only in when the node is "visited" relative to its children in a small working example.', 'Demonstrate Level-order traversal — a direct application of BFS (9) in a small working example.', 'Demonstrate Recursive vs iterative implementations of each order in a small working example.', 'Demonstrate Binary Search Tree-specific properties that in-order traversal reveals (sorted output) in a small working example.', 'Demonstrate Common tree problems: validate BST, lowest common ancestor, tree diameter, serialize/deserialize in a small working example.']::text[], array['Submit a working Tree Traversal example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m03-t02']::text[], '[]'::jsonb, 60, 'intermediate', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m03-t04', 'zte-fullstack-v1-core-phase-08-m03', 'Floyd''s Cycle Detection', array['Explain and apply null in Floyd''s Cycle Detection.', 'Use Floyd''s Cycle Detection to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Fast/slow pointer technique ("tortoise and hare") for detecting a cycle in a linked list in a small working example.', 'Demonstrate Finding the start of a cycle once one is detected in a small working example.', 'Demonstrate Why this is effectively Two Pointers (Stage 1) applied to a linked structure instead of an array in a small working example.']::text[], array['Submit a working Floyd''s Cycle Detection example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m03-t03']::text[], '[]'::jsonb, 300, 'intermediate', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m03-t05', 'zte-fullstack-v1-core-phase-08-m03', 'Heap / Priority Queue', array['Explain and apply null in Heap / Priority Queue.', 'Use Heap / Priority Queue to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate Min-heap vs max-heap — underlying array representation and heapify operations in a small working example.', 'Demonstrate Insert and extract-min/max — O(log n) operations and why they matter for priority-based problems in a small working example.', 'Demonstrate Classic problems: top K frequent elements (combines directly with Stage 2''s frequency counting), merge K sorted lists, median of a data stream in a small working example.', 'Demonstrate When a heap beats sorting the entire dataset — maintaining a running "best K" without re-sorting in a small working example.']::text[], array['Submit a working Heap / Priority Queue example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m03-t04']::text[], '[]'::jsonb, 1320, 'intermediate', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-08-m04', 'zte-fullstack-v1-core-phase-08', 4, 'Interview Meta-Skills', 'Requires actual DSA competence (Stages 1–6) to be meaningful — a communication framework or system design vocabulary is empty without real problems solved to apply it to.', 12, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m04-t01', 'zte-fullstack-v1-core-phase-08-m04', 'Interview Frameworks (STAR, REACTO)', array['Explain and apply null in Interview Frameworks (STAR, REACTO).', 'Use Interview Frameworks (STAR, REACTO) to complete a practical task in DSA & Interview Preparation.']::text[], array['Demonstrate STAR (Situation, Task, Action, Result) — structuring behavioral interview answers in a small working example.', 'Demonstrate REACTO (Requirements, Examples, Approach, Code, Tests, Optimize) — structuring a live coding interview response, applied directly to the patterns from Stages 1–6 in a small working example.', 'Demonstrate Practicing narrating your thought process out loud while solving a problem — the skill interviewers are actually evaluating, distinct from just getting the right answer in a small working example.']::text[], array['Submit a working Interview Frameworks (STAR, REACTO) example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'intermediate', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-m04-t02', 'zte-fullstack-v1-core-phase-08-m04', 'System Design Interview Basics', array['Explain and apply Core Concepts in System Design Interview Basics.', 'Explain and apply Framing a System Design Answer in System Design Interview Basics.']::text[], array['Demonstrate Scalability basics — vertical vs horizontal scaling in a small working example.', 'Demonstrate Load balancing — concept and common strategies in a small working example.', 'Demonstrate Caching layers — where and why (connects to Redis, introduced in a later phase, but the concept is introduced here) in a small working example.', 'Demonstrate Database scaling — read replicas, sharding (concept, connects to Phase 05''s PostgreSQL depth) in a small working example.', 'Demonstrate Clarifying requirements before designing — functional and non-functional (scale, latency, consistency) in a small working example.']::text[], array['Submit a working System Design Interview Basics example and explain the key decisions.', 'Record a short review showing how the example satisfies the DSA & Interview Preparation learning goal.']::text[], array['zte-fullstack-v1-core-phase-08-m04-t01']::text[], '[]'::jsonb, 1140, 'intermediate', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-01', 'zte-fullstack-v1-core-phase-08', 'Pattern Recognition Drill Set', 'Solve and document 8 problems each for Two Pointers and Sliding Window (16 total) from a mix of easy/medium difficulty, with a personal "pattern recognition cheat sheet" written afterward describing the signal phrases that indicate each pattern.', array['Deliver the working outcome described in the Pattern Recognition Drill Set brief.', 'Use at least two skills from Array & String Scanning Techniques and Hashing and Hashing and Hashing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Pattern Recognition Drill Set', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Array & String Scanning Techniques and Hashing and Hashing and Hashing']::text[], 'beginner', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-02', 'zte-fullstack-v1-core-phase-08', 'Binary Search Beyond Sorted Arrays', 'Solve 6 problems that use binary search in non-obvious ways (search on answer space, rotated arrays, first/last occurrence), documenting the invariant maintained in each solution.', array['Deliver the working outcome described in the Binary Search Beyond Sorted Arrays brief.', 'Use at least two skills from Array & String Scanning Techniques and Hashing and Hashing and Hashing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Binary Search Beyond Sorted Arrays', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Array & String Scanning Techniques and Hashing and Hashing and Hashing']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-03', 'zte-fullstack-v1-core-phase-08', 'Stock Trading Simulator via Kadane’s Variants', 'Solve the full family of "best time to buy/sell stock" problems (I through IV) building from basic Kadane’s to the DP-augmented versions with transaction limits, with a written explanation of how each variant extends the last.', array['Deliver the working outcome described in the Stock Trading Simulator via Kadane’s Variants brief.', 'Use at least two skills from Array & String Scanning Techniques and Hashing and Hashing and Hashing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Stock Trading Simulator via Kadane’s Variants', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Array & String Scanning Techniques and Hashing and Hashing and Hashing']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-04', 'zte-fullstack-v1-core-phase-08', 'Expression Evaluator', 'Build a calculator that evaluates infix mathematical expressions with correct operator precedence and parentheses using a stack-based approach (shunting-yard or recursive descent), tested against 20 hand-crafted tricky expressions. Solve 6 monotonic stack problems (next greater element family, daily temperatures, largest rectangle in histogram), with a written template for recognizing when a monotonic stack applies.', array['Deliver the working outcome described in the Expression Evaluator brief.', 'Use at least two skills from Linear Structures: Stack & Queue.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Expression Evaluator', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Linear Structures: Stack & Queue']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-05', 'zte-fullstack-v1-core-phase-08', 'Maze & Graph Explorer Toolkit', 'Solve a set of grid-based BFS/DFS problems (number of islands, rotting oranges, word ladder) with a shared, reusable grid-traversal helper function. Implement every classic tree traversal (in/pre/post-order, level-order) both recursively and iteratively, plus tree construction from traversal pairs, serialization/deserialization, and LCA — packaged as a small reusable tree utility module with tests.', array['Deliver the working outcome described in the Maze & Graph Explorer Toolkit brief.', 'Use at least two skills from Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Maze & Graph Explorer Toolkit', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-06', 'zte-fullstack-v1-core-phase-08', 'Cycle Detection Across Data Structures', 'Implement Floyd’s Cycle Detection (tortoise and hare) applied to 3 different contexts: a linked list, an implicit "functional graph" (array where value = next index), and duplicate-number detection — documenting the shared mathematical insight across all three.', array['Deliver the working outcome described in the Cycle Detection Across Data Structures brief.', 'Use at least two skills from Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cycle Detection Across Data Structures', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Traversal: BFS, DFS, and Trees and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming and Heap / Priority Queue and Dynamic Programming']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-07', 'zte-fullstack-v1-core-phase-08', '1D DP Warm-Up Set', 'Solve 6 classic 1D DP problems (climbing stairs, house robber, coin change, longest increasing subsequence) implementing each with both memoization (top-down) and tabulation (bottom-up), comparing code clarity and space usage. Solve 8 2D DP problems (unique paths, edit distance, longest common subsequence, 0/1 knapsack) with a written "DP state design" note for each: what does dp[i][j] represent, and why.', array['Deliver the working outcome described in the 1D DP Warm-Up Set brief.', 'Use at least two skills from Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working 1D DP Warm-Up Set', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Dynamic Programming']::text[], 'intermediate', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-08', 'zte-fullstack-v1-core-phase-08', 'DP Optimization Showcase', 'Take 3 of your 2D DP solutions and optimize their space complexity from O(n²) to O(n) using rolling arrays, documenting the transformation reasoning and benchmarking actual memory usage before/after on large inputs.', array['Deliver the working outcome described in the DP Optimization Showcase brief.', 'Use at least two skills from Dynamic Programming.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working DP Optimization Showcase', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Dynamic Programming']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-09', 'zte-fullstack-v1-core-phase-08', 'System Design Interview Playbook', 'Produce full written system design solutions (with diagrams) for 4 classic prompts (URL shortener, rate limiter, news feed, chat system) following a consistent framework: requirements clarification, capacity estimation, high-level design, deep dive, bottleneck/scaling discussion. Domain: systems design / interview prep.', array['Deliver the working outcome described in the System Design Interview Playbook brief.', 'Use at least two skills from Interview Meta-Skills.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working System Design Interview Playbook', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'Interview Meta-Skills']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-08-project-10', 'zte-fullstack-v1-core-phase-08', 'A Personal DSA + System Design Reference System', 'Build a personal, structured knowledge base (could be a static site generated from markdown, tying back to Phase 1– 3 skills) cataloging: every pattern from Stages 1–6 with your own annotated solutions and a "recognize this pattern when..." cheat sheet per category, 4 fully written system design case studies with Mermaid architecture diagrams (tying back to Phase 7), and a log of at least 10 timed, REACTO-framework mock interviews with self-critique notes. Domain: career preparation / technical knowledge management. Why it matters: the artifact itself (a searchable, well-organized personal reference) is arguably more valuable long-term than any single solved problem — and building it forces genuine synthesis rather than passive practice.', array['Deliver the working outcome described in the A Personal DSA + System Design Reference System brief.', 'Use at least two skills from DSA & Interview Preparation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Personal DSA + System Design Reference System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['DSA & Interview Preparation', 'engineering documentation']::text[], 'advanced', 9) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-fullstack-v1-core-phase-09', 'zte-fullstack-v1', id, '11', 'Caching + Email + Payments', 'Advanced', 'Requires PostgreSQL and a real backend (Phase 05\\) — caching only matters once there''s real query load and connection pressure to relieve.', 98, 10 from public.roadmap_versions where roadmap_id='zte-fullstack-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-09-m01', 'zte-fullstack-v1-core-phase-09', 1, 'Self-Hosted Caching Infrastructure', 'Requires PostgreSQL and a real backend (Phase 05\\) — caching only matters once there''s real query load and connection pressure to relieve.', 11.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m01-t01', 'zte-fullstack-v1-core-phase-09-m01', 'Redis', array['Explain and apply Core Data Structures in Redis.', 'Explain and apply Caching Patterns in Redis.', 'Explain and apply Beyond Simple Caching in Redis.']::text[], array['Demonstrate Strings, hashes, lists, sets, sorted sets — Redis''s core data types and when each fits a use case in a small working example.', 'Demonstrate Key expiration (TTL) — the foundation of cache invalidation in a small working example.', 'Demonstrate Redis as a cache vs Redis as a primary data store — the distinction and why it matters in a small working example.', 'Demonstrate Cache-aside (lazy loading) — the most common pattern: check cache, miss, fetch from DB, populate cache in a small working example.', 'Demonstrate Write-through vs write-behind caching in a small working example.']::text[], array['Submit a working Redis example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array[]::text[], '[]'::jsonb, 1140, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m01-t02', 'zte-fullstack-v1-core-phase-09-m01', 'ioredis', array['Explain and apply null in ioredis.', 'Use ioredis to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Connecting to a Redis instance from Node/Express (Phase 05) in a small working example.', 'Demonstrate Basic commands via the client API — get/set/expire, hash and list operations in a small working example.', 'Demonstrate Connection resilience — retry strategies, handling connection drops in a small working example.', 'Demonstrate Pipelining and transactions (MULTI/EXEC) for batching commands efficiently in a small working example.']::text[], array['Submit a working ioredis example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-fullstack-v1-core-phase-09-m01-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m01-t03', 'zte-fullstack-v1-core-phase-09-m01', 'PgBouncer', array['Explain and apply null in PgBouncer.', 'Use PgBouncer to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate The connection limit problem — why PostgreSQL can''t handle unlimited direct connections, especially from serverless/edge functions (Phase 02''s Edge Runtime) in a small working example.', 'Demonstrate Transaction pooling vs session pooling modes in a small working example.', 'Demonstrate Where PgBouncer sits in the request path — app → PgBouncer → PostgreSQL in a small working example.', 'Demonstrate Why this matters more in serverless contexts than traditional long-running servers in a small working example.']::text[], array['Submit a working PgBouncer example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-fullstack-v1-core-phase-09-m01-t02']::text[], '[]'::jsonb, 240, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-09-m02', 'zte-fullstack-v1-core-phase-09', 2, 'Hosted & Distributed Caching', 'Requires Redis fundamentals (Stage 1\\) — this stage is the caching-layer parallel to Phase 05''s PostgreSQL → Supabase/Neon progression: self-hosted concept first, hosted/managed alternative second.', 3.5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m02-t01', 'zte-fullstack-v1-core-phase-09-m02', 'Upstash', array['Explain and apply null in Upstash.', 'Use Upstash to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Serverless Redis — HTTP-based access instead of persistent TCP connections, designed for edge/serverless environments in a small working example.', 'Demonstrate Why Upstash fits Next.js Edge Runtime/Middleware (Phase 02) where traditional Redis clients (ioredis) can''t run in a small working example.', 'Demonstrate Pricing model differences — pay-per-request vs traditional Redis''s always-on instance cost in a small working example.', 'Demonstrate When to choose Upstash over self-hosted Redis — mirrors the Supabase/Neon vs raw PostgreSQL decision from Phase 05 in a small working example.']::text[], array['Submit a working Upstash example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m02-t02', 'zte-fullstack-v1-core-phase-09-m02', '@upstash/ratelimit', array['Explain and apply null in @upstash/ratelimit.', 'Use @upstash/ratelimit to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Why in-memory rate limiting (Phase 05) breaks across multiple serverless function instances — no shared state in a small working example.', 'Demonstrate Sliding window, fixed window, and token bucket algorithms as implemented by this library in a small working example.', 'Demonstrate Applying rate limits in Next.js Middleware (Phase 02) or Edge Functions using Upstash''s HTTP-based access (4) in a small working example.']::text[], array['Submit a working @upstash/ratelimit example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-fullstack-v1-core-phase-09-m02-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-09-m03', 'zte-fullstack-v1-core-phase-09', 3, 'Transactional Email and Payments and Payments and Payments', 'Independent of the caching stages above — a new capability area. Ordered so the delivery mechanism (Resend) is understood before investing in a component-based templating system (React Email) that plugs into it.', 5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m03-t01', 'zte-fullstack-v1-core-phase-09-m03', 'Resend', array['Explain and apply null in Resend.', 'Use Resend to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Sending a transactional email via Resend''s API — the simplest possible send call in a small working example.', 'Demonstrate Domain verification and sender reputation basics (SPF, DKIM — conceptual) in a small working example.', 'Demonstrate Common triggers: signup confirmation, password reset, notification emails — tying back to Phase 05''s auth flow in a small working example.', 'Demonstrate Handling send failures and retries in a small working example.']::text[], array['Submit a working Resend example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array[]::text[], '[]'::jsonb, 240, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m03-t02', 'zte-fullstack-v1-core-phase-09-m03', 'React Email', array['Explain and apply null in React Email.', 'Use React Email to complete a practical task in Caching + Email + Payments.']::text[], array['Demonstrate Building email templates as React components — familiar syntax from Phase 02, compiled to email-safe HTML in a small working example.', 'Demonstrate Why email HTML/CSS is far more constrained than web CSS (Phase 03) — table-based layouts, inline styles, limited property support in a small working example.', 'Demonstrate Component library (@react-email/components) — pre-built email-safe primitives (Button, Section, Text) in a small working example.', 'Demonstrate Previewing emails locally during development in a small working example.', 'Demonstrate Connecting a React Email template''s output to a Resend send call (6) — completing the pipeline in a small working example.']::text[], array['Submit a working React Email example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-fullstack-v1-core-phase-09-m03-t01']::text[], '[]'::jsonb, 480, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-m03-t03', 'zte-fullstack-v1-core-phase-09-m03', 'Razorpay', array['Explain and apply Payment Flow Fundamentals in Razorpay.', 'Explain and apply Webhooks in Razorpay.', 'Explain and apply Production Considerations in Razorpay.']::text[], array['Demonstrate Order creation → checkout → payment capture → webhook confirmation — the standard flow in a small working example.', 'Demonstrate Client-side checkout integration (Razorpay''s JS SDK) in a Next.js app (Phase 02) in a small working example.', 'Demonstrate Server-side order creation and signature verification in a small working example.', 'Demonstrate Why payment confirmation must be server-to-server (webhook), not trusted from the client alone in a small working example.', 'Demonstrate Verifying webhook signatures (HMAC-based, ties directly back to Phase 05''s HMAC-SHA256 topic) in a small working example.']::text[], array['Submit a working Razorpay example and explain the key decisions.', 'Record a short review showing how the example satisfies the Caching + Email + Payments learning goal.']::text[], array['zte-fullstack-v1-core-phase-09-m03-t02']::text[], '[]'::jsonb, 1140, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-project-01', 'zte-fullstack-v1-core-phase-09', 'Cache-Aside API Layer', 'Add Redis caching (via ioredis) to an earlier project’s read-heavy endpoints using the cache-aside pattern, with a documented cache-hit-rate measurement before/after and a sensible TTL/invalidation strategy per resource type. Domain: performance engineering.', array['Deliver the working outcome described in the Cache-Aside API Layer brief.', 'Use at least two skills from Self-Hosted Caching Infrastructure.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Cache-Aside API Layer', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Self-Hosted Caching Infrastructure']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-project-02', 'zte-fullstack-v1-core-phase-09', 'Connection Pool Exhaustion Lab', 'Deliberately misconfigure PgBouncer to cause connection pool exhaustion under simulated load, observe and document the failure mode, then correctly configure pooling (transaction vs session mode) and prove the fix under the same load test. Domain: database infrastructure / SRE.', array['Deliver the working outcome described in the Connection Pool Exhaustion Lab brief.', 'Use at least two skills from Self-Hosted Caching Infrastructure.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Connection Pool Exhaustion Lab', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Self-Hosted Caching Infrastructure']::text[], 'advanced', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-project-03', 'zte-fullstack-v1-core-phase-09', 'Serverless-Friendly Rate Limiter', 'Implement API rate limiting using Upstash (Redis-over-HTTP, works from serverless/edge functions) with @upstash/ratelimit, comparing sliding-window vs fixed-window algorithms with real traffic simulation. Domain: API infrastructure.', array['Deliver the working outcome described in the Serverless-Friendly Rate Limiter brief.', 'Use at least two skills from Hosted & Distributed Caching.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Serverless-Friendly Rate Limiter', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Hosted & Distributed Caching']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-project-04', 'zte-fullstack-v1-core-phase-09', 'Branded Transactional Email System', 'Build a full transactional email flow (welcome, password reset, receipt) using React Email for templates (so emails are built with real component reuse) and Resend for delivery, tested across multiple email clients for rendering consistency. Domain: product/growth engineering.', array['Deliver the working outcome described in the Branded Transactional Email System brief.', 'Use at least two skills from Transactional Email and Payments and Payments and Payments.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Branded Transactional Email System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Transactional Email and Payments and Payments and Payments']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-project-05', 'zte-fullstack-v1-core-phase-09', 'Subscription Billing System', 'A full subscription billing integration with Razorpay: plan selection, checkout, webhook-based subscription-status sync (active/past-due/cancelled) back into your own database, and a customer-facing billing history page. Domain: fintech / SaaS billing. A one-time purchase flow (e.g., for a digital product) with Razorpay, including a documented refund process both via API and via the dashboard, and idempotent webhook handling so a duplicate webhook delivery never double-credits an order. Domain: e-commerce/fintech.', array['Deliver the working outcome described in the Subscription Billing System brief.', 'Use at least two skills from Payments.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Subscription Billing System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'Payments']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-09-project-06', 'zte-fullstack-v1-core-phase-09', 'A Caching-Optimized SaaS Billing Backend', 'Extend Phase 5’s "Ledger" (or a similar backend) with: Redis cache-aside caching on the highest-traffic read endpoints with measured hit-rate improvements, PgBouncer correctly configured for connection pooling under load, Upstash-based edge-compatible rate limiting on public endpoints, a full React Email \+ Resend transactional email suite (welcome/receipt/billing-alert), and a complete Razorpay subscription billing integration with idempotent, signature-verified webhook handling syncing subscription state into the database. Domain: SaaS infrastructure / fintech. Why it matters: caching, email, and payments are the unglamorous plumbing every real SaaS product needs — getting them right (idempotency, cache invalidation, webhook security) is what separates hobby projects from production systems.', array['Deliver the working outcome described in the A Caching-Optimized SaaS Billing Backend brief.', 'Use at least two skills from Caching + Email + Payments.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Caching-Optimized SaaS Billing Backend', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Caching + Email + Payments', 'engineering documentation']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-fullstack-v1-core-phase-10', 'zte-fullstack-v1', id, '12', 'Monitoring & Analytics', 'Advanced', 'Requires a real backend (Phase 05\\) with real request traffic — logging and context tracing only matter once there''s something happening to log.', 103, 11 from public.roadmap_versions where roadmap_id='zte-fullstack-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-10-m01', 'zte-fullstack-v1-core-phase-10', 1, 'Request Context & Structured Logging', 'Requires a real backend (Phase 05\\) with real request traffic — logging and context tracing only matter once there''s something happening to log.', 6.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m01-t01', 'zte-fullstack-v1-core-phase-10-m01', 'AsyncLocalStorage', array['Explain and apply null in AsyncLocalStorage.', 'Use AsyncLocalStorage to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate The problem: a single Express request handler (Phase 05) may call through many async functions — how do you tag every log line from that request with the same request ID without passing it as a parameter everywhere? in a small working example.', 'Demonstrate AsyncLocalStorage.run() and .getStore() — the core API in a small working example.', 'Demonstrate Building request-scoped context: request ID, user ID, correlation ID in a small working example.', 'Demonstrate Express middleware pattern for initializing AsyncLocalStorage per request in a small working example.']::text[], array['Submit a working AsyncLocalStorage example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 360, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m01-t02', 'zte-fullstack-v1-core-phase-10-m01', 'pino', array['Explain and apply null in pino.', 'Use pino to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Why pino is fast — minimal serialization overhead, JSON-first output by design in a small working example.', 'Demonstrate Log levels (trace, debug, info, warn, error, fatal) and when to use each in a small working example.', 'Demonstrate Structured logging — logging objects, not just strings, so logs are queryable later (bridges to Stage 3''s aggregation platforms) in a small working example.', 'Demonstrate Child loggers — attaching AsyncLocalStorage context (1) automatically to every log call within a request in a small working example.']::text[], array['Submit a working pino example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-fullstack-v1-core-phase-10-m01-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m01-t03', 'zte-fullstack-v1-core-phase-10-m01', 'winston', array['Explain and apply null in winston.', 'Use winston to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Winston''s transport model — logging to multiple destinations simultaneously (console, file, external service) in a small working example.', 'Demonstrate Winston vs pino — performance tradeoffs (winston is more configurable, pino is faster by design) in a small working example.', 'Demonstrate When to choose one over the other for a given project''s needs in a small working example.']::text[], array['Submit a working winston example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-fullstack-v1-core-phase-10-m01-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-10-m02', 'zte-fullstack-v1-core-phase-10', 2, 'Error Tracking & Uptime', 'Requires structured logging (Stage 1\\) as a complementary but distinct concept — logs answer "what happened," error tracking answers "what went wrong and who does it affect."', 5, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m02-t01', 'zte-fullstack-v1-core-phase-10-m02', 'Sentry', array['Explain and apply Core Error Tracking in Sentry.', 'Explain and apply Context & Correlation in Sentry.']::text[], array['Demonstrate Automatic error capture — uncaught exceptions and promise rejections (ties back to Phase 01''s Node.js error handling topics) in a small working example.', 'Demonstrate Manual error capture — Sentry.captureException() for handled errors worth tracking anyway in a small working example.', 'Demonstrate Source maps — seeing real file/line info in production errors instead of minified gibberish in a small working example.', 'Demonstrate Error grouping — how Sentry deduplicates the same underlying error across many occurrences in a small working example.', 'Demonstrate Attaching user context to errors — connecting an error to the specific user/request that triggered it, using the same AsyncLocalStorage context (Stage 1, Topic 1) as your logs in a small working example.']::text[], array['Submit a working Sentry example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 420, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m02-t02', 'zte-fullstack-v1-core-phase-10-m02', 'UptimeRobot', array['Explain and apply null in UptimeRobot.', 'Use UptimeRobot to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Setting up HTTP(S) monitors against your deployed app (Phase 06) in a small working example.', 'Demonstrate Alert configuration — email/SMS/webhook when a monitor fails in a small working example.', 'Demonstrate Status pages — a public-facing uptime history, useful portfolio polish in a small working example.']::text[], array['Submit a working UptimeRobot example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-fullstack-v1-core-phase-10-m02-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-10-m03', 'zte-fullstack-v1-core-phase-10', 3, 'Log Aggregation & Observability Platforms', 'Requires structured logs to exist (Stage 1\\) — these platforms exist to collect, search, and visualize exactly that output at scale, which a single server''s local log files can''t do.', 10, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
