insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m03-t03', 'zte-fullstack-v1-core-phase-10-m03', 'Grafana Cloud', array['Explain and apply null in Grafana Cloud.', 'Use Grafana Cloud to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate The three pillars of observability: metrics, logs, traces — and how Grafana Cloud unifies them in one dashboard in a small working example.', 'Demonstrate Building dashboards from application metrics in a small working example.', 'Demonstrate Connecting Grafana to multiple data sources in a small working example.']::text[], array['Submit a working Grafana Cloud example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-fullstack-v1-core-phase-10-m03-t02']::text[], '[]'::jsonb, 300, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m03-t04', 'zte-fullstack-v1-core-phase-10-m03', 'Loki', array['Explain and apply null in Loki.', 'Use Loki to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Loki''s log-indexing model — indexing labels, not full log content (a key difference from Elasticsearch-style systems) in a small working example.', 'Demonstrate LogQL — Loki''s query language in a small working example.', 'Demonstrate Why Loki pairs naturally with Grafana (8) rather than standing alone in a small working example.']::text[], array['Submit a working Loki example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-fullstack-v1-core-phase-10-m03-t03']::text[], '[]'::jsonb, 180, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m03-t05', 'zte-fullstack-v1-core-phase-10-m03', 'Datadog', array['Explain and apply null in Datadog.', 'Use Datadog to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Datadog''s all-in-one model — APM, logs, infrastructure metrics, and RUM (Real User Monitoring) in one product in a small working example.', 'Demonstrate Where Datadog differs from Grafana Cloud — pricing at scale, ease of setup vs configurability in a small working example.', 'Demonstrate When a team would choose Datadog over a Grafana/Loki stack in a small working example.']::text[], array['Submit a working Datadog example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array['zte-fullstack-v1-core-phase-10-m03-t04']::text[], '[]'::jsonb, 180, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
