insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-10-m04', 'zte-fullstack-v1-core-phase-10', 4, 'Product Analytics Foundation', 'A distinct concern from infrastructure monitoring (Stages 1–3) — this is about user behavior, not system health. Independent of everything above, but grouped after it since it''s a separate observability axis, not a prerequisite.', 5.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-10-m04-t01', 'zte-fullstack-v1-core-phase-10-m04', 'PostHog', array['Explain and apply null in PostHog.', 'Use PostHog to complete a practical task in Monitoring & Analytics.']::text[], array['Demonstrate Event-based analytics model — tracking user actions as named events with properties in a small working example.', 'Demonstrate Self-hosted vs PostHog Cloud — the platform choice in a small working example.', 'Demonstrate Core concepts: persons, events, properties, cohorts in a small working example.', 'Demonstrate Dashboards and insights built from raw event data in a small working example.']::text[], array['Submit a working PostHog example and explain the key decisions.', 'Record a short review showing how the example satisfies the Monitoring & Analytics learning goal.']::text[], array[]::text[], '[]'::jsonb, 540, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
