insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-10-m05', 'zte-fullstack-v1-core-phase-10', 5, 'Analytics-Driven Features and Compliance and Compliance and Compliance', 'All four topics require the PostHog foundation (Stage 4\\) — none of these features exist without an analytics platform and event pipeline already in place.', 8.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
