insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-m07-t01', 'zte-fullstack-v1-core-phase-17-m07', 'Portfolio narrative and technical evidence', array['Connect project outcomes to concrete engineering decisions', 'Present measurable evidence without overstating impact']::text[], array['Write a case study with tradeoffs and results', 'Prepare a concise architecture walkthrough']::text[], array['Reviewed portfolio story linked to deployed project and repository']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-m07-t02', 'zte-fullstack-v1-core-phase-17-m07', 'Full-stack interview practice', array['Communicate assumptions and tradeoffs clearly', 'Debug and improve an end-to-end feature under time constraints']::text[], array['Complete timed coding and design mocks', 'Review gaps and schedule targeted practice']::text[], array['Interview log with feedback themes and follow-up actions']::text[], array['zte-fullstack-v1-core-phase-17-m07-t01']::text[], '[]'::jsonb, 210, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-01', 'zte-fullstack-v1-core-phase-17', 'Optimistic Social Feed', 'A social-media-style feed where likes/comments appear instantly (optimistic update) with correct rollback on simulated server rejection, backed by a cache-aside and a write-through caching strategy compared side-by-side on two different data types in the same app.', array['Deliver the working outcome described in the Optimistic Social Feed brief.', 'Use at least two skills from Caching & Optimistic Update Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Optimistic Social Feed', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Caching & Optimistic Update Patterns']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-02', 'zte-fullstack-v1-core-phase-17', 'Idempotent Payment Retry Handler', 'A payment processing endpoint that safely handles duplicate/retried requests (e.g., a client retrying after a timeout) using an idempotency key, proven with a test that fires the same request 10 times concurrently and confirms only one charge occurs.', array['Deliver the working outcome described in the Idempotent Payment Retry Handler brief.', 'Use at least two skills from Database Concurrency Control.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Idempotent Payment Retry Handler', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Database Concurrency Control']::text[], 'advanced', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-03', 'zte-fullstack-v1-core-phase-17', 'Order Fulfillment Saga', 'Model a multi-step order fulfillment process (charge payment → reserve inventory → schedule shipping) as a Saga with proper compensating transactions for each step, demonstrated by deliberately failing the shipping step and proving payment gets correctly refunded and inventory released.', array['Deliver the working outcome described in the Order Fulfillment Saga brief.', 'Use at least two skills from Distributed Transactions & Messaging Resilience.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Order Fulfillment Saga', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Distributed Transactions & Messaging Resilience']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-04', 'zte-fullstack-v1-core-phase-17', 'Resilient Event-Driven Order Pipeline', 'The same order pipeline rebuilt using the Outbox pattern (to guarantee at-least-once event publishing alongside the DB transaction), a Dead Letter Queue for messages that repeatedly fail processing, and a Circuit Breaker around a flaky downstream shipping-provider API call.', array['Deliver the working outcome described in the Resilient Event-Driven Order Pipeline brief.', 'Use at least two skills from Distributed Transactions & Messaging Resilience.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Resilient Event-Driven Order Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Distributed Transactions & Messaging Resilience']::text[], 'advanced', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-05', 'zte-fullstack-v1-core-phase-17', 'CQRS-Based Reporting System', 'Split a write-heavy transactional data model from a read-optimized reporting model using CQRS — writes go through a normalized command model, reads are served from a denormalized, eventually-consistent query model — with documented consistency-lag behavior.', array['Deliver the working outcome described in the CQRS-Based Reporting System brief.', 'Use at least two skills from Architectural Styles and Multi-Tenancy and Multi-Tenancy and Multi-Tenancy.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working CQRS-Based Reporting System', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Architectural Styles and Multi-Tenancy and Multi-Tenancy and Multi-Tenancy']::text[], 'advanced', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-06', 'zte-fullstack-v1-core-phase-17', 'Row-Level Multi-Tenant SaaS Data Layer', 'Implement multi-tenancy for a SaaS app using a shared-database, row-level isolation strategy (tenant_id on every table + enforced query scoping), with a deliberate test proving one tenant can never see another tenant’s data even under a crafted malicious query attempt.', array['Deliver the working outcome described in the Row-Level Multi-Tenant SaaS Data Layer brief.', 'Use at least two skills from Multi-Tenancy.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Row-Level Multi-Tenant SaaS Data Layer', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Multi-Tenancy']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-07', 'zte-fullstack-v1-core-phase-17', 'Chaos Engineering Game Day', 'Run a real chaos engineering exercise against one of your deployed systems: deliberately kill a service instance, inject network latency, or fail a dependency mid-request, and document what broke, what didn’t, and what you fixed afterward. Domain: SRE / resilience engineering.', array['Deliver the working outcome described in the Chaos Engineering Game Day brief.', 'Use at least two skills from Deployment Strategy & Resilience Validation.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Chaos Engineering Game Day', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'Deployment Strategy & Resilience Validation']::text[], 'advanced', 6) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-08', 'zte-fullstack-v1-core-phase-17', 'A Distributed, Multi-Tenant Order Platform', 'A multi-tenant e-commerce order platform combining every pattern in this phase: optimistic-locked inventory and idempotent payment handling preventing overselling and double-charges, a Saga-orchestrated fulfillment pipeline with the Outbox pattern for reliable event publishing, a Circuit Breaker and Dead Letter Queue protecting against a flaky shipping provider, an event-driven notification system decoupled via pub/sub, a CQRS-split reporting layer for seller analytics, strict row-level multi-tenant data isolation proven under adversarial testing, and a blue-green deployment pipeline validated with a real chaos engineering game day. Domain: e-commerce / distributed systems. Why it matters: this is the single most architecturally advanced project in the entire roadmap — it proves genuine distributed-systems thinking, not just feature-building.', array['Deliver the working outcome described in the A Distributed, Multi-Tenant Order Platform brief.', 'Use at least two skills from Architectural Patterns.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Distributed, Multi-Tenant Order Platform', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Architectural Patterns', 'engineering documentation']::text[], 'advanced', 7) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-17-project-09', 'zte-fullstack-v1-core-phase-17', 'Capstone launch and technical case study', 'Show that you can own a real product from problem framing through reliable operation.', array['Real user problem and validated workflow', 'Production deployment and monitored critical path', 'Security/privacy and recovery plan', 'Documented iteration based on feedback']::text[], array['Research and plan', 'Deliver vertical slices', 'Pilot with representative users', 'Measure, improve, and present']::text[], array['Product and source repository', 'Case study', 'Architecture and security notes', 'Interview walkthrough']::text[], array['product engineering', 'technical communication', 'system design', 'ownership', 'full-stack', 'engineering delivery']::text[], 'advanced', 8) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-fullstack-v1-core-phase-18', 'zte-fullstack-v1', id, '20', 'Engineering Craft + Package Publishing', 'Expert', 'Foundational to everything that follows in this phase — Stage 4''s documentation artifacts are largely the written record of the practices introduced here.', 62, 19 from public.roadmap_versions where roadmap_id='zte-fullstack-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-18-m01', 'zte-fullstack-v1-core-phase-18', 1, 'Decision-Making Practices and Package Publishing and Package Publishing and Package Publishing', 'Foundational to everything that follows in this phase — Stage 4''s documentation artifacts are largely the written record of the practices introduced here.', 4.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m01-t01', 'zte-fullstack-v1-core-phase-18-m01', 'Changesets', array['Explain and apply null in Changesets.', 'Use Changesets to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The problem — coordinating version bumps and changelog entries across a package (or monorepo of packages) without manually tracking what changed since the last release in a small working example.', 'Demonstrate Adding a changeset — a small markdown file describing a change and its semver impact (patch/minor/major), committed alongside the code change itself in a small working example.', 'Demonstrate Consuming changesets — a release step that reads all pending changesets, bumps versions accordingly, and generates a changelog automatically in a small working example.', 'Demonstrate Publishing workflow — combining Changesets with Phase 15''s tsup build step and Phase 06''s GitHub Actions to automate the actual npm publish in a small working example.', 'Demonstrate This is the direct mechanism behind this phase''s Build in Public goal — publishing a first real npm package in a small working example.']::text[], array['Submit a working Changesets example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 300, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m01-t02', 'zte-fullstack-v1-core-phase-18-m01', 'ADRs (Architectural Decision Records)', array['Explain and apply null in ADRs (Architectural Decision Records).', 'Use ADRs (Architectural Decision Records) to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The format — context (what problem/situation prompted this), decision (what was chosen), consequences (what tradeoffs follow from it) in a small working example.', 'Demonstrate Why ADRs matter more than comments or memory — a decision''s reasoning is often more valuable to a future reader than the decision itself, especially once circumstances have changed and someone''s questioning whether the original choice still makes sense in a small working example.', 'Demonstrate What''s actually worth writing one for — significant, hard-to-reverse decisions (Phase 12''s Exit D caution about documenting pgvector vs Pinecone, Haiku vs GPT-4o is exactly ADR-shaped content), not every minor implementation choice in a small working example.', 'Demonstrate Retroactively writing ADRs for major decisions already made across Phases 01–17 — this phase is a natural point to catch up the backlog, not just start going forward in a small working example.']::text[], array['Submit a working ADRs (Architectural Decision Records) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m01-t01']::text[], '[]'::jsonb, 240, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m01-t03', 'zte-fullstack-v1-core-phase-18-m01', 'RFCs (Request for Comments)', array['Explain and apply null in RFCs (Request for Comments).', 'Use RFCs (Request for Comments) to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Structure — problem statement, proposed approach, alternatives considered, open questions for discussion in a small working example.', 'Demonstrate When an RFC is worth writing vs when a decision is small enough to just make and document via ADR (2) afterward in a small working example.', 'Demonstrate The lifecycle — an RFC that reaches consensus typically becomes the basis for one or more ADRs (2) once implemented in a small working example.', 'Demonstrate Solo-developer context — even without a team to actually comment on an RFC, writing one forces the same rigor of considering alternatives before committing, which matters for the kind of documented decision-making Exit ★3 (Phase 17) already flagged as a portfolio differentiator in a small working example.']::text[], array['Submit a working RFCs (Request for Comments) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m01-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-18-m02', 'zte-fullstack-v1-core-phase-18', 2, 'Engineering Process Practices', 'A cluster of process disciplines, mostly independent of each other, but all downstream of having a real, deployed, monitored system (Phases 05–17) to actually apply them to.', 10, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m02-t01', 'zte-fullstack-v1-core-phase-18-m02', 'DORA Metrics', array['Explain and apply null in DORA Metrics.', 'Use DORA Metrics to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The four key metrics — deployment frequency, lead time for changes, change failure rate, time to restore service in a small working example.', 'Demonstrate Why these specific four — they''re the metrics DORA''s research found actually correlate with high-performing engineering organizations, not an arbitrary dashboard in a small working example.', 'Demonstrate Measuring them from your own pipeline — deployment frequency and lead time are readable directly from Phase 06''s GitHub Actions history; change failure rate and time to restore need incident tracking (foreshadows Topic 5 and the incidents/ artifact, Stage 4) in a small working example.']::text[], array['Submit a working DORA Metrics example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m02-t02', 'zte-fullstack-v1-core-phase-18-m02', 'Blameless Post-Mortems', array['Explain and apply null in Blameless Post-Mortems.', 'Use Blameless Post-Mortems to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The blameless framing — analyzing what happened and why the system allowed it, not who made a mistake; the practice exists because blame-oriented reviews make people hide information rather than surface it in a small working example.', 'Demonstrate Structure — timeline of events, root cause analysis, contributing factors, action items with owners in a small working example.', 'Demonstrate Using Phase 14/17''s chaos engineering experiments as low-stakes practice material — you already have a real "incident" (something you deliberately broke) to write a genuine post-mortem about in a small working example.', 'Demonstrate Directly feeds the incidents/ documentation artifact (Stage 4) in a small working example.']::text[], array['Submit a working Blameless Post-Mortems example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m02-t01']::text[], '[]'::jsonb, 180, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m02-t03', 'zte-fullstack-v1-core-phase-18-m02', 'Technical Debt Tracking', array['Explain and apply null in Technical Debt Tracking.', 'Use Technical Debt Tracking to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Distinguishing technical debt from "code I''d write differently today" — debt implies a deliberate or understood tradeoff, not just hindsight in a small working example.', 'Demonstrate A lightweight tracking format — what was deferred, why, and what the cost of leaving it unaddressed actually is in a small working example.', 'Demonstrate Directly feeds the TECH_DEBT.md documentation artifact (Stage 4) in a small working example.']::text[], array['Submit a working Technical Debt Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m02-t02']::text[], '[]'::jsonb, 120, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m02-t04', 'zte-fullstack-v1-core-phase-18-m02', 'Estimation Tracking', array['Explain and apply null in Estimation Tracking.', 'Use Estimation Tracking to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Recording estimates against actuals — the only way to actually improve at estimation is comparing predictions to outcomes over time in a small working example.', 'Demonstrate Common estimation failure patterns — optimism bias, ignoring integration/testing time, underestimating unfamiliar work in a small working example.', 'Demonstrate Using this phase''s own official-vs-actual hour discrepancies (flagged throughout every deep doc in this series) as a live, concrete example of estimation drift worth reflecting on in a small working example.']::text[], array['Submit a working Estimation Tracking example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m02-t03']::text[], '[]'::jsonb, 120, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m02-t05', 'zte-fullstack-v1-core-phase-18-m02', 'Code Review Conventions', array['Explain and apply null in Code Review Conventions.', 'Use Code Review Conventions to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Establishing what a review is actually checking for — correctness, readability, adherence to existing patterns, not just "does it work" in a small working example.', 'Demonstrate Self-review discipline in a solo-developer context — reviewing your own PR with the same rigor you''d apply to someone else''s, before merging in a small working example.']::text[], array['Submit a working Code Review Conventions example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m02-t04']::text[], '[]'::jsonb, 120, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m02-t06', 'zte-fullstack-v1-core-phase-18-m02', 'Ramp-Up Strategy', array['Explain and apply null in Ramp-Up Strategy.', 'Use Ramp-Up Strategy to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate What a new engineer (or a future version of yourself, returning to the project after months away) actually needs to become productive quickly in a small working example.', 'Demonstrate Structuring an onboarding path — which docs to read first, which parts of the codebase to explore, what NOT to worry about initially in a small working example.', 'Demonstrate The direct connection to Stage 4 — this practice is essentially designing the reading order for the documentation artifacts about to be built in a small working example.']::text[], array['Submit a working Ramp-Up Strategy example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m02-t05']::text[], '[]'::jsonb, 120, 'advanced', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-18-m03', 'zte-fullstack-v1-core-phase-18', 3, 'Documentation Artifacts: Decisions & Architecture', 'These artifacts are downstream of Stage 2''s practices — the folder structure and files exist to hold the output of the ADR/RFC discipline, not as independent new concepts.', 4, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m03-t01', 'zte-fullstack-v1-core-phase-18-m03', 'ARCHITECTURE.md', array['Explain and apply null in ARCHITECTURE.md.', 'Use ARCHITECTURE.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A high-level system overview — the map that makes docs/adr/''s (10) individual decisions make sense in context in a small working example.', 'Demonstrate Summarizing the major architectural patterns actually implemented (Phase 17''s Saga, Outbox, CQRS, Circuit Breaker, Multi-Tenancy) with links to the specific ADRs that decided them in a small working example.', 'Demonstrate Keeping this document high-level — detailed reasoning belongs in the individual ADRs (10), not duplicated here in a small working example.']::text[], array['Submit a working ARCHITECTURE.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m03-t02', 'zte-fullstack-v1-core-phase-18-m03', 'DECISIONS.md', array['Explain and apply null in DECISIONS.md.', 'Use DECISIONS.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A single-file chronological or categorized index of decisions — useful as a fast-scan overview when docs/adr/''s individual files would be too slow to browse one by one in a small working example.', 'Demonstrate Where this differs from ARCHITECTURE.md (11) — DECISIONS.md is a log, ARCHITECTURE.md is a synthesized picture in a small working example.']::text[], array['Submit a working DECISIONS.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m03-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m03-t03', 'zte-fullstack-v1-core-phase-18-m03', 'docs/adr/', array['Explain and apply null in docs/adr/.', 'Use docs/adr/ to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Numbered, sequential ADR files (0001-use-postgresql.md style naming) — a convention that preserves chronological decision history in a small working example.', 'Demonstrate Linking between related/superseding ADRs — architecture decisions evolve, and the record should show that evolution rather than silently overwriting old reasoning in a small working example.']::text[], array['Submit a working docs/adr/ example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m03-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-18-m04', 'zte-fullstack-v1-core-phase-18', 4, 'Documentation Artifacts: Operational', 'Each artifact in this stage draws its actual content from a specific earlier phase''s work — these are downstream summaries, not new material to learn.', 8.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m04-t01', 'zte-fullstack-v1-core-phase-18-m04', 'PERFORMANCE.md', array['Explain and apply null in PERFORMANCE.md.', 'Use PERFORMANCE.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Documenting real benchmark numbers — p95/p99 latency, throughput, error rate under load (the exact figures Exit ★3''s "what to highlight" checklist calls out) in a small working example.', 'Demonstrate Recording what was tuned and why — connecting a specific performance fix back to the k6 result that motivated it in a small working example.']::text[], array['Submit a working PERFORMANCE.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m04-t02', 'zte-fullstack-v1-core-phase-18-m04', 'SECURITY.md', array['Explain and apply null in SECURITY.md.', 'Use SECURITY.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Documenting the OWASP Top 10 audit results (Phase 14) — what was checked, what was found, what was fixed in a small working example.', 'Demonstrate Recording the security tooling actually in place — ZAP scanning, CSP configuration, secret scanning (Phase 14''s full Stage 2–4 content) as a reference for what protections exist in a small working example.']::text[], array['Submit a working SECURITY.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m04-t03', 'zte-fullstack-v1-core-phase-18-m04', 'MONITORING.md', array['Explain and apply null in MONITORING.md.', 'Use MONITORING.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Documenting what''s actually being monitored — which logs, which error tracking, which uptime checks, and where to find each dashboard in a small working example.', 'Demonstrate Runbook-adjacent content — what a specific alert actually means and what the first response step should be in a small working example.']::text[], array['Submit a working MONITORING.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m04-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m04-t04', 'zte-fullstack-v1-core-phase-18-m04', 'OPERATIONS.md', array['Explain and apply null in OPERATIONS.md.', 'Use OPERATIONS.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Deployment process — how a release actually goes out (Phase 06''s CI/CD, Phase 17''s blue-green strategy) in a small working example.', 'Demonstrate Infrastructure overview — the Terraform/Kubernetes setup (Phase 16) at an operational, "how do I actually work with this" level of detail, distinct from ARCHITECTURE.md''s (11) higher-level why in a small working example.']::text[], array['Submit a working OPERATIONS.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m04-t03']::text[], '[]'::jsonb, 60, 'advanced', 3) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m04-t05', 'zte-fullstack-v1-core-phase-18-m04', 'TECH_DEBT.md', array['Explain and apply null in TECH_DEBT.md.', 'Use TECH_DEBT.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate The running list itself, in the format established in Topic 6 in a small working example.', 'Demonstrate Prioritization — not every debt item needs fixing immediately; documenting the reasoning for what''s deliberately left alone is as valuable as documenting what needs attention in a small working example.']::text[], array['Submit a working TECH_DEBT.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m04-t04']::text[], '[]'::jsonb, 60, 'advanced', 4) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m04-t06', 'zte-fullstack-v1-core-phase-18-m04', 'incidents/', array['Explain and apply null in incidents/.', 'Use incidents/ to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate One file per incident, following the post-mortem structure from Topic 5 in a small working example.', 'Demonstrate Including the chaos engineering experiment writeups from Phase 14/17 here as genuine, if deliberately-caused, incident records in a small working example.']::text[], array['Submit a working incidents/ example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m04-t05']::text[], '[]'::jsonb, 60, 'advanced', 5) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-18-m05', 'zte-fullstack-v1-core-phase-18', 5, 'Documentation Artifacts: Product & Personal', 'The two most independent artifacts in the phase — neither draws on a specific prior phase''s technical content the way Stage 5''s artifacts do.', 2.5, 4) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m05-t01', 'zte-fullstack-v1-core-phase-18-m05', 'PRODUCT_DECISIONS.md', array['Explain and apply null in PRODUCT_DECISIONS.md.', 'Use PRODUCT_DECISIONS.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate A decision log at the product level rather than the architecture level — why a feature works the way it does, not why a technology was chosen (the ADR/docs-adr distinction from Stage 2/4, applied to product rather than engineering choices) in a small working example.', 'Demonstrate Especially relevant for a project like ClientSync with real product-shape decisions (onboarding flow design, what the two-sided portal actually needs) worth recording alongside the purely technical ADRs in a small working example.']::text[], array['Submit a working PRODUCT_DECISIONS.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-m05-t02', 'zte-fullstack-v1-core-phase-18-m05', 'READING_NOTES.md', array['Explain and apply null in READING_NOTES.md.', 'Use READING_NOTES.md to complete a practical task in Engineering Craft + Package Publishing.']::text[], array['Demonstrate Capturing what was actually learned while building — the kind of reflection that makes the difference between having built something and being able to explain why it was built that way in an interview in a small working example.', 'Demonstrate A natural home for the reasoning behind choices flagged throughout this entire deep-doc series — every SCOPE NOTICE, every ORDERING CORRECTION, every source discrepancy caught along the way is exactly the kind of reading-notes-worthy reflection this file is for in a small working example.', 'Demonstrate Post: your first published npm package, however small — the direct output of Stage 1''s Changesets work (Topic 1). in a small working example.', 'Demonstrate GitHub: actually publish it. Add ADRs (Stage 2, Topic 2 / Stage 4, Topic 10) to the repo — not just this package''s repo, but ideally backfilled onto ClientSync''s major decisions too. in a small working example.', 'Demonstrate Where + when: LinkedIn + dev.to, the day you publish — timed to the actual event, not batched with unrelated updates. in a small working example.']::text[], array['Submit a working READING_NOTES.md example and explain the key decisions.', 'Record a short review showing how the example satisfies the Engineering Craft + Package Publishing learning goal.']::text[], array['zte-fullstack-v1-core-phase-18-m05-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-project-01', 'zte-fullstack-v1-core-phase-18', 'Semantic-Release-Ready Open Source Package', 'Publish a real npm package (one of your earlier utility libraries) with Changesets managing version bumps and changelogs, wired into CI so merging a changeset automatically publishes a new version. Domain: open source maintenance.', array['Deliver the working outcome described in the Semantic-Release-Ready Open Source Package brief.', 'Use at least two skills from Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Semantic-Release-Ready Open Source Package', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Package Publishing']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-project-02', 'zte-fullstack-v1-core-phase-18', 'Architecture Decision Record Backfill', 'Go back through 3 major decisions made earlier in this roadmap (e.g., "why Zustand over Redux," "why row-level multi-tenancy over schema-per-tenant") and write proper retroactive ADRs for each, following a consistent template (context, decision, consequences, alternatives considered).', array['Deliver the working outcome described in the Architecture Decision Record Backfill brief.', 'Use at least two skills from Decision-Making Practices and Package Publishing and Package Publishing and Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Architecture Decision Record Backfill', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Decision-Making Practices and Package Publishing and Package Publishing and Package Publishing']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-project-03', 'zte-fullstack-v1-core-phase-18', 'RFC for a Real Architecture Change', 'Write a full RFC proposing a genuine architectural change to one of your existing projects (e.g., migrating from REST to GraphQL, or adding multi-region support), including alternatives considered and a rollout plan, as if presenting to a real engineering team.', array['Deliver the working outcome described in the RFC for a Real Architecture Change brief.', 'Use at least two skills from Decision-Making Practices and Package Publishing and Package Publishing and Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working RFC for a Real Architecture Change', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Decision-Making Practices and Package Publishing and Package Publishing and Package Publishing']::text[], 'intermediate', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-project-04', 'zte-fullstack-v1-core-phase-18', 'Personal DORA Metrics Tracker', 'A small tool/dashboard that tracks your own deployment frequency, lead time for changes, change failure rate, and time to restore across this roadmap’s projects, pulled from real Git/CI history, not estimated.', array['Deliver the working outcome described in the Personal DORA Metrics Tracker brief.', 'Use at least two skills from Engineering Process Practices.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Personal DORA Metrics Tracker', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Engineering Process Practices']::text[], 'intermediate', 3) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-project-05', 'zte-fullstack-v1-core-phase-18', 'Blameless Post-Mortem for a Real Bug', 'Write a full blameless post-mortem for a real bug or outage you caused somewhere in this roadmap (there will be one), following a proper template: timeline, impact, root cause, contributing factors, and concrete action items.', array['Deliver the working outcome described in the Blameless Post-Mortem for a Real Bug brief.', 'Use at least two skills from Engineering Process Practices.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Blameless Post-Mortem for a Real Bug', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'Engineering Process Practices']::text[], 'intermediate', 4) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-18-project-06', 'zte-fullstack-v1-core-phase-18', 'A Fully Documented, Publishable Engineering Portfolio Project', 'Take your single most impressive project from anywhere in this roadmap and bring its engineering craft to a publishable standard: a Changesets-managed, auto-published package extracted from its reusable internals, a complete ADR history and RFC for its next proposed evolution, real DORA metrics pulled from its Git/CI history, a blameless post-mortem for a genuine incident, and the full documentation set (ARCHITECTURE.md, DECISIONS.md, PERFORMANCE.md, SECURITY.md, MONITORING.md, OPERATIONS.md, TECH\\\_DEBT.md, PRODUCT\\\_DECISIONS.md) written to a standard where a stranger engineer could fully onboard and operate it without ever talking to you. Domain: engineering craft / technical leadership. Why it matters: documentation and process discipline is what makes an individual’s work into an organization’s asset — this is the artifact that signals senior/staff-level maturity, not just coding ability.', array['Deliver the working outcome described in the A Fully Documented, Publishable Engineering Portfolio Project brief.', 'Use at least two skills from Engineering Craft + Package Publishing.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Fully Documented, Publishable Engineering Portfolio Project', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Engineering Craft + Package Publishing', 'engineering documentation']::text[], 'advanced', 5) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_phases (id, roadmap_id, roadmap_version_id, phase_number, title, band, description, estimated_hours, order_index) select 'zte-fullstack-v1-core-phase-19', 'zte-fullstack-v1', id, '21', 'Career & Community', 'Expert', 'The only genuinely technical stage in this phase — placed first, trivial before real, as a warm-up before the career/community-focused stages that make up the rest of the phase.', 29, 20 from public.roadmap_versions where roadmap_id='zte-fullstack-v1' and version_number=2 on conflict (id) do update set title=excluded.title, band=excluded.band, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-19-m01', 'zte-fullstack-v1-core-phase-19', 1, 'API Practice', 'The only genuinely technical stage in this phase — placed first, trivial before real, as a warm-up before the career/community-focused stages that make up the rest of the phase.', 3.5, 0) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m01-t01', 'zte-fullstack-v1-core-phase-19-m01', 'JSONPlaceholder API', array['Explain and apply null in JSONPlaceholder API.', 'Use JSONPlaceholder API to complete a practical task in Career & Community.']::text[], array['Demonstrate Making requests against a free, no-auth-required fake REST API — useful for quickly demoing an integration pattern without needing real credentials or a real backend in a small working example.', 'Demonstrate Common use: prototyping a UI against realistic-shaped data before a real API (Phase 05) exists or is ready in a small working example.']::text[], array['Submit a working JSONPlaceholder API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 60, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m01-t02', 'zte-fullstack-v1-core-phase-19-m01', 'GitHub API', array['Explain and apply null in GitHub API.', 'Use GitHub API to complete a practical task in Career & Community.']::text[], array['Demonstrate Authentication — personal access tokens vs GitHub Apps vs OAuth, and which fits a given use case in a small working example.', 'Demonstrate Common operations — reading repo data, creating issues/PRs programmatically, managing releases (directly relevant to automating parts of Phase 18''s Changesets-driven publish workflow) in a small working example.', 'Demonstrate Rate limiting — GitHub''s API limits and how authenticated vs unauthenticated requests differ in a small working example.', 'Demonstrate Practical use: building a small tool or script that interacts with your own repos — a genuinely useful capstone exercise combining this phase''s API practice with Phase 18''s documentation/publishing work in a small working example.']::text[], array['Submit a working GitHub API example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-fullstack-v1-core-phase-19-m01-t01']::text[], '[]'::jsonb, 360, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-19-m02', 'zte-fullstack-v1-core-phase-19', 2, 'Job & Talent Platforms', 'Requires a complete portfolio (effectively all of Phases 01–18) to have a profile worth putting on any of these platforms. Ordered niche-to-broad: the two India/startup-focused platforms first, LinkedIn last since its payoff specifically depends on the accumulated 17-month posting history Exit E''s own description assumes already exists.', 6, 1) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m02-t01', 'zte-fullstack-v1-core-phase-19-m02', 'Wellfound (formerly AngelList)', array['Explain and apply null in Wellfound (formerly AngelList).', 'Use Wellfound (formerly AngelList) to complete a practical task in Career & Community.']::text[], array['Demonstrate Building a profile optimized for startup hiring — different norms than a traditional corporate resume in a small working example.', 'Demonstrate Filtering strategy — searching by "founding engineer" + stage + equity range, the exact filter Exit E''s own guidance recommends in a small working example.', 'Demonstrate What startups actually look for here — evidence of building and shipping (ClientSync, the published npm package from Phase 18), not just a credentials list in a small working example.']::text[], array['Submit a working Wellfound (formerly AngelList) example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m02-t02', 'zte-fullstack-v1-core-phase-19-m02', 'Instahyre', array['Explain and apply null in Instahyre.', 'Use Instahyre to complete a practical task in Career & Community.']::text[], array['Demonstrate Profile optimization specifically for the Indian product/startup hiring market in a small working example.', 'Demonstrate How Instahyre''s matching differs from Wellfound''s more founder-direct model — recruiter-mediated vs direct outreach in a small working example.']::text[], array['Submit a working Instahyre example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-fullstack-v1-core-phase-19-m02-t01']::text[], '[]'::jsonb, 120, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m02-t03', 'zte-fullstack-v1-core-phase-19-m02', 'LinkedIn', array['Explain and apply null in LinkedIn.', 'Use LinkedIn to complete a practical task in Career & Community.']::text[], array['Demonstrate Profile optimization — headline, about section, and featured section built around what''s actually been shipped (ClientSync, the npm package), not generic self-description in a small working example.', 'Demonstrate Why this phase treats LinkedIn last, not first — a strong profile with zero posting history undersells 17 months of real work; the accumulated content from every prior phase''s Build in Public section is what makes the profile credible in a small working example.', 'Demonstrate Thought leadership positioning — Exit E explicitly notes that if you''ve been posting consistently, inbound interest starts here in a small working example.', 'Demonstrate Direct outreach — messaging engineering managers with a specific technical observation about their stack, the exact tactic Exit ★3 (Phase 17) already flagged as more effective than cold applications at senior level in a small working example.']::text[], array['Submit a working LinkedIn example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-fullstack-v1-core-phase-19-m02-t02']::text[], '[]'::jsonb, 180, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-19-m03', 'zte-fullstack-v1-core-phase-19', 3, 'Product Launch & Community', 'Requires a genuinely complete, demo-able product — ClientSync, after 18 phases of work — to have anything worth launching or discussing.', 5, 2) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m03-t01', 'zte-fullstack-v1-core-phase-19-m03', 'Product Hunt', array['Explain and apply null in Product Hunt.', 'Use Product Hunt to complete a practical task in Career & Community.']::text[], array['Demonstrate Preparing a launch — assets, a compelling tagline, timing (Product Hunt''s day-of-week and timezone dynamics affect visibility) in a small working example.', 'Demonstrate Engaging during launch day — responding to comments and feedback in real time, which Exit E''s own "what to highlight" list calls out specifically (upvotes, comments, feedback received and acted on) in a small working example.', 'Demonstrate What a launch actually demonstrates to a hiring manager — not just that a product exists, but that you can ship something real people react to in a small working example.']::text[], array['Submit a working Product Hunt example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 120, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m03-t02', 'zte-fullstack-v1-core-phase-19-m03', 'Indie Hackers', array['Explain and apply null in Indie Hackers.', 'Use Indie Hackers to complete a practical task in Career & Community.']::text[], array['Demonstrate Sharing the journey, not just the launch — Indie Hackers'' culture rewards process and lessons-learned content over pure announcement posts in a small working example.', 'Demonstrate Cross-posting the Product Hunt launch (6) here for a different, builder-focused audience in a small working example.']::text[], array['Submit a working Indie Hackers example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-fullstack-v1-core-phase-19-m03-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m03-t03', 'zte-fullstack-v1-core-phase-19-m03', 'SaaS India Slack', array['Explain and apply null in SaaS India Slack.', 'Use SaaS India Slack to complete a practical task in Career & Community.']::text[], array['Demonstrate A smaller, higher-signal community compared to Product Hunt''s broad public audience in a small working example.', 'Demonstrate Networking value specifically relevant to your stated target companies (Bangalore product startups) — the people in this community may overlap directly with your actual target employer list in a small working example.']::text[], array['Submit a working SaaS India Slack example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-fullstack-v1-core-phase-19-m03-t02']::text[], '[]'::jsonb, 60, 'advanced', 2) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_modules (id, phase_id, module_number, title, description, estimated_hours, order_index) values ('zte-fullstack-v1-core-phase-19-m04', 'zte-fullstack-v1-core-phase-19', 4, 'Technical Writing Platforms', 'dev.to has already been used informally throughout nearly every Build in Public section since Phase 06 — this stage is about formal platform mastery and audience-building, not the first introduction to posting there.', 3.5, 3) on conflict (id) do update set title=excluded.title, description=excluded.description, estimated_hours=excluded.estimated_hours, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m04-t01', 'zte-fullstack-v1-core-phase-19-m04', 'dev.to', array['Explain and apply null in dev.to.', 'Use dev.to to complete a practical task in Career & Community.']::text[], array['Demonstrate Series and tagging strategy — organizing the 17-month posting history (every phase''s Build in Public output) into a coherent, discoverable body of work rather than scattered individual posts in a small working example.', 'Demonstrate Engagement patterns — what actually drives readership on dev.to specifically, distinct from LinkedIn''s algorithm (Stage 2, Topic 5) in a small working example.', 'Demonstrate This phase''s own retrospective post (see Build in Public below) as the capstone piece tying the whole series together in a small working example.']::text[], array['Submit a working dev.to example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array[]::text[], '[]'::jsonb, 180, 'advanced', 0) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_topics (id, module_id, title, learning_objectives, practice_tasks, completion_evidence, prerequisite_topic_ids, learning_resources, estimated_minutes, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-m04-t02', 'zte-fullstack-v1-core-phase-19-m04', 'Hashnode', array['Explain and apply null in Hashnode.', 'Use Hashnode to complete a practical task in Career & Community.']::text[], array['Demonstrate Feature comparison with dev.to — custom domains, newsletter integration, and other differences worth knowing in a small working example.', 'Demonstrate Cross-posting strategy — publishing the same retrospective content (Build in Public below) to both platforms to maximize reach, rather than choosing one exclusively in a small working example.', 'Demonstrate Post: the full journey — a genuine retrospective. What was built, what was surprising, what would be done differently. Not a highlight reel; the honest version is more credible and more useful to write. in a small working example.', 'Demonstrate GitHub: a final README pass on ClientSync — this is explicitly called out as the actual artifact recruiters click through to, more than any individual phase''s work. in a small working example.', 'Demonstrate Where + when: LinkedIn (long-form retrospective) + dev.to (the technical version, Stage 4) + shared on Indie Hackers (Stage 3, Topic 7) — one piece of writing, three audiences. in a small working example.']::text[], array['Submit a working Hashnode example and explain the key decisions.', 'Record a short review showing how the example satisfies the Career & Community learning goal.']::text[], array['zte-fullstack-v1-core-phase-19-m04-t01']::text[], '[]'::jsonb, 60, 'advanced', 1) on conflict (id) do update set title=excluded.title, learning_objectives=excluded.learning_objectives, practice_tasks=excluded.practice_tasks, completion_evidence=excluded.completion_evidence, prerequisite_topic_ids=excluded.prerequisite_topic_ids, learning_resources=excluded.learning_resources, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-project-01', 'zte-fullstack-v1-core-phase-19', 'Portfolio-to-Application Pipeline', 'A polished, professional profile presence across Wellfound, Instahyre, and LinkedIn, each tailored to its audience (startup-focused vs. broad), all linking back to a coherent personal portfolio site showcasing this roadmap’s best 4–5 capstone projects with real metrics (not just screenshots).', array['Deliver the working outcome described in the Portfolio-to-Application Pipeline brief.', 'Use at least two skills from Job & Talent Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Portfolio-to-Application Pipeline', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Career & Community', 'Job & Talent Platforms']::text[], 'intermediate', 0) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-project-02', 'zte-fullstack-v1-core-phase-19', 'Technical Deep-Dive Article Series', 'Write and publish 3 genuinely useful technical articles (on dev.to and cross-posted to Hashnode) documenting real, hard-won lessons from this roadmap — e.g., "What actually breaks when you load-test a Node API," "I built the same feature with REST and GraphQL, here’s the real difference" — not generic tutorials.', array['Deliver the working outcome described in the Technical Deep-Dive Article Series brief.', 'Use at least two skills from Technical Writing Platforms.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working Technical Deep-Dive Article Series', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Career & Community', 'Technical Writing Platforms']::text[], 'intermediate', 1) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
insert into public.roadmap_projects (id, phase_id, title, problem_statement, requirements, milestones, deliverables, skills, difficulty, order_index) values ('zte-fullstack-v1-core-phase-19-project-03', 'zte-fullstack-v1-core-phase-19', 'A Complete Public Engineering Presence', 'Synthesize the entire roadmap into a real public footprint: a portfolio site (built with everything learned in Phases 1–3) showcasing your 5 strongest capstones with real architecture docs linked in, a genuine Product Hunt launch of your best project with measured traction, a 3-part technical article series published across dev.to and Hashnode documenting real lessons learned (load testing failures, security findings, architectural tradeoffs — not tutorials), and tailored, live profiles on LinkedIn/Wellfound/Instahyre driving toward real conversations. Domain: career development / developer relations. Why it matters: an extraordinary body of technical work that nobody knows about has zero career leverage — this final phase converts 1,159.5 hours of deep engineering work into a visible, credible, discoverable professional presence.', array['Deliver the working outcome described in the A Complete Public Engineering Presence brief.', 'Use at least two skills from Career & Community.', 'Document setup, decisions, and known limitations.']::text[], array['Write a short plan and split the work into reviewable steps.', 'Build and refine the working result using the phase concepts.', 'Review the result, capture evidence, and document what you learned.']::text[], array['Working A Complete Public Engineering Presence', 'README with setup instructions and design decisions', 'Evidence of the result, such as a deployment, recording, or screenshots']::text[], array['Career & Community', 'engineering documentation']::text[], 'advanced', 2) on conflict (id) do update set title=excluded.title, problem_statement=excluded.problem_statement, requirements=excluded.requirements, milestones=excluded.milestones, deliverables=excluded.deliverables, skills=excluded.skills, difficulty=excluded.difficulty, order_index=excluded.order_index;
